const keys = new Set();
// Player report 23 (js/held-keys.js): a held key is let go of whenever the page cannot vouch for
// it (blur, a context menu, Cmd, a text field), as the client's KeyBeacon.reset did.
const heldKeys = installHeldKeyGuard(keys, { onRelease: (why) => setCanvasData('keysReleased', why) });
let app, world, bgLayer, entityLayer, fxLayer, player, prompt, promptLayer, camTarget, camY, portalSprites;
/** Ticket 21: street deco art, released from the image cache once no street draws it (releaseIdleImages). */
const STREET_ART_URL = /(^|\/)assets\/decos\//;
let imagesReleased = 0;
// FEEL (js/camera-feel.js): per axis, whether the eased camera rests on its target this frame and
// the way it last travelled.
const cameraRest = { x: { rest: true, dir: 0 }, y: { rest: true, dir: 0 } };
/** FEEL: the parallax layers snap to device pixels only on an axis whose camera rests. */
function parallaxSnap() {
  const res = app?.renderer?.resolution || 1;
  return { x: cameraRest.x.rest ? res : 0, y: cameraRest.y.rest ? res : 0, dx: cameraRest.x.dir, dy: cameraRest.y.dir };
}
/** Holds the street's layers above the middleground (street-render frontView), over entityLayer. */
let streetFrontLayer = null;
/** The Dametime atmosphere (updateDametimeChrome): a multiply wash between the street and fxLayer. */
let atmosphere = null;
let hoveredSignBoard = null;
let cameraRightInset = 0;

/**
 * Show the current street's front layers over the avatars and entities, as the client's
 * layer order does (street-render layerDrawsInFront). Every scene swap replaces bgLayer, so
 * this follows it: called on street entry and every frame. Scenes without a frontView
 * (feature backgrounds, quest rooms drawn by hand) clear it; it copies bgLayer's transform.
 */
function syncStreetFront() {
  if (!streetFrontLayer) return;
  const live = bgLayer && !bgLayer.destroyed ? bgLayer.frontView : null;
  const front = live && !live.destroyed ? live : null;
  if (streetFrontLayer.children[0] !== front || streetFrontLayer.children.length > (front ? 1 : 0)) {
    streetFrontLayer.removeChildren();
    if (front) streetFrontLayer.addChild(front);
  }
  if (!front) return;
  streetFrontLayer.position.copyFrom(bgLayer.position);
  streetFrontLayer.scale.copyFrom(bgLayer.scale);
  streetFrontLayer.visible = bgLayer.visible;
  streetFrontLayer.alpha = bgLayer.alpha;
}

/** The top bar's Menu: the less-used panels, closed by a pick, Esc or a click away. */
function installMoreMenu() {
  const btn = document.getElementById('more-btn');
  const list = document.getElementById('more-list');
  if (!btn || !list) return;
  const setOpen = (open) => {
    list.hidden = !open;
    btn.setAttribute('aria-expanded', String(open));
  };
  btn.addEventListener('click', () => setOpen(list.hidden));
  list.addEventListener('click', (e) => {
    if (e.target.closest('button')) setOpen(false);
  });
  document.addEventListener('pointerdown', (e) => {
    if (!list.hidden && !e.target.closest('.more-menu')) setOpen(false);
  });
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && !list.hidden) {
      setOpen(false);
      // The Menu button after a keyboard open, the world after a click (js/ui/focus-return.js).
      focusBack(btn);
    }
  });
}

/**
 * The player menu (PlayerInfoUI.as toggleMenu): clicking your name or the
 * level pill drops down PlayerStatsUI (level, iMG 'til the next level, mood,
 * energy, currants) above the PlayerInfoButtons the remake has (Skills,
 * Vanity, Wardrobe, Encyclopedia: ENCYC 2026-11-05). Profile, Groups, Friends,
 * Keys, Forums, Auctions, Preferences and Account had nothing behind them
 * without the website and other players, so they are left out.
 */
function renderPlayerMenu(menu) {
  const info = levelInfoForXp(pc.xp);
  const fmt = (n) => Math.round(Number(n) || 0).toLocaleString();
  menu.replaceChildren();
  const head = document.createElement('div');
  head.className = 'pm-head';
  head.innerHTML = `<span class="pm-level-label">Level:</span><span class="pm-level">${info.level}</span>`;
  const stats = document.createElement('dl');
  stats.className = 'pm-stats';
  const row = (label, value, cls = '') => {
    const dt = document.createElement('dt');
    dt.textContent = label;
    const dd = document.createElement('dd');
    if (cls) dd.className = cls;
    dd.innerHTML = value;
    stats.append(dt, dd);
  };
  if (!info.atCap) row('iMG', `<b>${fmt(info.remaining)}</b><small>’til level ${info.level + 1}</small>`, 'pm-img');
  row('Mood', `<b>${fmt(pc.mood)}</b>/${fmt(moodMax(pc))}`);
  row('Energy', `<b>${fmt(pc.energy)}</b>/${fmt(energyCap())}`);
  row('Currants', `<b>${fmt(pc.currants)}</b>`);
  const buttons = document.createElement('div');
  buttons.className = 'pm-buttons';
  for (const [label, run] of [
    ['Skills', () => document.getElementById('skills-btn')?.click()],
    ['Vanity', () => openLookBuilderOn('hair')],
    ['Wardrobe', () => openLookBuilderOn('top')],
    // ENCYC: PlayerInfoButtons.as 43 (TSFrontController.as openEncyclopediaPage 4395-4400): the home page.
    [ENCYCLOPEDIA_MENU_LABEL, () => openEncyclopedia(null)],
  ]) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'chrome-btn';
    btn.textContent = label;
    btn.addEventListener('click', run);
    buttons.append(btn);
  }
  menu.append(head, stats, buttons);
}

/** Vanity and Wardrobe open the look builder on a face or clothing tab. */
function openLookBuilderOn(slot) {
  avatarBuilderSlot = slot;
  if (!state.started) {
    openBuilderOnStart = true;
    beginGame();
    return;
  }
  if (isAvatarOpen()) renderAvatarBuilder();
  else openAvatarPanel();
}

/** G254: the client's hold-? sheet (js/client-hotkeys.js); the keyring row only in multiplayer. */
const hotkeysSheet = createHotkeysSheet(document, { keyring: () => Boolean(document.getElementById('keys-btn')), hub: () => modernUi(), reports: () => Boolean(document.getElementById('bug-btn')) });

/**
 * ENCYC (Austin 2026-11-05, js/encyclopedia-links.js): the Encyclopedia from the game. Its index
 * (encyclopedia/search.json) loads a few seconds after the game starts; once it is in, the open
 * item card and sheets draw their "In the Encyclopedia" links.
 */
const encyclopedia = createEncyclopedia({
  onReady: () => {
    updateHud();
    if (isSkillsOpen()) renderSkillsPanel();
  },
});

/** ENCYC: a world thing as an Encyclopedia subject (a dropped stack is its item; players have no page). */
function encyclopediaTargetSubject(t) {
  if (!t) return null;
  const id = t.classId === 'dropped_item' ? t.state?.classTsid : t.classId;
  if (!id || /^pc_/.test(String(id))) return null;
  return { id: String(id), name: String(t.label || ITEM_CATALOG[id]?.label || '') };
}

/** ENCYC: an item class as a subject, by its pack name. */
function encyclopediaItemSubject(cls) {
  return cls ? { id: String(cls), name: String(ITEM_CATALOG[cls]?.label || cls) } : null;
}

/**
 * ENCYC: what `i` is about: the item card (the pack's stack menu) or verb menu that is open, then
 * what the pointer is over (a pack slot or store tile, then something in the world), then a pack
 * slot with the keyboard's focus, then the street's region; null is the home page.
 */
function encyclopediaSubject() {
  if (isPackPopoverOpen()) {
    const cls = document.getElementById('pack-popover')?.dataset.packFor;
    if (cls) return encyclopediaItemSubject(cls);
  }
  if (menuTarget) {
    const subject = encyclopediaTargetSubject(menuTarget);
    if (subject) return subject;
  }
  const hovered = [...document.querySelectorAll('.pack-slot[data-tsid]:hover, [data-vendor-item]:hover')].pop();
  if (hovered) return encyclopediaItemSubject(hovered.dataset.tsid || hovered.dataset.vendorItem);
  // The world's hover outline stays after the pointer leaves the canvas: only a pointer on the canvas counts.
  if (hoverTarget?.sprite && !hoverTarget.sprite.destroyed && app?.canvas?.matches?.(':hover')) {
    const subject = encyclopediaTargetSubject(hoverTarget);
    if (subject) return subject;
  }
  const focused = document.activeElement?.closest?.('.pack-slot[data-tsid], [data-vendor-item]');
  if (focused) return encyclopediaItemSubject(focused.dataset.tsid || focused.dataset.vendorItem);
  const hubName = currentStreet?.hubName || '';
  return hubName ? { section: 'places', name: hubName, hubId: String(currentStreet?.hubId ?? '') } : null;
}

/** ENCYC: open the Encyclopedia (on a subject, or its home page) and note where it went for QA. */
function openEncyclopedia(subject = null) {
  const went = encyclopedia.open(subject);
  const note = (url) => setCanvasData('encyclopediaOpened', String(url || ''));
  if (went && typeof went.then === 'function') went.then(note);
  else note(went);
  return went;
}

/**
 * ENCYC: the `i` key (TSMainView.as iKeyHandler 870-891, which started Info mode). It is quiet where
 * the client's was: where the tutorial hides the imagination menu (nx-hide-actions, the client's
 * location.no_imagination), in decorate or cultivate mode and in the look builder (decorator,
 * cult and chassis modes); the main keydown has already let typing in a field through.
 */
function encyclopediaKey(e) {
  if (!isEncyclopediaKey(e)) return false;
  if (document.body.classList.contains('nx-hide-actions') || features.query('homeEditMode', engine) || isAvatarOpen()) return false;
  e.preventDefault();
  keys.delete(e.key);
  if (!e.repeat) openEncyclopedia(encyclopediaSubject());
  return true;
}

/** A visible element (not under a hidden ancestor or display: none). */
function shownElement(node) {
  return Boolean(node && !node.closest('[hidden]') && node.getClientRects().length);
}

/**
 * G254: the client's keys the remake has a panel for (js/client-hotkeys.js
 * CLIENT_KEY_TABLE: TSMainView.as 641-660 and hotkeys.png). M is with G below and
 * ? is the sheet; this takes Z, Shift+L, Shift+K and Shift+D. The main keydown
 * handler has already let typing in a field through. Returns true when the key
 * was taken (the caller stops there).
 *
 * Shift+F and backquote: Inventory Search (shiftFKeyHandler 846-855, 655), the
 * pack's search (js/ui/pack-row.js), not while Gentle Island hides the pack.
 *
 * Comma is Preferences (js/classic/classic-prefs.js, both skins). I is the
 * Encyclopedia (ENCYC, encyclopediaKey: the client's Info mode, iKeyHandler 870-891,
 * led there). Shift+M shows or hides the street map (G370). F stays the remake's apple.
 */
function clientShortcutKey(e) {
  const action = clientKeyAction(e);
  // Shift+M: the street map (G370, js/ui/street-minimap.js), on or off. The client's Shift+M
  // showed the chat column's map tab (shiftMKeyHandler 925-940), whose map this is.
  if (action === 'street-map') {
    if (!e.repeat) toggleStreetMap();
    return true;
  }
  if (action === 'pack-search') {
    if (document.body.classList.contains('nx-hide-pack') || !shownElement(document.getElementById('pack-bar'))) return false;
    // The key must not type itself into the field it focuses.
    e.preventDefault();
    keys.delete(e.key);
    if (!e.repeat) packRow.openSearch();
    return true;
  }
  // Z: the player menu (zKeyHandler 1031-1042: TSFrontController.togglePlayerMenu),
  // not where the location hides the mood (no_mood; newxp-feature's nx-hide-mood).
  if (action === 'player-menu') {
    const btn = document.getElementById('player-menu-btn');
    if (!e.repeat && shownElement(btn) && !document.body.classList.contains('nx-hide-mood')) btn.click();
    return true;
  }
  // Shift+L: your looks (shiftLKeyHandler 980-994: opens ImaginationYourLooksUI unless it is up).
  if (action === 'looks') {
    if (!e.repeat && !isAvatarOpen()) openAvatarPanel();
    // Ticket 59: straight to Your looks, as the client opened it (features/your-looks-feature.js).
    if (!e.repeat) features.query('showYourLooks', engine);
    return true;
  }
  // Shift+K: the keyring (shiftKKeyHandler 962-978: ACLDialog start, or end when open).
  // The keyring is multiplayer's (neighbours-mp-feature); solo has no keys to hold.
  if (action === 'keyring') {
    if (e.repeat) return true;
    const shade = document.getElementById('keys-shade');
    if (shade && !shade.hidden) shade.querySelector('.keys-close')?.click();
    else document.getElementById('keys-btn')?.click();
    return true;
  }
  // Shift+D: decorate mode (shiftDKeyHandler 831-844): CLICK_SUCCESS and out when it is on,
  // else startDecoratorMode, which only goes ahead where you can decorate
  // (TSFrontController.as setDecoratorMode 3957-3968: can_decorate, inside your house
  // or tower). Anywhere else Shift+D is still a step right.
  if (action === 'decorate') {
    const mode = features.query('homeEditMode', engine);
    const close = mode === 'decorate' ? document.querySelector('#homes-bar .hb-close') : null;
    const open = mode ? null : document.getElementById('homes-decorate-btn');
    if (!close && !shownElement(open)) return false;
    keys.delete('d');
    keys.delete('D');
    if (e.repeat) return true;
    if (close) {
      playSound('CLICK_SUCCESS', { volume: 0.32 });
      close.click();
    } else open.click();
    return true;
  }
  return false;
}

/** The vitals menu (installVitalsMenu): which stat it is open for, and the meter that opened it. */
let vitalsMenuFor = null;
let vitalsMenuPill = null;

/** Redraw the open vitals menu (after an eat, or when the pack changes); a no-op when closed. */
function refreshVitalsMenu() {
  const menu = document.getElementById('vitals-menu');
  if (!menu || menu.hidden || !vitalsMenuFor) return;
  const stat = vitalsMenuFor;
  const snacks = vitalSnacks({ inv, stat, useInfoFor: getPackUseInfo });
  const max = stat === 'mood' ? moodMax(pc) : energyCap();
  const now = stat === 'mood' ? pc.mood : pc.energy;
  const unit = stat === 'mood' ? 'mood' : 'energy';
  const key = `${stat}|${Math.round(now)}|${snacks.map((s) => `${s.classTsid}:${s.count}`).join(',')}`;
  if (menu.dataset.key === key) return;
  menu.dataset.key = key;
  menu.dataset.stat = stat;
  const rows = snacks.map((s) => {
    const label = ITEM_CATALOG[s.classTsid]?.label || s.classTsid;
    return `<button type="button" class="vitals-snack" data-vital-use="${escapeHtml(s.classTsid)}" title="${escapeHtml(`${s.verb} a ${label}`)}">
        <img src="${escapeHtml(itemIconUrl(s.classTsid))}" alt="" />
        <span class="vitals-snack-name">${escapeHtml(label)} <small>×${s.count}</small></span>
        <b>+${Math.round(s.gain)} ${unit}</b>
      </button>`;
  }).join('');
  menu.innerHTML = `<div class="vitals-menu-head"><strong>${escapeHtml(vitalMenuHeading(stat))}</strong><span>${Math.round(now)}/${Math.round(max)}</span></div>
    ${rows || `<p class="vitals-menu-empty">${escapeHtml(vitalMenuEmpty(stat))}</p>`}`;
}

/**
 * g458 (Austin's UI audit 2): a click (or Enter) on the top bar's Energy or
 * Mood offers what in the pack would raise it, best first; a pick eats or
 * drinks one through the pack's own Eat / Drink (usePackItem).
 */
function installVitalsMenu() {
  const bar = document.querySelector('header.top-bar');
  if (!bar || document.getElementById('vitals-menu')) return;
  const menu = document.createElement('div');
  menu.id = 'vitals-menu';
  menu.className = 'vitals-menu';
  // A click in it (eat one) gives the world the keys, so Space jumps (js/ui/focus-return.js).
  menu.dataset.clickReleases = '';
  menu.hidden = true;
  menu.setAttribute('role', 'dialog');
  menu.setAttribute('aria-label', 'Something from your pack');
  bar.appendChild(menu);
  const close = (back = false) => {
    if (menu.hidden) return;
    menu.hidden = true;
    menu.dataset.key = '';
    vitalsMenuPill?.setAttribute('aria-expanded', 'false');
    if (back && vitalsMenuPill) focusBack(vitalsMenuPill);
    vitalsMenuFor = null;
  };
  const open = (stat, pill) => {
    if (!menu.hidden && vitalsMenuFor === stat) {
      close();
      return;
    }
    vitalsMenuPill?.setAttribute('aria-expanded', 'false');
    vitalsMenuFor = stat;
    vitalsMenuPill = pill;
    menu.hidden = false;
    menu.dataset.key = '';
    const b = bar.getBoundingClientRect();
    const r = pill.getBoundingClientRect();
    menu.style.left = `${Math.max(6, Math.round(r.left - b.left - 8))}px`;
    pill.setAttribute('aria-expanded', 'true');
    refreshVitalsMenu();
    menu.querySelector('button')?.focus();
  };
  for (const stat of ['energy', 'mood']) {
    const pill = bar.querySelector(`.meta-pill.${stat}`);
    if (!pill) continue;
    pill.tabIndex = 0;
    pill.setAttribute('role', 'button');
    pill.setAttribute('aria-haspopup', 'dialog');
    pill.setAttribute('aria-controls', 'vitals-menu');
    pill.setAttribute('aria-expanded', 'false');
    pill.addEventListener('click', () => open(stat, pill));
    pill.addEventListener('keydown', (e) => {
      if (e.key !== 'Enter' && e.key !== ' ') return;
      // Not the game's Enter (verbs) or Space (jump).
      e.preventDefault();
      e.stopPropagation();
      open(stat, pill);
    });
  }
  menu.addEventListener('click', (e) => {
    const btn = e.target.closest('[data-vital-use]');
    if (!btn) return;
    usePackItem(btn.dataset.vitalUse, 1);
    menu.dataset.key = '';
    refreshVitalsMenu();
    (menu.querySelector(`[data-vital-use="${btn.dataset.vitalUse}"]`) || menu.querySelector('button'))?.focus();
  });
  menu.addEventListener('keydown', (e) => {
    // The menu's own keys stay out of the game (Space jumps, Enter runs verbs).
    if (e.key === 'Enter' || e.key === ' ') e.stopPropagation();
    // 1 to 9 eat the row with that number (the HUD mock's popover keys), never Say Hi (5).
    if (/^[1-9]$/.test(e.key) && !e.metaKey && !e.ctrlKey && !e.altKey) {
      const row = menu.querySelectorAll('[data-vital-use]')[Number(e.key) - 1];
      e.stopPropagation();
      e.preventDefault();
      row?.click();
    }
  });
  document.addEventListener('pointerdown', (e) => {
    if (!menu.hidden && !e.target.closest('#vitals-menu, .meta-pill.energy, .meta-pill.mood, #low-energy-btn')) close();
  });
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && !menu.hidden) close(true);
  });
}

function installPlayerMenu() {
  const btn = document.getElementById('player-menu-btn');
  const menu = document.getElementById('player-menu');
  const meter = document.getElementById('level-meter');
  if (!btn || !menu) return;
  const setOpen = (open) => {
    if (open) renderPlayerMenu(menu);
    menu.hidden = !open;
    btn.setAttribute('aria-expanded', String(open));
  };
  const toggle = () => setOpen(menu.hidden);
  btn.addEventListener('click', toggle);
  // The modern bar's level ring is the button itself (its meter inside): one toggle.
  if (meter && !btn.contains(meter)) meter.addEventListener('click', toggle);
  menu.addEventListener('click', (e) => {
    if (e.target.closest('button')) setOpen(false);
  });
  document.addEventListener('pointerdown', (e) => {
    if (!menu.hidden && !e.target.closest('#player-menu, #player-menu-btn, #level-meter')) setOpen(false);
  });
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && !menu.hidden) {
      setOpen(false);
      focusBack(btn);
    }
  });
}

/** Keep the backing store at the canvas's displayed density (js/render-density.js). */
function syncRenderResolution() {
  if (!app?.renderer || !app.canvas) return;
  const cssWidth = app.canvas.getBoundingClientRect().width;
  const next = renderResolution(cssWidth, VIEW_W, window.devicePixelRatio || 1);
  if (Math.abs(next - app.renderer.resolution) < RESOLUTION_STEP / 2) return;
  app.renderer.resize(VIEW_W, VIEW_H, next);
  app.canvas.dataset.renderResolution = String(next);
}

/** The scene whose size last held the view (syncLocationViewHeight). */
let viewSceneLayer = null;

/** `?viewh=<px>` (QA, the restoration and landing shots): the old page, a 960 px view scaled to the width. */
const PINNED_VIEW_H = Number(new URLSearchParams(location.search).get('viewh')) || 0;
if (PINNED_VIEW_H > 0) document.documentElement.classList.add('stage-pinned');

/**
 * The stage for the window (g458, js/location-view.js stageFor): the CSS room
 * #game-root leaves under the top bar, the current scene's own width and
 * height (TSMainView's smallest layer), and `viewh` for the pinned layout.
 */
function stageArgs() {
  const root = document.getElementById('game-root');
  const sceneHeight = sceneViewCap(bgLayer);
  if (!root) return { sceneHeight };
  if (PINNED_VIEW_H > 0) {
    const host = app?.canvas?.isConnected ? app.canvas : root;
    return { width: host.getBoundingClientRect().width || root.clientWidth, height: 1, pinnedHeight: PINNED_VIEW_H, sceneHeight };
  }
  return {
    width: root.clientWidth,
    height: root.clientHeight,
    packReserve: PACK_VIEW_RESERVE,
    sceneWidth: sceneViewWidthCap(bgLayer, WORLD_W),
    sceneHeight,
  };
}

function measureStage() {
  // ZOOM (js/world-zoom.js): Wide (0) to Original (1), this device's choice.
  return stageFor({ ...stageArgs(), zoom: worldZoom() });
}

/**
 * ZOOM FIXED (#149): this street draws the same at every zoom in this window (a narrow
 * layer caps the view, js/location-view.js zoomMovesStage). Modern only: Classic's zoom also
 * scales its frame, so the picture always changes there; the pinned QA page ignores zoom.
 */
function streetZoomFixed() {
  if (PINNED_VIEW_H > 0 || !modernUi() || !bgLayer) return false;
  return !zoomMovesStage(stageArgs());
}

/**
 * Size the canvas to the window, live; true when the view changed. The view
 * grows with the window at about 1:1 (VIEWHEIGHT = grow, now in both axes),
 * a scene smaller than it magnifies to fill, and the canvas always fills
 * #game-root, so the page never scrolls (style.css STAGE block).
 */
function syncLocationViewHeight({ keepFraming = false } = {}) {
  viewSceneLayer = bgLayer;
  const before = { viewW: VIEW_W, camX: camTarget };
  const stage = measureStage();
  setZoomFixed(streetZoomFixed());
  const root = document.getElementById('game-root');
  if (root && !stage.pinned) {
    // Only a view held under the window's height (a portrait phone) leaves a band above the canvas.
    const band = root.clientHeight - stage.cssHeight;
    if (band >= 1) {
      root.style.setProperty('--stage-h', `${stage.cssHeight.toFixed(2)}px`);
      root.style.setProperty('--stage-gap', `${band.toFixed(2)}px`);
    } else {
      root.style.removeProperty('--stage-h');
      root.style.removeProperty('--stage-gap');
    }
  }
  STAGE_SCALE = stage.scale;
  const next = stage.viewH;
  if (next === LOCATION_VIEW_H && stage.viewW === VIEW_W) return false;
  const grew = next - LOCATION_VIEW_H;
  LOCATION_VIEW_H = next;
  VIEW_H = next + PACK_VIEW_RESERVE;
  VIEW_W = stage.viewW;
  if (app?.renderer) {
    // A scene can change the scale without the canvas changing size: keep the density with it.
    const resolution = renderResolution(stage.cssWidth, VIEW_W, window.devicePixelRatio || 1);
    app.renderer.resize(VIEW_W, VIEW_H, resolution);
    app.canvas.dataset.renderResolution = String(resolution);
    app.canvas.dataset.locationViewportHeight = String(LOCATION_VIEW_H);
    app.canvas.dataset.viewWidth = String(VIEW_W);
    app.canvas.dataset.stageScale = STAGE_SCALE.toFixed(3);
  }
  // CameraMan scales y_cam_offset with loc_vp_h: the avatar keeps its share of the view.
  if (world && Number.isFinite(camY)) {
    const anchor = streetCameraAnchor();
    camY = clamp(camY - grew * anchor, 0, Math.max(0, activeCameraWorldHeight(anchor) - LOCATION_VIEW_H));
    world.y = -Math.round(camY * 2) / 2;
  }
  if (world && player && Number.isFinite(WORLD_W)) {
    if (keepFraming && Number.isFinite(before.camX) && before.viewW > 0 && VIEW_W < WORLD_W) {
      // ZOOM: the avatar keeps its place across the window, so the view grows or shrinks around
      // it; the eased camera then glides to its new target (js/camera-feel.js), never a jump.
      const share = (player.x - before.camX) / before.viewW;
      camTarget = clamp(player.x - share * VIEW_W, 0, WORLD_W - VIEW_W);
      cameraRest.x = { rest: false, dir: cameraRest.x.dir };
      cameraRest.y = { rest: false, dir: cameraRest.y.dir };
      world.x = -camTarget;
    } else {
      camTarget = cameraTargetForPlayer(player.x, player.vx || 0);
      world.x = -Math.round(camTarget * 2) / 2;
    }
  }
  return true;
}

/** ZOOM: a resize this file sends after a zoom change, so the camera keeps the framing it chose. */
let zoomRelaying = false;

/**
 * ZOOM (js/world-zoom.js): the player moved the zoom. The stage resizes live (renderer density
 * with it, so art redraws at the new scale), the camera keeps the avatar where it was on screen,
 * and the usual resize listeners (pack pagers, overlays, Classic's frame) measure again.
 */
function applyWorldZoom() {
  syncCameraSafeArea();
  syncLocationViewHeight({ keepFraming: true });
  syncRenderResolution();
  if (app?.canvas) app.canvas.dataset.worldZoom = String(worldZoom());
  try {
    zoomRelaying = true;
    window.dispatchEvent(new Event('resize'));
  } finally {
    zoomRelaying = false;
  }
}

/**
 * G582: the part of the world's right edge the HUD covers, in Pixi view coordinates. The original
 * client reserved its right-hand column's width when calculating its location viewport (loc_vp_w),
 * so the camera stopped with a street's end left of it. Modern: the Social drawer (js/ui/social-drawer.js
 * insetNow, the same width --inset-r holds: its folded rail or the open drawer, plus their gaps; 0 when
 * hidden). Classic puts its chat column beside the world, so nothing covers it there (insetNow is 0);
 * the old #play-context rail still counts wherever a skin shows it over the world.
 */
function syncCameraSafeArea() {
  const root = document.getElementById('game-root');
  if (!root || root.clientWidth <= 0) {
    cameraRightInset = 0;
    return cameraRightInset;
  }
  const rootRect = root.getBoundingClientRect();
  const drawerCss = Math.max(0, Number(socialDrawer?.inset()?.right) || 0);
  const rail = document.getElementById('play-context');
  const railCss = rail && rail.offsetParent !== null ? Math.max(0, rootRect.right - rail.getBoundingClientRect().left) : 0;
  const overlapCss = Math.max(drawerCss, railCss);
  cameraRightInset = overlapCss > 0
    ? clamp(overlapCss * (VIEW_W / rootRect.width) + CAMERA_RAIL_CLEARANCE, 0, VIEW_W * 0.42)
    : 0;
  drawerInsetSeen = root.style.getPropertyValue('--inset-r');
  return cameraRightInset;
}

/** G582: Pixi px kept between the covered edge and the street's end (the drawer's inset already holds its gaps). */
const CAMERA_RAIL_CLEARANCE = 6;
/** G582: how far the ground skirt runs past a street's right end (street-render buildGroundSkirt rightPad). */
const SKIRT_RIGHT_PAD = 900;
/** G582: the --inset-r the camera last measured (the drawer writes it as it opens, folds or hides). */
let drawerInsetSeen = '';

/** Once a frame: the drawer opened, folded or hid, so measure the camera's reserve again (it glides there). */
function followDrawerInset() {
  const root = document.getElementById('game-root');
  if (root && root.style.getPropertyValue('--inset-r') !== drawerInsetSeen) syncCameraSafeArea();
}

function cameraTargetForPlayer(playerX, velocityX = 0) {
  // A scene narrower than the view (only where the 408 px floor holds the scale) sits centred.
  const spare = VIEW_W - WORLD_W;
  if (spare > 0) return -Math.round(spare / 2);
  return cameraTargetX(playerX, velocityX, WORLD_W, VIEW_W, 4.4, cameraRightInset);
}

function horizontalLocationViewWidth() {
  return cameraLocationViewWidth(VIEW_W, cameraRightInset);
}

function deepestWalkableGroundY() {
  const platforms = Array.isArray(streetPlatforms) ? streetPlatforms : [];
  return platforms.reduce(
    (deepest, platform) => Math.max(
      deepest,
      Number(platform?.y1) || 0,
      Number(platform?.y2) || 0
    ),
    Number(GROUND_Y) || 0
  );
}

/** The street's own y_cam_offset (G*.xml physics; default 150) as a viewport anchor. */
function streetCameraAnchor() {
  const offset = Number(currentStreet?.physics?.setting?.y_cam_offset);
  return yCamOffsetAnchor(Number.isFinite(offset) ? offset : 150, LOCATION_VIEW_H);
}

function activeCameraWorldHeight(anchorRatio = 0.75) {
  return cameraWorldHeightForGround(
    bgLayer?.worldH || VIEW_H,
    deepestWalkableGroundY(),
    LOCATION_VIEW_H,
    anchorRatio
  );
}

/**
 * Keep a world-space overlay wholly inside the same rail-safe viewport used by
 * the camera. Width is expressed in Pixi coordinates.
 */
function clampWorldOverlayX(worldX, width = 0, padding = 12) {
  const cameraX = Number.isFinite(camTarget) ? camTarget : 0;
  const requestedX = Number(worldX);
  const resolvedX = Number.isFinite(requestedX) ? requestedX : cameraX;
  return cameraX + cameraOverlayCenterX(
    resolvedX - cameraX,
    width,
    VIEW_W,
    cameraRightInset,
    padding
  );
}
