function fourLetterIsInstanced() {
  return Boolean(fourLetterState && currentStreetTsid === FOUR_LETTER_ROOM_ID);
}

function fourLetterTexture(letter) {
  return textures[`letterBlock${letter}`]?.frames?.[0] || PIXI.Texture.WHITE;
}

function drawPlayroomBackground() {
  // The Kid's Room, dressed from the CC0 k04 decos the players' Snaps show (js/kids-room-scene.js).
  return buildKidsRoomScene(PIXI, { label: 'four-letter-playroom' });
}

function renderFourLetterHud(spinningIndex = -1) {
  const hud = document.getElementById('four-letter-hud');
  const visible = fourLetterIsInstanced();
  if (hud) hud.hidden = !visible;
  if (!visible) return;

  const riddle = currentFourLetterRiddle(fourLetterState);
  const progress = hud.querySelector('[data-four-letter-progress]');
  const copy = hud.querySelector('[data-four-letter-riddle]');
  if (progress) {
    progress.textContent =
      fourLetterState.status === 'staging'
        ? 'Meet Mr. Block'
        : fourLetterState.status === 'solved'
        ? '3 of 3 solved'
        : `Riddle ${fourLetterState.riddleIndex + 1} of ${FOUR_LETTER_RIDDLES.length}`;
  }
  if (copy) {
    copy.textContent =
      fourLetterState.status === 'staging'
        ? fourLetterObjective(fourLetterState)
        : riddle?.text || fourLetterObjective(fourLetterState);
  }
  for (let i = 0; i < 4; i += 1) {
    const cell = hud.querySelector(`[data-four-letter-cell="${i}"]`);
    if (!cell) continue;
    cell.textContent = fourLetterState.letters[i];
    cell.classList.toggle('is-spinning', i === spinningIndex);
  }
  if (app?.canvas) {
    app.canvas.dataset.fourLetterStatus = fourLetterState.status;
    app.canvas.dataset.fourLetterRiddle = String(fourLetterState.riddleIndex + 1);
    app.canvas.dataset.fourLetterWord = fourLetterWord(fourLetterState);
    app.canvas.dataset.fourLetterSolved = fourLetterState.solvedWords.join(',');
    app.canvas.dataset.fourLetterObjective = fourLetterObjective(fourLetterState);
  }
}

function spawnFourLetterBlocks() {
  const xs = FOUR_LETTER_LAYOUT.blockXs;
  fourLetterTargets = FOUR_LETTER_BLOCKS.map((block, index) => {
    const letter = fourLetterState.letters[index];
    const spr = new PIXI.Sprite(fourLetterTexture(letter));
    spr.name = block.id;
    spr.anchor.set(0.5, 1);
    spr.scale.set(0.74);
    spr.x = xs[index];
    spr.y = 620;
    spr.zIndex = 45;
    entityLayer.addChild(spr);
    // letter_block_2.js 74-98 createItemStackWithPoof: proto_puff poof_in (G285).
    playPoofIn(PIXI, { layer: fxLayer || entityLayer, x: spr.x, bottom: spr.y, itemH: Math.round(197 * 0.74) });
    return register({
      classId: 'letter_block',
      label: `Letter Block ${index + 1}`,
      subtitle: `Shows ${letter} · spins through ${block.letters.join(', ')}`,
      sprite: spr,
      state: {
        puzzleState: fourLetterState,
        blockIndex: index,
        letters: [...block.letters],
      },
    });
  });
  return fourLetterTargets;
}

function spawnFourLetterMrBlock() {
  const spr = new PIXI.Sprite(textures.mrBlock?.frames?.[0] || PIXI.Texture.WHITE);
  spr.label = 'mr-block';
  spr.anchor.set(0.5, 1);
  spr.scale.set(1.15);
  spr.x = FOUR_LETTER_LAYOUT.mrBlock.x;
  spr.y = FOUR_LETTER_LAYOUT.mrBlock.y;
  spr.zIndex = 44;
  entityLayer.addChild(spr);
  fourLetterMrBlock = register({
    classId: 'npc_letterblock',
    label: 'Mr. Block',
    subtitle: 'A block with a letter on it.', // G318: items/npc_letterblock.js 8
    sprite: spr,
    state: { puzzleState: fourLetterState },
  });
  return fourLetterMrBlock;
}

function openCurrentFourLetterRiddle() {
  const riddle = currentFourLetterRiddle(fourLetterState);
  if (!riddle) return;
  openScriptedQuestDialogue({
    title: 'Mr. Block',
    kicker: `Riddle ${fourLetterState.riddleIndex + 1} of ${FOUR_LETTER_RIDDLES.length}`,
    beats: [{ text: riddle.text, response: 'Hm…' }],
  });
}

function confirmLeaveFourLetterQuest() {
  if (!fourLetterIsInstanced()) return;
  openScriptedQuestDialogue({
    title: 'Mr. Block',
    kicker: 'Leaving so soon?',
    cancelable: true,
    beats: [
      {
        text: 'Oh, are you not having fun here? You can come back and try the riddles again later.',
        response: 'Leave the playroom',
      },
    ],
    onComplete: () => leaveFourLetterQuest({ abandon: true }),
  });
}

function finishFourLetterQuest() {
  if (!fourLetterState || fourLetterState.status !== 'solved') return;
  const updates = applyQuestProgress(questState, 'riddles_solved', 1, pc);
  announceQuestCompletions(
    updates.map((update) =>
      (update.classTsid || update.def?.classTsid) === FOUR_LETTER_QUEST_ID
        ? { ...update, onDismiss: () => leaveFourLetterQuest({ abandon: false }) }
        : update
    )
  );
  pushActivity('Mr. Block is going to be staring at those blocks for days.');
  savePlayerState();
  updateHud();
}

function handleFourLetterTarget(target, verbId) {
  if (!fourLetterIsInstanced() || !target) return;
  if (target.classId === 'npc_letterblock') {
    if (verbId === 'leave') confirmLeaveFourLetterQuest();
    else openCurrentFourLetterRiddle();
    return;
  }
  if (target.classId !== 'letter_block' || verbId !== 'spin') return;

  const index = Number(target.state?.blockIndex);
  const result = spinFourLetterBlock(fourLetterState, index);
  if (!result.ok) {
    toast(result.reason === 'not_running' ? 'Talk to Mr. Block first.' : 'That block will not turn.');
    return;
  }
  target.sprite.texture = fourLetterTexture(result.letter);
  target.sprite._fourLetterSpin = { startedAt: Date.now(), durationMs: 520 };
  target.subtitle = `Shows ${result.letter} · spins through ${target.state.letters.join(', ')}`;
  renderFourLetterHud(index);
  playSfx('pickup', { volume: 0.32, rate: 0.72 + index * 0.08 });
  burst(target.sprite.x, target.sprite.y - 60, 0xffd86b, 7);
  if (!result.solved) return;

  floatText(target.sprite.x, target.sprite.y - 118, `${result.word}!`, 0xffe066);
  pushActivity(`Riddle ${fourLetterState.riddleIndex} solved: ${result.word}.`);
  if (!result.complete) {
    applyQuestProgress(questState, 'riddles_solved', 1, pc);
    updateHud();
    const dialogue = FOUR_LETTER_NEXT_DIALOGUE[fourLetterState.riddleIndex - 1];
    openScriptedQuestDialogue({
      title: 'Mr. Block',
      kicker: `${result.word}!`,
      beats: dialogue,
    });
    return;
  }

  openScriptedQuestDialogue({
    title: 'Mr. Block',
    kicker: 'BEAT!',
    beats: FOUR_LETTER_FINAL_DIALOGUE,
    onComplete: finishFourLetterQuest,
  });
}

async function startFourLetterQuest(opts = {}) {
  if (fourLetterStartPromise) return fourLetterStartPromise;
  if (fourLetterIsInstanced()) return fourLetterState;
  fourLetterStartPromise = (async () => {
    if (!questState.active[FOUR_LETTER_QUEST_ID]) {
      const assigned = assignQuest(questState, FOUR_LETTER_QUEST_ID, { ignorePrereq: true });
      if (!assigned.ok) return null;
    }
    fourLetterSourceLocation = opts.sourceLocation || instanceSourceHere({
      tsid: currentStreetTsid,
      x: player?.x ?? WORLD_W * 0.5,
      y: player?.y ?? GROUND_Y,
    });
    fourLetterState = createFourLetterState();
    fourLetterPlayerBaseScale = player?.baseScale ?? null;
    savePlayerLocation(fourLetterSourceLocation);

    await enterStreet(FOUR_LETTER_BASE_STREET_ID, { quiet: true });
    clearWorldEntities();
    if (bgLayer && world) {
      world.removeChild(bgLayer);
      bgLayer.destroy({ children: true });
    }
    bgLayer = drawPlayroomBackground();
    world.addChildAt(bgLayer, 0);
    currentStreet = {
      tsid: FOUR_LETTER_ROOM_ID,
      label: "Mr. Block's Playroom",
      hubName: '', // G363: the kids_room instance (letter_block_1.js 107): no hub line (location.js 3311)
      bounds: { l: 0, r: KIDS_ROOM_W, t: 0, b: 760 },
      platforms: bgLayer.platformsScreen,
      signposts: [],
    };
    currentStreetTsid = FOUR_LETTER_ROOM_ID;
    WORLD_W = KIDS_ROOM_W;
    GROUND_Y = 620;
    streetPlatforms = bgLayer.platformsScreen;
    streetWalls = [];
    climb = { active: false, wall: null };
    spawnFourLetterBlocks();
    playSound('PROTO_PUFF', { volume: 0.5 });
    spawnFourLetterMrBlock();

    if (player) {
      player.baseScale = (fourLetterPlayerBaseScale || player.baseScale) * 0.42;
      player.x = FOUR_LETTER_LAYOUT.spawnX;
      player.y = GROUND_Y;
      player.vx = 0;
      player.vy = 0;
      player.onGround = true;
      applyPlayerFacing();
    }
    camTarget = cameraTargetForPlayer(player.x);
    camY = cameraTargetY(player.y, activeCameraWorldHeight(), LOCATION_VIEW_H);
    world.x = -Math.round(camTarget);
    world.y = -Math.round(camY);
    const nameEl = document.getElementById('street-name');
    if (nameEl) {
      nameEl.textContent = "Mr. Block's Playroom";
      nameEl.dataset.tsid = FOUR_LETTER_ROOM_ID;
    }
    savePlayerLocation(fourLetterSourceLocation);
    renderFourLetterHud();
    updateHud();
    pushActivity('You shrink down and arrive in Mr. Block’s Playroom.');
    toast('Everything suddenly looks enormous.', 3200);
    openScriptedQuestDialogue({
      title: 'Mr. Block',
      kicker: 'Four Letter Words',
      beats: FOUR_LETTER_INTRO,
      onComplete: () => {
        startFourLetterPuzzle(fourLetterState);
        renderFourLetterHud();
        if (app?.canvas) app.canvas.dataset.fourLetterStatus = fourLetterState.status;
      },
    });
    return fourLetterState;
  })();
  try {
    return await fourLetterStartPromise;
  } finally {
    fourLetterStartPromise = null;
  }
}

async function leaveFourLetterQuest({ abandon = false } = {}) {
  if (!fourLetterState || !fourLetterSourceLocation?.tsid) return false;
  const destination = { ...fourLetterSourceLocation };
  if (abandon) {
    delete questState.active[FOUR_LETTER_QUEST_ID];
    pushActivity('You left Mr. Block’s riddles for another time.');
  }
  if (fourLetterPlayerBaseScale && player) {
    player.baseScale = fourLetterPlayerBaseScale;
    applyPlayerFacing();
  }
  fourLetterState = null;
  fourLetterSourceLocation = null;
  fourLetterPlayerBaseScale = null;
  fourLetterTargets = [];
  fourLetterMrBlock = null;
  legalizeTargets = [];
  document.getElementById('four-letter-hud').hidden = true;
  closeQuestDialogue({ force: true });
  await enterStreetWithTransition(destination.tsid, {
    spawnX: destination.x,
    spawnY: destination.y,
    quiet: true,
  });
  if (app?.canvas) app.canvas.dataset.fourLetterStatus = abandon ? 'abandoned' : 'completed';
  savePlayerState();
  savePlayerLocation(destination);
  updateHud();
  return true;
}

function updateFourLetterQuest() {
  if (!fourLetterIsInstanced()) return;
  const now = Date.now();
  for (const target of fourLetterTargets) {
    const spin = target.sprite?._fourLetterSpin;
    if (!spin) continue;
    const progress = clamp((now - spin.startedAt) / spin.durationMs, 0, 1);
    const bounce = Math.sin(progress * Math.PI);
    target.sprite.rotation = Math.sin(progress * Math.PI * 2) * 0.075;
    target.sprite.scale.set(0.74 + bounce * 0.08, 0.74 - bounce * 0.05);
    if (progress >= 1) {
      target.sprite.rotation = 0;
      target.sprite.scale.set(0.74);
      delete target.sprite._fourLetterSpin;
      renderFourLetterHud();
    }
  }

  if (new URLSearchParams(location.search).get('letterautoplay') !== '1') return;
  if (now < (fourLetterState._autoNextAt || 0)) return;
  fourLetterState._autoNextAt = now + 260;
  if (isQuestDialogueOpen()) {
    advanceQuestDialogue();
    return;
  }
  if (fourLetterState.status !== 'running') return;
  const answer = currentFourLetterRiddle(fourLetterState)?.answer;
  if (!answer) return;
  const index = fourLetterState.letters.findIndex((letter, i) => letter !== answer[i]);
  if (index >= 0) handleFourLetterTarget(fourLetterTargets[index], 'spin');
}

const LEGALIZE_ASSET_ROOT = 'assets/sprites/quests/legalize';
const LEGALIZE_BUREAUCRAT_ART = [
  'npc_bureaucrat_arms_01_glasses_none_hair_01_legs_01_necklace_none_tie_01_torso_01_x1_iconic_png_1354832989.webp',
  'npc_bureaucrat_arms_02_glasses_none_hair_02_legs_02_necklace_none_tie_02_torso_02_x1_iconic_png_1354832997.webp',
  'npc_bureaucrat_arms_03_glasses_none_hair_04_legs_03_necklace_01_tie_none_torso_03_x1_iconic_png_1354833006.webp',
  'npc_bureaucrat_arms_04_glasses_none_hair_05_legs_04_necklace_02_tie_none_torso_04_x1_iconic_png_1354833015.webp',
];

/**
 * Legalize It runs on the real places (card_carrying_qualification.js,
 * subway_gate.js, npc_bureaucrat.js, location.js): Gregarious Grange's own
 * subway station (features/subway-feature.js, Tiny Speck's subway1.swf), the
 * imported Gregarious Grange street (GLI32G3NUTD100I) with its hall door,
 * and the two places only the quest opens, The Back Alley instance (the one
 * set, js/quest-rooms/back-alley-set.js) and the Bureaucratic Hall.
 */
const LEGALIZE_STATION = surfaceStation(LEGALIZE_GRANGE_TSID);
const LEGALIZE_STATION_STREET = LEGALIZE_STATION.streetTsid;
const LEGALIZE_GRANGE_STREET = LEGALIZE_STATION.surfaceStreetTsid;
/** The street's hall door (location XML; features/bureaucratic-halls-feature.js HALL_DOORS) and the station's stairs (js/subway.js stationStreet). */
const LEGALIZE_HALL_DOOR = 'door_1300484753304';
const LEGALIZE_STAIRS_DOOR = 'door_subway_stairs';
/** Down the stairs from the street (its subway door door_1300233269757 connects at x -575). */
const LEGALIZE_STATION_ARRIVAL = stationArrival(-575);
/** In front of A Red Button, where the refusal found you: instances_exit puts you back there. */
const LEGALIZE_GATE_SPOT = stationScreen(STATION_X.gate - 70);
/** Up the stairs: in front of the street's subway entrance (the stairs door's connect arrive). */
const LEGALIZE_GRANGE_ARRIVAL = Object.freeze({ x: 3430, y: 910 });
/**
 * The way out when an application has none recorded: Gregarious Grange
 * Subway Station in front of A Red Button, the door into The Back Alley
 * (subway_gate.js 158), where instances_exit returns whoever came in by it.
 */
const LEGALIZE_EXIT_FALLBACK = Object.freeze({ tsid: LEGALIZE_STATION_STREET, x: LEGALIZE_GATE_SPOT.x, y: LEGALIZE_GATE_SPOT.y });
/** npc_bureaucrat.js 784: the halls the Bureaucrat marks on your map (prod), as streets. */
const LEGALIZE_HALL_STREETS = Object.freeze(['GLI32G3NUTD100I', 'GA91JUQT2G82GUL', 'GA5I10NJDL52TKD']);

/** The two places only the quest opens: The Back Alley instance and its Bureaucratic Hall. */
function legalizeIsInstanced() {
  return Boolean(legalizeRun && [LEGALIZE_BACK_ALLEY_TSID, LEGALIZE_HALL_TSID].includes(currentStreetTsid));
}

/** The application under way, also after a reload or a walk away and back. */
function legalizeRouteState() {
  if (legalizeRun) return legalizeRun;
  if (!questState.active?.[LEGALIZE_QUEST_ID] || !questState.story?.legalize) return null;
  legalizeRun = ensureLegalizeState(questState);
  // An application with no way back (an older build made one from the pack) leads out by the station.
  legalizeSourceLocation = ensureLegalizeWayBack(legalizeRun, LEGALIZE_EXIT_FALLBACK);
  return legalizeRun;
}

/** Where leaving The Back Alley or the quest's hall takes you, never null (js/legalize-it.js legalizeWayBack). */
function legalizeWayOut() {
  return legalizeWayBack(
    { sourceLocation: legalizeSourceLocation || legalizeRun?.sourceLocation || null },
    LEGALIZE_EXIT_FALLBACK
  );
}

/** On one of the route's places (the station, the street, the alley, the hall). */
function legalizeOnRoute() {
  return Boolean(
    legalizeRouteState() &&
      [LEGALIZE_STATION_STREET, LEGALIZE_GRANGE_STREET, LEGALIZE_BACK_ALLEY_TSID, LEGALIZE_HALL_TSID].includes(currentStreetTsid)
  );
}

/**
 * The real door that carries a step, as the target content.js knows: the
 * station's stairs once you are back from the alley (Exit) and the street's
 * hall door on the way to the application (Enter). null otherwise.
 */
function legalizeRealTarget(target) {
  if (target?.classId !== 'street_door' || !legalizeOnRoute()) return null;
  const id = target.door?.id;
  const stage = legalizeRun.stage;
  const as = (classId, routeAction) => ({
    classId,
    label: target.label,
    subtitle: target.subtitle,
    sprite: target.sprite,
    state: { legalizeState: legalizeRun, routeAction },
  });
  if (currentStreetTsid === LEGALIZE_STATION_STREET && id === LEGALIZE_STAIRS_DOOR && stage === 'gregarious_arrival') {
    return as('legalize_transit_gate', 'exit_gregarious_station');
  }
  if (
    currentStreetTsid === LEGALIZE_GRANGE_STREET && id === LEGALIZE_HALL_DOOR &&
    ['grange_exterior', 'hall_waiting', 'hall_called', 'hall_processing'].includes(stage)
  ) {
    return as('legalize_hall_entrance', 'enter_hall');
  }
  return null;
}

/**
 * subway_gate.js onConversation 'ok' after the papers refusal (the subway
 * feature's Red Button): on the quest's first step it is the way into The
 * Back Alley, as the quest's onStarted instance was. True when it went.
 */
function legalizeGateRefused() {
  if (!legalizeOnRoute()) return offerLegalizeAtGate();
  if (currentStreetTsid !== LEGALIZE_STATION_STREET) return false;
  if (legalizeRun.stage !== 'gregarious_departure') return false;
  handleLegalizeTarget({ classId: 'legalize_transit_gate', state: { legalizeState: legalizeRun, routeAction: 'depart_back_alley' } }, 'travel');
  return true;
}

/**
 * subway_gate.js 150-161: a gate that turns away a player with no Card-Carrying Qualification (no
 * badge, none in the pack) offers Legalize It there, and from then on it waits in the quest log.
 */
function offerLegalizeAtGate() {
  if (questState.active?.[LEGALIZE_QUEST_ID] || questState.completed.includes(LEGALIZE_QUEST_ID)) return false;
  if (achieveState.unlocked.includes(LEGALIZE_QUEST_ID) || countItem(inv, LEGALIZE_QUEST_ID) > 0) return false;
  questState.story ||= {};
  questState.story.gates = { ...(questState.story.gates || {}), legalize: true };
  savePlayerState();
  return openQuestDialogue(LEGALIZE_QUEST_ID, { kicker: 'A Red Button' });
}

function legalizeStageProgress(state = legalizeRun) {
  if (!state) return 0;
  if (['gregarious_departure', 'back_alley'].includes(state.stage)) return 1;
  if (['back_alley_briefed', 'back_alley_station'].includes(state.stage)) return 2;
  if (['gregarious_arrival', 'grange_exterior'].includes(state.stage)) return 3;
  if (['hall_waiting', 'hall_called'].includes(state.stage)) return 4;
  return 5;
}

function renderLegalizeHud() {
  const hud = document.getElementById('legalize-hud');
  const visible = legalizeOnRoute();
  if (hud) hud.hidden = !visible;
  if (!visible) return;
  const progress = legalizeStageProgress();
  const stage = hud.querySelector('[data-legalize-stage]');
  const count = hud.querySelector('[data-legalize-progress]');
  const objective = hud.querySelector('[data-legalize-objective]');
  if (stage) {
    const labels = {
      gregarious_departure: 'Gregarious Grange Subway Station',
      back_alley: 'The Back Alley',
      back_alley_briefed: 'The Back Alley',
      back_alley_station: 'The Back Alley Subway Station',
      gregarious_arrival: 'Gregarious Grange Subway Station',
      grange_exterior: 'Gregarious Grange',
      hall_waiting: 'Bureaucratic Hall · waiting area',
      hall_called: `Bureaucratic Hall · ${LEGALIZE_CLERKS[legalizeRun.clerkIndex].name}`,
      hall_processing: `Bureaucratic Hall · ${LEGALIZE_CLERKS[legalizeRun.clerkIndex].name}`,
      card_owned: 'Qualification received',
      complete: 'Qualification activated',
    };
    stage.textContent = labels[legalizeRun.stage] || 'Legalize It';
  }
  if (count) count.textContent = `${progress} / 5`;
  if (objective) objective.textContent = legalizeObjective(legalizeRun);
  const dots = ['alley', 'subway', 'hall', 'waiting', 'activate'];
  dots.forEach((name, index) => {
    hud.querySelector(`[data-legalize-dot="${name}"]`)?.classList.toggle(
      'is-done',
      index < progress
    );
  });
  if (app?.canvas) {
    app.canvas.dataset.legalizeStage = legalizeRun.stage;
    app.canvas.dataset.legalizeHandoffs = String(legalizeRun.handoffs);
    app.canvas.dataset.legalizeClerk = String(legalizeRun.clerkIndex);
    app.canvas.dataset.legalizeObjective = legalizeObjective(legalizeRun);
    app.canvas.dataset.legalizeCardOwned = legalizeRun.cardOwned ? '1' : '0';
    app.canvas.dataset.legalizeActivated = legalizeRun.activated ? '1' : '0';
    app.canvas.dataset.legalizeRoute =
      'gregarious-subway>back-alley>gregarious-subway>gregarious-grange>bureaucratic-hall';
    app.canvas.dataset.legalizeBackAlleyBriefed =
      ['back_alley_briefed', 'back_alley_station', 'gregarious_arrival', 'grange_exterior',
        'hall_waiting', 'hall_called', 'hall_processing', 'card_owned', 'complete']
        .includes(legalizeRun.stage)
        ? '1'
        : '0';
    app.canvas.dataset.legalizeArt = 'subway1-station>back-alley-set>gregarious-grange-street>bhall';
    app.canvas.dataset.legalizePlace = currentStreetTsid || '';
    app.canvas.dataset.legalizeClerkArt = 'recovered-animated-bureaucrats';
    app.canvas.dataset.legalizeQuestion = 'Beige|Other';
  }
}

function legalizeRoomBase(name, width = 1600, height = 760, groundY = 620) {
  const layer = new PIXI.Container();
  layer.name = name;
  layer.worldH = height;
  layer.platformsScreen = [
    { id: `${name}-floor`, x1: 0, y1: groundY, x2: width, y2: groundY, pc_perm: 1 },
  ];
  return layer;
}

/**
 * Tiny Speck's own Bureaucratic Hall (bldg_int_bhall.swf, glitch-locations,
 * CC0): the whole-room backdrop bureaucratic_hall_bg (desk room, the waiting
 * wall with its orange chairs, the counter opening), drawn 1:1 at its stage
 * size; js/bureaucratic-hall.js maps the source's x numbers onto it. The
 * chairs are painted into the backdrop: scenery, nothing to sit on (no chair
 * item or verb exists in the source). The hall's location XML is lost, so
 * where the signs hang is our reconstruction: the WAITING AREA plaque and
 * the waiting-room pictogram on the wall over the chairs, the PLEASE WAIT
 * stand at the waiting line (source x -220), the Department of
 * Administrative Affairs lettering on the counter's lintel, the TV and the
 * light where the remake's hall had them.
 */
function drawBureaucraticHall() {
  const layer = legalizeRoomBase('legalize-bureaucratic-hall', HALL.width, HALL.height, HALL.ground);
  layer.worldW = HALL.width;
  layer.groundY = HALL.ground;
  // The camera keeps the pack's allowance below the floor: the backdrop's dirt carries on down.
  const under = new PIXI.Graphics();
  under.rect(0, HALL.height - 2, HALL.width, 300).fill(0x5d5140);
  layer.addChild(under);
  // Decos ship at 2x (js/deco-hires.js): scale 0.5 is their stage size.
  const deco = (name, x, y, { ax = 0.5, ay = 0.5, scale = 0.5 } = {}) => {
    const spr = new PIXI.Sprite(textureFromUrl(`assets/decos/groddle/${name}.png`));
    spr.anchor.set(ax, ay);
    spr.position.set(x, y);
    spr.scale.set(scale);
    layer.addChild(spr);
    return spr;
  };
  deco('bureaucratic_hall_bg', 0, 0, { ax: 0, ay: 0 });
  deco('bureaucratic_hall_waitingroom_1', 900, 336);
  deco('sign_waiting_area', 1012, 338);
  deco('bureaucratic_hall_sign_wait_1', HALL_LAYOUT.waitingLine, HALL.ground - 12, { ay: 1 });
  deco('bureaucratic_hall_sign_1', 1810, 196);
  deco('bureaucratic_hall_tv_1', 1330, 178, { scale: 0.72 });
  deco('bureaucratic_hall_light_1', 980, 74, { ay: 0, scale: 1.35 });
  layer.sortableChildren = true;
  return layer;
}

function installLegalizeScene(layer, { tsid, label, hubName, spawnX, spawnY = null }) {
  clearWorldEntities();
  if (bgLayer && world) {
    world.removeChild(bgLayer);
    bgLayer.destroy({ children: true });
  }
  bgLayer = layer;
  world.addChildAt(bgLayer, 0);
  currentStreet = {
    tsid,
    label,
    hubName,
    bounds: { l: 0, r: layer.worldW || 1600, t: 0, b: layer.worldH || 760 },
    platforms: layer.platformsScreen,
    signposts: [],
  };
  currentStreetTsid = tsid;
  WORLD_W = layer.worldW || 1600;
  GROUND_Y = layer.groundY || 620;
  streetPlatforms = layer.platformsScreen;
  streetWalls = [];
  climb = { active: false, wall: null };
  Object.assign(jumpState, createJumpState(movementNow()));
  if (player) {
    player.position.set(spawnX, spawnY ?? GROUND_Y);
    player.vx = 0;
    player.vy = 0;
    player.onGround = true;
    applyPlayerFacing();
  }
  camTarget = cameraTargetForPlayer(player?.x || spawnX);
  camY = cameraTargetY(
    player?.y || GROUND_Y,
    activeCameraWorldHeight(),
    LOCATION_VIEW_H
  );
  world.x = -Math.round(camTarget);
  world.y = -Math.round(camY);
  const nameEl = document.getElementById('street-name');
  if (nameEl) {
    nameEl.textContent = hubName ? `${label} · ${hubName}` : label;
    nameEl.dataset.tsid = tsid;
  }
  // A reload resumes at the way out, never inside (a null here threw and left the alley empty).
  savePlayerLocation(legalizeWayOut());
}

function makeLegalizeBureaucrat(index, x, y, scale = 0.86) {
  const idle = textures[`bureaucrat${index}Idle`]?.frames;
  const talk = textures[`bureaucrat${index}Talk`]?.frames;
  const fallback = textureFromUrl(`${LEGALIZE_ASSET_ROOT}/${LEGALIZE_BUREAUCRAT_ART[index]}`);
  const spr = new PIXI.AnimatedSprite(idle?.length ? idle : [fallback]);
  spr.texturesIdle = idle?.length ? idle : [fallback];
  spr.texturesTalk = talk?.length ? talk : spr.texturesIdle;
  spr.texturesWalk1 = textures[`bureaucrat${index}Walk1`]?.frames?.length ? textures[`bureaucrat${index}Walk1`].frames : spr.texturesIdle;
  spr.texturesWalk2 = textures[`bureaucrat${index}Walk2`]?.frames?.length ? textures[`bureaucrat${index}Walk2`].frames : spr.texturesWalk1;
  spr.anchor.set(0.5, 1);
  spr.position.set(x, y);
  spr.scale.set(scale);
  // The sheets are the SWF's 30 fps frames (sprite-sheets.js pixiSpeed); slower, the idle's blink came every 8 s.
  spr.animationSpeed = 0.5;
  spr.loop = true;
  spr.autoUpdate = true;
  spr.play();
  spr.zIndex = 40;
  return spr;
}

function setLegalizeBureaucratAnimation(target, mode = 'idle', durationMs = 0) {
  const spr = target?.sprite;
  if (!(spr instanceof PIXI.AnimatedSprite)) return;
  spr.textures = mode === 'talk' ? spr.texturesTalk : spr.texturesIdle;
  spr.animationSpeed = 0.5;
  spr.gotoAndPlay(0);
  spr._legalizeAnimation = mode;
  spr._legalizeAnimationUntil = durationMs ? Date.now() + durationMs : 0;
}

/** Into a real street of the route, with its loading card, standing at `spot` (screen space). */
async function legalizeEnterStreet(tsid, spot) {
  legalizeTargets = [];
  legalizeTransitionBusy = true;
  try {
    await enterStreetWithTransition(tsid, { spawnX: spot.x, spawnY: spot.y });
  } finally {
    legalizeTransitionBusy = false;
  }
  renderLegalizeHud();
}

/** The quest's own place: the loading card (the client's "Entering ..."), then the scene. */
async function legalizeSceneTransition(label, setup) {
  const el = document.getElementById('screen-transition');
  if (!el || new URLSearchParams(location.search).get('legalizefx') === '0') {
    setup();
    return;
  }
  await runStreetTransition(el, {
    fromLabel: currentStreet?.label || '',
    fromHub: currentStreet?.hubName || '',
    toLabel: label,
    toHub: '',
    topColor: 0x26302a,
    bottomColor: 0x121714,
    onMid: async () => setup(),
  });
}

/** Gregarious Grange Subway Station, the real one, down its stairs (the quest's first step: its Red Button). */
function spawnLegalizeDepartureStation() {
  return legalizeEnterStreet(LEGALIZE_STATION_STREET, LEGALIZE_STATION_ARRIVAL);
}

/**
 * The Back Alley (LIF177DTS6T1KFG, the instance onStarted copies): the one
 * set We're Off to See the Lizard uses too, its Shady Bureaucrat where that
 * room has him, and you arriving where that room puts you.
 */
function spawnLegalizeBackAlley() {
  const layer = drawAlley(PIXI);
  layer.name = 'legalize-back-alley';
  layer.groundY = ALLEY.FLOOR;
  layer.platformsScreen = [{ id: 'ba_floor', x1: 0, y1: ALLEY.FLOOR, x2: ALLEY.W, y2: ALLEY.FLOOR, pc_perm: 1 }];
  installLegalizeScene(layer, {
    tsid: LEGALIZE_BACK_ALLEY_TSID,
    label: 'The Back Alley',
    hubName: '', // G363: the back_alley instance (card_carrying_qualification.js 88): no hub line (location.js 3311)
    spawnX: ALLEY.spawnX,
  });
  legalizeTargets = [];
  const shady = makeLegalizeBureaucrat(0, SHADY.x, SHADY.y, SHADY.scale);
  shady.zIndex = 43;
  entityLayer.addChild(shady);
  legalizeTargets.push(register({
    classId: 'npc_back_alley_bureaucrat',
    label: 'Shady Bureaucrat',
    subtitle:
      legalizeRun.stage === 'back_alley'
        ? // G318: his own opener in the back alley (npc_bureaucrat.js 897), not ours.
          "Psssst. Here'sss the deal."
        : 'The closest Hall is marked on your route.',
    sprite: shady,
    state: { legalizeState: legalizeRun },
  }));
  renderLegalizeHud();
}

/** Back from the alley: instances_exit returns you to the station, in front of the gate. */
function spawnLegalizeGregariousStation() {
  return legalizeEnterStreet(LEGALIZE_STATION_STREET, LEGALIZE_GATE_SPOT);
}

/** Up the stairs onto the imported Gregarious Grange, its Bureaucratic Hall along the street. */
function spawnLegalizeGregariousExterior() {
  return legalizeEnterStreet(LEGALIZE_GRANGE_STREET, LEGALIZE_GRANGE_ARRIVAL);
}

function spawnLegalizeHall() {
  installLegalizeScene(drawBureaucraticHall(), {
    tsid: LEGALIZE_HALL_TSID,
    label: 'Bureaucratic Hall',
    hubName: 'Gregarious Grange',
    spawnX: HALL_LAYOUT.arrival.x,
    spawnY: HALL_LAYOUT.arrival.y,
  });
  legalizeTargets = LEGALIZE_CLERKS.map((clerk, index) => {
    const spr = makeLegalizeBureaucrat(index, HALL_LAYOUT.clerkHomes[index], HALL_LAYOUT.clerkBackY, 1);
    spr.zIndex = 40;
    entityLayer.addChild(spr);
    // The hall's visit (features/bureaucratic-halls-feature.js) owns the bureaucrats' verbs.
    return register({
      classId: 'npc_bureaucrat',
      featureId: 'bureaucratic-halls',
      label: clerk.name,
      subtitle: index === legalizeRun.clerkIndex ? 'Handling your application' : 'Not your department',
      sprite: spr,
      state: { legalizeState: legalizeRun, clerkIndex: index },
    });
  });
  const counter = new PIXI.Sprite(textureFromUrl('assets/decos/groddle/bureaucratic_hall_counter_1.png'));
  counter.anchor.set(0, 1);
  // The same counter as every hall's (features/bureaucratic-halls-feature.js placeCounter).
  counter.position.set(HALL_LAYOUT.counterLeft, HALL.ground + 4);
  counter.width = 811;
  counter.height = 103;
  counter.zIndex = 44;
  counter.eventMode = 'none';
  entityLayer.addChild(counter);
  // Legalize It runs the hall's own visit, with the recorded session's choices.
  const done = ['card_owned', 'complete'].includes(legalizeRun.stage);
  features.query('bureaucraticHallFlow', engine, {
    targets: legalizeTargets.slice(),
    label: 'Bureaucratic Hall',
    script: legalizeHallScript(),
    start: done ? 'done' : null,
  });
  refreshLegalizeClerks();
  renderLegalizeHud();
}

/**
 * The recorded Legalize It session through the shared hall visit
 * (js/bureaucratic-hall.js): the first clerk is called with "Attention, Ur!
 * When you're ready?" (helping_ready 6), passes you on with
 * purchasing_step1 1 to the second, who asks purchasing_step2 1 and the
 * recorded "Your favorite color?" (Beige / Other), with no further transfer,
 * then purchasing_confirm 0 and the 50-currant fee. Each step moves the
 * quest's own state (js/legalize-it.js).
 */
const LEGALIZE_HALL_PICKS = Object.freeze({ helping_ready: 6, purchasing_step1: 1, purchasing_step2: 1, purchasing_confirm: 0 });
const LEGALIZE_HALL_QUESTION = HALL_QUESTIONS.findIndex((qn) => qn.options.join('|') === 'Beige|Other');

function legalizeHallScript() {
  const refresh = () => {
    refreshLegalizeClerks();
    renderLegalizeHud();
  };
  return {
    pick: (kind) => LEGALIZE_HALL_PICKS[kind] ?? null,
    question: () => LEGALIZE_HALL_QUESTION,
    handoff: () => false,
    helperFor: () => (legalizeRun ? legalizeRun.clerkIndex : null),
    onHelp: (index) => {
      if (!legalizeRun) return;
      // The clerk who comes over handles the application (the nearest free one, as in every hall).
      legalizeRun.clerkIndex = Math.max(0, Math.min(LEGALIZE_CLERKS.length - 1, index));
      const called = callLegalizeApplicant(legalizeRun);
      if (called.ok) pushActivity(`${called.clerk.name} calls you to the counter.`);
      refresh();
    },
    onTalk: () => {
      if (legalizeRun) beginLegalizeApplication(legalizeRun);
      refresh();
    },
    onItem: () => {
      if (legalizeRun) requestLegalizeQualification(legalizeRun);
      refresh();
    },
    onAnswer: (optionIndex) => {
      if (legalizeRun) answerLegalizeQuestion(legalizeRun, Math.min(1, optionIndex));
    },
    onPurchase: () => finishLegalizePurchase(),
    onEnd: (bought) => {
      if (bought || !legalizeRun || ['card_owned', 'complete'].includes(legalizeRun.stage)) return;
      // Nevermind: the application starts over. The quest's hall has no street door, so walking
      // back into the desk room is the "exit and re-enter" (a fresh visit greets you there).
      Object.assign(legalizeRun, { stage: 'hall_waiting', handoffs: 0, clerkIndex: 0 });
      setTimeout(() => {
        if (currentStreetTsid !== LEGALIZE_HALL_TSID || !legalizeRun) return;
        features.query('bureaucraticHallFlow', engine, { targets: legalizeTargets.slice(), label: 'Bureaucratic Hall', script: legalizeHallScript() });
        refresh();
      }, 1000);
      refresh();
    },
  };
}

function refreshLegalizeClerks() {
  for (const target of legalizeTargets) {
    if (target.classId !== 'npc_bureaucrat') continue;
    const index = Number(target.state?.clerkIndex);
    const current = index === Number(legalizeRun.clerkIndex);
    const called =
      current && ['hall_called', 'hall_processing', 'card_owned'].includes(legalizeRun.stage);
    target.subtitle = called
      ? 'Handling your application'
      : current
        ? 'Please wait to be called'
        : 'Not your department';
  }
  renderLegalizeHud();
}

/** The fee paid (the hall visit's Pay 50): the quest's purchase; 'ok' or 'broke' for the visit. */
function finishLegalizePurchase() {
  const result = purchaseQualification(legalizeRun, pc.currants, Date.now());
  if (!result.ok) {
    toast(`You need ${result.shortfall} more currants.`);
    return 'broke';
  }
  pc.currants -= result.cost;
  addItem(inv, LEGALIZE_CARD_ID, 1);
  applyQuestProgress(questState, 'acquired_card_carrying_qualification', 1, pc);
  playSfx('pickup', { volume: 0.55, rate: 0.88 });
  pushActivity(`You paid ${result.cost} currants and received a Card-Carrying Qualification.`);
  floatText(player.x, player.y - 90, 'Qualification acquired', 0xffe066);
  burst(player.x, player.y - 50, 0xffe066, 15);
  refreshLegalizeClerks();
  renderLegalizeHud();
  updateHud();
  // The visit then shows items/npc_bureaucrat.js showEndPrompt (js/bureaucratic-hall.js).
  return 'ok';
}

/** The Shady Bureaucrat's proposition (npc_bureaucrat.js propositionPlayer, no back_alley_business). */
function legalizeBriefing(target) {
  if (legalizeRun.stage !== 'back_alley') {
    // npc_bureaucrat.js 762-797: the proposition's OK (or cancel) always ends in instances_exit('back_alley').
    toast('The Bureaucratic Hall on Gregarious Grange is marked on your route.');
    legalizeExitAlley();
    return;
  }
  if (isQuestDialogueOpen()) return;
  setLegalizeBureaucratAnimation(target, 'talk', 13_000);
  openScriptedQuestDialogue({
    title: 'Shady Bureaucrat',
    kicker: 'The Back Alley',
    beats: LEGALIZE_BACK_ALLEY_BEATS,
    onComplete: () => {
      const result = completeBackAlleyBriefing(legalizeRun);
      if (!result.ok) return;
      setLegalizeBureaucratAnimation(target, 'idle');
      target.subtitle = 'The closest Hall is marked on your route.';
      // npc_bureaucrat.js 782-794: buildPath to the closest of the three halls from where you came in.
      features.query('mapRoute', 'set', { from: LEGALIZE_STATION_STREET, to: [...LEGALIZE_HALL_STREETS], source: LEGALIZE_QUEST_ID, quest: LEGALIZE_QUEST_ID }, engine);
      pushActivity('The Shady Bureaucrat marks the Bureaucratic Hall on your route.');
      renderLegalizeHud();
      // ... then instances_exit('back_alley'): back where you were.
      setTimeout(() => legalizeLeaveAlley(), 500);
    },
  });
}

/** One step's place change, then its activity line and hint. */
async function legalizeRunStep(spawn, activity, message) {
  legalizeTransitionBusy = true;
  try {
    await spawn();
  } finally {
    legalizeTransitionBusy = false;
  }
  if (activity) pushActivity(activity);
  if (message) toast(message, 4200);
  renderLegalizeHud();
}

/**
 * Out of the alley the source way, straight back to Gregarious Grange
 * Subway Station: the route's two subway steps (js/legalize-it.js) both run,
 * with no Back Alley station or train between (the source has neither).
 */
async function legalizeLeaveAlley() {
  if (!legalizeRun || legalizeRun.stage !== 'back_alley_briefed' || currentStreetTsid !== LEGALIZE_BACK_ALLEY_TSID) return;
  if (!enterBackAlleyStation(legalizeRun).ok || !travelToGregarious(legalizeRun).ok) return;
  await legalizeRunStep(
    spawnLegalizeGregariousStation,
    'You leave The Back Alley for Gregarious Grange Subway Station.',
    'Exit the station to reach the Bureaucratic Hall.'
  );
}

/**
 * instances_exit('back_alley') whatever the stage: after the briefing, on to
 * the station as the route goes; a finished application goes back where it
 * came from; anything else to the station in front of A Red Button.
 */
async function legalizeExitAlley() {
  if (currentStreetTsid !== LEGALIZE_BACK_ALLEY_TSID || legalizeTransitionBusy) return;
  if (legalizeRun?.stage === 'back_alley_briefed') return legalizeLeaveAlley();
  if (!legalizeRun || legalizeRun.stage === 'complete') return leaveLegalizeIt({ abandon: false });
  await legalizeRunStep(spawnLegalizeGregariousStation, 'You leave The Back Alley for Gregarious Grange Subway Station.', '');
}

function handleLegalizeTarget(target, verbId) {
  if (!legalizeOnRoute() || !target) return;
  if (target.classId === 'npc_back_alley_bureaucrat' && verbId === 'talk_to') {
    legalizeBriefing(target);
    return;
  }
  if (['legalize_transit_gate', 'legalize_hall_entrance'].includes(target.classId)) {
    const action = target.state?.routeAction;
    let result = { ok: false };
    let spawn = null;
    let activity = '';
    let message = '';
    if (action === 'depart_back_alley' && verbId === 'travel') {
      result = departForBackAlley(legalizeRun);
      spawn = () => legalizeSceneTransition('The Back Alley', spawnLegalizeBackAlley);
      activity = 'You are whisked away to The Back Alley.';
      message = 'Find the Shady Bureaucrat in the forest.';
    } else if (action === 'exit_gregarious_station' && verbId === 'exit') {
      result = exitToGregariousGrange(legalizeRun);
      spawn = spawnLegalizeGregariousExterior;
      activity = 'You step out onto Gregarious Grange.';
      message = 'The Bureaucratic Hall is along the street to the left.';
    } else if (action === 'enter_hall' && verbId === 'enter') {
      if (legalizeRun.stage === 'grange_exterior') {
        result = enterBureaucraticHall(legalizeRun);
      } else if (['hall_waiting', 'hall_called', 'hall_processing'].includes(legalizeRun.stage)) {
        // location.js 810-819: leaving the hall cleared the visit, so an application under way starts over.
        Object.assign(legalizeRun, { stage: 'hall_waiting', handoffs: 0, clerkIndex: 0 });
        result = { ok: true };
      }
      spawn = spawnLegalizeHall;
      activity = 'You enter the Bureaucratic Hall.';
      message = '';
    }
    if (!result.ok || !spawn) return;
    // In the hall a bureaucrat greets you (js/bureaucratic-hall.js), as in every hall.
    legalizeRunStep(spawn, activity, message);
  }
}

/**
 * The pack's Activate (js/legalize-it.js activateCardFromPack): a card from
 * any hall, player or auction, with or without Legalize It. Inside the quest's
 * two instanced places the completion takes you back where you came from;
 * anywhere else the application just ends where you stand.
 */
function activateLegalizeCard() {
  const inInstance = legalizeIsInstanced();
  const result = activateCardFromPack({ questState, inv, achieveState, pc, now: Date.now() });
  if (!result.ok) {
    toast(result.msg);
    return false;
  }
  const badge = result.badge;
  if (result.questCompleted && !inInstance) endLegalizeRunInPlace();
  if (badge.ok) {
    announceAchievementUpdates([
      {
        classTsid: LEGALIZE_CARD_ID,
        unlocked: true,
        rewards: badge.rewards,
        def: badge.def,
      },
    ]);
  }
  announceQuestCompletions(
    result.updates.map((update) =>
      inInstance && (update.classTsid || update.def?.classTsid) === LEGALIZE_QUEST_ID
        ? { ...update, onDismiss: () => leaveLegalizeIt({ abandon: false }) }
        : update
    )
  );
  playSfx('quest', { volume: 0.65, rate: 1.04 });
  pushActivity('You activated your Card-Carrying Qualification.');
  toast('Your qualification is now active.', 3600);
  renderLegalizeHud();
  updateHud();
  savePlayerState();
  return true;
}

/** The application finished away from The Back Alley and the quest's hall: no trip back, the run just ends (its map route goes with the quest). */
function endLegalizeRunInPlace() {
  legalizeRun = null;
  legalizeSourceLocation = null;
  if (app?.canvas) app.canvas.dataset.legalizeStatus = 'completed';
  renderLegalizeHud();
}

async function startLegalizeIt(opts = {}) {
  if (legalizeStartPromise) return legalizeStartPromise;
  if (legalizeOnRoute()) return legalizeRun;
  legalizeStartPromise = (async () => {
    if (!questState.active?.[LEGALIZE_QUEST_ID]) {
      const assigned = assignQuest(questState, LEGALIZE_QUEST_ID, { ignorePrereq: true });
      if (!assigned.ok) return null;
    }
    // quests/card_carrying_qualification.js onAccepted 65-74: the badge already earned completes it here.
    const accepted = legalizeOnAccepted({ questState, inv, achieveState, pc, now: Date.now() });
    if (accepted.completed) {
      endLegalizeRunInPlace();
      announceQuestCompletions(accepted.updates);
      updateHud();
      savePlayerState();
      return null;
    }
    legalizeSourceLocation = opts.sourceLocation || instanceSourceHere({
      tsid: currentStreetTsid,
      x: player?.x ?? WORLD_W * 0.5,
      y: player?.y ?? GROUND_Y,
    });
    // Started from inside the alley or the hall: their way back can't be themselves.
    if (LEGALIZE_INSTANCE_TSIDS.includes(legalizeSourceLocation?.tsid)) legalizeSourceLocation = { ...LEGALIZE_EXIT_FALLBACK };
    legalizeRun = ensureLegalizeState(questState, legalizeSourceLocation);
    legalizeRun.sourceLocation ||= createLegalizeState(legalizeSourceLocation).sourceLocation;
    legalizeSourceLocation = legalizeRun.sourceLocation || legalizeSourceLocation;
    savePlayerLocation(legalizeSourceLocation);
    // A save from before the route ran on the real places: the alley's station is the real one.
    if (legalizeRun.stage === 'back_alley_station') travelToGregarious(legalizeRun);
    const stage = legalizeRun.stage;
    if (stage === 'gregarious_departure') {
      await spawnLegalizeDepartureStation();
      pushActivity('You arrive at Gregarious Grange Subway Station.');
      toast('Push A Red Button at the gate.', 3600);
    } else if (['back_alley', 'back_alley_briefed'].includes(stage)) {
      await legalizeSceneTransition('The Back Alley', spawnLegalizeBackAlley);
      pushActivity('You arrive in the forest at The Back Alley.');
      if (stage === 'back_alley') toast('Find the Shady Bureaucrat.', 3600);
      else setTimeout(() => legalizeLeaveAlley(), 500);
    } else if (stage === 'gregarious_arrival') {
      await spawnLegalizeGregariousStation();
      pushActivity('You arrive at Gregarious Grange Subway Station.');
      toast('Exit the station to Gregarious Grange.', 3600);
    } else if (stage === 'grange_exterior') {
      await spawnLegalizeGregariousExterior();
      pushActivity('You return to Gregarious Grange.');
      toast('Enter the Bureaucratic Hall along the street.', 3600);
    } else {
      // location.js 810-819: leaving the hall cleared the visit, so an application under way starts over.
      if (['hall_called', 'hall_processing'].includes(stage)) Object.assign(legalizeRun, { stage: 'hall_waiting', handoffs: 0, clerkIndex: 0 });
      spawnLegalizeHall();
      pushActivity('You return to the Bureaucratic Hall on Gregarious Grange.');
    }
    renderLegalizeHud();
    updateHud();
    return legalizeRun;
  })();
  try {
    return await legalizeStartPromise;
  } finally {
    legalizeStartPromise = null;
  }
}

async function leaveLegalizeIt({ abandon = false } = {}) {
  if (legalizeTransitionBusy) return false;
  if (!legalizeRun && !LEGALIZE_INSTANCE_TSIDS.includes(currentStreetTsid)) return false;
  // The way back, else the station in front of A Red Button: Leave always has somewhere to go.
  const destination = legalizeWayOut();
  legalizeTransitionBusy = true;
  if (abandon && legalizeRun && legalizeRun.stage !== 'complete') {
    // The quest and its route go; the cards in the pack were bought, so they stay (js/legalize-it.js abandonLegalize).
    abandonLegalize(questState);
    pushActivity('You left the bureaucracy for another time.');
  }
  closeQuestDialogue({ force: true });
  legalizeRun = null;
  legalizeSourceLocation = null;
  legalizeTargets = [];
  const hud = document.getElementById('legalize-hud');
  if (hud) hud.hidden = true;
  try {
    await enterStreetWithTransition(destination.tsid, {
      spawnX: destination.x,
      spawnY: destination.y,
      quiet: true,
    });
    if (app?.canvas) app.canvas.dataset.legalizeStatus = abandon ? 'abandoned' : 'completed';
    savePlayerState();
    savePlayerLocation(destination);
    updateHud();
    return true;
  } finally {
    legalizeTransitionBusy = false;
  }
}

function confirmLeaveLegalizeIt() {
  if (!legalizeOnRoute()) return;
  openScriptedQuestDialogue({
    title: 'Legalize It',
    kicker: 'Leave the application?',
    cancelable: true,
    beats: [{
      text: 'Leaving now will abandon the current application. You can visit the Back Alley again later.',
      response: 'Abandon application',
    }],
    onComplete: () => leaveLegalizeIt({ abandon: true }),
  });
}

function updateLegalizeIt() {
  if (!legalizeOnRoute() || legalizeTransitionBusy || !player) return;
  const now = Date.now();
  for (const target of legalizeTargets) {
    const sprite = target?.sprite;
    if (
      target.classId === 'npc_bureaucrat' &&
      sprite?._legalizeAnimation === 'talk' &&
      sprite._legalizeAnimationUntil > 0 &&
      now >= sprite._legalizeAnimationUntil
    ) {
      setLegalizeBureaucratAnimation(target, 'idle');
    }
  }
  // The back_alley_entered box (location.js 1314-1321): walking in starts the Bureaucrat's proposition.
  if (
    currentStreetTsid === LEGALIZE_BACK_ALLEY_TSID && legalizeRun.stage === 'back_alley' &&
    inEnteredBox(player.x) && !isQuestDialogueOpen()
  ) {
    const shady = legalizeTargets.find((entry) => entry.classId === 'npc_back_alley_bureaucrat');
    if (shady) legalizeBriefing(shady);
  }
  // The waiting area, Please Wait and the calls are the hall's own visit (features/bureaucratic-halls-feature.js).
  const autoplayMode =
    new URLSearchParams(location.search).get('legalizeautoplay') || '';
  const autoplay = ['1', 'hall', 'purchase'].includes(autoplayMode);
  if (!autoplay || now < legalizeAutoNextAt) return;
  legalizeAutoNextAt = now + 180;
  if (isQuestDialogueOpen()) {
    advanceQuestDialogue();
    return;
  }
  if (
    autoplayMode === 'hall' &&
    currentStreetTsid === LEGALIZE_HALL_TSID &&
    legalizeRun.stage === 'hall_called'
  ) {
    return;
  }
  if (autoplayMode === 'purchase' && legalizeRun.stage === 'card_owned') return;
  const streetDoor = (id) => interactables.find((t) => t.classId === 'street_door' && t.door?.id === id);
  if (legalizeRun.stage === 'gregarious_departure' && currentStreetTsid === LEGALIZE_STATION_STREET) {
    // Push A Red Button, then OK on the papers refusal.
    const ok = document.querySelector('.subway-dialog button[data-value="ok"]');
    if (ok) {
      ok.click();
      return;
    }
    const gate = interactables.find((t) => t.classId === 'subway_gate');
    if (gate && !document.querySelector('.subway-dialog')) {
      player.x = gate.sprite.x - 70;
      executeVerb(gate, 'push');
    }
  } else if (legalizeRun.stage === 'back_alley' && currentStreetTsid === LEGALIZE_BACK_ALLEY_TSID) {
    // Walk into the entered box.
    player.x = ALLEY.triggerX - 40;
  } else if (legalizeRun.stage === 'gregarious_arrival' && currentStreetTsid === LEGALIZE_STATION_STREET) {
    const stairs = streetDoor(LEGALIZE_STAIRS_DOOR);
    if (stairs) {
      player.x = stairs.sprite.x + 40;
      executeVerb(stairs, 'exit');
    }
  } else if (legalizeRun.stage === 'grange_exterior' && currentStreetTsid === LEGALIZE_GRANGE_STREET) {
    const hall = streetDoor(LEGALIZE_HALL_DOOR);
    if (hall) {
      player.x = hall.sprite.x;
      executeVerb(hall, 'enter');
    }
  } else if (['hall_waiting', 'hall_called', 'hall_processing'].includes(legalizeRun.stage)) {
    // One step of the hall's visit: answer, step into the waiting area, skip the walks and the wait.
    features.query('hallAutoStep', engine);
  } else if (legalizeRun.stage === 'card_owned') {
    activateLegalizeCard();
  }
}

function winterWalkIsInstanced() {
  return Boolean(
    winterWalkState &&
      [WINTER_WALK_STREET_ID, WINTER_HAVEN_STREET_ID].includes(currentStreetTsid)
  );
}

function greedyStreetIsInstanced() {
  return Boolean(
    greedyStreetState &&
    [GREEDY_STREET_GEOMETRY_TSID, GREEDY_STREET_ID].includes(currentStreetTsid)
  );
}

function applyGreedySceneEvent(eventId) {
  const event = greedyStreetSceneManifest?.events?.[eventId];
  const views = bgLayer?.decoViews;
  if (!event || !views) return { hidden: 0, shown: 0, missing: 0 };
  const dynamicOnly = new Set(greedyStreetSceneManifest.dynamicOnlyDecos || []);
  let hidden = 0;
  let shown = 0;
  let missing = 0;
  for (const id of event.hide || []) {
    const view = views.get(id);
    if (!view) {
      if (!dynamicOnly.has(id)) missing += 1;
      continue;
    }
    view.visible = false;
    hidden += 1;
  }
  for (const id of event.show || []) {
    const view = views.get(id);
    if (!view) {
      if (!dynamicOnly.has(id)) missing += 1;
      continue;
    }
    view.visible = true;
    shown += 1;
  }
  if (app?.canvas) {
    app.canvas.dataset.greedySceneEvent = eventId;
    app.canvas.dataset.greedySceneChanged = `${hidden}:${shown}`;
    app.canvas.dataset.greedySceneMissing = String(missing);
  }
  return { hidden, shown, missing };
}

function greedyButtonSprite(actIndex, x, y) {
  const root = new PIXI.Container();
  root.name = `greedy-story-act-${actIndex + 1}`;
  root.sortableChildren = true;
  const button = new PIXI.Sprite(textureFromUrl('assets/sprites/quests/greedy-street-spirit/wall_button__x1_out_png_1354839763.webp'));
  button.anchor.set(0.5, 1);
  button.width = 126;
  button.height = 18;
  button.zIndex = 1;
  root.addChild(button);
  const label = new PIXI.Text({ text: `ACT ${['I', 'II', 'III', 'IV', 'V'][actIndex]}`, style: {
    fontFamily: 'Fredoka, Arial, sans-serif',
    fontSize: 17,
    fontWeight: '800',
    fill: 0xfff6c8,
    stroke: { color: 0x422b54, width: 4 },
    dropShadow: { blur: 2, color: 0x24172e, distance: 1 },
  } });
  label.anchor.set(0.5, 1);
  label.y = -20;
  label.zIndex = 2;
  root.addChild(label);
  root.x = x;
  root.y = y;
  // A wall_button item: under the avatars, as every item is (MiddleGroundRenderer.setupEndShapes 111-171).
  root.zIndex = 44;
  root._buttonArt = button;
  entityLayer.addChild(root);
  return root;
}

function createGreedyExitSprite(x, y) {
  const root = new PIXI.Container();
  root.label = 'greedy-story-exit';
  const sign = new PIXI.Graphics();
  sign.roundRect(-82, -43, 164, 38, 14).fill({ color: 0x5c3d72, alpha: 0.94 }).stroke({ width: 3, color: 0xfff1ae, alpha: 0.94 });
  root.addChild(sign);
  const label = new PIXI.Text({ text: 'RETURN TO UR →', style: {
    fontFamily: 'Fredoka, Arial, sans-serif',
    fontSize: 15,
    fontWeight: '800',
    fill: 0xfff9dd,
  } });
  label.anchor.set(0.5);
  label.y = -24;
  root.addChild(label);
  root.x = x;
  root.y = y;
  // A sign standing in the room: under the avatars, like the signposts (MiddleGroundRenderer GEO).
  root.zIndex = 44;
  entityLayer.addChild(root);
  return root;
}

function renderGreedyStreetHud() {
  const hud = document.getElementById('greedy-street-hud');
  const visible = greedyStreetIsInstanced();
  if (!hud) return;
  hud.hidden = !visible;
  if (!visible) return;
  const remaining = greedyRemainingMs(greedyStreetState);
  const seconds = Math.ceil(remaining / 1000);
  const timer = hud.querySelector('[data-greedy-timer]');
  const stage = hud.querySelector('[data-greedy-stage]');
  const objective = hud.querySelector('[data-greedy-objective]');
  const line = hud.querySelector('[data-greedy-line]');
  const firstIncomplete = greedyStreetState.actSteps.findIndex(
    (step, index) => step < GREEDY_ACTS[index].lines.length
  );
  if (timer) {
    timer.textContent = `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`;
    timer.classList.toggle('is-low', remaining > 0 && remaining <= 30_000);
  }
  if (stage) {
    stage.textContent = firstIncomplete < 0
      ? 'Storyland · all five acts read'
      : `Storyland · ${GREEDY_ACTS[firstIncomplete].title}`;
  }
  if (objective) objective.textContent = greedyObjective(greedyStreetState);
  if (line) line.textContent = greedyStreetState.lastLine || 'Once upon a time…';
  hud.querySelectorAll('[data-greedy-act]').forEach((dot) => {
    dot.classList.toggle(
      'is-done',
      greedyStreetState.actsRead.includes(Number(dot.dataset.greedyAct))
    );
  });
  if (greedyStreetExit?.sprite) {
    greedyStreetExit.sprite.alpha = greedyStreetState.status === 'ready' ? 1 : 0.38;
  }
  if (app?.canvas) {
    app.canvas.dataset.greedyStoryStatus = greedyStreetState.status;
    app.canvas.dataset.greedyStoryRepeat = greedyStreetState.repeat ? '1' : '0';
    app.canvas.dataset.greedyStoryActs = greedyStreetState.actsRead.join(',');
    app.canvas.dataset.greedyStorySteps = greedyStreetState.actSteps.join(',');
    app.canvas.dataset.greedyStoryRemaining = String(remaining);
    app.canvas.dataset.greedyStoryObjective = greedyObjective(greedyStreetState);
    app.canvas.dataset.greedyStoryProductionTsid = GREEDY_STREET_PRODUCTION_TSID;
  }
}

function setupGreedyStreetInstance() {
  clearWorldEntities();
  currentStreetTsid = GREEDY_STREET_ID;
  currentStreetPopulation = {
    source: 'production-instance',
    sourceTsid: GREEDY_STREET_PRODUCTION_TSID,
    giantId: '',
    piggies: 0,
    chickens: 0,
    butterflies: 0,
    flyingButterflies: 0,
    treeClasses: [],
    rockClasses: [],
    gardens: 0,
    vendor: false,
    shrine: false,
  };
  applyGreedySceneEvent('player_enter');
  const groundY = streetPlatforms?.[0]?.y1 || GROUND_Y;
  const buttonXs = [700, 1775, 2925, 4075, 5200];
  greedyStreetButtons = GREEDY_ACTS.map((act, actIndex) => {
    const sprite = greedyButtonSprite(actIndex, buttonXs[actIndex], groundY);
    return register({
      classId: 'greedy_story_button',
      label: `${act.title} Wall Button`,
      subtitle: `Read ${act.title} of The Greedy Street Spirit`,
      sprite,
      state: {
        storyState: greedyStreetState,
        actIndex,
        actTitle: act.title,
        totalSteps: act.lines.length,
      },
    });
  });
  const exitSprite = createGreedyExitSprite(WORLD_W - 120, groundY);
  greedyStreetExit = register({
    classId: 'greedy_story_exit',
    label: 'Storyland exit',
    subtitle: 'Return to Ur after reading all five acts',
    sprite: exitSprite,
    state: { storyState: greedyStreetState },
  });
  if (player) {
    player.x = 365;
    player.y = groundY;
    player.vx = 0;
    player.vy = 0;
    player.onGround = true;
  }
  const name = document.getElementById('street-name');
  if (name) {
    name.textContent = 'The Greedy Street Spirit'; // G363: an instance, no hub line (location.js 3311)
    name.dataset.tsid = GREEDY_STREET_PRODUCTION_TSID;
  }
  camTarget = cameraTargetForPlayer(player?.x || 365);
  camY = cameraTargetY(player?.y || groundY, activeCameraWorldHeight(), LOCATION_VIEW_H);
  world.x = -Math.round(camTarget);
  world.y = -Math.round(camY);
  renderGreedyStreetHud();
  updateHud();
}

async function startGreedyStreetSpirit(opts = {}) {
  if (greedyStreetStartPromise) return greedyStreetStartPromise;
  if (greedyStreetIsInstanced()) return greedyStreetState;
  greedyStreetStartPromise = (async () => {
    const repeat = Boolean(opts.repeat);
    const questId = repeat
      ? GREEDY_STREET_SPIRIT_REPEAT_ID
      : GREEDY_STREET_SPIRIT_QUEST_ID;
    if (repeat) {
      questState.completed = questState.completed.filter(
        (id) => id !== GREEDY_STREET_SPIRIT_REPEAT_ID
      );
    }
    if (!questState.active[questId]) {
      const assigned = assignQuest(questState, questId, { ignorePrereq: repeat });
      if (!assigned.ok) return null;
    }
    closeQuestPanel();
    closeQuestDialogue({ force: true });
    closePackPopover();
    greedyStreetSourceLocation = opts.sourceLocation || instanceSourceHere({
      tsid: currentStreetTsid,
      x: player?.x ?? WORLD_W * 0.5,
      y: player?.y ?? GROUND_Y,
    });
    greedyStreetState = createGreedyStreetSpiritState({
      repeat,
      sourceLocation: greedyStreetSourceLocation,
      enteredAt: Date.now(),
    });
    greedyStreetAutoNextAt = 0;
    savePlayerLocation(greedyStreetSourceLocation);
    const [manifest] = await Promise.all([
      fetch('assets/content/greedy-street-spirit-scenes.json').then((response) => {
        if (!response.ok) throw new Error(`Greedy Street Spirit scenes: HTTP ${response.status}`);
        return response.json();
      }),
      enterStreetWithTransition(GREEDY_STREET_GEOMETRY_TSID, {
        useTransition: opts.useTransition !== false,
        quiet: true,
      }),
    ]);
    greedyStreetSceneManifest = manifest;
    if (!greedyStreetState) return null;
    setupGreedyStreetInstance();
    savePlayerLocation(greedyStreetSourceLocation);
    pushActivity('The Greedy Street Spirit: read all five acts before Storyland fades.');
    toast('Five minutes. Press each act’s Wall Button.', 3400);
    return greedyStreetState;
  })();
  try {
    return await greedyStreetStartPromise;
  } finally {
    greedyStreetStartPromise = null;
  }
}

function pressGreedyStoryButton(target) {
  if (!greedyStreetIsInstanced() || !target?.state) return false;
  const result = pressGreedyAct(
    greedyStreetState,
    target.state.actIndex,
    Date.now()
  );
  if (!result.ok) {
    if (result.reason === 'expired') returnFromGreedyStreetSpirit({ expired: true });
    else toast(result.reason === 'act_complete' ? 'That act is already complete.' : 'The story cannot continue.');
    return false;
  }
  applyGreedySceneEvent(result.eventId);
  if (target.sprite?._buttonArt) {
    const art = target.sprite._buttonArt;
    art.texture = textureFromUrl('assets/sprites/quests/greedy-street-spirit/wall_button__x1_in_png_1354839762.webp');
    window.setTimeout(() => {
      if (!art.destroyed) {
        art.texture = textureFromUrl('assets/sprites/quests/greedy-street-spirit/wall_button__x1_out_png_1354839763.webp');
      }
    }, 240);
  }
  if (result.actCompleted) {
    const activeId = greedyStreetState.repeat
      ? GREEDY_STREET_SPIRIT_REPEAT_ID
      : GREEDY_STREET_SPIRIT_QUEST_ID;
    if (questState.active?.[activeId]) {
      questState.active[activeId].progress[`read_act_${result.actIndex + 1}`] = 1;
    }
  }
  playSfx(result.actCompleted ? 'quest' : 'pickup', {
    volume: result.actCompleted ? 0.54 : 0.34,
    rate: 0.92 + result.actIndex * 0.04,
  });
  // Player report 37: the line is the story's dialogue and then the quest pill's caption
  // (features/quest-plate-feature.js), so it goes to the log only, not a notice stacked under them.
  notify.log(`${GREEDY_ACTS[result.actIndex].title}: ${result.line}`);
  openScriptedQuestDialogue({
    title: 'The Greedy Street Spirit',
    kicker: `${GREEDY_ACTS[result.actIndex].title} · scene ${result.step + 1} of ${GREEDY_ACTS[result.actIndex].lines.length}`,
    beats: [{ text: result.line, response: result.storyCompleted ? 'The end' : 'Continue' }],
    onComplete: () => {
      if (result.storyCompleted) {
        const text = greedyStreetState.repeat
          ? 'The whole story has been remembered. Return to Ur for breakfast.'
          : "What a wonderful story. Let's return to the Piggy to wrap this up.";
        toast(text, 4800);
        pushActivity(text);
      }
      renderGreedyStreetHud();
    },
  });
  renderGreedyStreetHud();
  savePlayerState();
  return true;
}

function handleGreedyStreetTarget(target, verbId) {
  if (target?.classId === 'greedy_story_button' && verbId === 'press') {
    pressGreedyStoryButton(target);
    return;
  }
  if (target?.classId === 'greedy_story_exit' && verbId === 'leave_storyland') {
    returnFromGreedyStreetSpirit();
  }
}

function finishGreedyRepeat() {
  const active = questState.active?.[GREEDY_STREET_SPIRIT_REPEAT_ID];
  if (!active || greedyStreetState?.actsRead.length !== GREEDY_ACTS.length) return false;
  greedyStreetState.status = 'complete';
  const result = completeQuest(questState, GREEDY_STREET_SPIRIT_REPEAT_ID, pc);
  if (!result.ok) return false;
  addItem(inv, GREEDY_REPEAT_REWARD.item, GREEDY_REPEAT_REWARD.count);
  markGreedyRepeatComplete(questState, Date.now());
  announceQuestCompletions([{
    classTsid: GREEDY_STREET_SPIRIT_REPEAT_ID,
    completed: true,
    rewards: result.rewards,
    def: result.def,
  }]);
  pushActivity("Wasn't that sweet? Now that naptime is over, here's some breakfast. +4 Waffles.");
  if (app?.canvas) {
    app.canvas.dataset.greedyStoryReward = 'waffles:4';
    app.canvas.dataset.greedyStoryCooldown = String(
      ensureGreedyStory(questState).lastRepeatCompletedAt
    );
  }
  return true;
}

async function returnFromGreedyStreetSpirit({ abandon = false, expired = false } = {}) {
  if (!greedyStreetState || greedyStreetTransitionBusy) return false;
  if (!abandon && !expired && greedyStreetState.status !== 'ready') {
    toast("You've missed some of the story! It's much more rewarding if you read it all the way through.", 4800);
    return false;
  }
  greedyStreetTransitionBusy = true;
  const wasRepeat = greedyStreetState.repeat;
  const destination = greedyStreetSourceLocation?.tsid
    ? { ...greedyStreetSourceLocation }
    : { tsid: STREET_INDEX.default };
  const questId = wasRepeat
    ? GREEDY_STREET_SPIRIT_REPEAT_ID
    : GREEDY_STREET_SPIRIT_QUEST_ID;
  let status = expired ? 'expired' : abandon ? 'abandoned' : greedyStreetState.status;
  if (expired || abandon) {
    delete questState.active[questId];
    if (wasRepeat) markGreedyRepeatFailed(questState, Date.now());
  } else if (wasRepeat) {
    finishGreedyRepeat();
    status = 'complete';
  }
  closeQuestDialogue({ force: true });
  greedyStreetState = null;
  greedyStreetSourceLocation = null;
  greedyStreetSceneManifest = null;
  greedyStreetButtons = [];
  greedyStreetExit = null;
  const hud = document.getElementById('greedy-street-hud');
  if (hud) hud.hidden = true;
  try {
    await enterStreetWithTransition(destination.tsid, {
      spawnX: destination.x,
      spawnY: destination.y,
      quiet: true,
    });
    savePlayerLocation(destination);
    if (app?.canvas) app.canvas.dataset.greedyStoryStatus = status;
    if (expired) toast('Storyland faded before the bedtime story was finished.', 4200);
    else if (abandon) {
      toast("You've missed some of the story. You can begin again later.", 3600);
    } else if (wasRepeat) {
      toast("Wasn't that sweet? Breakfast: +4 Waffles.", 4200);
    } else {
      toast("What a wonderful story. Find a Piggy to wrap this up.", 4200);
      if (new URLSearchParams(location.search).get('greedyautoplay') === '1') {
        const piggy = interactables.find((entry) => entry.classId === 'npc_piggy');
        if (piggy) handleGreedyStreetPiggy(piggy);
      }
    }
    savePlayerState();
    updateHud();
    return true;
  } finally {
    greedyStreetTransitionBusy = false;
  }
}

function completeGreedyStreetSpiritWithPiggy(target) {
  const active = questState.active?.[GREEDY_STREET_SPIRIT_QUEST_ID];
  if (!active) return false;
  const actsRead = GREEDY_ACTS.every(
    (_act, index) => Number(active.progress[`read_act_${index + 1}`]) >= 1
  );
  if (!actsRead) return false;
  active.progress.talk_to_piggy = 1;
  const result = completeQuest(questState, GREEDY_STREET_SPIRIT_QUEST_ID, pc);
  if (!result.ok) return false;
  addItem(inv, GREEDY_FIRST_REWARD.item, GREEDY_FIRST_REWARD.count);
  markGreedyFirstComplete(questState, Date.now());
  syncEmotionalBearCatalog();
  announceQuestCompletions([{
    classTsid: GREEDY_STREET_SPIRIT_QUEST_ID,
    completed: true,
    rewards: result.rewards,
    def: result.def,
  }]);
  const completion = "Wasn't that sweet? Here's a cuddly Emotional Bear to remind you of this bedtime story.";
  showSpeechBubble(target, {
    speaker: target.label || 'Piggy',
    text: completion,
    durationMs: 7200,
  });
  pushActivity(`${completion} +1 Emotional Bear · +100 favor with Pot.`);
  toast('Quest complete · Emotional Bear acquired!', 4600);
  playSfx('quest', { volume: 0.74, rate: 1.05 });
  if (app?.canvas) {
    app.canvas.dataset.greedyStoryStatus = 'complete';
    app.canvas.dataset.greedyStoryReward = 'emotional_bear:1';
    app.canvas.dataset.greedyStoryPiggy = 'talked';
  }
  savePlayerState();
  updateHud();
  return true;
}

function handleGreedyStreetPiggy(target) {
  if (completeGreedyStreetSpiritWithPiggy(target)) return true;
  if (!canOfferGreedyFirst(questState, pc).ok) return false;
  openQuestDialogue(GREEDY_STREET_SPIRIT_QUEST_ID);
  return true;
}

function confirmLeaveGreedyStreetSpirit() {
  if (!greedyStreetIsInstanced()) return;
  const complete = greedyStreetState.status === 'ready';
  openScriptedQuestDialogue({
    title: 'The Greedy Street Spirit',
    kicker: complete ? 'Return to Ur?' : 'Leave Storyland?',
    cancelable: true,
    beats: [{
      text: complete
        ? greedyStreetState.repeat
          ? 'Return to Ur and collect your breakfast.'
          : 'Return to Ur, then talk to a Piggy to wrap this up.'
        : "You've missed some of the story! It's much more rewarding if you read it all the way through.",
      response: complete ? 'Return to Ur' : 'Leave anyway',
    }],
    onComplete: () => returnFromGreedyStreetSpirit({ abandon: !complete }),
  });
}

function updateGreedyStreetSpirit() {
  if (!greedyStreetIsInstanced() || greedyStreetTransitionBusy) return;
  const now = Date.now();
  if (greedyRemainingMs(greedyStreetState, now) <= 0) {
    expireGreedyStreetSpirit(greedyStreetState, now);
    returnFromGreedyStreetSpirit({ expired: true });
    return;
  }
  const autoplay = new URLSearchParams(location.search).get('greedyautoplay');
  if (autoplay === '1' && now >= greedyStreetAutoNextAt) {
    greedyStreetAutoNextAt = now + 190;
    if (isQuestDialogueOpen()) {
      advanceQuestDialogue();
    } else if (greedyStreetState.status === 'ready') {
      returnFromGreedyStreetSpirit();
    } else {
      const nextIndex = greedyStreetState.actSteps.findIndex(
        (step, index) => step < GREEDY_ACTS[index].lines.length
      );
      const target = greedyStreetButtons[nextIndex];
      if (target) {
        player.x = target.sprite.x - 44;
        player.y = target.sprite.y;
        player.vx = 0;
        player.vy = 0;
        pressGreedyStoryButton(target);
      }
    }
  }
  renderGreedyStreetHud();
}

function winterLocationLabel(tsid) {
  if (tsid === WINTER_WALK_STREET_ID) {
    // G363: both are level_quest_winter_walk / _haven instances (winter_walk.js 24-33, 100), and
    // getLoadingInfo sends an instance no hub_name (location.js 3311): no hub line.
    return { street: 'Winter Walk', hub: '' };
  }
  if (tsid === WINTER_HAVEN_STREET_ID) {
    return { street: 'Winter Haven', hub: '' };
  }
  return null;
}

function winterRouteCandidates(stage = winterWalkState?.stage) {
  const rows = (streetPlatforms || [])
    .map((platform) => {
      const width = Math.abs(platform.x2 - platform.x1);
      return {
        x: (platform.x1 + platform.x2) / 2,
        y: (platform.y1 + platform.y2) / 2,
        width,
        platform,
      };
    })
    .filter((point) => Number.isFinite(point.x) && Number.isFinite(point.y) && point.width >= 24);
  if (stage === 'haven') {
    return rows.sort((a, b) => b.y - a.y || a.x - b.x);
  }
  const surface = rows.sort((a, b) => a.x - b.x || b.y - a.y);
  if (stage === 'return') {
    const count = Math.max(6, Math.ceil(surface.length * 0.22));
    return surface.slice(-count);
  }
  return surface;
}

function winterRoutePoints(stage, count) {
  const pool = winterRouteCandidates(stage);
  if (!pool.length) return samplePlatformPoints(count);
  const points = [];
  const start = stage === 'haven' ? 0.08 : 0.12;
  const end = stage === 'haven' ? 0.9 : 0.84;
  for (let i = 0; i < count; i += 1) {
    const progress = count <= 1 ? 0.5 : i / (count - 1);
    const index = Math.round((start + (end - start) * progress) * (pool.length - 1));
    const point = pool[clamp(index, 0, pool.length - 1)];
    points.push({ x: point.x, y: point.y, platform: point.platform });
  }
  return points;
}

function clearWinterAtmosphere() {
  if (winterSnow?.parent) winterSnow.parent.removeChild(winterSnow);
  if (winterSnow && !winterSnow.destroyed) winterSnow.destroy({ children: true });
  winterSnow = null;
}

function spawnWinterSnow() {
  clearWinterAtmosphere();
  if (!fxLayer) return null;
  // Weather over the whole view: in the overlay holder, over the street's front layers (the Winter
  // Walk's front ground and drifts) as well as the avatars; under the speech bubbles and hint chip.
  const snow = new PIXI.Container();
  snow.label = 'winter-snow';
  snow.eventMode = 'none';

  const veil = new PIXI.Graphics();
  // A unit square stretched to the view each frame (updateWinterSnow): the view follows the window.
  veil.rect(0, 0, 1, 1).fill({ color: winterWalkState?.stage === 'haven' ? 0x18345f : 0xc9efff, alpha: 0.055 });
  veil._winterVeil = true;
  snow.addChild(veil);

  const count = winterWalkState?.stage === 'haven' ? 64 : 92;
  for (let i = 0; i < count; i += 1) {
    const flake = new PIXI.Sprite(PIXI.Texture.WHITE);
    const size = 1.4 + ((i * 17) % 31) / 10;
    flake.width = size;
    flake.height = size;
    flake.tint = i % 7 === 0 ? 0xc8eaff : 0xffffff;
    flake.alpha = 0.34 + ((i * 13) % 54) / 100;
    flake.x = (i * 149 + 31) % VIEW_W;
    flake.y = (i * 83 + 17) % VIEW_H;
    flake._winterFlake = true;
    flake._vx = -0.18 - ((i * 7) % 13) / 28;
    flake._vy = 0.42 + ((i * 11) % 17) / 18;
    flake._phase = i * 0.91;
    snow.addChild(flake);
  }
  fxLayer.addChildAt(snow, 0);
  winterSnow = snow;
  return snow;
}

function updateWinterSnow(dt) {
  if (!winterSnow || winterSnow.destroyed) return;
  const left = Number.isFinite(camTarget) ? camTarget : 0;
  const top = Number.isFinite(camY) ? camY : 0;
  const veil = winterSnow.children.find((child) => child._winterVeil);
  if (veil) {
    veil.position.set(left, top);
    veil.width = VIEW_W;
    veil.height = VIEW_H;
  }
  for (const flake of winterSnow.children) {
    if (!flake._winterFlake) continue;
    flake._phase += 0.018 * dt;
    flake.x += (flake._vx + Math.sin(flake._phase) * 0.12) * dt;
    flake.y += flake._vy * dt;
    if (flake.x < left - 18) flake.x = left + VIEW_W + 18;
    if (flake.x > left + VIEW_W + 18) flake.x = left - 18;
    if (flake.y > top + VIEW_H + 18) {
      flake.y = top - 18;
      flake.x = left + ((flake._phase * 173) % VIEW_W);
    }
    if (flake.y < top - 24) flake.y = top + VIEW_H + 18;
  }
}

function spawnWinterMotes(stage) {
  const rewards = WINTER_MOTE_REWARDS[stage] || [];
  const points = winterRoutePoints(stage, rewards.length);
  winterWalkMotes = [];
  points.forEach((point, index) => {
    if (winterWalkState?.collected?.[stage]?.includes(index)) return;
    const sprite = new PIXI.AnimatedSprite(quoinFrames('xp'));
    sprite.anchor.set(0.5);
    sprite.animationSpeed = 0.28;
    sprite.loop = true;
    sprite.play();
    sprite.baseScale = SCALE * (index === 2 && stage === 'surface' ? 1.12 : 0.94);
    sprite.scale.set(sprite.baseScale);
    sprite.x = point.x;
    sprite.baseY = point.y - 62 - (index % 2) * 26;
    sprite.y = sprite.baseY;
    sprite.phase = index * 1.37;
    sprite.tint = index === 2 && stage === 'surface' ? 0xe0a8ff : 0xc58cff;
    sprite.zIndex = 42;
    const glow = new PIXI.Graphics();
    glow.circle(0, 0, index === 2 && stage === 'surface' ? 30 : 23).fill({ color: 0x9b5de5, alpha: index === 2 && stage === 'surface' ? 0.34 : 0.2 });
    sprite.addChildAt(glow, 0);
    entityLayer.addChild(sprite);
    winterWalkMotes.push({ stage, index, amount: rewards[index], sprite });
  });
  return winterWalkMotes;
}

function spawnWinterPortal(stage) {
  const route = winterRouteCandidates(stage);
  const point = route[route.length - 1];
  const fallback = samplePlatformPoints(1)[0] || { x: WORLD_W - 140, y: GROUND_Y };
  const spot = point || fallback;
  const root = new PIXI.Container();
  root.name = `winter-portal-${stage}`;
  root.position.set(spot.x, spot.y + 2);
  root.zIndex = 48;
  root.hitArea = new PIXI.Rectangle(-66, -190, 132, 190);

  let art = 'ice-passage';
  if (stage === 'haven') {
    art = 'recovered-exit-ladder';
    const ladder = new PIXI.Sprite(
      textureFromUrl('assets/decos/groddle/ladder_interior_4steps.png')
    );
    ladder.anchor.set(0.5, 1);
    ladder.scale.set(0.58);
    root.addChild(ladder);

    const sign = new PIXI.Sprite(
      textureFromUrl('assets/decos/groddle/sign_exit_starter_01a.png')
    );
    sign.anchor.set(0.5);
    sign.position.set(78, -112);
    sign.scale.set(0.9);
    root.addChild(sign);
  } else {
    const light = new PIXI.Graphics();
    const returning = stage === 'return';
    art = returning ? 'white-home-light' : art;
    light.ellipse(0, -78, returning ? 108 : 46, returning ? 152 : 82).fill({ color: 0xffffff, alpha: returning ? 0.24 : 0.045 });
    light.ellipse(0, -66, returning ? 56 : 26, returning ? 128 : 62).fill({ color: returning ? 0xf5feff : 0xcdf4ff, alpha: returning ? 0.52 : 0.12 });
    if (returning) {
      light.rect(-18, -206, 36, 206).fill({ color: 0xffffff, alpha: 0.34 });
    }
    root.addChild(light);

    if (!returning) {
      const ice = new PIXI.Sprite(
        textureFromUrl('assets/decos/groddle/snow_skirt_01b_al1.png')
      );
      ice.anchor.set(0.5, 0);
      ice.position.set(0, -174);
      ice.scale.set(0.42);
      root.addChild(ice);
    }
  }
  root._winterPortalArt = art;

  entityLayer.addChild(root);
  winterWalkPortal = register({
    classId: 'winter_portal',
    label:
      stage === 'surface'
        ? 'Passage to Winter Haven'
        : stage === 'haven'
          ? 'Exit Ladder'
          : 'The Way Home',
    subtitle:
      stage === 'surface'
        ? 'The path continues below'
        : stage === 'haven'
          ? 'Climb back to Winter Walk'
          : 'Return to Ur',
    sprite: root,
    state: { stage, active: true },
  });
  if (app?.canvas) {
    app.canvas.dataset.winterWalkPortalArt = art;
    app.canvas.dataset.winterWalkPortalCount = '1';
  }
  return winterWalkPortal;
}

function renderWinterWalkHud() {
  const hud = document.getElementById('winter-walk-hud');
  const visible = winterWalkIsInstanced();
  if (hud) hud.hidden = !visible;
  if (!visible) return;
  const remaining = winterWalkRemainingMs(winterWalkState);
  const seconds = Math.ceil(remaining / 1000);
  const progress = winterWalkProgress(winterWalkState);
  const stage = hud.querySelector('[data-winter-stage]');
  const timer = hud.querySelector('[data-winter-timer]');
  const objective = hud.querySelector('[data-winter-objective]');
  const motes = hud.querySelector('[data-winter-motes]');
  const img = hud.querySelector('[data-winter-img]');
  if (stage) {
    stage.textContent =
      winterWalkState.stage === 'haven'
        ? 'Winter Haven'
        : winterWalkState.stage === 'return'
          ? 'Winter Walk · Homeward'
          : 'Snowy path';
  }
  if (timer) {
    timer.textContent = `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`;
    timer.classList.toggle('is-low', remaining <= 30_000);
  }
  if (objective) objective.textContent = winterWalkObjective(winterWalkState);
  if (motes) motes.textContent = `${progress.collected} / ${progress.total}`;
  if (img) img.textContent = winterWalkState.imgEarned.toLocaleString();
  if (app?.canvas) {
    app.canvas.dataset.winterWalkStatus = winterWalkState.status;
    app.canvas.dataset.winterWalkStage = winterWalkState.stage;
    app.canvas.dataset.winterWalkRemaining = String(remaining);
    app.canvas.dataset.winterWalkMotes = `${progress.collected}/${progress.total}`;
    app.canvas.dataset.winterWalkImg = String(winterWalkState.imgEarned);
    app.canvas.dataset.winterWalkObjective = winterWalkObjective(winterWalkState);
    app.canvas.dataset.winterWalkRoute = 'surface>haven>return';
  }
}

function setupWinterWalkStage(stage) {
  clearWorldEntities();
  for (const sign of bgLayer?.signViews || []) sign.visible = false;
  if (currentStreet) currentStreet.signposts = [];
  spawnWinterSnow();
  spawnWinterMotes(stage);
  spawnWinterPortal(stage);
  const route = winterRouteCandidates(stage);
  const routeStart = route[0] || samplePlatformPoints(1)[0] || { x: 100, y: GROUND_Y };
  const preview = new URLSearchParams(location.search).get('winterpreview');
  const portalSpot = winterWalkPortal?.sprite;
  const start =
    preview === 'portal' && portalSpot
      ? { x: portalSpot.x - 86, y: portalSpot.y }
      : routeStart;
  if (player) {
    player.x = clamp(start.x, 40, Math.max(80, WORLD_W - 40));
    player.y = start.y;
    player.vx = 0;
    player.vy = 0;
    player.onGround = true;
    noteGrounded(jumpState, true, movementNow());
  }
  camTarget = cameraTargetForPlayer(player.x);
  camY = cameraTargetY(player.y, activeCameraWorldHeight(), LOCATION_VIEW_H);
  world.x = -camTarget;
  world.y = -camY;
  const label = winterLocationLabel(currentStreetTsid);
  if (currentStreet && label) {
    currentStreet.label = label.street;
    currentStreet.hubName = label.hub;
  }
  const name = document.getElementById('street-name');
  if (name && label) {
    name.textContent = label.hub ? `${label.street} · ${label.hub}` : label.street;
    name.dataset.tsid = currentStreetTsid;
  }
  renderWinterWalkHud();
  updateHud();
}

async function startWinterWalk(opts = {}) {
  if (winterWalkStartPromise) return winterWalkStartPromise;
  if (winterWalkIsInstanced()) return winterWalkState;
  winterWalkStartPromise = (async () => {
    const repeat = Boolean(opts.repeat);
    const questId = repeat ? WINTER_WALK_REPEAT_QUEST_ID : WINTER_WALK_QUEST_ID;
    if (repeat) {
      questState.completed = questState.completed.filter(
        (id) => id !== WINTER_WALK_REPEAT_QUEST_ID
      );
    }
    if (!questState.active[questId]) {
      const assigned = assignQuest(questState, questId, { ignorePrereq: true });
      if (!assigned.ok) return null;
    }
    closeQuestPanel();
    closeQuestDialogue();
    closePackPopover();
    winterWalkSourceLocation = opts.sourceLocation || instanceSourceHere({
      tsid: currentStreetTsid,
      x: player?.x ?? WORLD_W * 0.5,
      y: player?.y ?? GROUND_Y,
    });
    winterWalkState = createWinterWalkState({
      now: Date.now(),
      sourceLocation: winterWalkSourceLocation,
      repeat,
    });
    winterWalkAutoNextAt = 0;
    savePlayerLocation(winterWalkSourceLocation);
    await enterStreetWithTransition(WINTER_WALK_STREET_ID, {
      useTransition: opts.useTransition !== false,
      quiet: true,
    });
    savePlayerLocation(winterWalkSourceLocation);
    setupWinterWalkStage('surface');
    pushActivity('Winter Walk: cross the snowy path, then climb through Winter Haven.');
    toast('Five minutes. Follow the winter motes.', 3200);
    return winterWalkState;
  })();
  try {
    return await winterWalkStartPromise;
  } finally {
    winterWalkStartPromise = null;
  }
}

function collectWinterWalkMote(entry) {
  if (!entry?.sprite || entry.collected || !winterWalkState) return false;
  // The motes are iMG quoins in a place that keeps the daily quoin limit (items/quoin.js 159, 236-237).
  if (quoinState.collectedToday >= quoinState.dailyLimit) return false;
  const result = collectWinterMote(
    winterWalkState,
    entry.stage,
    entry.index,
    Date.now()
  );
  if (!result.ok) return false;
  entry.collected = true;
  // The motes are iMG quoins (items/quoin.js 184): the quoin multiplier and the mood bonus apply, and each counts today.
  const quoin = collectQuoin(quoinState, 'xp', pc, { amount: result.amount });
  const amount = quoin.ok ? quoin.actual : 0;
  winterWalkState.imgEarned += amount - result.amount;
  // inc_stats.js stats_add_quoins_today 686-699, as a street quoin does (grabWorldQuoin).
  if (quoin.hitLimit) announceQuoinLimit(quoin.dailyLimit);
  const { x, y } = entry.sprite;
  if (entry.sprite.parent) entry.sprite.parent.removeChild(entry.sprite);
  if (!entry.sprite.destroyed) entry.sprite.destroy({ children: true });
  playSfx('quoin', { volume: result.amount >= 1000 ? 0.8 : 0.56, rate: result.amount >= 1000 ? 1.18 : 1.04 });
  floatText(x, y - 18, `+${amount.toLocaleString()} iMG`, 0xc98dff);
  burst(x, y, 0xb873ed, result.amount >= 1000 ? 26 : 13);
  pushActivity(`A winter mote sparkles into imagination. +${amount.toLocaleString()} iMG.`);
  renderWinterWalkHud();
  updateHud();
  return true;
}

async function enterWinterHavenStage() {
  if (!winterWalkIsInstanced() || winterWalkTransitionBusy) return false;
  const result = enterWinterHaven(winterWalkState, Date.now());
  if (!result.ok) return false;
  winterWalkTransitionBusy = true;
  if (winterWalkPortal?.state) winterWalkPortal.state.active = false;
  keys.clear();
  try {
    await enterStreetWithTransition(WINTER_HAVEN_STREET_ID, { quiet: true });
    if (!winterWalkState) return false;
    savePlayerLocation(winterWalkSourceLocation);
    setupWinterWalkStage('haven');
    pushActivity('You descend into Winter Haven. The exit ladder waits above.');
    toast('Winter Haven: climb to the EXIT sign.', 2800);
    return true;
  } finally {
    winterWalkTransitionBusy = false;
  }
}

async function reenterWinterWalkStage() {
  if (!winterWalkIsInstanced() || winterWalkTransitionBusy) return false;
  const result = returnToWinterWalk(winterWalkState, Date.now());
  if (!result.ok) return false;
  winterWalkTransitionBusy = true;
  if (winterWalkPortal?.state) winterWalkPortal.state.active = false;
  keys.clear();
  try {
    await enterStreetWithTransition(WINTER_WALK_STREET_ID, { quiet: true });
    if (!winterWalkState) return false;
    savePlayerLocation(winterWalkSourceLocation);
    setupWinterWalkStage('return');
    pushActivity('You climb back into Winter Walk. Three bright motes mark the way home.');
    toast('Winter Walk: gather the last motes and follow the light.', 3200);
    return true;
  } finally {
    winterWalkTransitionBusy = false;
  }
}

async function returnFromWinterWalk({ abandon = false, expired = false } = {}) {
  if (!winterWalkState || winterWalkTransitionBusy) return false;
  winterWalkTransitionBusy = true;
  const destination = winterWalkSourceLocation?.tsid
    ? { ...winterWalkSourceLocation }
    : { tsid: STREET_INDEX.default };
  const repeatWalk = Boolean(winterWalkState.repeat);
  const questId = repeatWalk
    ? WINTER_WALK_REPEAT_QUEST_ID
    : WINTER_WALK_QUEST_ID;
  if (abandon || expired) {
    // winter_walk.js onExitLocation 96-107 / winter_walk_part2.js 88-100: leaving early fails the walk.
    delete questState.active[questId];
    noteWinterWalkEnd(questState, { repeat: winterWalkState.repeat, outcome: 'failed' });
  }
  const status = expired ? 'expired' : abandon ? 'abandoned' : winterWalkState.status;
  closeQuestDialogue({ force: true });
  clearWinterAtmosphere();
  winterWalkState = null;
  winterWalkSourceLocation = null;
  winterWalkMotes = [];
  winterWalkPortal = null;
  const hud = document.getElementById('winter-walk-hud');
  if (hud) hud.hidden = true;
  try {
    await enterStreetWithTransition(destination.tsid, {
      spawnX: destination.x,
      spawnY: destination.y,
      quiet: true,
    });
    savePlayerLocation(destination);
    savePlayerState();
    if (app?.canvas) app.canvas.dataset.winterWalkStatus = status;
    if (expired) toast(repeatWalk ? 'The winter path faded. You can walk it again in an hour.' : 'The winter path faded. You can try the walk again.', 4000);
    else if (abandon) toast(repeatWalk ? 'You leave the winter path. You can walk it again in an hour.' : 'You leave the winter path for another time.', 3200);
    updateHud();
    return true;
  } finally {
    winterWalkTransitionBusy = false;
  }
}

async function completeWinterWalk() {
  if (!winterWalkIsInstanced() || winterWalkTransitionBusy) return false;
  const result = finishWinterWalk(winterWalkState, Date.now());
  if (!result.ok) return false;
  const questId = winterWalkState.repeat
    ? WINTER_WALK_REPEAT_QUEST_ID
    : WINTER_WALK_QUEST_ID;
  if (result.iceReward) addItem(inv, 'ice', result.iceReward);
  noteWinterWalkEnd(questState, { repeat: winterWalkState.repeat, outcome: 'complete' });
  const active = questState.active?.[questId];
  if (active) active.progress.leave = 1;
  const completed = active ? completeQuest(questState, questId, pc) : null;
  const updates = completed?.ok
    ? [{ classTsid: questId, completed: true, rewards: completed.rewards, def: completed.def }]
    : [];
  announceQuestCompletions(updates);
  playSfx('quest', { volume: 0.72, rate: 1.05 });
  pushActivity(
    winterWalkState.repeat
      ? `Winter Walk complete. ${result.imgEarned.toLocaleString()} iMG gathered.`
      : `Winter Walk complete. +${WINTER_WALK_ICE_REWARD} Ice · ${result.imgEarned.toLocaleString()} iMG gathered.`
  );
  savePlayerState();
  renderWinterWalkHud();
  await returnFromWinterWalk();
  return true;
}

function handleWinterPortal(target, verbId) {
  if (!winterWalkIsInstanced() || verbId !== 'enter' || target?.state?.active === false) return;
  if (target.state.stage === 'surface') enterWinterHavenStage();
  else if (target.state.stage === 'haven') reenterWinterWalkStage();
  else completeWinterWalk();
}

function confirmLeaveWinterWalk() {
  if (!winterWalkIsInstanced()) return;
  openScriptedQuestDialogue({
    title: 'Winter Walk',
    kicker: 'Leave the winter path?',
    cancelable: true,
    beats: [
      {
        text: 'The cold path will close behind you, but you can begin another walk later.',
        response: 'Leave Winter Walk',
      },
    ],
    onComplete: () => returnFromWinterWalk({ abandon: true }),
  });
}

function updateWinterWalk(dt) {
  if (!winterWalkIsInstanced() || winterWalkTransitionBusy) return;
  const now = Date.now();
  updateWinterSnow(dt);
  if (winterWalkRemainingMs(winterWalkState, now) <= 0) {
    expireWinterWalk(winterWalkState, now);
    pushActivity('The five-minute Winter Walk timer ran out.');
    returnFromWinterWalk({ expired: true });
    return;
  }
  for (const entry of winterWalkMotes) {
    if (entry.collected || !entry.sprite?.parent) continue;
    entry.sprite.phase += 0.05 * dt;
    entry.sprite.y = entry.sprite.baseY + Math.sin(entry.sprite.phase) * 8;
    const pulse = 1 + Math.sin(entry.sprite.phase * 1.5) * 0.075;
    entry.sprite.scale.set(entry.sprite.baseScale * pulse);
    if (!menuTarget && Math.hypot(entry.sprite.x - player.x, entry.sprite.y - (player.y - 28)) < 48) {
      collectWinterWalkMote(entry);
    }
  }
  if (
    !menuTarget &&
    winterWalkPortal?.sprite &&
    winterWalkPortal.state.active !== false &&
    Math.hypot(
      winterWalkPortal.sprite.x - player.x,
      winterWalkPortal.sprite.y - player.y
    ) < 62
  ) {
    handleWinterPortal(winterWalkPortal, 'enter');
    return;
  }
  const autoplay = new URLSearchParams(location.search).get('winterautoplay');
  const autoplayStages = {
    surface: ['surface'],
    haven: ['surface', 'haven'],
    return: ['surface', 'haven', 'return'],
  };
  const autoplayActive =
    autoplay === '1' || autoplayStages[autoplay]?.includes(winterWalkState.stage);
  if (autoplayActive && now >= winterWalkAutoNextAt) {
    winterWalkAutoNextAt = now + 260;
    if (isQuestDialogueOpen()) {
      advanceQuestDialogue();
    } else {
      const next = winterWalkMotes.find((entry) => !entry.collected && entry.sprite?.parent);
      const target = next?.sprite || winterWalkPortal?.sprite;
      if (target && player) {
        player.x = target.x;
        player.y = next ? target.y + 28 : target.y;
        player.vx = 0;
        player.vy = 0;
        player.onGround = true;
      }
    }
  }
  renderWinterWalkHud();
}

function summersDayIsInstanced() {
  return Boolean(
    summersDayRun &&
      [SUMMERS_DAY_STREET_TSID, SUMMERS_DAY_BONUS_ID].includes(currentStreetTsid)
  );
}

/** The instance holding the imported street now (puzzles-feature runs its boxes inside it). */
function summersDayHeldInstance() {
  return summersDayRun?.stage === 'main' && currentStreetTsid === SUMMERS_DAY_STREET_TSID
    ? 'summers-day'
    : null;
}

function summersDayLocationLabel(tsid = currentStreetTsid) {
  if (tsid === SUMMERS_DAY_STREET_TSID) {
    // G363: the blue_and_white instance (blue_and_white_part1.js 98): no hub line (location.js 3311).
    return { street: 'A Summer’s Day', hub: '' };
  }
  if (tsid === SUMMERS_DAY_BONUS_ID) {
    return { street: 'Annex of A Summer’s Day', hub: '' };
  }
  return null;
}

/**
 * The memory's own silhouette light: the main street's realmid and plus layers (contrast -100,
 * brightness 100, saturation -100) for the Annex's decos, and its middleground (contrast -100,
 * tintAmount 100, brightness 100) for the avatar and the quoins, white in both recordings.
 */
const SUMMERS_DAY_DECO_LIGHT = Object.freeze({ contrast: -100, brightness: 100, saturation: -100 });
const SUMMERS_DAY_ENTITY_LIGHT = Object.freeze({ contrast: -100, tintAmount: 100, brightness: 100 });
const SUMMERS_DAY_ANNEX_SURROUND = 0xe9eeee;

function summersDayLightFilter(filters) {
  const filter = new PIXI.ColorMatrixFilter();
  filter.matrix = glitchLayerMatrix(filters);
  return filter;
}

/** A Tiny Speck deco from assets/decos/groddle, anchored at its foot centre, sized w x h. */
function summersDayAnnexDeco(name, x, y, w, h, { flip = false, z = 0 } = {}) {
  const sprite = new PIXI.Sprite(textureFromUrl(`assets/decos/groddle/${name}.png`));
  sprite.anchor.set(0.5, 1);
  sprite.position.set(x, y);
  sprite.zIndex = z;
  sprite.label = name;
  const fit = () => {
    const tw = sprite.texture?.orig?.width || sprite.texture?.width || 1;
    const th = sprite.texture?.orig?.height || sprite.texture?.height || 1;
    sprite.scale.set((flip ? -1 : 1) * (w / tw), h / th);
  };
  fit();
  sprite.texture?.once?.('update', fit);
  sprite.texture?.source?.once?.('update', fit);
  return sprite;
}

/**
 * The Annex as the recordings show it (js/summers-day.js): the pale surround, the blue cavity
 * from the grassy bowl up the straight walls to the pitched roof, its decos in the memory's
 * white light, and the veil over the climb until the bubble over the bowl is touched.
 */
function drawSummersDayBonusBackground() {
  const root = new PIXI.Container();
  root.label = 'summers-day-annex-background';
  root.sortableChildren = true;
  root.worldW = SUMMERS_DAY_ANNEX_W;
  root.worldH = SUMMERS_DAY_ANNEX_H;
  const { left, right } = SUMMERS_DAY_ANNEX_WALLS;
  const wash = new PIXI.Graphics();
  // Past the room's edges too, so a tall or wide view never shows the default skirt.
  wash.rect(-800, -800, root.worldW + 1600, root.worldH + 1600).fill(SUMMERS_DAY_ANNEX_SURROUND);
  wash.zIndex = -1000;
  root.addChild(wash);
  // The cavity: roof, the right wall (its brushed edge), the bowl, the left wall back up.
  const roof = SUMMERS_DAY_ANNEX_ROOF;
  const bowl = SUMMERS_DAY_ANNEX_BOWL;
  const ragged = (x, y0, y1, side) => {
    const out = [];
    const step = 26;
    const n = Math.max(1, Math.round(Math.abs(y1 - y0) / step));
    for (let i = 1; i < n; i += 1) {
      const y = y0 + ((y1 - y0) * i) / n;
      out.push(x + side * (3 + 4 * Math.sin(i * 2.3 + x)), y);
    }
    return out;
  };
  const outline = [
    ...roof.flatMap((p) => [p.x, p.y]),
    ...ragged(right, roof.at(-1).y, bowl.at(-1).y, 1),
    ...[...bowl].reverse().flatMap((p) => [p.x, p.y]),
    ...ragged(left, bowl[0].y, roof[0].y, -1),
  ];
  const sky = new PIXI.FillGradient({ start: { x: 0, y: 0 }, end: { x: 0, y: 1 }, textureSpace: 'local' });
  sky.addColorStop(0, 0xdbe8ed);
  sky.addColorStop(0.42, 0xaed1e1);
  sky.addColorStop(1, 0x67a7c8);
  const cavity = new PIXI.Graphics();
  cavity.poly(outline).fill(sky);
  cavity.zIndex = -900;
  root.addChild(cavity);

  // Decos, Tiny Speck's own (the main memory's set), in its white light.
  const decos = new PIXI.Container();
  decos.label = 'summers-day-annex-decos';
  decos.sortableChildren = true;
  decos.zIndex = -600;
  decos.filters = [summersDayLightFilter(SUMMERS_DAY_DECO_LIGHT)];
  root.addChild(decos);
  for (const shelf of SUMMERS_DAY_ANNEX_SHELVES) {
    // wall_shelf1 (452 x 60), drawn with its top on the line.
    decos.addChild(summersDayAnnexDeco('wall_shelf1', (shelf.x1 + shelf.x2) / 2, shelf.y1 + 12, shelf.x2 - shelf.x1 + 4, 14, { z: 10 }));
  }
  // The ladder exit on the top centre shelf, into the roof.
  const ladder = SUMMERS_DAY_ANNEX_LADDER;
  decos.addChild(summersDayAnnexDeco('firebog_ladder', ladder.x, ladder.y + 2, ladder.w, ladder.h + 2, { z: 8 }));
  // The bowl: a log railing at right (stood on), a ladder stub at left, grass and a reed.
  const rail = SUMMERS_DAY_ANNEX_RAILING;
  decos.addChild(summersDayAnnexDeco('railing', (rail.x1 + rail.x2) / 2, SUMMERS_DAY_ANNEX_FLOOR_Y + 10, rail.x2 - rail.x1, 40, { z: 6 }));
  decos.addChild(summersDayAnnexDeco('firebog_ladder', 508, SUMMERS_DAY_ANNEX_FLOOR_Y + 30, 62, 74, { z: 5 }));
  decos.addChild(summersDayAnnexDeco('plant_fern_4', 404, 942, 26, 70, { z: 7 }));
  const tufts = [[334, 884, 0.8], [372, 912, 1], [446, 966, 0.7], [560, 1004, 0.6], [612, 1004, 0.8], [668, 1004, 0.5], [760, 1004, 0.6], [902, 966, 0.9], [948, 924, 1], [962, 900, 0.7]];
  tufts.forEach(([x, y, k], i) => {
    decos.addChild(summersDayAnnexDeco('plant_grass_1', x, y + 4, 22 * k, 46 * k, { flip: i % 2 === 1, z: 9 }));
  });
  // The floor under the bowl: the surround again, over the decos' feet.
  const ground = new PIXI.Graphics();
  ground.poly([
    left - 20, bowl[0].y + 6,
    ...bowl.flatMap((p) => [p.x, p.y + 6]),
    right + 20, bowl.at(-1).y + 6,
    right + 20, root.worldH,
    left - 20, root.worldH,
  ]).fill(SUMMERS_DAY_ANNEX_SURROUND);
  ground.zIndex = -500;
  root.addChild(ground);

  // The veil over the climb: pale down to the bowl's grassy rim (306 1:17).
  const veil = new PIXI.Graphics();
  const vy = SUMMERS_DAY_ANNEX_VEIL_Y;
  // The rim, right to left: grass blades standing up out of the bowl into the pale.
  const rim = [];
  const wobble = (i, k) => Math.abs(Math.sin(i * k + 0.7) * Math.cos(i * 0.37));
  for (let x = right + 10, i = 0; x >= left - 10; i += 1) {
    // Uneven blades: a root on the rim, then a tip leaning a little, 6 to 50 px tall.
    const blade = 6 + 30 * wobble(i, 1.9) + (wobble(i, 0.61) > 0.8 ? 14 : 0);
    const lean = 3 * Math.sin(i * 2.9);
    rim.push(x, vy - 2 * wobble(i, 3.1), x - 3 + lean, vy - blade);
    x -= 5 + 7 * wobble(i, 1.3);
  }
  veil.poly([left - 24, 0, right + 24, 0, right + 24, vy - 40, ...rim, left - 24, vy - 40]).fill(SUMMERS_DAY_ANNEX_SURROUND);
  veil.zIndex = -400;
  veil.label = 'summers-day-annex-veil';
  root.addChild(veil);
  root.summersDayAnnexVeil = veil;
  root.summersDayAnnexArt = 'memory-wall-shelves-quoins-and-ladder';
  return root;
}

/** The seven quoins over the shelves and the bubble over the bowl that reveals the climb. */
function spawnSummersDayBonusRoom() {
  summersDayBonusQuoins = SUMMERS_DAY_ANNEX_PICKUPS.map((pickup, index) => {
    const sprite = spawnWorldQuoin(pickup, pickup.type, { useExactY: true, phaseIndex: index });
    sprite.alpha = 0;
    return { index, sprite, type: pickup.type, collected: false };
  });
  // The switch over the bowl: "you'd hit a switch to get the loot inside" (the Glitch Tribute
  // Blog's Annex post). A white dot on a short string from the rim (306 1:17, cYK 3:08): the
  // main memory's own pulseDot, playing its pulse. It pays nothing.
  const reveal = new PIXI.Container();
  reveal.position.set(SUMMERS_DAY_ANNEX_REVEAL.x, SUMMERS_DAY_ANNEX_REVEAL.y);
  reveal.zIndex = 32;
  const string = new PIXI.Graphics();
  string.moveTo(0, SUMMERS_DAY_ANNEX_VEIL_Y - SUMMERS_DAY_ANNEX_REVEAL.y - 12).lineTo(0, -9).stroke({ width: 1.5, color: 0xf4f8f9 });
  reveal.addChild(string);
  const dot = sceneAnim(PIXI, 'pulseDot', 0, 0, { scale: 0.34, ay: 0.5 });
  reveal.addChild(dot);
  reveal.pulse = dot;
  entityLayer.addChild(reveal);
  summersDayAnnexReveal = { sprite: reveal, touched: false, fade: 0 };
  const ladder = SUMMERS_DAY_ANNEX_LADDER;
  summersDayExit = {
    id: 'annex_exit',
    sprite: null,
    x: ladder.x,
    y: ladder.y - ladder.h,
    art: 'recovered-firebog-ladder',
  };
}

/** Touching the bubble over the bowl (or climbing past the rim) lifts the veil. */
function revealSummersDayAnnex() {
  if (!summersDayAnnexReveal || summersDayAnnexReveal.touched) return false;
  summersDayAnnexReveal.touched = true;
  const { sprite } = summersDayAnnexReveal;
  if (sprite?.parent) {
    burst(sprite.x, sprite.y, 0xdff8ff, 9);
    sprite.parent.removeChild(sprite);
  }
  playSfx('quoin', { volume: 0.32, rate: 1.24 });
  return true;
}

function tickSummersDayAnnexReveal(dt) {
  const reveal = summersDayAnnexReveal;
  if (!reveal) return;
  if (!reveal.touched) {
    const { sprite } = reveal;
    if (sprite.pulse) syncAnim(sprite.pulse);
    if (
      Math.hypot(sprite.x - player.x, sprite.y - (player.y - 28)) < 46 ||
      player.y < SUMMERS_DAY_ANNEX_VEIL_Y - 24
    ) revealSummersDayAnnex();
  } else if (reveal.fade < 1) {
    reveal.fade = Math.min(1, reveal.fade + 0.03 * dt);
  }
  const veil = bgLayer?.summersDayAnnexVeil;
  if (veil) veil.alpha = 1 - reveal.fade;
  for (const entry of summersDayBonusQuoins) {
    if (!entry.collected && entry.sprite) entry.sprite.alpha = reveal.fade;
  }
}

function renderSummersDayHud() {
  const hud = document.getElementById('summers-day-hud');
  const visible = summersDayIsInstanced();
  if (hud) hud.hidden = !visible;
  if (!visible) return;
  const remaining = summersDayRemainingMs(summersDayRun);
  const seconds = Math.ceil(remaining / 1000);
  const progress = summersDayProgress(summersDayRun);
  const stage = hud.querySelector('[data-summer-stage]');
  const timer = hud.querySelector('[data-summer-timer]');
  const objective = hud.querySelector('[data-summer-objective]');
  const count = hud.querySelector('[data-summer-progress]');
  const bonus = hud.querySelector('[data-summer-bonus]');
  if (stage) stage.textContent = summersDayRun.stage === 'bonus' ? 'The Annex' : 'The shared memory';
  if (timer) {
    timer.textContent = `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`;
    timer.classList.toggle('is-low', remaining <= 30_000);
  }
  if (objective) objective.textContent = summersDayObjective(summersDayRun);
  if (count) count.textContent =
    summersDayRun.stage === 'bonus'
      ? 'Memory unfolded'
      : `${progress.current} / ${progress.total} moments`;
  if (bonus) {
    bonus.textContent =
      summersDayRun.stage === 'bonus'
        ? `${progress.bonusCollected} / ${progress.bonusTotal} memory quoins`
        : 'Follow what the Giants remember';
  }
  if (app?.canvas) {
    app.canvas.dataset.summerDayStatus = summersDayRun.status;
    app.canvas.dataset.summerDayStage = summersDayRun.stage;
    app.canvas.dataset.summerDayCheckpoint =
      summersDayNextCheckpoint(summersDayRun) || 'complete';
    app.canvas.dataset.summerDayProgress = `${progress.current}/${progress.total}`;
    app.canvas.dataset.summerDayRemaining = String(remaining);
    app.canvas.dataset.summerDayBonusQuoins = `${progress.bonusCollected}/${progress.bonusTotal}`;
    app.canvas.dataset.summerDayBonusImg = String(summersDayRun.bonusImgEarned || 0);
    app.canvas.dataset.summerDayObjective = summersDayObjective(summersDayRun);
    app.canvas.dataset.summerDayMainTsid = SUMMERS_DAY_MAIN_PRODUCTION_TSID;
    app.canvas.dataset.summerDayBonusTsid = SUMMERS_DAY_BONUS_PRODUCTION_TSID;
    // The memory is Tiny Speck's own street, its guides the street's flitterbug_limbo1 decos.
    app.canvas.dataset.summerDayMainArt =
      summersDayRun.stage === 'main' ? 'tiny-speck-street' : 'not-in-main';
    app.canvas.dataset.summerDayStreet = SUMMERS_DAY_STREET_TSID;
    app.canvas.dataset.summerDayGuideArt = 'source-flitterbug';
    app.canvas.dataset.summerDayAnnexArt =
      bgLayer?.summersDayAnnexArt || 'not-in-annex';
    app.canvas.dataset.summerDayAnnexDots = String(SUMMERS_DAY_BONUS_DOT_COUNT);
    app.canvas.dataset.summerDayAnnexDotReward = String(SUMMERS_DAY_BONUS_DOT_IMG);
    app.canvas.dataset.summerDayAnnexPickups = SUMMERS_DAY_ANNEX_PICKUPS.map((p) => `${p.type}:${p.amount}`).join(',');
    app.canvas.dataset.summerDayAnnexRevealed = summersDayAnnexReveal?.touched ? '1' : '0';
    app.canvas.dataset.summerDayAnnexExit =
      summersDayExit?.art || 'not-in-annex';
    app.canvas.dataset.summerDayGuide =
      SUMMERS_DAY_GUIDE_LINES[summersDayNextCheckpoint(summersDayRun)] || '';
  }
}

/** The Annex (LNVIL1E14M13K5I, not archived): the room the recordings show (js/summers-day.js). */
function setupSummersDayAnnex() {
  clearWorldEntities();
  if (bgLayer && world) {
    world.removeChild(bgLayer);
    bgLayer.destroy({ children: true });
  }
  bgLayer = drawSummersDayBonusBackground();
  world.addChildAt(bgLayer, 0);
  currentStreetTsid = SUMMERS_DAY_BONUS_ID;
  const label = summersDayLocationLabel();
  // Its walls, shelves, roof and ladder as street data: the same the reach tests walk.
  const annex = summersDayAnnexStreet();
  currentStreet = {
    ...annex,
    tsid: currentStreetTsid,
    label: label.street,
    hubName: label.hub,
    // The memory's blue-and-white light is its own: no Dametime tint.
    ownLight: true,
  };
  WORLD_W = bgLayer.worldW;
  GROUND_Y = SUMMERS_DAY_ANNEX_FLOOR_Y;
  streetPlatforms = platformsScreen(annex);
  bgLayer.platformsScreen = streetPlatforms;
  streetWalls = wallsScreen(annex);
  climb = { active: false, wall: null };
  Object.assign(jumpState, createJumpState(movementNow()));
  // The avatar and the quoins in the memory's white light, as on the main street.
  if (entityLayer) entityLayer.filters = [summersDayLightFilter(SUMMERS_DAY_ENTITY_LIGHT)];
  spawnSummersDayBonusRoom();
  if (player) {
    player.x = SUMMERS_DAY_ANNEX_SPAWN.x;
    player.y = SUMMERS_DAY_ANNEX_SPAWN.y;
    player.vx = 0;
    player.vy = 0;
    player.onGround = true;
    player.rotation = 0;
    noteGrounded(jumpState, true, movementNow());
  }
  camTarget = cameraTargetForPlayer(player.x);
  const summerCameraAnchor = 0.64;
  camY = cameraTargetY(
    player.y,
    activeCameraWorldHeight(summerCameraAnchor),
    LOCATION_VIEW_H,
    summerCameraAnchor
  );
  world.x = -camTarget;
  world.y = -camY;
  summersDayNameplate(label);
}

function summersDayNameplate(label) {
  const name = document.getElementById('street-name');
  if (name) {
    name.textContent = label.hub ? `${label.street} · ${label.hub}` : label.street;
    name.dataset.tsid = currentStreetTsid;
  }
  savePlayerLocation(summersDaySourceLocation);
  updateDametimeChrome();
  renderSummersDayHud();
  updateHud();
}

/**
 * The main memory: Tiny Speck's own copy of the template, held as the private instance.
 * Its arrival scripts, physics (pc_scale 0.622) and rebuilt boxes start in enterStreet's
 * feature hooks; onStarted's 3709, -258 is the spawn.
 */
async function setupSummersDayMain() {
  const spawn = summersDayStreetPoint(SUMMERS_DAY_SOURCE_SPAWN);
  summersDayAutoStep = 0;
  await enterStreet(SUMMERS_DAY_STREET_TSID, {
    spawnX: spawn.x,
    spawnY: spawn.y,
    quiet: true,
    bypassFeatureGates: true,
  });
  if (!summersDayRun || currentStreetTsid !== SUMMERS_DAY_STREET_TSID) return;
  const label = summersDayLocationLabel();
  currentStreet.label = label.street;
  currentStreet.hubName = label.hub;
  // The memory's blue-and-white light is its own: no Dametime tint.
  currentStreet.ownLight = true;
  summersDayNameplate(label);
}

async function transitionIntoSummersDay(stage, useTransition = true) {
  const setup = () => (stage === 'bonus' ? setupSummersDayAnnex() : setupSummersDayMain());
  const el = document.getElementById('screen-transition');
  if (!useTransition || !el) {
    await setup();
    return;
  }
  const label = stage === 'bonus' ? 'Annex of A Summer’s Day' : 'A Summer’s Day';
  await runStreetTransition(el, {
    fromLabel: currentStreet?.label || '',
    fromHub: currentStreet?.hubName || '',
    toLabel: label,
    toHub: '',
    topColor: 0xf9fdff,
    bottomColor: 0xb8dce8,
    onMid: async () => setup(),
  });
}

async function startSummersDay(opts = {}) {
  if (summersDayStartPromise) return summersDayStartPromise;
  if (summersDayIsInstanced()) return summersDayRun;
  summersDayStartPromise = (async () => {
    const repeat = Boolean(opts.repeat);
    const questId = repeat ? SUMMERS_DAY_REPEAT_QUEST_ID : SUMMERS_DAY_QUEST_ID;
    if (repeat) {
      questState.completed = questState.completed.filter(
        (id) => id !== SUMMERS_DAY_REPEAT_QUEST_ID
      );
    }
    if (!questState.active[questId]) {
      const assigned = assignQuest(questState, questId, { ignorePrereq: true });
      if (!assigned.ok) return null;
    }
    closeQuestPanel();
    closeQuestDialogue({ force: true });
    closePackPopover();
    summersDaySourceLocation = opts.sourceLocation || instanceSourceHere({
      tsid: currentStreetTsid,
      x: player?.x ?? WORLD_W * 0.5,
      y: player?.y ?? GROUND_Y,
    });
    summersDayRun = createSummersDayRun({
      now: Date.now(),
      sourceLocation: summersDaySourceLocation,
      repeat,
    });
    summersDayAutoNextAt = 0;
    savePlayerLocation(summersDaySourceLocation);
    await transitionIntoSummersDay('main', opts.useTransition !== false);
    pushActivity('A Summer’s Day: follow the collision of birds, stones, water, and blue lights.');
    toast('Five minutes. Let the Giants’ memory unfold.', 3600);
    return summersDayRun;
  })();
  try {
    return await summersDayStartPromise;
  } finally {
    summersDayStartPromise = null;
  }
}

/**
 * A moment the street fired (puzzles-feature, engine.instanceMoment): its own events
 * already showed the signs, moved the stones and played the sounds.
 */
function advanceSummersDayMoment(id) {
  if (!summersDayRun || summersDayRun.stage !== 'main' || !summersDayIsInstanced()) return false;
  const result = advanceSummersDayCheckpoint(summersDayRun, id, Date.now());
  if (!result.ok) return false;
  renderSummersDayHud();
  if (id === 'exit') enterSummersDayAnnex();
  return true;
}

async function enterSummersDayAnnex() {
  if (!summersDayIsInstanced() || summersDayTransitionBusy) return false;
  const result = enterSummersDayBonus(summersDayRun, Date.now());
  if (!result.ok) return false;
  summersDayTransitionBusy = true;
  keys.clear();
  try {
    await transitionIntoSummersDay('bonus', true);
    pushActivity('The memory opens into the Annex of A Summer’s Day.');
    toast('Two minutes in the Annex. Climb toward the way home.', 3200);
    return true;
  } finally {
    summersDayTransitionBusy = false;
  }
}

async function returnFromSummersDay({ expired = false, abandon = false, completionText = '' } = {}) {
  if (!summersDayRun || summersDayTransitionBusy) return false;
  summersDayTransitionBusy = true;
  const destination = summersDaySourceLocation?.tsid
    ? { ...summersDaySourceLocation }
    : { tsid: STREET_INDEX.default };
  const questId = summersDayRun.repeat
    ? SUMMERS_DAY_REPEAT_QUEST_ID
    : SUMMERS_DAY_QUEST_ID;
  if (expired) expireSummersDay(summersDayRun, questState, Date.now());
  else if (abandon) abandonSummersDay(summersDayRun, questState, Date.now());
  if (expired || abandon) delete questState.active[questId];
  const status = expired ? 'expired' : abandon ? 'abandoned' : summersDayRun.status;
  closeQuestDialogue({ force: true });
  keys.clear();
  summersDayRun = null;
  summersDaySourceLocation = null;
  summersDayBonusQuoins = [];
  summersDayExit = null;
  summersDayAnnexReveal = null;
  const hud = document.getElementById('summers-day-hud');
  if (hud) hud.hidden = true;
  try {
    await enterStreetWithTransition(destination.tsid, {
      spawnX: destination.x,
      spawnY: destination.y,
      quiet: true,
    });
    savePlayerLocation(destination);
    updateDametimeChrome();
    savePlayerState();
    if (app?.canvas) {
      app.canvas.dataset.summerDayStatus = status;
      app.canvas.dataset.summerDayCompleted = status === 'complete' ? '1' : '0';
      app.canvas.dataset.summerDayPendingQurazies = String(
        ensureSummersDayStory(questState).pendingQurazies
      );
    }
    if (expired) toast('The summer memory faded. You can try again later.', 4200);
    else if (abandon) toast('You let the summer memory go for now.', 3200);
    else if (completionText) {
      openScriptedQuestDialogue({
        title: 'A Summer’s Day',
        kicker: 'The Giants remember',
        beats: [{ text: completionText, response: 'Let my imagination go wild' }],
      });
    }
    updateHud();
    return true;
  } finally {
    summersDayTransitionBusy = false;
  }
}

async function completeSummersDay() {
  if (!summersDayIsInstanced() || summersDayTransitionBusy) return false;
  const wasRepeat = summersDayRun.repeat;
  const result = finishSummersDay(summersDayRun, questState, Date.now());
  if (!result.ok) return false;
  const questId = wasRepeat ? SUMMERS_DAY_REPEAT_QUEST_ID : SUMMERS_DAY_QUEST_ID;
  const active = questState.active?.[questId];
  if (active) active.progress.leave = 1;
  const completed = active ? completeQuest(questState, questId, pc) : null;
  const updates = completed?.ok
    ? [{ classTsid: questId, completed: true, rewards: completed.rewards, def: completed.def }]
    : [];
  announceQuestCompletions(updates);
  playSfx('quest', { volume: 0.74, rate: 1.08 });
  pushActivity(
    wasRepeat
      ? 'You reminisce A Summer’s Day and return to Ur.'
      : 'A Summer’s Day complete. Five Qurazy quoins gather around you.'
  );
  savePlayerState();
  renderSummersDayHud();
  const copy = (wasRepeat ? SUMMERS_DAY_REPEAT_COMPLETION : SUMMERS_DAY_COMPLETION)
    .replace('{pc_label}', 'friend');
  await returnFromSummersDay({ completionText: copy });
  return true;
}

function confirmLeaveSummersDay() {
  if (!summersDayIsInstanced()) return;
  openScriptedQuestDialogue({
    title: 'A Summer’s Day',
    kicker: 'Leave the memory?',
    cancelable: true,
    beats: [{
      text: 'This private memory will dissolve behind you, but you can ask to visit again.',
      response: 'Leave the memory',
    }],
    onComplete: () => returnFromSummersDay({ abandon: true }),
  });
}

/** In the pool's swim: the street's own set_phys (jetpack) is on until a reset_phys box. */
function summersDayInBuoyancy() {
  return Boolean(
    summersDayRun?.stage === 'main' &&
      summersDayIsInstanced() &&
      features.physics(engine).jetpack === true
  );
}

function updateSummersDay(dt) {
  if (!summersDayIsInstanced() || summersDayTransitionBusy) return;
  const now = Date.now();
  if (summersDayRemainingMs(summersDayRun, now) <= 0) {
    pushActivity(
      summersDayRun.stage === 'bonus'
        ? 'The two-minute Annex faded.'
        : 'The five-minute summer memory faded.'
    );
    returnFromSummersDay({ expired: true });
    return;
  }
  if (summersDayRun.stage !== 'main') {
    tickSummersDayAnnexReveal(dt);
    for (const entry of summersDayBonusQuoins) {
      const q = entry.sprite;
      if (entry.collected || !q?.parent) continue;
      q.frameClock = advanceQuoinClock(q.frameClock, q.animationSpeed, dt, q.totalFrames);
      q.gotoAndStop(Math.floor(q.frameClock) % q.totalFrames);
      q.phase += 0.045 * dt;
      q.y = q.baseY + Math.sin(q.phase) * 4;
      if (!summersDayAnnexReveal?.touched) continue;
      if (menuTarget || !quoinTouches(q, player.x, player.y, { scale: features.query('avatarBodyScale', engine) ?? 1, quoinScale: q.scale?.y || 1 })) continue;
      const result = collectSummersDayBonusQuoin(
        summersDayRun,
        entry.index,
        Date.now(),
        SUMMERS_DAY_BONUS_DOT_COUNT
      );
      if (!result.ok) continue;
      entry.collected = true;
      // items/quoin.js 162-187: iMG takes the mood bonus, mood and currants add as they are.
      const landed = creditQuoinStat(pc, result.type, result.amount);
      if (result.type === 'xp') summersDayRun.bonusImgEarned += landed - result.amount;
      const label = QUOIN_TYPES[result.type]?.label || 'iMG';
      const { x, y } = q;
      entityLayer.removeChild(q);
      playSfx('quoin', { volume: 0.48, rate: 1.08 });
      floatText(x, y - 18, `+${landed} ${label}`, 0xeafcff);
      burst(x, y, 0xdff8ff, 11);
      pushActivity(`A memory quoin: +${landed} ${label}.`);
      updateHud();
    }
    // The exit: climbing the ladder up into the roof leaves the memory (cYK 3:25).
    if (summersDayAnnexAtExit(player)) {
      completeSummersDay();
      return;
    }
  }
  const autoplay = new URLSearchParams(location.search).get('summerautoplay');
  const autoplayActive =
    autoplay === '1' ||
    (['main', 'water', 'bonus'].includes(autoplay) && summersDayRun.stage === 'main');
  if (autoplayActive && now >= summersDayAutoNextAt) {
    summersDayAutoNextAt = now + 190;
    if (isQuestDialogueOpen()) {
      advanceQuestDialogue();
      return;
    }
    if (summersDayRun.stage === 'main') {
      summersDayAutoplayStep(autoplay);
    } else {
      // The bubble over the bowl, each quoin, then the ladder's top.
      const nextQuoin = summersDayAnnexReveal?.touched
        ? summersDayBonusQuoins.find((entry) => !entry.collected && entry.sprite?.parent)
        : null;
      const target = !summersDayAnnexReveal?.touched
        ? summersDayAnnexReveal?.sprite
        : nextQuoin?.sprite || summersDayExit;
      if (target) {
        player.x = target.x;
        player.y = target === summersDayExit ? target.y + 20 : target.y + 28;
        player.vx = 0;
        player.vy = 0;
        player.onGround = true;
      }
    }
  }
  if (app?.canvas) app.canvas.dataset.summerDayBuoyancy = summersDayInBuoyancy() ? '1' : '0';
  renderSummersDayHud();
}

/**
 * QA autoplay on the real street: stand in each rebuilt box in turn (SUMMERS_DAY_ROUTE)
 * and let the street's own events run; `reset` steps wait for the swim to end. `water`
 * stays hovering at the first orb, swimming.
 */
function summersDayAutoplayStep(mode) {
  if (!summersDayIsInstanced() || currentStreetTsid !== SUMMERS_DAY_STREET_TSID) return;
  const reached = new Set(summersDayRun.checkpoints);
  while (summersDayAutoStep < SUMMERS_DAY_ROUTE.length) {
    const step = SUMMERS_DAY_ROUTE[summersDayAutoStep];
    const done = step.id === 'reset' ? !summersDayInBuoyancy() && reached.has('orb_4') : reached.has(step.id);
    if (!done) break;
    if (mode === 'water' && step.id === 'orb_1') break;
    summersDayAutoStep += 1;
  }
  const step = SUMMERS_DAY_ROUTE[summersDayAutoStep];
  if (!step) return;
  const at = summersDayStreetPoint(step);
  player.x = at.x;
  player.y = at.y;
  player.vx = 0;
  player.vy = 0;
  player.onGround = false;
}

function rookWoodsIsInstanced() {
  return Boolean(rookWoodsState && currentStreetTsid === ROOK_WOODS_STREET_ID);
}

function rookEggTexture(state = ROOK_EGG_INITIAL_STATE) {
  if (!rookEggTextures.length) {
    const texture = textureFromUrl('assets/sprites/quests/rook-woods/rook-egg-states.webp');
    rookEggTextures = Array.from(
      { length: 5 },
      (_, index) =>
        frameTexture(texture.source, new PIXI.Rectangle(index * 171, 0, 171, 168))
    );
  }
  const index = clamp(ROOK_EGG_INITIAL_STATE - Number(state || 5), 0, 4);
  return rookEggTextures[index] || rookEggTextures[0];
}

function drawRookWoodsBackground() {
  const root = new PIXI.Container();
  root.sortableChildren = true;
  root.worldW = 2300;
  root.worldH = 900;

  const sky = new PIXI.Graphics();
  sky.rect(0, 0, root.worldW, root.worldH).fill(0x262a24);
  sky.rect(0, 245, root.worldW, 350).fill({ color: 0x394038, alpha: 0.76 });
  sky.rect(0, 595, root.worldW, 305).fill({ color: 0x1b211d, alpha: 0.88 });
  sky.zIndex = -1000;
  root.addChild(sky);

  const hills = new PIXI.Graphics();
  hills.zIndex = -900;
  hills.poly([
    0, 650, 210, 505, 420, 620, 660, 470, 890, 625, 1120, 485,
    1360, 610, 1580, 450, 1820, 615, 2050, 490, 2300, 625, 2300, 900, 0, 900,
  ]);
  hills.fill({ color: 0x212923, alpha: 0.7 });
  root.addChild(hills);

  const mist = new PIXI.Graphics();
  mist.zIndex = -880;
  for (let i = 0; i < 14; i += 1) {
    mist.ellipse(100 + i * 175, 510 + (i % 4) * 34, 230, 58).fill({ color: 0x8b9184, alpha: 0.035 + (i % 3) * 0.012 });
  }
  root.addChild(mist);

  const layerById = new Map(
    ROOK_FOREST_DEPTH_LAYERS.map((layer) => [layer.id, layer])
  );
  for (const spec of ROOK_FOREST_DECOS) {
    const layer = layerById.get(spec.layer);
    if (!layer) continue;
    const sprite = new PIXI.Sprite(
      textureFromUrl(`assets/decos/groddle/${spec.asset}`)
    );
    sprite.anchor.set(spec.anchorX, spec.anchorY);
    sprite.position.set(spec.x, spec.y);
    sprite.scale.set(spec.scaleX, spec.scaleY);
    sprite.rotation = spec.rotation;
    sprite.tint = layer.tint;
    sprite.alpha = layer.alpha * spec.alpha;
    sprite.zIndex = layer.zIndex;
    sprite.eventMode = 'none';
    root.addChild(sprite);
  }

  const limbs = new PIXI.Graphics();
  limbs.zIndex = -165;
  for (const limb of ROOK_FOREST_LIMBS) {
    const [startX, startY, ...rest] = limb.points;
    limbs.moveTo(startX, startY);
    for (let index = 0; index < rest.length; index += 2) {
      limbs.lineTo(rest[index], rest[index + 1]);
    }
    limbs.stroke({ width: limb.width + 11, color: 0x050806, alpha: limb.alpha * 0.42 });
    limbs.moveTo(startX, startY);
    for (let index = 0; index < rest.length; index += 2) {
      limbs.lineTo(rest[index], rest[index + 1]);
    }
    limbs.stroke({ width: limb.width, color: 0x0a0d0a, alpha: limb.alpha ?? 1 });
    limbs.moveTo(startX, startY - limb.width * 0.13);
    for (let index = 0; index < rest.length; index += 2) {
      limbs.lineTo(rest[index], rest[index + 1] - limb.width * 0.13);
    }
    limbs.stroke({ width: Math.max(3, limb.width * 0.1), color: 0x343a2e, alpha: limb.alpha * 0.24 });
  }
  root.addChild(limbs);

  const platforms = ROOK_WOODS_PLATFORMS.map((platform) => ({ ...platform }));

  const path = new PIXI.Graphics();
  path.zIndex = -80;
  for (const platform of platforms) {
    path.moveTo(platform.x1, platform.y1 + 16);
    path.lineTo(platform.x2, platform.y2 + 16);
    path.stroke({ width: 62, color: 0x0b0e0c, alpha: 1 });
    path.moveTo(platform.x1, platform.y1 + 3);
    path.lineTo(platform.x2, platform.y2 + 3);
    path.stroke({ width: 27, color: 0x20251c, alpha: 1 });
    path.moveTo(platform.x1, platform.y1 - 2);
    path.lineTo(platform.x2, platform.y2 - 2);
    path.stroke({ width: 5, color: 0x5d624b, alpha: 0.28 });
  }
  root.addChild(path);

  const foreground = new PIXI.Graphics();
  foreground.zIndex = -40;
  foreground.poly([
    0, 797, 310, 790, 455, 805, 610, 790, 760, 705, 1010, 706,
    1208, 578, 1438, 578, 1610, 798, 1790, 792, 1940, 804, 2300, 792,
    2300, 900, 0, 900,
  ]);
  foreground.fill(0x080b09);
  root.addChild(foreground);

  // The Egg's nest: the rook_nest deco (js/rook-woods.js ROOK_NEST).
  const nest = new PIXI.Sprite(textureFromUrl(`assets/decos/groddle/${ROOK_NEST.asset}`));
  nest.anchor.set(0.5, 1);
  nest.position.set(ROOK_NEST.x, ROOK_NEST.y);
  nest.width = ROOK_NEST.w;
  nest.height = ROOK_NEST.h;
  nest.zIndex = -25;
  nest.eventMode = 'none';
  nest.name = 'rook-nest';
  root.addChild(nest);

  const birds = new PIXI.Graphics();
  birds.zIndex = -860;
  for (let i = 0; i < 8; i += 1) {
    const bx = 330 + i * 245;
    const by = 215 + (i % 3) * 44;
    birds.moveTo(bx - 14, by + 3);
    birds.quadraticCurveTo(bx - 5, by - 8, bx, by);
    birds.quadraticCurveTo(bx + 6, by - 9, bx + 15, by + 2);
  }
  birds.stroke({ width: 3, color: 0x0d110e, alpha: 0.52 });
  root.addChild(birds);

  root.platformsScreen = platforms;
  root.signViews = [];
  return root;
}

/** A Crusher: Tiny Speck's crusher.swf still (js/rook-woods.js ROOK_CRUSHER_ART), centred on its position. */
function drawRookCrusher(spec) {
  const root = new PIXI.Sprite(textureFromUrl(ROOK_CRUSHER_ART.file));
  root.name = `rook-crusher-${spec.id}`;
  root.anchor.set(0.5, 0.5);
  root.scale.set(crusherArtScale(spec));
  root.zIndex = 58;
  root.eventMode = 'none';
  root._lastPhase = '';
  return root;
}

function spawnRookCrushers() {
  rookCrushers = ROOK_CRUSHERS.map((spec) => {
    const sprite = drawRookCrusher(spec);
    const position = crusherPosition(spec, 0);
    sprite.position.set(position.x, position.y);
    entityLayer.addChild(sprite);
    return { spec, sprite, position };
  });
}

function spawnRookEgg() {
  const sprite = new PIXI.Sprite(rookEggTexture(rookWoodsState?.eggState));
  sprite.anchor.set(0.5, 1);
  sprite.scale.set(0.84);
  sprite.position.set(2140, 784);
  // rook_egg is in_background (BG_ITEM): under the avatars. The Crushers stay over them.
  sprite.zIndex = itemZ('rook_egg', 9);
  sprite.eventMode = 'static';
  sprite.cursor = 'pointer';
  sprite._rookHitW = 145;
  sprite._rookHitH = 118;
  entityLayer.addChild(sprite);
  rookEggTarget = register({
    classId: 'rook_egg',
    label: 'Rook Egg',
    subtitle: 'Do it! Smash it open!',
    sprite,
    state: { rookState: rookWoodsState },
  });
  return rookEggTarget;
}

function resetRookEggSmashVisual() {
  if (!rookEggTarget || rookWoodsState?.eggSmashed) return;
  rookWoodsState.eggState = ROOK_EGG_INITIAL_STATE;
  rookEggTarget.sprite.texture = rookEggTexture(ROOK_EGG_INITIAL_STATE);
  rookEggTarget.sprite.rotation = 0;
  rookEggTarget.sprite.scale.set(0.84);
}

function updateRookEggSmashVisual(action) {
  if (action?.target !== rookEggTarget || !rookWoodsState || rookWoodsState.eggSmashed) return;
  const state = rookEggStateForProgress(action.progress);
  if (state !== rookWoodsState.eggState) {
    rookWoodsState.eggState = state;
    rookEggTarget.sprite.texture = rookEggTexture(state);
    playSfx('pickup', { volume: 0.32, rate: 0.56 + (5 - state) * 0.08 });
    burst(rookEggTarget.sprite.x, rookEggTarget.sprite.y - 56, 0x9b997c, 8);
  }
  const pulse = Math.sin(action.progress * Math.PI * 8);
  rookEggTarget.sprite.rotation = pulse * 0.025;
  rookEggTarget.sprite.scale.set(0.84 + Math.abs(pulse) * 0.025, 0.84 - Math.abs(pulse) * 0.015);
}

function renderRookWoodsHud() {
  const hud = document.getElementById('rook-woods-hud');
  const visible = rookWoodsIsInstanced();
  if (hud) hud.hidden = !visible;
  if (!visible) return;
  const remaining = rookWoodsRemainingMs(rookWoodsState);
  const seconds = Math.ceil(remaining / 1000);
  const tool = findWorkingRookTool(inv, toolState);
  const timer = hud.querySelector('[data-rook-timer]');
  const objective = hud.querySelector('[data-rook-objective]');
  const hits = hud.querySelector('[data-rook-hits]');
  const egg = hud.querySelector('[data-rook-egg]');
  const toolEl = hud.querySelector('[data-rook-tool]');
  if (timer) {
    timer.textContent = `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`;
    timer.classList.toggle('is-low', remaining <= 20_000);
  }
  if (objective) objective.textContent = rookWoodsObjective(rookWoodsState);
  if (hits) hits.textContent = String(rookWoodsState.hits);
  if (egg) egg.textContent = rookWoodsState.eggSmashed ? 'Smashed' : `State ${rookWoodsState.eggState}/5`;
  if (toolEl) {
    toolEl.textContent = tool.ok
      ? `${tool.profile.label} ready · ${Math.round(tool.condition.condition.remaining)} condition`
      : 'No working smashing tool';
  }
  if (app?.canvas) {
    app.canvas.dataset.rookWoodsStatus = rookWoodsState.status;
    app.canvas.dataset.rookWoodsRemaining = String(remaining);
    app.canvas.dataset.rookWoodsHits = String(rookWoodsState.hits);
    app.canvas.dataset.rookEggState = String(rookWoodsState.eggState);
    app.canvas.dataset.rookWoodsObjective = rookWoodsObjective(rookWoodsState);
    app.canvas.dataset.rookTool = tool.ok ? tool.classTsid : 'none';
  }
}

function setupRookWoodsInstance() {
  clearWorldEntities();
  if (bgLayer && world) {
    world.removeChild(bgLayer);
    bgLayer.destroy({ children: true });
  }
  bgLayer = drawRookWoodsBackground();
  world.addChildAt(bgLayer, 0);
  currentStreet = {
    tsid: ROOK_WOODS_STREET_ID,
    label: "Rooks' Woods",
    hubName: '', // G363: the humbaba instance (rook_egg_smash.js 79): no hub line (location.js 3311)
    hubId: 'rook',
    bounds: { l: 0, r: bgLayer.worldW, t: 0, b: bgLayer.worldH },
    platforms: bgLayer.platformsScreen,
    signposts: [],
  };
  currentStreetTsid = ROOK_WOODS_STREET_ID;
  WORLD_W = bgLayer.worldW;
  GROUND_Y = rookWoodsState.spawn.y;
  streetPlatforms = bgLayer.platformsScreen;
  streetWalls = [];
  climb = { active: false, wall: null };
  Object.assign(jumpState, createJumpState(movementNow()));
  spawnRookCrushers();
  spawnRookEgg();
  if (player) {
    player.position.set(rookWoodsState.spawn.x, rookWoodsState.spawn.y);
    player.vx = 0;
    player.vy = 0;
    player.onGround = true;
    player.rotation = 0;
    noteGrounded(jumpState, true, movementNow());
  }
  camTarget = cameraTargetForPlayer(player.x);
  camY = cameraTargetY(player.y, activeCameraWorldHeight(), LOCATION_VIEW_H);
  world.position.set(-Math.round(camTarget), -Math.round(camY));
  const name = document.getElementById('street-name');
  if (name) {
    name.textContent = "Rooks' Woods";
    name.dataset.tsid = ROOK_WOODS_STREET_ID;
  }
  setAmbientForStreet({ hubName: 'Rook Woods' }, { force: true });
  if (app?.canvas) {
    app.canvas.dataset.rookWoodsSource = 'rook_egg_smash.js + crusher.js + supplied video';
    app.canvas.dataset.rookForestArt = ROOK_FOREST_ART_ID;
    app.canvas.dataset.rookForestLayers = String(ROOK_FOREST_DEPTH_LAYERS.length);
    app.canvas.dataset.rookForestDecos = String(ROOK_FOREST_DECOS.length);
    app.canvas.dataset.rookForestLimbs = String(ROOK_FOREST_LIMBS.length);
    app.canvas.dataset.rookCrusherArt = ROOK_CRUSHER_ART.swf;
    app.canvas.dataset.rookNestArt = ROOK_NEST.asset.replace(/\.png$/, '');
  }
  savePlayerLocation(rookWoodsSourceLocation);
  renderRookWoodsHud();
  updateHud();
}

async function startRookWoodsQuest(opts = {}) {
  if (rookWoodsStartPromise) return rookWoodsStartPromise;
  if (rookWoodsIsInstanced()) return rookWoodsState;
  const tool = findWorkingRookTool(inv, toolState);
  if (!tool.ok) {
    toast(tool.msg, 4200);
    return null;
  }
  rookWoodsStartPromise = (async () => {
    if (!questState.active[ROOK_QUEST_ID]) {
      const assigned = assignQuest(questState, ROOK_QUEST_ID, { ignorePrereq: true });
      if (!assigned.ok) return null;
    }
    closeQuestPanel();
    closeQuestDialogue();
    closePackPopover();
    rookWoodsSourceLocation = opts.sourceLocation || instanceSourceHere({
      tsid: currentStreetTsid,
      x: player?.x ?? WORLD_W * 0.5,
      y: player?.y ?? GROUND_Y,
    });
    rookWoodsState = createRookWoodsState({
      sourceLocation: rookWoodsSourceLocation,
    });
    rookWoodsTransitionBusy = true;
    rookLastHitAt = 0;
    rookHitFx = null;
    rookAutoNextAt = 0;
    savePlayerLocation(rookWoodsSourceLocation);
    const setup = () => setupRookWoodsInstance();
    const transition = document.getElementById('screen-transition');
    if (opts.useTransition !== false && transition) {
      await runStreetTransition(transition, {
        fromLabel: currentStreet?.label || '',
        fromHub: currentStreet?.hubName || '',
        toLabel: "Rooks' Woods",
        toHub: '',
        topColor: '#2e332c',
        bottomColor: '#101411',
        onMid: setup,
      });
    } else {
      setup();
    }
    rookWoodsTransitionBusy = false;
    pushActivity("Rooks' Woods: evade the Crushers and smash the Rook Egg.");
    openScriptedQuestDialogue({
      title: "Rooks' Woods",
      kicker: 'A warning from Humbaba',
      beats: [
        {
          text: "Ah, the Rooks' Woods. Careful of the Crushers …",
          response: 'Crushers?',
        },
        {
          text: "Get too close to those mean rocks and you'll get a bad shock and have to start over.",
          response: "I'll be careful.",
        },
      ],
      onComplete: () => {
        beginRookWoods(rookWoodsState, Date.now());
        renderRookWoodsHud();
        toast('Two minutes. Find the Egg!', 3000);
      },
    });
    return rookWoodsState;
  })();
  try {
    return await rookWoodsStartPromise;
  } finally {
    rookWoodsStartPromise = null;
    rookWoodsTransitionBusy = false;
  }
}

async function returnFromRookWoods({ abandon = false, expired = false } = {}) {
  if (!rookWoodsState || rookWoodsTransitionBusy) return false;
  rookWoodsTransitionBusy = true;
  const destination = rookWoodsSourceLocation?.tsid
    ? { ...rookWoodsSourceLocation }
    : { tsid: STREET_INDEX.default };
  if (abandon || expired) delete questState.active[ROOK_QUEST_ID];
  const status = expired ? 'expired' : abandon ? 'abandoned' : rookWoodsState.status;
  closeQuestDialogue({ force: true });
  rookWoodsState = null;
  rookWoodsSourceLocation = null;
  rookCrushers = [];
  rookEggTarget = null;
  rookHitFx = null;
  mrHairballTarget = null;
  smallWorthlessTarget = null;
  rookMuseumTargets = [];
  rookMuseumGreeter = null;
  closeRookMuseumExhibit();
  const hud = document.getElementById('rook-woods-hud');
  if (hud) hud.hidden = true;
  try {
    await enterStreetWithTransition(destination.tsid, {
      spawnX: destination.x,
      spawnY: destination.y,
      quiet: true,
    });
    savePlayerLocation(destination);
    savePlayerState();
    if (app?.canvas) app.canvas.dataset.rookWoodsStatus = status;
    if (expired) toast("The Rooks' Woods closed. You can try again later.", 4000);
    else if (abandon) toast('You leave the Rook Egg for another attempt.', 3200);
    updateHud();
    return true;
  } finally {
    rookWoodsTransitionBusy = false;
  }
}

function confirmLeaveRookWoods() {
  if (!rookWoodsIsInstanced()) return;
  openScriptedQuestDialogue({
    title: "Rooks' Woods",
    kicker: 'Leave the trial?',
    cancelable: true,
    beats: [
      {
        text: 'Humbaba can send you back when you have another working tool and feel ready.',
        response: "Leave Rooks' Woods",
      },
    ],
    onComplete: () => returnFromRookWoods({ abandon: true }),
  });
}

function handleRookEggTarget(target, verbId) {
  if (!rookWoodsIsInstanced() || target !== rookEggTarget || verbId !== 'smash') return;
  const tool = findWorkingRookTool(inv, toolState);
  if (!tool.ok) {
    toast(tool.msg, 3600);
    resetRookEggSmashVisual();
    return;
  }
  const result = completeRookEggSmash(rookWoodsState, tool.classTsid);
  if (!result.ok) return;
  const wear = useToolCondition(toolState, tool.classTsid, tool.profile.wear);
  target.sprite.texture = rookEggTexture(1);
  target.sprite.rotation = 0;
  target.sprite.scale.set(0.84);
  target.subtitle = "It's been smashed already.";
  playSfx('quest', { volume: 0.76, rate: 0.92 });
  burst(target.sprite.x, target.sprite.y - 58, 0xd2c281, 34);
  floatText(target.sprite.x, target.sprite.y - 122, 'ROOK EGG SMASHED!', 0xf0d78d);
  const updates = applyQuestProgress(questState, 'rook_egg_smashed', 1, pc);
  announceQuestCompletions(
    updates.map((update) =>
      (update.classTsid || update.def?.classTsid) === ROOK_QUEST_ID
        ? { ...update, onDismiss: () => returnFromRookWoods() }
        : update
    )
  );
  pushActivity(
    `You smashed the Rook Egg with a ${tool.profile.label}.` +
      (wear.broke ? ` ${wear.msg}` : '')
  );
  savePlayerState();
  renderRookWoodsHud();
  updateHud();
}

function beginRookCrusherHit(entry, now) {
  if (!rookWoodsState || rookHitFx || now - rookLastHitAt < 900) return false;
  const hit = recordCrusherHit(rookWoodsState, entry.spec.id);
  if (!hit.ok) return false;
  rookLastHitAt = now;
  cancelCurrentAction({ quiet: true });
  const moodLoss = crusherMoodLoss(player.x, rookWoodsState.spawn.x);
  loseMood(pc, moodLoss); // G289 metabolics_lose_mood (inc_metabolics.js 180-194)
  keys.clear();
  rookHitFx = {
    startedAt: now,
    durationMs: 760,
    fromX: player.x,
    fromY: player.y,
    toX: rookWoodsState.spawn.x,
    toY: rookWoodsState.spawn.y,
  };
  burst(player.x, player.y - 48, 0xa79d7b, 26);
  // crusher.js: the hit pose through the knockback, then angry on arrival.
  engine.playHit('hit1', rookHitFx.durationMs);
  engine.playEmotion('angry', rookHitFx.durationMs);
  playSfx('pickup', { volume: 0.62, rate: 0.45 });
  toast('Ow. Crushers suck!', 2200);
  pushActivity(
    `A Crusher knocked you back to the start.${moodLoss ? ` -${moodLoss} mood.` : ''}`
  );
  if (app?.canvas) app.canvas.dataset.rookLastHit = entry.spec.id;
  renderRookWoodsHud();
  updateHud();
  return true;
}

function updateRookHitFx(now) {
  if (!rookHitFx || !player) return false;
  const progress = clamp((now - rookHitFx.startedAt) / rookHitFx.durationMs, 0, 1);
  const eased = 1 - Math.pow(1 - progress, 3);
  player.x = rookHitFx.fromX + (rookHitFx.toX - rookHitFx.fromX) * eased;
  player.y =
    rookHitFx.fromY +
    (rookHitFx.toY - rookHitFx.fromY) * eased -
    Math.sin(progress * Math.PI) * 86;
  player.vx = 0;
  player.vy = 0;
  player.onGround = false;
  player.rotation = Math.sin(progress * Math.PI * 6) * 0.13 * (1 - progress);
  if (progress < 1) return true;
  player.position.set(rookHitFx.toX, rookHitFx.toY);
  player.rotation = 0;
  player.onGround = true;
  noteGrounded(jumpState, true, movementNow());
  rookHitFx = null;
  resetRookEggSmashVisual();
  return false;
}

function updateRookWoods(dt) {
  if (!rookWoodsIsInstanced() || rookWoodsTransitionBusy) return;
  const now = Date.now();
  if (rookWoodsState.status === 'running' && rookWoodsRemainingMs(rookWoodsState, now) <= 0) {
    expireRookWoods(rookWoodsState, now);
    pushActivity("The two-minute Rooks' Woods timer ran out.");
    returnFromRookWoods({ expired: true });
    return;
  }

  const knocked = updateRookHitFx(now);
  const elapsed = rookWoodsState.startedAt ? now - rookWoodsState.startedAt : 0;
  for (const entry of rookCrushers) {
    const position = crusherPosition(entry.spec, elapsed);
    entry.position = position;
    entry.sprite.position.set(position.x, position.y);
    const impact = position.phase === 'impact';
    if (impact && entry.sprite._lastPhase !== 'impact') {
      burst(position.x, position.y + entry.spec.size * 0.45, 0x7d765f, 12);
      playSfx('pickup', { volume: 0.24, rate: 0.42 });
    }
    entry.sprite._lastPhase = position.phase;
  }

  const autoplay = new URLSearchParams(location.search).get('rookautoplay') === '1';
  if (
    !knocked &&
    !autoplay &&
    rookWoodsState.status === 'running' &&
    now - rookLastHitAt >= 900
  ) {
    for (const entry of rookCrushers) {
      if (
        crusherHitsAvatar(entry.spec, entry.position, {
          x: player.x,
          y: player.y,
          ...ROOK_AVATAR_HIT,
        })
      ) {
        beginRookCrusherHit(entry, now);
        break;
      }
    }
  }

  if (autoplay && now >= rookAutoNextAt) {
    rookAutoNextAt = now + 220;
    if (isQuestDialogueOpen()) {
      advanceQuestDialogue();
    } else if (
      rookWoodsState.status === 'running' &&
      !currentAction &&
      rookEggTarget?.sprite
    ) {
      player.position.set(rookEggTarget.sprite.x - 72, rookEggTarget.sprite.y);
      player.vx = 0;
      player.vy = 0;
      player.onGround = true;
      const smash = getVerbsFor(rookEggTarget, {
        pc,
        inv,
        tools: toolState,
        skills: skillState,
      }).find((verb) => verb.id === 'smash' && verb.enabled);
      if (smash) beginVerbAction(rookEggTarget, smash);
    }
  }
  renderRookWoodsHud();
}

const ROOK_MUSEUM_ASSET_ROOT = 'assets/sprites/quests/rook-museum';

function rookMuseumIsInstanced() {
  return Boolean(rookMuseumState && currentStreetTsid === ROOK_MUSEUM_STREET_ID);
}

/** A tower deco in the museum hall: bottom-centre at (x, y), world px, turned `r` degrees. */
function addRookMuseumDeco(root, name, x, y, w, h, { z = -900, r = 0, tint, alpha = 1, flip = false } = {}) {
  const sprite = new PIXI.Sprite(textureFromUrl(`assets/decos/groddle/${name}.png`));
  sprite.anchor.set(0.5, 1);
  sprite.position.set(x, y);
  sprite.width = w;
  sprite.height = h;
  if (flip) sprite.scale.x *= -1;
  sprite.rotation = (r * Math.PI) / 180;
  if (tint !== undefined) sprite.tint = tint;
  sprite.alpha = alpha;
  sprite.zIndex = z;
  sprite.eventMode = 'none';
  root.addChild(sprite);
  return sprite;
}

/** Plaque and sign lettering in the tower rooms' style (features/tower-rooms-feature.js drawSigns). */
function addRookMuseumSignText(root, text, x, y, z) {
  const label = new PIXI.Text({ text, style: {
    fontFamily: '"Trebuchet MS", sans-serif',
    fontSize: text.length > 10 ? 15 : 19,
    fontWeight: '700',
    fill: 0xf3e2b8,
    stroke: { color: 0x2b1a0e, width: 3 },
    align: 'center',
  } });
  label.resolution = 3;
  label.anchor.set(0.5, 0.5);
  label.position.set(x, y);
  label.zIndex = z;
  label.eventMode = 'none';
  root.addChild(label);
  return label;
}

/**
 * The museum hall (js/rook-museum.js ROOK_MUSEUM_HALL): the Jethimadh Tower's
 * wood wall, pointed windows, arrival door and plaque, sign, bench and
 * spotlights, all Tiny Speck's decos.
 */
function drawRookMuseumBackground() {
  const hall = ROOK_MUSEUM_HALL;
  const floor = ROOK_MUSEUM_WORLD.floorY;
  const root = new PIXI.Container();
  root.sortableChildren = true;
  root.worldW = ROOK_MUSEUM_WORLD.right - ROOK_MUSEUM_WORLD.left;
  root.worldH = ROOK_MUSEUM_WORLD.height;
  root.sourceWorldH = ROOK_MUSEUM_WORLD.height;
  const H = root.worldH;

  // Wall: the corridors' wood backdrop tiled along the hall, as the Hall of Rejected Concepts.
  const tile = 760;
  for (let x = tile / 2 - 60, i = 0; x < root.worldW + tile / 2; x += tile, i += 1) {
    addRookMuseumDeco(root, 'jethimadh_int_bg_center', x, H + 60, tile + 120, H + 120, { z: -1000 + (i % 2), tint: hall.wallTint });
  }
  // firebog_linear_gradient_shadow: opaque on its left, turned 90 to darken the ceiling, -90 the floor.
  const run = 700;
  for (let x = -100; x < root.worldW + 100; x += run) {
    addRookMuseumDeco(root, 'firebog_linear_gradient_shadow', x, 110, 220, run + 2, { z: -990, r: 90 });
    addRookMuseumDeco(root, 'firebog_linear_gradient_shadow', x + run, floor + 60, 200, run + 2, { z: -990, r: -90 });
  }
  for (const x of hall.windows) {
    addRookMuseumDeco(root, 'jethimadh_tower_window_1', x, hall.windowSize.bottom, hall.windowSize.w, hall.windowSize.h, { z: -950 });
  }
  // A spotlight over the orb and the shrine (the recordings), doubled as in the Hall: the cone is faint.
  for (const id of hall.spotlights) {
    const exhibit = getRookMuseumExhibit(id);
    const cx = exhibit.kind === 'shrine' ? exhibit.x + 101 : exhibit.x;
    for (const k of [0, 1]) addRookMuseumDeco(root, 'rookhall_spotlight', cx, floor - 30, 210 - k * 40, 600, { z: -940 + k });
  }
  addRookMuseumDeco(root, 'door_asset_jethimadh_int', hall.door.x, floor, hall.door.w, hall.door.h, { z: -930 });
  const plaqueY = floor - hall.door.h + 4;
  addRookMuseumDeco(root, 'jethimadh_int_door_sign', hall.plaque.x, plaqueY, 188, 110, { z: -925 });
  addRookMuseumDeco(root, 'firebog_sign_blank', hall.plaque.x, plaqueY - 17, 138, 80, { z: -924 });
  addRookMuseumSignText(root, hall.plaque.text, hall.plaque.x, plaqueY - 17 - 40 + 4, -923);
  addRookMuseumDeco(root, 'sign_arrow_1', hall.arrow.x, hall.arrow.y, hall.arrow.w, hall.arrow.h, { z: -925 });
  addRookMuseumSignText(root, hall.arrow.text, hall.arrow.x - 8, hall.arrow.y - hall.arrow.h / 2 + 4, -924);
  addRookMuseumDeco(root, 'bench', hall.bench.x, floor + 4, hall.bench.w, hall.bench.h, { z: -920 });

  root.platformsScreen = [
    { id: 'rook-museum-floor', x1: 0, y1: floor, x2: root.worldW, y2: floor, pc_perm: 1 },
  ];
  root.signViews = [];
  return root;
}

function makeRookMuseumSpeaker(exhibit) {
  const sprite = new PIXI.Sprite(
    textureFromUrl(`${ROOK_MUSEUM_ASSET_ROOT}/rook_hall_speaker__x1_stop_png_1354835940.webp`)
  );
  sprite.anchor.set(0.5, 1);
  const hall = ROOK_MUSEUM_HALL;
  if (exhibit.kind === 'painting') {
    sprite.position.set(exhibit.x + hall.paintingSpeaker.dx, hall.paintingSpeaker.bottom);
  } else if (exhibit.kind === 'orb') {
    sprite.position.set(exhibit.x + hall.orbSpeaker.dx, hall.orbSpeaker.bottom);
  } else {
    // On the squawk stand, over its board.
    const stand = ROOK_MUSEUM_STAND_ART;
    sprite.position.set(hall.shrineStand.x, ROOK_MUSEUM_WORLD.floorY - stand.h + 83);
  }
  // rook_hall_speaker is in_foreground (FG_ITEM), still under the avatars (MiddleGroundRenderer 111-171).
  sprite.zIndex = 44;
  sprite.eventMode = 'static';
  sprite.cursor = 'pointer';
  entityLayer.addChild(sprite);
  const target = register({
    classId: 'rook_hall_speaker',
    label: `${exhibit.number}. ${exhibit.shortTitle}`,
    subtitle: 'Push for the recorded lesson',
    sprite,
    state: { museumState: rookMuseumState, exhibitId: exhibit.id },
  });
  rookMuseumTargets.push(target);
  return target;
}

/** A framed painting: its picture in the window, the deco's frame over it (js/rook-art.js). */
function makeRookMuseumPainting(exhibit) {
  const art = ROOK_MUSEUM_PAINTING_ART[exhibit.painting];
  const root = new PIXI.Container();
  root.name = `rook-museum-painting-${exhibit.painting}`;
  // The overlay point is the stage's centre-bottom.
  const at = rookMuseumOverlayPoint(exhibit.id);
  root.position.set(at.x - art.stage[0] / 2, at.y - art.stage[1]);
  const [wx, wy, ww, wh] = art.window;
  const picture = new PIXI.Sprite(textureFromUrl(`${ROOK_MUSEUM_ASSET_ROOT}/paintings/${art.picture}`));
  picture.position.set(wx, wy);
  picture.width = ww;
  picture.height = wh;
  root.addChild(picture);
  const frame = new PIXI.Sprite(textureFromUrl(art.file));
  frame.position.set(art.trim[0], art.trim[1]);
  root.addChild(frame);
  root.eventMode = 'none';
  return root;
}

function spawnRookMuseumExhibits() {
  rookMuseumTargets = [];
  const floor = ROOK_MUSEUM_WORLD.floorY;
  for (const exhibit of ROOK_MUSEUM_EXHIBITS) {
    let sprite;
    if (exhibit.kind === 'painting') {
      sprite = makeRookMuseumPainting(exhibit);
    } else if (exhibit.kind === 'orb') {
      sprite = new PIXI.Sprite(
        textureFromUrl(`${ROOK_MUSEUM_ASSET_ROOT}/rook_hall_focusing_orb__x1_1_png_1354835872.webp`)
      );
      sprite.anchor.set(0.5, 1);
      sprite.position.set(exhibit.x, floor);
    } else {
      sprite = new PIXI.Sprite(
        textureFromUrl(`${ROOK_MUSEUM_ASSET_ROOT}/rook_hall_shrine_holofilm__x1_stop_png_1354835839.webp`)
      );
      sprite.anchor.set(0.5, 1);
      sprite.position.set(exhibit.x, floor + 15);
      const stand = new PIXI.Sprite(textureFromUrl(ROOK_MUSEUM_STAND_ART.file));
      stand.anchor.set(0.5, 1);
      stand.position.set(ROOK_MUSEUM_HALL.shrineStand.x, floor + 1);
      stand.zIndex = 40;
      stand.eventMode = 'none';
      entityLayer.addChild(stand);
    }
    sprite.zIndex = 35;
    entityLayer.addChild(sprite);
    makeRookMuseumSpeaker(exhibit);
  }
}

function spawnRookMuseumGreeter() {
  // npc_quest_widget, variant widgetWood (rook_hall.js onEnterLocation): the Mezzanine Greeterbot's art.
  const sprite = new PIXI.Sprite(textureFromUrl(ROOK_MUSEUM_HALL.greeterArt));
  sprite.anchor.set(0.5, 1);
  // An NPC is an item: under the avatars (MiddleGroundRenderer 111-171).
  sprite.zIndex = 46;
  sprite.position.set(ROOK_MUSEUM_HALL.greeterStart.x, ROOK_MUSEUM_HALL.greeterStart.y);
  sprite.eventMode = 'static';
  sprite.cursor = 'pointer';
  entityLayer.addChild(sprite);
  rookMuseumGreeter = register({
    classId: 'npc_quest_widget',
    label: 'Greeterbot Sentry G-42',
    subtitle: 'Museum docent',
    sprite,
    state: { museumState: rookMuseumState },
  });
  return rookMuseumGreeter;
}

function renderRookMuseumHud() {
  const hud = document.getElementById('rook-museum-hud');
  const visible = rookMuseumIsInstanced();
  if (hud) hud.hidden = !visible;
  if (!visible) return;
  const visited = rookMuseumState.visited || [];
  const objective = hud.querySelector('[data-rook-museum-objective]');
  const count = hud.querySelector('[data-rook-museum-count]');
  const stage = hud.querySelector('[data-rook-museum-stage]');
  if (objective) objective.textContent = rookMuseumObjective(rookMuseumState);
  if (count) count.textContent = `${visited.length} / ${ROOK_MUSEUM_EXHIBIT_COUNT}`;
  if (stage) {
    stage.textContent =
      rookMuseumState.status === 'arrival'
        ? 'Greeterbot orientation'
        : rookMuseumState.status === 'ready'
          ? 'Final briefing'
          : 'Self-guided exhibition';
  }
  for (const dot of hud.querySelectorAll('[data-rook-museum-dot]')) {
    dot.classList.toggle('visited', visited.includes(dot.dataset.rookMuseumDot));
  }
  if (app?.canvas) {
    app.canvas.dataset.rookMuseumStatus = rookMuseumState.status;
    app.canvas.dataset.rookMuseumVisited = String(visited.length);
    app.canvas.dataset.rookMuseumObjective = rookMuseumObjective(rookMuseumState);
    app.canvas.dataset.rookMuseumProductionTsid = ROOK_MUSEUM_PRODUCTION_TSID;
  }
}

function isRookMuseumExhibitOpen() {
  const panel = document.getElementById('rook-museum-exhibit');
  return Boolean(panel && !panel.hidden);
}

function clearRookMuseumArtTimer() {
  if (rookMuseumArtTimer) clearInterval(rookMuseumArtTimer);
  rookMuseumArtTimer = null;
}

/**
 * A painting exhibit: the deco's frame with the overlay's three frames
 * cross-fading in its window (js/rook-museum.js ROOK_MUSEUM_PAINTING_LOOP),
 * from when the exhibit opened, at the overlay's 24 fps.
 */
function playRookMuseumPainting(painting, exhibit) {
  const art = ROOK_MUSEUM_PAINTING_ART[exhibit.painting];
  const base = `${ROOK_MUSEUM_ASSET_ROOT}/paintings/painting-${exhibit.painting}`;
  const [wx, wy, ww, wh] = art.window;
  const pct = (v, of) => `${(100 * v / of).toFixed(3)}%`;
  const frame = painting.querySelector('[data-rook-museum-frame]');
  if (frame) {
    frame.src = art.file;
    frame.alt = exhibit.title;
  }
  painting.style.aspectRatio = `${art.w} / ${art.h}`;
  const layers = [...painting.querySelectorAll('[data-rook-museum-layer]')];
  ['c', 'b', 'a', 'c'].forEach((letter, i) => {
    const img = layers[i];
    if (!img) return;
    img.src = `${base}${letter}.jpg`;
    Object.assign(img.style, {
      left: pct(wx - art.trim[0], art.w),
      top: pct(wy - art.trim[1], art.h),
      width: pct(ww, art.w),
      height: pct(wh, art.h),
    });
  });
  const tick = () => {
    const alphas = rookMuseumPaintingAlphas(Date.now() - rookMuseumArtStartedAt);
    layers.forEach((img, i) => { img.style.opacity = String(alphas[i] ?? 0); });
  };
  tick();
  rookMuseumArtTimer = setInterval(tick, 1000 / 24);
}

function renderRookMuseumExhibitPage() {
  const exhibit = rookMuseumActiveExhibit;
  if (!exhibit) return;
  const panel = document.getElementById('rook-museum-exhibit');
  const visual = panel?.querySelector('[data-rook-museum-visual]');
  const art = panel?.querySelector('[data-rook-museum-art]');
  const glow = panel?.querySelector('[data-rook-museum-orb-glow]');
  const title = panel?.querySelector('[data-rook-museum-title]');
  const kicker = panel?.querySelector('[data-rook-museum-kicker]');
  const copy = panel?.querySelector('[data-rook-museum-page]');
  const count = panel?.querySelector('[data-rook-museum-page-count]');
  const next = document.getElementById('rook-museum-exhibit-next');
  if (!visual || !art) return;
  clearRookMuseumArtTimer();
  visual.className = `rook-museum-exhibit-visual is-${exhibit.kind}`;
  if (title) title.textContent = exhibit.title;
  if (kicker) kicker.textContent = `Exhibit ${exhibit.number} · recorded lesson`;
  if (copy) copy.textContent = exhibit.pages[rookMuseumPageIndex] || '';
  if (count) count.textContent = `${rookMuseumPageIndex + 1} / ${exhibit.pages.length}`;
  if (next) next.textContent = rookMuseumPageIndex >= exhibit.pages.length - 1 ? 'Finish exhibit' : 'Continue';
  const painting = panel?.querySelector('[data-rook-museum-painting]');
  art.hidden = exhibit.kind === 'painting';
  if (painting) painting.hidden = exhibit.kind !== 'painting';
  if (exhibit.kind === 'painting') {
    art.removeAttribute('src');
    art.alt = '';
    if (painting) playRookMuseumPainting(painting, exhibit);
    if (glow) glow.hidden = true;
  } else if (exhibit.kind === 'orb') {
    art.src = `${ROOK_MUSEUM_ASSET_ROOT}/rook_hall_focusing_orb__x1_1_png_1354835872.webp`;
    art.alt = 'Ancient Focusing Orb';
    visual.style.setProperty('--rook-orb-scale', String(0.68 + rookMuseumPageIndex * 0.07));
    visual.classList.toggle('is-broken', rookMuseumPageIndex === exhibit.pages.length - 1);
    if (glow) glow.hidden = false;
  } else {
    art.src = `${ROOK_MUSEUM_ASSET_ROOT}/rook_hall_shrine_holofilm__x1_stop_png_1354835839.webp`;
    art.alt = 'Primitive shrine holofilm';
    if (glow) glow.hidden = true;
  }
  if (app?.canvas) {
    app.canvas.dataset.rookMuseumExhibit = exhibit.id;
    app.canvas.dataset.rookMuseumPage = String(rookMuseumPageIndex + 1);
  }
}

function openRookMuseumExhibit(exhibit) {
  if (!exhibit || !rookMuseumState) return false;
  const visit = visitRookMuseumExhibit(rookMuseumState, exhibit.id);
  if (!visit.ok) {
    toast('Speak with Greeterbot before starting the exhibits.');
    return false;
  }
  rookMuseumActiveExhibit = exhibit;
  rookMuseumPageIndex = 0;
  rookMuseumArtStartedAt = Date.now();
  const panel = document.getElementById('rook-museum-exhibit');
  if (panel) panel.hidden = false;
  playSfx('alert', { volume: 0.35, rate: 0.86 });
  if (visit.firstVisit) {
    pushActivity(`You studied museum exhibit ${exhibit.number}: ${exhibit.shortTitle}.`);
    if (visit.complete) toast('All six exhibits studied. Return to Greeterbot.', 4200);
  }
  renderRookMuseumExhibitPage();
  renderRookMuseumHud();
  updateHud();
  return true;
}

function closeRookMuseumExhibit() {
  clearRookMuseumArtTimer();
  const panel = document.getElementById('rook-museum-exhibit');
  if (panel) panel.hidden = true;
  rookMuseumActiveExhibit = null;
  rookMuseumPageIndex = 0;
  if (rookMuseumState) rookMuseumState.activeExhibitId = null;
  if (app?.canvas) {
    delete app.canvas.dataset.rookMuseumExhibit;
    delete app.canvas.dataset.rookMuseumPage;
  }
}

function advanceRookMuseumExhibit() {
  if (!rookMuseumActiveExhibit) return;
  if (rookMuseumPageIndex < rookMuseumActiveExhibit.pages.length - 1) {
    rookMuseumPageIndex += 1;
    renderRookMuseumExhibitPage();
  } else {
    closeRookMuseumExhibit();
  }
}

function beginRookMuseumOrientation() {
  if (!rookMuseumState || rookMuseumState.status !== 'arrival') return;
  const beginTourDialogue = () =>
    openScriptedQuestDialogue({
      title: 'Museum of the Rook',
      kicker: 'Greeterbot Sentry G-42',
      beats: ROOK_MUSEUM_TOUR_INTRO,
      onComplete: () => {
        beginRookMuseumTour(rookMuseumState);
        // rook_hall.js callback_widgetConversation: move_to_xy 2200, -100.
        if (rookMuseumGreeter?.sprite) {
          rookMuseumGreeter.sprite.position.set(ROOK_MUSEUM_HALL.greeterEnd.x, ROOK_MUSEUM_HALL.greeterEnd.y);
        }
        pushActivity('Greeterbot asked you to study all six Rook exhibits.');
        renderRookMuseumHud();
        updateHud();
      },
    });
  // Report 191: Part II is its own offer, as the Greeterbot gave it (items/include/npc_quests.js
  // offerQuests: the quest by its title, then its offer, rook_hall.js "Now, this way please. Let us
  // enter the museum." with "Lead the way."). It used to start silently, so its completion card
  // was the first a player heard of It's Educational II. Not now leaves it for another talk.
  const offerPartTwo = () => {
    if (questState.active?.[ROOK_HALL_QUEST_ID]) {
      beginTourDialogue();
      return;
    }
    const def = getQuestCatalog()[ROOK_HALL_QUEST_ID] || {};
    openScriptedQuestDialogue({
      title: def.title || 'It’s Educational II',
      kicker: 'Greeterbot Sentry G-42',
      offer: true,
      beats: [{ text: def.offer || 'Now, this way please. Let us enter the museum.', response: def.acceptLabel || 'Lead the way.' }],
      onComplete: () => {
        playSound('QUEST_ADDED', { volume: 0.6 });
        if (!questState.active?.[ROOK_HALL_QUEST_ID]) assignQuest(questState, ROOK_HALL_QUEST_ID, { ignorePrereq: true });
        beginTourDialogue();
      },
      onCancel: () => {},
      cancelable: true,
      primaryLabel: def.acceptLabel || 'Lead the way.',
      cancelLabel: 'Not right now',
    });
  };
  if (questState.completed.includes(ROOK_HALL_START_QUEST_ID)) {
    // Part one done but part two left unfinished: the Greeterbot offers it again (rook_hall.js).
    if (!questState.completed.includes(ROOK_HALL_QUEST_ID)) offerPartTwo();
    else beginTourDialogue();
    return;
  }
  openScriptedQuestDialogue({
    title: 'It’s Educational',
    kicker: 'Greeterbot Sentry G-42',
    beats: ROOK_MUSEUM_GREETING,
    onComplete: () => {
      if (questState.active?.[ROOK_HALL_START_QUEST_ID]) {
        completeQuest(questState, ROOK_HALL_START_QUEST_ID, pc);
      }
      offerPartTwo();
    },
  });
}

function finishRookMuseumQuest() {
  const result = completeRookMuseum(rookMuseumState);
  if (!result.ok) return false;
  const active = questState.active?.[ROOK_HALL_QUEST_ID];
  if (active) active.progress.learn_rook = 1;
  const completed = active ? completeQuest(questState, ROOK_HALL_QUEST_ID, pc) : null;
  playSfx('quest', { volume: 0.7 });
  // A return visit (hall_repeat) reviews the exhibits without a second reward.
  pushActivity(completed?.ok ? 'You completed It’s Educational II. +400 iMG.' : 'You reviewed the Museum of the Rook.');
  toast(completed?.ok ? 'Museum training complete · +400 iMG' : 'Museum review complete', 4200);
  if (app?.canvas) {
    app.canvas.dataset.rookMuseumReward = '400';
    app.canvas.dataset.rookMuseumQuestCompleted = completed?.ok ? '1' : '0';
  }
  if (completed?.ok) {
    announceQuestCompletions([{
      classTsid: ROOK_HALL_QUEST_ID,
      completed: true,
      rewards: completed.rewards,
      def: completed.def,
      onDismiss: () => returnFromRookMuseum(),
    }]);
  }
  savePlayerState();
  updateHud();
  if (!completed?.ok) setTimeout(() => returnFromRookMuseum(), 650);
  return true;
}

function handleRookMuseumTarget(target, verbId) {
  if (!rookMuseumState) return false;
  if (target?.classId === 'rook_hall_speaker' && String(verbId).split(':')[0] === 'push') {
    const exhibit = getRookMuseumExhibit(target.state?.exhibitId);
    if (target.sprite) {
      target.sprite.tint = 0xffd789;
      setTimeout(() => { if (target.sprite && !target.sprite.destroyed) target.sprite.tint = 0xffffff; }, 420);
    }
    return openRookMuseumExhibit(exhibit);
  }
  if (target?.classId !== 'npc_quest_widget') return false;
  if (rookMuseumState.status === 'arrival') {
    beginRookMuseumOrientation();
  } else if (rookMuseumState.status === 'ready') {
    openScriptedQuestDialogue({
      title: 'It’s Educational II',
      kicker: 'Greeterbot Sentry G-42',
      beats: ROOK_MUSEUM_COMPLETION,
      onComplete: finishRookMuseumQuest,
    });
  } else {
    const remaining = ROOK_MUSEUM_EXHIBIT_COUNT - rookMuseumState.visited.length;
    openScriptedQuestDialogue({
      title: 'Museum of the Rook',
      kicker: 'Greeterbot Sentry G-42',
      beats: [{
        text: `Study each exhibit and push its speaker button. ${remaining} remain${remaining === 1 ? 's' : ''}.`,
        response: 'Back to the exhibits.',
      }],
    });
  }
  return true;
}

function setupRookMuseumInstance() {
  clearWorldEntities();
  if (bgLayer && world) {
    world.removeChild(bgLayer);
    bgLayer.destroy({ children: true });
  }
  bgLayer = drawRookMuseumBackground();
  world.addChildAt(bgLayer, 0);
  currentStreet = {
    tsid: ROOK_MUSEUM_STREET_ID,
    productionTsid: ROOK_MUSEUM_PRODUCTION_TSID,
    label: 'Museum of the Rook',
    hubName: '', // G363: the rook_museum instance (rook_hall.js 288): no hub line (location.js 3311)
    hubId: 'rook-museum',
    bounds: { l: 0, r: bgLayer.worldW, t: 0, b: bgLayer.worldH },
    platforms: bgLayer.platformsScreen,
    signposts: [],
  };
  currentStreetTsid = ROOK_MUSEUM_STREET_ID;
  WORLD_W = bgLayer.worldW;
  GROUND_Y = ROOK_MUSEUM_WORLD.floorY;
  streetPlatforms = bgLayer.platformsScreen;
  streetWalls = [];
  climb = { active: false, wall: null };
  Object.assign(jumpState, createJumpState(movementNow()));
  spawnRookMuseumExhibits();
  spawnRookMuseumGreeter();
  if (player) {
    // rook_hall.js: questInstanceLocation(pc, 'rook_museum', -2270, -136).
    player.position.set(ROOK_MUSEUM_HALL.spawn.x, GROUND_Y);
    player.vx = 0;
    player.vy = 0;
    player.onGround = true;
    noteGrounded(jumpState, true, movementNow());
  }
  camTarget = cameraTargetForPlayer(player.x);
  camY = cameraTargetY(player.y, activeCameraWorldHeight(), LOCATION_VIEW_H);
  world.x = -camTarget;
  world.y = -camY;
  const name = document.getElementById('street-name');
  if (name) {
    name.textContent = 'Museum of the Rook';
    name.dataset.tsid = ROOK_MUSEUM_PRODUCTION_TSID;
  }
  renderRookMuseumHud();
}

async function startRookMuseum(opts = {}) {
  if (rookMuseumStartPromise) return rookMuseumStartPromise;
  if (rookMuseumIsInstanced()) return rookMuseumState;
  rookMuseumStartPromise = (async () => {
    if (!questState.completed.includes(ROOK_HALL_START_QUEST_ID) &&
        !questState.active?.[ROOK_HALL_START_QUEST_ID]) {
      assignQuest(questState, ROOK_HALL_START_QUEST_ID, { ignorePrereq: true });
    }
    rookMuseumSourceLocation = instanceSourceHere({
      tsid: currentStreetTsid,
      x: player?.x || 120,
      y: player?.y || GROUND_Y,
    });
    rookMuseumState = createRookMuseumState({
      sourceLocation: rookMuseumSourceLocation,
    });
    rookMuseumTransitionBusy = true;
    setupRookMuseumInstance();
    rookMuseumTransitionBusy = false;
    pushActivity('You entered the Museum of the Rook.');
    updateHud();
    setTimeout(beginRookMuseumOrientation, opts.autoGreeting === false ? 850 : 180);
    return rookMuseumState;
  })();
  try {
    return await rookMuseumStartPromise;
  } finally {
    rookMuseumStartPromise = null;
  }
}

async function returnFromRookMuseum({ abandon = false } = {}) {
  if (!rookMuseumState || rookMuseumTransitionBusy) return false;
  rookMuseumTransitionBusy = true;
  closeRookMuseumExhibit();
  closeQuestDialogue({ force: true });
  const source = rookMuseumSourceLocation || rookMuseumState.sourceLocation;
  if (abandon && rookMuseumState.status !== 'complete') {
    delete questState.active[ROOK_HALL_START_QUEST_ID];
    delete questState.active[ROOK_HALL_QUEST_ID];
    pushActivity('You left the museum before finishing the tour.');
  }
  rookMuseumState = null;
  rookMuseumSourceLocation = null;
  if (source?.tsid && source.tsid !== ROOK_MUSEUM_STREET_ID) {
    await enterStreet(source.tsid, { spawnX: source.x, spawnY: source.y, quiet: true });
  } else {
    await enterStreet(STREET_INDEX.default, { quiet: true });
  }
  rookMuseumTransitionBusy = false;
  savePlayerState();
  updateHud();
  return true;
}

function confirmLeaveRookMuseum() {
  if (!rookMuseumState) return;
  if (rookMuseumState.status === 'complete' ||
      window.confirm('Leave the museum? The unfinished tour will be abandoned.')) {
    returnFromRookMuseum({ abandon: rookMuseumState.status !== 'complete' });
  }
}

function updateRookMuseum() {
  if (!rookMuseumIsInstanced() || rookMuseumTransitionBusy) return;
  const autoplay = new URLSearchParams(location.search).get('rookmuseumautoplay') === '1';
  const now = Date.now();
  if (autoplay && now >= rookMuseumAutoNextAt) {
    rookMuseumAutoNextAt = now + 90;
    if (isQuestDialogueOpen()) {
      advanceQuestDialogue();
    } else if (isRookMuseumExhibitOpen()) {
      advanceRookMuseumExhibit();
    } else if (rookMuseumState.status === 'arrival') {
      beginRookMuseumOrientation();
    } else if (rookMuseumState.status === 'touring') {
      const next = ROOK_MUSEUM_EXHIBITS.find(
        (exhibit) => !rookMuseumState.visited.includes(exhibit.id)
      );
      const target = rookMuseumTargets.find((entry) => entry.state?.exhibitId === next?.id);
      if (target?.sprite) player.position.set(target.sprite.x - 60, GROUND_Y);
      if (next) openRookMuseumExhibit(next);
    } else if (rookMuseumState.status === 'ready') {
      player.position.set(rookMuseumGreeter?.sprite?.x - 70 || 3060, GROUND_Y);
      handleRookMuseumTarget(rookMuseumGreeter, 'talk_to');
    }
  }
  renderRookMuseumHud();
}

const EESTI_ASSET_ROOT = 'assets/sprites/quests/de-embiggenify';

function deEmbiggenifyIsInstanced() {
  return Boolean(deEmbiggenifyState && currentStreetTsid === EESTI_STREET_ID);
}

/** The instance holding the imported street now (puzzles-feature runs its box inside it). */
function deEmbiggenifyHeldInstance() {
  return deEmbiggenifyIsInstanced() ? EESTI_INSTANCE : null;
}

/**
 * The archived myles_is_great box was entered (puzzles-feature, engine.instanceMoment):
 * location.js 1194-1210 creates the small shiny object while part two is open.
 */
function deEmbiggenifyMoment(moment) {
  if (moment !== EESTI_FIND_BOX.id || deEmbiggenifyState?.status !== 'searching') return false;
  return pickUpSmallWorthless();
}

function spawnMrHairball() {
  const idleFrames = textures.dustBunnyIdle?.frames;
  const talkFrames = textures.dustBunnyTalk?.frames;
  const fallback = textureFromUrl(`${EESTI_ASSET_ROOT}/npc_dustbunny__x1_idle_stand_png_1354831147.webp`);
  const sprite = new PIXI.AnimatedSprite(idleFrames?.length ? idleFrames : [fallback]);
  sprite.texturesIdle = idleFrames?.length ? idleFrames : [fallback];
  sprite.texturesTalk = talkFrames?.length ? talkFrames : sprite.texturesIdle;
  sprite.anchor.set(0.5, 1);
  // The x1 sheets at the street's own scale; our spot (EESTI_HAIRBALL_SPOT), on the item line.
  const at = eestiStreetPoint(EESTI_HAIRBALL_SPOT);
  sprite.position.set(at.x, at.y);
  // npc_dustbunny is in_foreground (FG_ITEM), still under the avatars (MiddleGroundRenderer 111-171).
  sprite.zIndex = 45;
  sprite.animationSpeed = 0.16;
  sprite.loop = true;
  sprite.play();
  sprite._eestiAnimation = 'idle';
  entityLayer.addChild(sprite);
  mrHairballTarget = register({
    classId: 'npc_dustbunny',
    label: 'Mr. Hairball',
    subtitle: 'An ikkle fwuffy cutesy wutesy Dust Bunny.', // G318: items/npc_dustbunny.js 8
    sprite,
    state: { deEmbiggenifyState },
  });
  return mrHairballTarget;
}

function setMrHairballAnimation(mode = 'idle') {
  const sprite = mrHairballTarget?.sprite;
  if (!(sprite instanceof PIXI.AnimatedSprite)) return;
  sprite.textures = mode === 'talk' ? sprite.texturesTalk : sprite.texturesIdle;
  sprite.animationSpeed = mode === 'talk' ? 0.22 : 0.14;
  sprite._eestiAnimation = mode;
  sprite.gotoAndPlay(0);
}

function spawnSmallWorthless() {
  const sprite = new PIXI.Sprite(
    textureFromUrl(`${EESTI_ASSET_ROOT}/small_worthless__x1_1_x1_2_png_1354829517.webp`)
  );
  sprite.anchor.set(0.5, 1);
  // Inside the archived box on the tabletop; the street's own cake (middleplus, in front of
  // the avatars) hides its right half. A restrained glint makes the target discoverable
  // without turning the hidden-object beat into guesswork.
  const at = eestiStreetPoint(EESTI_SHINY_SPOT);
  sprite.position.set(at.x, at.y);
  sprite.zIndex = 49;
  sprite.visible = false;
  entityLayer.addChild(sprite);

  const glint = new PIXI.Graphics();
  glint.moveTo(-8, 0);
  glint.lineTo(8, 0);
  glint.moveTo(0, -8);
  glint.lineTo(0, 8).stroke({ width: 2, color: 0xfff5af, alpha: 0.88 });
  glint.zIndex = 53;
  glint.position.set(at.x, at.y - 24);
  glint.visible = false;
  entityLayer.addChild(glint);

  smallWorthlessTarget = register({
    classId: SMALL_WORTHLESS_ID,
    label: 'Small shiny object with no intrinsic value',
    subtitle: 'Shiny, but you can barely see the shine so it ends up a little dull.', // G318: items/small_worthless.js 8
    sprite,
    state: { deEmbiggenifyState, glint },
  });
  return smallWorthlessTarget;
}

function renderDeEmbiggenifyHud(now = Date.now()) {
  const hud = document.getElementById('de-embiggenify-hud');
  const visible = deEmbiggenifyIsInstanced();
  if (hud) hud.hidden = !visible;
  if (!visible) return;
  const remaining = eestiRemainingMs(deEmbiggenifyState, now);
  const minutes = Math.floor(remaining / 60000);
  const seconds = Math.floor((remaining % 60000) / 1000);
  const timer = hud.querySelector('[data-eesti-timer]');
  const objective = hud.querySelector('[data-eesti-objective]');
  const stage = hud.querySelector('[data-eesti-stage]');
  if (timer) {
    timer.textContent = `${minutes}:${String(seconds).padStart(2, '0')}`;
    timer.classList.toggle('is-low', remaining > 0 && remaining <= 30000);
  }
  if (objective) objective.textContent = deEmbiggenifyObjective(deEmbiggenifyState);
  if (stage) {
    stage.textContent =
      deEmbiggenifyState.status === 'arrival'
        ? 'Find Mr. Hairball'
        : deEmbiggenifyState.status === 'searching'
          ? 'Search behind the cake'
          : deEmbiggenifyState.status === 'found'
            ? 'Return to Mr. Hairball'
            : 'Quest complete';
  }
  const order = ['arrival', 'searching', 'found', 'complete'];
  const step = order.indexOf(deEmbiggenifyState.status);
  for (const [selector, index] of [
    ['[data-eesti-hairball]', 0],
    ['[data-eesti-object]', 1],
    ['[data-eesti-return]', 2],
  ]) {
    const el = hud.querySelector(selector);
    el?.classList.toggle('done', step > index);
    el?.classList.toggle('active', step === index);
  }
  if (smallWorthlessTarget?.sprite) {
    const available = deEmbiggenifyState.status === 'searching';
    smallWorthlessTarget.sprite.visible = available;
    if (smallWorthlessTarget.state?.glint) {
      smallWorthlessTarget.state.glint.visible = available;
      smallWorthlessTarget.state.glint.rotation = now * 0.0013;
      smallWorthlessTarget.state.glint.alpha = 0.52 + Math.sin(now * 0.006) * 0.3;
    }
  }
  if (app?.canvas) {
    app.canvas.dataset.deEmbiggenifyStatus = deEmbiggenifyState.status;
    app.canvas.dataset.deEmbiggenifyObjective = deEmbiggenifyObjective(deEmbiggenifyState);
    app.canvas.dataset.deEmbiggenifyRemaining = String(remaining);
    app.canvas.dataset.deEmbiggenifyProductionTsid = EESTI_PRODUCTION_TSID;
    app.canvas.dataset.deEmbiggenifyPlayerScale = String(player?.baseScale || 0);
    // The room is Tiny Speck's own street; its landmarks and table are the street's decos.
    app.canvas.dataset.deEmbiggenifyArt = 'tiny-speck-street';
    app.canvas.dataset.deEmbiggenifyStreet = EESTI_STREET_ID;
    app.canvas.dataset.deEmbiggenifyLandmarks = EESTI_ROOM_ROUTE.join('>');
    app.canvas.dataset.deEmbiggenifyTableArt = 'k04_table_03_back+k04_table_03_front';
    app.canvas.dataset.deEmbiggenifyFindBox = EESTI_FIND_BOX.id;
    app.canvas.dataset.deEmbiggenifyHairball = `${EESTI_HAIRBALL_SPOT.x},${EESTI_HAIRBALL_SPOT.y}`;
    app.canvas.dataset.deEmbiggenifyMusic = EESTI_MUSIC_FILE.split('/').pop();
    app.canvas.dataset.deEmbiggenifySourceSpawn =
      `${EESTI_SOURCE_SPAWN.x},${EESTI_SOURCE_SPAWN.y}`;
  }
}

function openMrHairballRequest() {
  setMrHairballAnimation('talk');
  openScriptedQuestDialogue({
    title: 'De-Embiggenify II',
    kicker: 'Mr. Hairball',
    beats: MR_HAIRBALL_REQUEST,
    onComplete: () => {
      setMrHairballAnimation('idle');
      beginDeEmbiggenifySearch(deEmbiggenifyState, Date.now());
      pushActivity('Mr. Hairball asked you to find a small shiny object behind the cake.');
      toast('Two minutes. Look behind the cake!', 3600);
      renderDeEmbiggenifyHud();
      updateHud();
    },
  });
  return true;
}

function startMrHairballSearch() {
  if (!deEmbiggenifyState || deEmbiggenifyState.status !== 'arrival') return false;
  setMrHairballAnimation('talk');
  openScriptedQuestDialogue({
    title: 'De-Embiggenify',
    kicker: 'Mr. Hairball',
    beats: MR_HAIRBALL_GREETING,
    onComplete: () => {
      if (questState.active?.[DE_EMBIGGENIFY_QUEST_ID]) {
        completeQuest(questState, DE_EMBIGGENIFY_QUEST_ID, pc);
      }
      if (!questState.active?.[DE_EMBIGGENIFY_PART2_QUEST_ID]) {
        assignQuest(questState, DE_EMBIGGENIFY_PART2_QUEST_ID, { ignorePrereq: true });
      }
      openMrHairballRequest();
    },
  });
  return true;
}

function pickUpSmallWorthless() {
  const result = findSmallWorthless(deEmbiggenifyState, Date.now());
  if (!result.ok) return false;
  addItem(inv, SMALL_WORTHLESS_ID, 1);
  playSfx('pickup', { volume: 0.55, rate: 1.25 });
  const spot = eestiStreetPoint(EESTI_SHINY_SPOT);
  const pickupX = smallWorthlessTarget?.sprite?.x || spot.x;
  const pickupY = smallWorthlessTarget?.sprite?.y || spot.y;
  // It is in the pack now: no target (and no Enter prompt) left on the table.
  const glint = smallWorthlessTarget?.state?.glint;
  if (glint && !glint.destroyed) glint.destroy();
  if (smallWorthlessTarget) unregisterTarget(smallWorthlessTarget);
  smallWorthlessTarget = null;
  burst(pickupX, pickupY - 23, 0xffef9a, 18);
  floatText(pickupX, pickupY - 56, 'SMALL! SHINY! WORTHLESS!', 0xffe899);
  pushActivity('You found the small shiny object with no intrinsic value.');
  renderDeEmbiggenifyHud();
  updateHud();
  return true;
}

function finishDeEmbiggenifyQuest() {
  const result = completeDeEmbiggenify(deEmbiggenifyState);
  if (!result.ok) return false;
  removeItem(inv, SMALL_WORTHLESS_ID, 1);
  const active = questState.active?.[DE_EMBIGGENIFY_PART2_QUEST_ID];
  if (active) active.progress.r96 = 1;
  const completed = active
    ? completeQuest(questState, DE_EMBIGGENIFY_PART2_QUEST_ID, pc)
    : null;
  if (completed?.ok) addItem(inv, EMOTIONAL_BEAR_ID, 1);
  playSfx('quest', { volume: 0.72 });
  pushActivity('You completed De-Embiggenify II. +200 iMG, +200 currants, +50 mood, +1 Emotional Bear.');
  toast('Emotional Bear received · +200 iMG · +200 currants', 4600);
  if (app?.canvas) {
    app.canvas.dataset.deEmbiggenifyReward = '200-img,200-currants,50-mood,1-emotional-bear';
    app.canvas.dataset.deEmbiggenifyQuestCompleted = completed?.ok ? '1' : '0';
  }
  if (completed?.ok) {
    announceQuestCompletions([{
      classTsid: DE_EMBIGGENIFY_PART2_QUEST_ID,
      completed: true,
      rewards: completed.rewards,
      def: completed.def,
      onDismiss: () => returnFromDeEmbiggenify(),
    }]);
  }
  savePlayerState();
  updateHud();
  if (!completed?.ok) setTimeout(() => returnFromDeEmbiggenify(), 700);
  return true;
}

function handleDeEmbiggenifyTarget(target, verbId) {
  if (!deEmbiggenifyIsInstanced() || !target) return false;
  const verb = String(verbId || '').split(':')[0];
  if (target.classId === SMALL_WORTHLESS_ID && verb === 'pickup') {
    return pickUpSmallWorthless();
  }
  if (target.classId !== 'npc_dustbunny' || verb !== 'talk_to') return false;
  if (deEmbiggenifyState.status === 'arrival') return startMrHairballSearch();
  if (deEmbiggenifyState.status === 'found') {
    setMrHairballAnimation('talk');
    openScriptedQuestDialogue({
      title: 'De-Embiggenify II',
      kicker: 'Mr. Hairball',
      beats: MR_HAIRBALL_COMPLETION,
      onComplete: () => {
        setMrHairballAnimation('idle');
        finishDeEmbiggenifyQuest();
      },
    });
    return true;
  }
  if (deEmbiggenifyState.status === 'searching') {
    setMrHairballAnimation('talk');
    openScriptedQuestDialogue({
      title: 'De-Embiggenify II',
      kicker: 'Mr. Hairball',
      // G318: part two's own words, the appendage line and the hint (de_embiggenify_part2.js 3), and its OK!.
      beats: [{
        text: "I'd get it myself, but I'm kind of lacking in the appendage department, if you know what I mean. (And here's a hint: have a look behind the cake!)",
        response: 'OK!',
      }],
      onComplete: () => setMrHairballAnimation('idle'),
    });
    return true;
  }
  return false;
}

/**
 * Enter Tiny Speck's own copy of the room (GHFBQQ4N68733LB) as the private instance, at
 * onStarted's -1832, -76 (quests/de_embiggenify.js 43): its geometry, decos, front layer
 * (the table front and the cake), DE_EMBIGGENIFY music and the myles_is_great box.
 */
async function setupDeEmbiggenifyInstance() {
  const spawn = eestiStreetPoint(EESTI_SOURCE_SPAWN);
  await enterStreet(EESTI_STREET_ID, {
    spawnX: spawn.x,
    spawnY: spawn.y,
    quiet: true,
    bypassFeatureGates: true,
  });
  if (!deEmbiggenifyState || currentStreetTsid !== EESTI_STREET_ID) return;
  currentStreet.label = 'Eesti Life Catalogue Page 17';
  currentStreet.productionTsid = EESTI_PRODUCTION_TSID;
  currentStreet.hubName = ''; // G363: the eesti instance (de_embiggenify.js 43): no hub line (location.js 3311)
  currentStreet.hubId = '49';
  // An indoor catalogue page with its own light: no Dametime tint (the client had none).
  currentStreet.ownLight = true;
  // pc_perm 0 lines (pl1267165485151, the floor's back edge) are hard on top only for
  // items (GodItemViewer.as 800, platform_item_perm -1). The avatar never stands on one
  // anywhere (street-model.js isStandable) and walks the floor in front of it; the
  // instance also drops it from the list so no other item lands there: the line stays
  // Mr. Hairball's alone.
  for (let i = streetPlatforms.length - 1; i >= 0; i -= 1) {
    if (streetPlatforms[i].pcPerm === 0) streetPlatforms.splice(i, 1);
  }
  // #109: the long table's right leg lets you walk back out of the pocket past it.
  applyEestiWallFix(currentStreet);
  spawnMrHairball();
  spawnSmallWorthless();
  if (player) {
    player.baseScale = (deEmbiggenifyPlayerBaseScale || player.baseScale) * EESTI_PLAYER_SCALE;
    applyPlayerFacing();
  }
  const name = document.getElementById('street-name');
  if (name) {
    name.textContent = 'Eesti Life Catalogue Page 17';
    name.dataset.tsid = EESTI_PRODUCTION_TSID;
  }
  // A reload resumes at the street you came from, never inside the instance.
  savePlayerLocation(deEmbiggenifySourceLocation);
  updateDametimeChrome();
  renderDeEmbiggenifyHud();
}

async function startDeEmbiggenify(opts = {}) {
  if (deEmbiggenifyStartPromise) return deEmbiggenifyStartPromise;
  if (deEmbiggenifyIsInstanced()) return deEmbiggenifyState;
  deEmbiggenifyStartPromise = (async () => {
    const resumingPart2 = Boolean(questState.active?.[DE_EMBIGGENIFY_PART2_QUEST_ID]);
    if (!questState.active?.[DE_EMBIGGENIFY_QUEST_ID] && !resumingPart2) {
      const assigned = assignQuest(questState, DE_EMBIGGENIFY_QUEST_ID, {
        ignorePrereq: true,
      });
      if (!assigned.ok) return null;
    }
    deEmbiggenifySourceLocation = opts.sourceLocation || instanceSourceHere({
      tsid: currentStreetTsid,
      x: player?.x ?? WORLD_W * 0.5,
      y: player?.y ?? GROUND_Y,
    });
    deEmbiggenifyPlayerBaseScale = player?.baseScale ?? null;
    if (app?.canvas) {
      app.canvas.dataset.deEmbiggenifySourceScale = String(
        deEmbiggenifyPlayerBaseScale || 0
      );
    }
    deEmbiggenifyState = createDeEmbiggenifyState({
      sourceLocation: deEmbiggenifySourceLocation,
    });
    deEmbiggenifyTransitionBusy = true;
    try {
      await setupDeEmbiggenifyInstance();
    } finally {
      deEmbiggenifyTransitionBusy = false;
    }
    if (!deEmbiggenifyIsInstanced()) return null;
    // The two minutes start once the room is on screen, not while its street loads.
    deEmbiggenifyState.enteredAt = Date.now();
    deEmbiggenifyState.deadlineAt = deEmbiggenifyState.enteredAt + EESTI_DURATION_MS;
    if (resumingPart2) beginDeEmbiggenifySearch(deEmbiggenifyState, Date.now());
    pushActivity('You shrink down inside Eesti Life Catalogue Page 17.');
    toast('Everything is enormous. Find Mr. Hairball.', 3400);
    updateHud();
    return deEmbiggenifyState;
  })();
  try {
    return await deEmbiggenifyStartPromise;
  } finally {
    deEmbiggenifyStartPromise = null;
  }
}

async function returnFromDeEmbiggenify({ abandon = false, expired = false } = {}) {
  if (!deEmbiggenifyState || deEmbiggenifyTransitionBusy) return false;
  deEmbiggenifyTransitionBusy = true;
  const source = deEmbiggenifySourceLocation || deEmbiggenifyState.sourceLocation;
  const status = expired ? 'expired' : abandon ? 'abandoned' : deEmbiggenifyState.status;
  if ((abandon || expired) && deEmbiggenifyState.status !== 'complete') {
    // #109: part one is done once you meet Mr. Hairball (de_embiggenify.js silent_complete), so
    // part two stays in the log to try again, as the source's stays todo (de_embiggenify_part2.js:
    // the instance only offers an exit, instances_show_exit_prompt). Dropping it left the log
    // showing De-Embiggenify done with no way back. The log's Enter button resumes the search.
    const part2 = Boolean(questState.active?.[DE_EMBIGGENIFY_PART2_QUEST_ID]);
    for (const id of deEmbiggenifyEndDrops({ part2 })) delete questState.active[id];
    removeItem(inv, SMALL_WORTHLESS_ID, countItem(inv, SMALL_WORTHLESS_ID));
    pushActivity(deEmbiggenifyEndLine({ expired, part2 }));
  }
  closeQuestDialogue({ force: true });
  if (deEmbiggenifyPlayerBaseScale && player) {
    player.baseScale = deEmbiggenifyPlayerBaseScale;
    applyPlayerFacing();
    if (app?.canvas) {
      app.canvas.dataset.deEmbiggenifyRestoredScale = String(player.baseScale);
    }
  }
  deEmbiggenifyState = null;
  deEmbiggenifySourceLocation = null;
  deEmbiggenifyPlayerBaseScale = null;
  mrHairballTarget = null;
  smallWorthlessTarget = null;
  const hud = document.getElementById('de-embiggenify-hud');
  if (hud) hud.hidden = true;
  try {
    if (source?.tsid && source.tsid !== EESTI_STREET_ID) {
      await enterStreetWithTransition(source.tsid, {
        spawnX: source.x,
        spawnY: source.y,
        quiet: true,
      });
    } else {
      await enterStreet(STREET_INDEX.default, { quiet: true });
    }
    if (app?.canvas) app.canvas.dataset.deEmbiggenifyStatus = status;
    savePlayerState();
    updateHud();
    return true;
  } finally {
    deEmbiggenifyTransitionBusy = false;
  }
}

function confirmLeaveDeEmbiggenify() {
  if (!deEmbiggenifyIsInstanced()) return;
  const part2 = Boolean(questState.active?.[DE_EMBIGGENIFY_PART2_QUEST_ID]);
  openScriptedQuestDialogue({
    title: 'De-Embiggenify',
    kicker: 'Leave the catalogue page?',
    cancelable: true,
    beats: [{
      text: part2
        ? 'Leaving now will end this tiny attempt. You can come back from your quest log to look again.'
        : 'Leaving now will abandon this tiny attempt. You can accept the quest again later.',
      response: 'Return to normal size',
    }],
    onComplete: () => returnFromDeEmbiggenify({ abandon: true }),
  });
}

function updateDeEmbiggenify() {
  if (!deEmbiggenifyIsInstanced() || deEmbiggenifyTransitionBusy) return;
  const now = Date.now();
  if (
    !['complete', 'expired'].includes(deEmbiggenifyState.status) &&
    eestiRemainingMs(deEmbiggenifyState, now) <= 0
  ) {
    expireDeEmbiggenify(deEmbiggenifyState, now);
    renderDeEmbiggenifyHud(now);
    toast('The catalogue page closes. You return to normal size.', 4200);
    setTimeout(() => returnFromDeEmbiggenify({ expired: true }), 450);
    return;
  }
  // The archived myles_is_great box creates the object (deEmbiggenifyMoment); the Pickup
  // verb on the glint stays as an accessible fallback.
  const autoplayMode = new URLSearchParams(location.search).get('eestiautoplay') || '';
  const autoplay = ['1', 'hairball', 'search', 'found'].includes(autoplayMode);
  if (autoplay && now >= deEmbiggenifyAutoNextAt) {
    deEmbiggenifyAutoNextAt = now + 90;
    if (isQuestDialogueOpen()) {
      if (autoplayMode !== 'hairball') advanceQuestDialogue();
    } else if (deEmbiggenifyState.status === 'arrival') {
      placeDeEmbiggenifyAutoplay(EESTI_AUTOPLAY_POINTS.hairball);
      handleDeEmbiggenifyTarget(mrHairballTarget, 'talk_to');
    } else if (deEmbiggenifyState.status === 'searching') {
      // Stand inside the archived box and let puzzles-feature fire it; `search` waits short of it.
      placeDeEmbiggenifyAutoplay(
        autoplayMode === 'search' ? EESTI_AUTOPLAY_POINTS.search : EESTI_AUTOPLAY_POINTS.find
      );
    } else if (deEmbiggenifyState.status === 'found') {
      if (autoplayMode !== 'found') {
        placeDeEmbiggenifyAutoplay(EESTI_AUTOPLAY_POINTS.hairball);
        handleDeEmbiggenifyTarget(mrHairballTarget, 'talk_to');
      }
    }
  }
  renderDeEmbiggenifyHud(now);
}

/** QA autoplay: stand at a source point of the street (EESTI_AUTOPLAY_POINTS). */
function placeDeEmbiggenifyAutoplay(point) {
  if (!player) return;
  const at = eestiStreetPoint(point);
  if (Math.abs(player.x - at.x) < 2 && Math.abs(player.y - at.y) < 12) return;
  player.position.set(at.x, at.y);
  player.vx = 0;
  player.vy = 0;
  player.onGround = false;
}

/** Narrow game hooks for js/paradise-course-runtime.js (the nine reconstructed courses). */
function paradiseCourseHost() {
  return {
    player,
    keys,
    bgLayer,
    preview: new URLSearchParams(location.search).get('paradisepreview') || '',
    consumeJump: () => {
      const queued = hasQueuedJump(jumpState, movementNow());
      if (queued) clearJumpQueue(jumpState);
      return queued;
    },
    playSfx,
    burst,
    toast,
    setPlayerAnim,
    applyPlayerFacing,
    dampingAlpha,
    now: () => Date.now(),
    time: () => time,
  };
}

function paradiseIsInstanced() {
  return Boolean(
    paradiseRun &&
      currentStreetTsid === `PARADISE_${String(paradiseRun.courseId).toUpperCase()}`
  );
}

function paradiseCourse() {
  return paradiseRun ? PARADISE_COURSES[paradiseRun.courseId] || null : null;
}

function paradiseRewardColor(rewardDef) {
  return rewardDef?.type === 'xp'
    ? 0xc58cff
    : rewardDef?.type === 'currants'
      ? 0xe0b65b
      : rewardDef?.type === 'favor'
        ? 0xe986ad
        : rewardDef?.type === 'energy'
          ? 0xbde663
          : 0x8fd160;
}

function applyParadiseReward(rewardDef) {
  if (!rewardDef) return { actual: 0, copy: '' };
  const amount = Math.max(0, Math.floor(Number(rewardDef.amount) || 0));
  let actual = amount;
  if (rewardDef.type === 'xp') {
    pc.imagination = Math.max(0, pc.imagination || 0);
    pc.xp = Math.max(0, pc.xp || 0);
    // Paradise iMG quoins and Qurazies (items/quoin.js 184, 209) take the mood bonus.
    actual = grantMoodXp(pc, amount);
  } else if (rewardDef.type === 'currants') {
    pc.currants = Math.max(0, pc.currants || 0) + amount;
  } else if (rewardDef.type === 'energy' || rewardDef.type === 'mood') {
    // #156: the quoin path (items/quoin.js 185-186): the player's own tank, never
    // lowering a stat above it, refused while dead or Super Pooped (G213).
    const credited = creditMetabolicReward(pc, rewardDef.type, amount);
    return { actual: credited.actual, copy: credited.copy };
  } else if (rewardDef.type === 'favor') {
    const giantId = rewardDef.giantId || 'friendly';
    shrineState.favor[giantId] = Math.max(0, shrineState.favor[giantId] || 0) + amount;
  }
  const copy =
    rewardDef.type === 'xp'
      ? `${rewardDef.quoin === 'qurazy' ? 'Qurazy! ' : ''}+${actual.toLocaleString()} iMG`
      : rewardDef.type === 'currants'
        ? `+${amount.toLocaleString()} currants`
        : rewardDef.type === 'favor'
          ? `+${amount.toLocaleString()} ${giantDisplayName(rewardDef.giantId || 'friendly')} favor`
          : `+${actual.toLocaleString()} ${rewardDef.type}`;
  return { actual, copy };
}

function vectorStar(radius = 16, color = 0xffe96a, alpha = 1) {
  const star = new PIXI.Graphics();
  const points = [];
  for (let index = 0; index < 10; index += 1) {
    const angle = -Math.PI / 2 + index * Math.PI / 5;
    const r = index % 2 === 0 ? radius : radius * 0.43;
    points.push(Math.cos(angle) * r, Math.sin(angle) * r);
  }
  star.poly(points).fill({ color: color, alpha: alpha }).stroke({ width: Math.max(1, radius * 0.08), color: 0xfff8c5, alpha: alpha * 0.9 });
  return star;
}

function addParadiseCloud(root, x, y, width, height, alpha = 0.9, tint = 0xffffff) {
  const kind = width > 520 ? 'cloud_fluffy_2' : 'cloud_fluffy_1';
  const cloud = new PIXI.Sprite(textureFromUrl(`assets/decos/groddle/${kind}.png`));
  cloud.anchor.set(0.5, 1);
  cloud.position.set(x, y);
  cloud.width = width;
  cloud.height = height;
  cloud.alpha = alpha;
  cloud.tint = tint;
  cloud.zIndex = -20;
  root.addChild(cloud);
  return cloud;
}

/** How far the sky runs on under a course: more than any window's view past the course's bottom. */
const PARADISE_SKY_BELOW = 1200;
/** Courses whose art ends in a floor run on in the floor's colour (js/paradise-course-runtime.js), not the sky's. */
const PARADISE_FLOOR_BELOW = Object.freeze({ abysmal_thrill: 0x1d2522, arbor_hollow: 0x24331c, sky_plunge: 0xffffff });

function paintParadiseSky(root, course) {
  const palettes = {
    cloud_rings: [0x789ed0, 0xe3a1a5, 0xf2d3aa, 0x889aba],
    radial_heights: [0x071e31, 0x0d3a50, 0x286276, 0x567d89],
    starlit_night: [0x170d3e, 0x382264, 0x65447d, 0x79678d],
    slip_n_slide: [0x102f42, 0x17485b, 0x2a6170, 0x477b82],
  };
  const colors = palettes[course.id] || course.palette;
  const sky = new PIXI.Graphics();
  const bands = 28;
  for (let index = 0; index < bands; index += 1) {
    const progress = index / Math.max(1, bands - 1);
    const section = Math.min(2, Math.floor(progress * 3));
    const local = progress * 3 - section;
    const from = colors[section];
    const to = colors[section + 1];
    const mix = (a, b) => Math.round(a + (b - a) * local);
    const color =
      (mix((from >> 16) & 0xff, (to >> 16) & 0xff) << 16) |
      (mix((from >> 8) & 0xff, (to >> 8) & 0xff) << 8) |
      mix(from & 0xff, to & 0xff);
    sky.rect(0, (course.height / bands) * index, course.width, course.height / bands + 2).fill(color);
    // Report 131: the camera sits up to its pack allowance and the pack's strip below the course (the
    // street view's skirt has no twin here), and the empty canvas showed there as a band.
    if (index === bands - 1) sky.rect(0, course.height, course.width, PARADISE_SKY_BELOW).fill(PARADISE_FLOOR_BELOW[course.id] ?? color);
  }
  sky.zIndex = -100;
  root.addChild(sky);

  const stars = new PIXI.Graphics();
  const starCount = course.skyStars ?? (course.id === 'cloud_rings' ? 45 : course.id === 'slip_n_slide' ? 95 : 180);
  for (let index = 0; index < starCount; index += 1) {
    const x = (index * 193 + 71) % course.width;
    const y = (index * 83 + 29) % Math.max(200, course.height * 0.84);
    const size = 0.8 + ((index * 17) % 22) / 10;
    stars.circle(x, y, size);
    stars.fill({ color: course.id === 'cloud_rings' ? 0xfff4dc : 0xe7f7ff, alpha: course.id === 'cloud_rings' ? 0.18 : course.id === 'slip_n_slide' ? 0.34 : 0.28 + (index % 5) * 0.08 });
  }
  stars.zIndex = -90;
  root.addChild(stars);
  return sky;
}

function buildCloudRingsBackground(root, course) {
  const mountains = new PIXI.Graphics();
  mountains.poly([0, 810, 0, 470, 115, 405, 210, 470, 300, 610, 365, 810]);
  mountains.poly([3215, 810, 3300, 600, 3385, 465, 3490, 385, 3600, 450, 3600, 810]);
  mountains.fill({ color: 0x5f6f8c, alpha: 0.58 });
  mountains.poly([0, 850, 0, 600, 90, 530, 185, 620, 250, 850]);
  mountains.poly([3370, 850, 3435, 620, 3525, 520, 3600, 580, 3600, 850]);
  mountains.fill({ color: 0x3f526f, alpha: 0.76 });
  mountains.zIndex = -60;
  root.addChild(mountains);

  for (let index = 0; index < 12; index += 1) {
    addParadiseCloud(
      root,
      index * 330 + 90,
      910 - (index % 3) * 32,
      500 + (index % 4) * 90,
      135 + (index % 3) * 24,
      0.78,
      index % 2 ? 0xdce9f3 : 0xf4e6df
    );
  }
  for (let index = 0; index < 9; index += 1) {
    addParadiseCloud(
      root,
      280 + index * 410,
      300 + (index % 4) * 80,
      210 + (index % 3) * 60,
      62 + (index % 2) * 18,
      0.28,
      0xfff4ee
    );
  }
}

function buildRadialBackground(root, course) {
  for (let index = 0; index < 8; index += 1) {
    const side = index % 2 ? course.width - 150 : 150;
    addParadiseCloud(
      root,
      side + ((index * 71) % 210) - 105,
      420 + index * 205,
      620 + (index % 3) * 170,
      210 + (index % 3) * 55,
      0.2,
      0x74a5b2
    );
  }
  addParadiseCloud(root, 1000, 1950, 1550, 320, 0.52, 0xc3d9de);
  addParadiseCloud(root, 500, 1685, 410, 120, 0.88, 0xe9f1f0);
  addParadiseCloud(root, 1000, 1160, 440, 120, 0.72, 0xdbe7e8);

  const moonAsset = `assets/decos/groddle/${RADIAL_HEIGHTS_MOON.asset}?v=radial-322`;
  const moonTexture = textureFromUrl(moonAsset);
  const moon = new PIXI.Sprite(moonTexture);
  moon.anchor.set(0.5);
  moon.position.set(RADIAL_HEIGHTS_MOON.x, RADIAL_HEIGHTS_MOON.y);
  moon.width = RADIAL_HEIGHTS_MOON.width;
  moon.height = RADIAL_HEIGHTS_MOON.height;
  moon.zIndex = -3;
  moon._sourceStreetTsid = course.sourceStreetTsid;
  root.addChild(moon);
  root.paradiseRadialMoon = moon;
}

function buildStarlitBackground(root, course, points) {
  const starFieldAsset = 'assets/decos/groddle/stars_2.png';
  const starFields = STARLIT_NIGHT_STAR_FIELDS.map((spec, index) => {
    const field = new PIXI.Sprite(textureFromUrl(starFieldAsset));
    field.anchor.set(0.5);
    field.position.set(spec.x, spec.y);
    field.width = spec.width;
    field.height = spec.height;
    field.tint = spec.depth === 'sky' ? 0xbca9d7 : 0xd4c7e7;
    field.alpha = spec.depth === 'sky' ? 0.32 : 0.46;
    field.zIndex = spec.depth === 'sky' ? -82 : -72;
    field._sourceFieldIndex = index;
    root.addChild(field);
    return field;
  });

  const cloudFloor = new PIXI.Graphics();
  for (let index = 0; index < 15; index += 1) {
    cloudFloor.ellipse(index * 115 - 40, 865 - (index % 3) * 16, 135, 58).fill({ color: index % 2 ? 0xb6a7cb : 0xd9d1e2, alpha: 0.82 });
  }
  cloudFloor.zIndex = -30;
  root.addChild(cloudFloor);

  points.forEach((point, index) => {
    const starAsset = `assets/decos/groddle/star_asset_0${point.major ? '1' : '2'}.png`;
    const ghost = new PIXI.Sprite(
      textureFromUrl(starAsset)
    );
    ghost.anchor.set(0.5);
    ghost.position.set(point.x, point.y);
    ghost.width = (point.radius || 13) * 2.38;
    ghost.height = (point.radius || 13) * 2.38;
    ghost.alpha = 0;
    ghost.zIndex = -4;
    ghost.rotation = index % 2 ? 0.18 : -0.12;
    ghost._litStartedAt = 0;
    root.addChild(ghost);
    paradiseBackdropStars[index] = ghost;
  });

  const makeMoonState = (spec, version, zIndex) => {
    const src = `assets/decos/groddle/${spec.asset}?v=${version}`;
    const sprite = new PIXI.Sprite(textureFromUrl(src));
    sprite.anchor.set(0.5);
    sprite.position.set(spec.x, spec.y);
    sprite.width = spec.width;
    sprite.height = spec.height;
    sprite.zIndex = zIndex;
    root.addChild(sprite);
    return sprite;
  };
  const smile = makeMoonState(STARLIT_NIGHT_MOON.smile, 'starlit-150', -8);
  const plain = makeMoonState(STARLIT_NIGHT_MOON.plain, 'starlit-149', -7);
  root.paradiseMoonSmile = smile;
  root.paradiseMoonPlain = plain;
  root.paradiseMoonFadeStartedAt = 0;
  root.paradiseStarlitStarFields = starFields;
}

function addSlipRecoveredDeco(root, spec) {
  const texture = textureFromUrl(`assets/decos/groddle/${spec.sprite}.png`);
  const sprite = new PIXI.Sprite(texture);
  sprite.anchor.set(0.5, 1);
  sprite.position.set(
    spec.x,
    slipTerrainY(spec.x) + (Number(spec.groundOffset) || 0)
  );
  sprite.alpha = Number.isFinite(spec.alpha) ? spec.alpha : 1;
  sprite.zIndex = Number(spec.z) || -20;
  sprite._slipLandmarkId = spec.id || '';
  const applySize = () => {
    const sourceWidth = Math.max(1, texture.orig?.width || texture.width || 1);
    const sourceHeight = Math.max(1, texture.orig?.height || texture.height || 1);
    sprite.width = spec.width;
    sprite.height = spec.width * (sourceHeight / sourceWidth);
  };
  if (isLoaded(texture.source)) applySize();
  else onLoaded(texture.source, applySize);
  root.addChild(sprite);
  return sprite;
}

function buildSlipBackground(root, course) {
  const moon = new PIXI.Graphics();
  moon.circle(0, 0, 72).fill({ color: 0xffef9a, alpha: 0.78 });
  moon.circle(28, -18, 70).fill({ color: 0x17485b, alpha: 1 });
  moon.position.set(2860, 175);
  moon.zIndex = -78;
  root.addChild(moon);

  const mountains = new PIXI.Graphics();
  mountains.poly([
    0, 690, 0, 520, 170, 405, 285, 555, 430, 350, 610, 540, 795, 365,
    1010, 565, 1200, 410, 1410, 575, 1640, 330, 1860, 555, 2090, 390,
    2290, 580, 2520, 350, 2760, 555, 3010, 390, 3250, 565, 3600, 430,
    3600, 690,
  ]);
  mountains.fill({ color: 0x79949a, alpha: 0.48 });
  mountains.poly([
    0, 700, 0, 570, 185, 440, 285, 555, 430, 383, 610, 550, 795, 405,
    1010, 575, 1200, 450, 1410, 585, 1640, 375, 1860, 565, 2090, 430,
    2290, 590, 2520, 395, 2760, 565, 3010, 430, 3250, 575, 3600, 470,
    3600, 700,
  ]);
  mountains.fill({ color: 0xc7d7d9, alpha: 0.82 });
  mountains.zIndex = -55;
  root.addChild(mountains);

  const snowTrees = [];
  for (let index = 0; index < 24; index += 1) {
    const x = 70 + ((index * 271) % (course.width - 140));
    const ground = slipTerrainY(x);
    const width = 34 + (index % 5) * 9;
    const tree = addSlipRecoveredDeco(root, {
      id: `snow-tree-${index + 1}`,
      sprite: SLIP_N_SLIDE_TREE_SPRITES[index % SLIP_N_SLIDE_TREE_SPRITES.length],
      x,
      width,
      z: -24,
      groundOffset: 4,
      alpha: 0.86 + (index % 3) * 0.06,
    });
    tree.y = ground + 4;
    snowTrees.push(tree);
  }

  const landmarks = SLIP_N_SLIDE_LANDMARKS.map((spec) =>
    addSlipRecoveredDeco(root, spec)
  );

  const terrain = new PIXI.Graphics();
  const terrainPoints = [0, course.height];
  for (let x = 0; x <= course.width; x += 16) {
    terrainPoints.push(x, slipTerrainY(x));
  }
  terrainPoints.push(course.width, course.height);
  terrain.poly(terrainPoints).fill(0xdce8e9).stroke({ width: 5, color: 0xf6fbfa, alpha: 1 });
  terrain.zIndex = -10;
  root.addChild(terrain);

  const flakes = [];
  for (let index = 0; index < 90; index += 1) {
    const flake = new PIXI.Graphics();
    const radius = 0.8 + (index % 4) * 0.55;
    flake.circle(0, 0, radius).fill({ color: 0xf8ffff, alpha: 0.32 + (index % 5) * 0.1 });
    flake.position.set((index * 167 + 31) % course.width, (index * 79 + 23) % 650);
    flake._speed = 0.18 + (index % 7) * 0.055;
    flake._drift = ((index % 5) - 2) * 0.035;
    flake.zIndex = 4;
    root.addChild(flake);
    flakes.push(flake);
  }
  root.paradiseSnowflakes = flakes;
  root.paradiseSlipLandmarks = landmarks;
  root.paradiseSlipTrees = snowTrees;
}

async function loadParadiseSourcePoints(course) {
  if (!course?.sourceStreetTsid) return [];
  try {
    const response = await fetch(`assets/streets/${course.sourceStreetTsid}.json`);
    if (!response.ok) return [];
    const data = await response.json();
    const layer = (data.layers || []).find((entry) =>
      course.id === 'radial_heights'
        ? entry.name === 'yellow stars'
        : entry.name === 'middleground'
    );
    if (!layer) return [];
    return (layer.decos || [])
      .filter((deco) => /^star_asset_0[12]$/.test(String(deco.sprite || '')))
      .map((deco) => {
        const screenSpace = /^T_/.test(String(layer.id || ''));
        return {
          x: screenSpace ? deco.x : deco.x - data.bounds.l,
          y: screenSpace ? deco.y : deco.y - data.bounds.t,
          radius: Math.max(10, Math.min(28, Number(deco.w || 30) * 0.42)),
          major: String(deco.sprite) === 'star_asset_01',
        };
      });
  } catch {
    return [];
  }
}

async function loadParadiseVisualAssets(course) {
  if (course?.art) {
    await Promise.all(
      paradiseCoursePreloadUrls(course).map((src) => loadTexture(src).catch(() => null))
    );
    return;
  }
  if (course?.id === 'radial_heights') {
    const src = `assets/decos/groddle/${RADIAL_HEIGHTS_MOON.asset}?v=radial-322`;
    await loadTexture(src, { width: RADIAL_HEIGHTS_MOON.width, height: RADIAL_HEIGHTS_MOON.height }).catch(() => null);
    return;
  }
  if (course?.id === 'starlit_night') {
    const moonAssets = [
      [STARLIT_NIGHT_MOON.plain, 'starlit-149'],
      [STARLIT_NIGHT_MOON.smile, 'starlit-150'],
    ];
    await Promise.all([
      ...moonAssets.map(([spec, version]) =>
        loadTexture(`assets/decos/groddle/${spec.asset}?v=${version}`, { width: spec.width, height: spec.height }).catch(() => null)
      ),
      loadTexture('assets/decos/groddle/stars_2.png').catch(() => null),
      loadTexture('assets/decos/groddle/star_asset_01.png').catch(() => null),
      loadTexture('assets/decos/groddle/star_asset_02.png').catch(() => null),
    ]);
    return;
  }
  if (course?.id !== 'slip_n_slide') return;
  const sprites = new Set([
    ...SLIP_N_SLIDE_LANDMARKS.map((entry) => entry.sprite),
    ...SLIP_N_SLIDE_TREE_SPRITES,
  ]);
  await Promise.all(
    [...sprites].map((sprite) =>
      loadTexture(`assets/decos/groddle/${sprite}.png`).catch(() => null)
    )
  );
}

function cloudRingPickupPoints(course) {
  return Array.from({ length: course.pickupCount }, (_, index) => {
    const progress = (index + 1) / (course.pickupCount + 1);
    return {
      x: 260 + progress * (course.width - 520),
      y: 420 + Math.sin(progress * Math.PI * 5.2) * 185 + (index % 3) * 22,
      radius: 18,
    };
  });
}

function slipPickupPoints(course) {
  const heights = [58, 116, 62, 132, 58, 108, 62, 138, 58, 112, 60, 136, 58, 108, 62, 128, 58, 104];
  return heights.map((height, index) => {
    const x = 350 + index * ((course.width - 700) / (heights.length - 1));
    return {
      x,
      y: slipTerrainY(x) - height,
      radius: index % 3 === 1 ? 22 : 17,
      major: index % 3 === 1,
    };
  });
}

function fallbackParadisePoints(course) {
  const count = course.pickupCount;
  if (course.id === 'radial_heights') {
    return Array.from({ length: count }, (_, index) => {
      const progress = index / Math.max(1, count - 1);
      const angle = progress * Math.PI * 6.3;
      const radius = 90 + progress * 470;
      return {
        x: 1000 + Math.cos(angle) * radius,
        y: 1000 + Math.sin(angle) * radius,
        radius: index % 4 ? 12 : 23,
      };
    });
  }
  return Array.from({ length: count }, (_, index) => ({
    x: 140 + index * ((course.width - 280) / Math.max(1, count - 1)),
    y: 440 + Math.sin(index * 1.17) * 220,
    radius: 13,
  }));
}

function buildParadiseBackground(course, points) {
  const root = new PIXI.Container();
  root.sortableChildren = true;
  root.worldH = course.height;
  root.platformsScreen = [];
  root.signViews = [];
  paintParadiseSky(root, course);
  if (course.id === 'cloud_rings') buildCloudRingsBackground(root, course);
  else if (course.id === 'radial_heights') buildRadialBackground(root, course);
  else if (course.id === 'starlit_night') buildStarlitBackground(root, course, points);
  else if (course.art) buildParadiseCourseArt(root, course, { foreground: entityLayer });
  else buildSlipBackground(root, course);
  return root;
}

function paradiseQuoinType(course, index) {
  const type = course.rewards[index % course.rewards.length]?.type || 'xp';
  return QUOIN_TYPES[type] ? type : type === 'favor' ? 'favor' : 'xp';
}

function spawnParadisePickup(course, point, index) {
  let sprite;
  let typeId = '';
  if (PARADISE_STAR_COURSES.includes(course.id)) {
    sprite = vectorStar(point.radius || 13, 0xffe15c, 0.96);
    sprite.rotation = index % 2 ? 0.13 : -0.13;
    sprite.baseScale = 1;
  } else {
    const quoinType = paradiseQuoinType(course, index);
    typeId = quoinType;
    sprite = new PIXI.AnimatedSprite(quoinFrames(quoinType));
    sprite.anchor.set(0.5);
    sprite.animationSpeed = 0.28;
    sprite.loop = true;
    sprite.play();
    sprite.baseScale = paradiseQuoinScale(course.id);
    sprite.scale.set(sprite.baseScale);
    const glow = new PIXI.Graphics();
    glow.circle(0, 0, 23).fill({ color: QUOIN_TYPES[quoinType].color, alpha: 0.18 });
    sprite.addChildAt(glow, 0);
  }
  sprite.position.set(point.x, point.y);
  sprite.baseY = point.y;
  sprite.phase = index * 0.91;
  sprite.zIndex = 30;
  entityLayer.addChild(sprite);
  const entry = { index, sprite, point, typeId, collected: false };
  paradisePickups.push(entry);
  return entry;
}

function spawnCloudRing(course, index) {
  const positions = [
    [670, 425],
    [1240, 610],
    [1850, 330],
    [2460, 570],
    [3040, 370],
  ];
  const [x, y] = positions[index] || [500 + index * 580, 450];
  const root = new PIXI.Container();
  root.position.set(x, y);
  root.zIndex = 12;
  root.sortableChildren = true;
  root._cloudPhase = index * 1.37;
  const profile = CLOUD_RING_PROFILES[index % CLOUD_RING_PROFILES.length];
  const glow = new PIXI.Graphics();
  glow.ellipse(0, 0, profile.outerRx - 20, profile.outerRy - 28).stroke({ width: 72, color: profile.tint, alpha: 0.18 });
  glow.zIndex = -2;
  root.addChild(glow);
  const puffs = cloudRingPuffLayout(index).map((puff, puffIndex) => {
    // The source tunnels fill most of the location viewport. Build their
    // cloud masses as native-resolution vector lobes so scaling never carries
    // thumbnail blur or recording artifacts into the remake.
    const sprite = new PIXI.Container();
    const shadow = new PIXI.Graphics();
    shadow.ellipse(3, 5, puff.width * 0.5, puff.height * 0.45).fill({ color: puff.shadowTint, alpha: 0.24 });
    sprite.addChild(shadow);
    const body = new PIXI.Graphics();
    body.ellipse(0, 0, puff.width * 0.5, puff.height * 0.38);
    body.ellipse(-puff.width * 0.22, -puff.height * 0.08, puff.width * 0.27, puff.height * 0.35);
    body.ellipse(puff.width * 0.03, -puff.height * 0.19, puff.width * 0.31, puff.height * 0.4);
    body.ellipse(puff.width * 0.27, -puff.height * 0.04, puff.width * 0.25, puff.height * 0.32);
    body.fill({ color: puff.tint, alpha: 0.96 });
    sprite.addChild(body);
    const highlight = new PIXI.Graphics();
    highlight.ellipse(-puff.width * 0.08, -puff.height * 0.22, puff.width * 0.29, puff.height * 0.16).fill({ color: 0xffffff, alpha: 0.14 });
    sprite.addChild(highlight);
    sprite.position.set(puff.x, puff.y);
    sprite.rotation = puff.rotation;
    sprite.alpha = puff.alpha;
    sprite.zIndex = Math.sin((puffIndex / 32) * Math.PI * 2) > 0 ? 2 : 0;
    sprite._baseX = puff.x;
    sprite._baseY = puff.y;
    sprite._baseAlpha = puff.alpha;
    sprite._phase = puffIndex * 0.61 + index;
    root.addChild(sprite);
    return sprite;
  });
  const sparkle = new PIXI.Graphics();
  for (let dot = 0; dot < 14; dot += 1) {
    const angle = (dot / 14) * Math.PI * 2 + index * 0.4;
    sparkle.circle(
      Math.cos(angle) * (profile.outerRx + 8),
      Math.sin(angle) * (profile.outerRy + 10),
      1.4 + (dot % 2)
    );
    sparkle.fill({ color: 0xffffff, alpha: 0.3 + (dot % 3) * 0.16 });
  }
  sparkle.zIndex = 4;
  root.addChild(sparkle);
  root._cloudPuffs = puffs;
  entityLayer.addChild(root);
  const entry = {
    index,
    sprite: root,
    rx: profile.innerRx,
    ry: profile.innerRy,
    passed: false,
  };
  paradiseRings.push(entry);
  return entry;
}

function spawnParadiseExit(course) {
  const root = new PIXI.Container();
  root.position.set(
    course.exit.x,
    course.movement === 'slide' ? slipTerrainY(course.exit.x) : course.exit.y
  );
  root.zIndex = 44;
  const glow = new PIXI.Graphics();
  // Reconstructed courses paint their own exit door; keep only a soft glow.
  if (course.art) glow.alpha = 0.35;
  glow.setFillStyle({ color: 0xbfefff, alpha: 0.18 });
  glow.ellipse(0, -50, 62, 84).fill();
  glow.roundRect(-42, -120, 84, 112, 39).fill().stroke({ width: 5, color: 0xf9ffff, alpha: 0.94 });
  glow.roundRect(-33, -110, 66, 101, 31).fill().stroke({ width: 2, color: 0x7dadd1, alpha: 0.88 });
  root.addChild(glow);
  const arrow = new PIXI.Text({ text: '↓', style: {
    fontFamily: 'Trebuchet MS, sans-serif',
    fontSize: 27,
    fontWeight: '900',
    fill: 0xffffff,
    stroke: { color: 0x34506f, width: 3 },
  } });
  arrow.anchor.set(0.5);
  arrow.position.set(0, -68);
  root.addChild(arrow);
  const label = new PIXI.Text(
    { text: course.id === 'radial_heights' ? "EXIT'S DOWN HERE!" : course.exitLabel ?? 'WAY HOME', style: {
      fontFamily: 'Trebuchet MS, sans-serif',
      fontSize: 12,
      fontWeight: '900',
      fill: 0xffffff,
      stroke: { color: 0x314764, width: 4 },
    } }
  );
  label.anchor.set(0.5);
  label.position.set(0, -140);
  root.addChild(label);
  // Report 131: shut until the course's goal is met: planks nailed across it and the word, not only faded.
  arrow.visible = false;
  const shut = paradiseExitShutSign();
  root.addChild(shut);
  root.alpha = 0.82;
  entityLayer.addChild(root);
  paradiseExit = { sprite: root, active: false, shut, arrow, lineAt: 0 };
  return paradiseExit;
}

/** The closed way home's boards (over the arch, in its own px) and its SHUT sign. */
function paradiseExitShutSign() {
  const root = new PIXI.Container();
  const planks = new PIXI.Graphics();
  for (const [from, to] of [[[-46, -108], [46, -22]], [[46, -108], [-46, -22]]]) {
    const dx = to[0] - from[0];
    const dy = to[1] - from[1];
    const len = Math.hypot(dx, dy);
    const nx = (-dy / len) * 8;
    const ny = (dx / len) * 8;
    planks.poly([from[0] + nx, from[1] + ny, to[0] + nx, to[1] + ny, to[0] - nx, to[1] - ny, from[0] - nx, from[1] - ny])
      .fill(0x8a5a33).stroke({ width: 2, color: 0x4b2d17 });
  }
  planks.circle(0, -65, 5).fill(0x4b2d17);
  root.addChild(planks);
  const sign = new PIXI.Text({ text: 'SHUT', style: {
    fontFamily: 'Trebuchet MS, sans-serif',
    fontSize: 15,
    fontWeight: '900',
    fill: 0xffffff,
    stroke: { color: 0x8c1f1f, width: 5 },
  } });
  sign.anchor.set(0.5);
  sign.position.set(0, -122);
  root.addChild(sign);
  return root;
}

function announceParadiseFlight(course) {
  const promptText = new PIXI.Text(
    { text: course.prompt || (course.movement === 'slide' ? 'BUILD SPEED · SPACEBAR JUMPS!' : 'PRESS SPACEBAR TO FLY!'), style: {
    fontFamily: 'Trebuchet MS, sans-serif',
    fontSize: 26,
    fontWeight: '900',
    fill: 0xffffff,
    stroke: { color: 0x283a66, width: 5 },
    dropShadow: { blur: 6, color: 0x11152f, distance: 2 },
    } }
  );
  promptText.anchor.set(0.5);
  promptText.position.set(course.spawn.x + 260, course.spawn.y - 145);
  promptText.zIndex = 90;
  promptText._life = 0;
  promptText._max = 190;
  promptText._vy = -0.08;
  fxLayer.addChild(promptText);
}

function renderParadiseFlightHud() {
  const hud = document.getElementById('paradise-flight-hud');
  const visible = paradiseIsInstanced();
  if (hud) hud.hidden = !visible;
  if (!visible || !hud) return;
  const course = paradiseCourse();
  const progress = paradiseRunProgress(paradiseRun);
  const remaining = paradiseRemainingMs(paradiseRun);
  const seconds = Math.ceil(remaining / 1000);
  const icon = hud.querySelector('[data-paradise-icon]');
  const title = hud.querySelector('[data-paradise-title]');
  const timer = hud.querySelector('[data-paradise-timer]');
  const objective = hud.querySelector('[data-paradise-objective]');
  const progressEl = hud.querySelector('[data-paradise-progress]');
  const tickets = hud.querySelector('[data-paradise-tickets]');
  const controls = hud.querySelector('[data-paradise-controls]');
  if (icon) icon.src = `assets/sprites/icons/${course.ticketId}.webp`;
  if (title) title.textContent = course.name;
  if (controls) {
    controls.textContent = course.controls || (course.movement === 'slide'
      ? 'Arrows build speed · Spacebar jumps'
      : 'Spacebar to fly · arrows to steer');
  }
  if (timer) {
    timer.textContent = `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`;
    timer.classList.toggle('is-low', remaining <= 30_000);
  }
  if (objective) objective.textContent = paradiseObjective(paradiseRun);
  if (progressEl) {
    progressEl.textContent = course.ringCount
      ? `${progress.rings} / ${progress.ringTotal} rings · ${progress.collected} quoins`
      : `${progress.collected} / ${progress.total} ${
          course.progressNoun || (course.id === 'radial_heights' || course.id === 'slip_n_slide' ? 'stars' : 'lights')
        }`;
  }
  if (tickets) tickets.textContent = `${paradiseState.ticketsToday}/${PARADISE_DAILY_LIMIT} tickets today`;
  if (app?.canvas) {
    app.canvas.dataset.paradiseCourse = course.id;
    app.canvas.dataset.paradiseStatus = paradiseRun.status;
    app.canvas.dataset.paradiseRemaining = String(remaining);
    app.canvas.dataset.paradiseCollected = String(progress.collected);
    app.canvas.dataset.paradiseTotal = String(progress.total);
    app.canvas.dataset.paradiseRings = String(progress.rings);
    app.canvas.dataset.paradiseRingTotal = String(progress.ringTotal);
    app.canvas.dataset.paradiseObjective = paradiseObjective(paradiseRun);
    app.canvas.dataset.paradiseExit = paradiseExit?.active ? 'open' : 'closed';
    if (course.id === 'cloud_rings') {
      app.canvas.dataset.paradiseRingArt = 'clean-cloud-puffs';
      app.canvas.dataset.paradiseRingPuffs = String(
        paradiseRings.reduce(
          (total, entry) => total + (entry.sprite?._cloudPuffs?.length || 0),
          0
        )
      );
    } else if (course.id === 'radial_heights') {
      app.canvas.dataset.paradiseRadialArt = 'source-moon-and-stars';
      app.canvas.dataset.paradiseRadialMoon = [
        RADIAL_HEIGHTS_MOON.x,
        RADIAL_HEIGHTS_MOON.y,
        RADIAL_HEIGHTS_MOON.width,
      ].join(',');
      app.canvas.dataset.paradiseSourceStars = String(paradisePickups.length);
    } else if (course.id === 'starlit_night') {
      app.canvas.dataset.paradiseStarlitArt = 'source-starfield-and-moon-states';
      app.canvas.dataset.paradiseStarlitFields = String(
        bgLayer?.paradiseStarlitStarFields?.length || 0
      );
      app.canvas.dataset.paradiseStarlitMoon = [
        STARLIT_NIGHT_MOON.plain.x,
        STARLIT_NIGHT_MOON.plain.y,
        STARLIT_NIGHT_MOON.plain.width,
      ].join(',');
      app.canvas.dataset.paradiseStarlitLit = String(
        paradiseBackdropStars.filter((star) => star?._litStartedAt > 0).length
      );
      app.canvas.dataset.paradiseStarlitSourceStars = String(paradiseBackdropStars.length);
    } else if (course.art) {
      Object.assign(app.canvas.dataset, paradiseCourseRuntime.dataset(paradiseCourseHost(), course));
    } else if (course.id === 'slip_n_slide') {
      app.canvas.dataset.paradiseSlipArt = 'recovered-k03-landmarks';
      app.canvas.dataset.paradiseSlipLandmarks = String(
        bgLayer?.paradiseSlipLandmarks?.length || 0
      );
      app.canvas.dataset.paradiseSlipTrees = String(
        bgLayer?.paradiseSlipTrees?.length || 0
      );
    }
  }
}

function setupParadiseCourse(course, sourcePoints) {
  clearWorldEntities();
  const points = sourcePoints.length === course.pickupCount
    ? sourcePoints
    : course.id === 'cloud_rings'
      ? cloudRingPickupPoints(course)
      : course.id === 'slip_n_slide'
        ? slipPickupPoints(course)
      : course.pickups
        ? course.pickups.map((point) => ({ ...point, radius: 13 }))
      : fallbackParadisePoints(course);
  if (bgLayer && world) {
    world.removeChild(bgLayer);
    bgLayer.destroy({ children: true });
  }
  const backdropPoints =
    course.id === 'starlit_night' && sourcePoints.length
      ? sourcePoints
      : points;
  bgLayer = buildParadiseBackground(course, backdropPoints);
  world.addChildAt(bgLayer, 0);
  currentStreetTsid = `PARADISE_${course.id.toUpperCase()}`;
  currentStreet = {
    tsid: currentStreetTsid,
    label: course.name,
    hubName: '', // G363: a paradise_ticket instance (paradise_ticket.js 285): no hub line (location.js 3311)
    musicFile: course.musicFile || null,
    bounds: { l: 0, r: course.width, t: 0, b: course.height },
    platforms: [],
    signposts: [],
  };
  if (course.musicFile) setAmbientForStreet(currentStreet);
  WORLD_W = course.width;
  GROUND_Y = course.height - 80;
  streetPlatforms = [];
  streetWalls = [];
  climb = { active: false, wall: null };
  points.forEach((point, index) => spawnParadisePickup(course, point, index));
  if (course.id === 'cloud_rings') {
    for (let index = 0; index < course.ringCount; index += 1) spawnCloudRing(course, index);
  }
  spawnParadiseExit(course);
  if (player) {
    const previewRing =
      course.id === 'cloud_rings' &&
      new URLSearchParams(location.search).get('paradisepreview') === 'ring'
        ? paradiseRings[0]
        : null;
    const previewMoon =
      course.id === 'radial_heights' &&
      new URLSearchParams(location.search).get('paradisepreview') === 'moon';
    const starlitPreview =
      course.id === 'starlit_night'
        ? new URLSearchParams(location.search).get('paradisepreview')
        : '';
    const previewStarlitMoon = starlitPreview === 'moon' || starlitPreview === 'smile';
    const previewFinish =
      course.id === 'slip_n_slide' &&
      new URLSearchParams(location.search).get('paradisepreview') === 'finish';
    player.x = previewRing
      ? previewRing.sprite.x - 330
      : previewMoon
        ? 1080
        : previewStarlitMoon
          ? 1100
        : previewFinish
          ? 3160
          : course.spawn.x;
    player.y = previewRing
      ? previewRing.sprite.y - 80
      : previewMoon
        ? 1120
        : previewStarlitMoon
          ? 350
          : previewFinish
            ? slipTerrainY(player.x)
            : course.movement === 'slide'
              ? slipTerrainY(course.spawn.x)
              : course.spawn.y;
    player.vx = previewFinish ? 0 : course.movement === 'slide' ? 2.4 : 0;
    player.vy = 0;
    player.onGround = course.movement === 'slide';
    player.rotation = 0;
    setPlayerAnim('idle');
    if (previewRing && app?.canvas) app.canvas.dataset.paradisePreview = 'cloud-ring';
    if (previewMoon && app?.canvas) app.canvas.dataset.paradisePreview = 'radial-moon';
    if (previewStarlitMoon && bgLayer) {
      if (starlitPreview === 'smile') {
        const now = Date.now();
        bgLayer.paradiseMoonFadeStartedAt = now - STARLIT_NIGHT_MOON_FADE_MS;
        for (const star of paradiseBackdropStars) {
          if (star) star._litStartedAt = now - STARLIT_NIGHT_STAR_FADE_MS;
        }
      }
      if (app?.canvas) {
        app.canvas.dataset.paradisePreview =
          starlitPreview === 'smile' ? 'starlit-moon-smile' : 'starlit-moon-plain';
      }
    }
    if (previewFinish && app?.canvas) app.canvas.dataset.paradisePreview = 'slip-finish';
    if (course.art) {
      paradiseCourseRuntime.enter(paradiseCourseHost(), course);
      const preview = new URLSearchParams(location.search).get('paradisepreview');
      if (preview && app?.canvas) app.canvas.dataset.paradisePreview = `${course.id}-${preview}`;
    }
  }
  camTarget = cameraTargetForPlayer(player.x);
  camY = cameraTargetY(
    player.y,
    activeCameraWorldHeight(0.55),
    LOCATION_VIEW_H,
    0.55
  );
  world.x = -camTarget;
  world.y = -camY;
  const name = document.getElementById('street-name');
  if (name) {
    name.textContent = course.name;
    name.dataset.tsid = currentStreetTsid;
  }
  savePlayerLocation(paradiseSourceLocation);
  announceParadiseFlight(course);
  renderParadiseFlightHud();
  updateHud();
}

async function transitionIntoParadise(course, points, useTransition = true) {
  const setup = () => setupParadiseCourse(course, points);
  const el = document.getElementById('screen-transition');
  if (!useTransition || !el) {
    setup();
    return;
  }
  const colors = {
    cloud_rings: [0x769ed1, 0xe5aca5],
    radial_heights: [0x08243a, 0x3f7380],
    starlit_night: [0x180f43, 0x725184],
    slip_n_slide: [0x14384a, 0x4b7c82],
  }[course.id] || course.transitionColors;
  await runStreetTransition(el, {
    fromLabel: currentStreet?.label || '',
    fromHub: currentStreet?.hubName || '',
    toLabel: course.name,
    toHub: '',
    topColor: colors[0],
    bottomColor: colors[1],
    onMid: async () => setup(),
  });
}

async function startParadiseFlight(courseId, opts = {}) {
  if (paradiseStartPromise) return paradiseStartPromise;
  if (paradiseRun) return paradiseRun;
  const course = PARADISE_COURSES[courseId];
  if (!course) return null;
  paradiseStartPromise = (async () => {
    closeQuestPanel();
    closeQuestDialogue({ force: true });
    closePackPopover();
    paradiseSourceLocation = opts.sourceLocation || instanceSourceHere({
      tsid: currentStreetTsid,
      x: player?.x ?? WORLD_W * 0.5,
      y: player?.y ?? GROUND_Y,
    });
    paradiseRun = createParadiseRun(courseId, {
      now: Date.now(),
      sourceLocation: paradiseSourceLocation,
    });
    state.hudTick = 0;
    paradiseAutoNextAt = 0;
    paradiseCompletionAnnounced = false;
    savePlayerLocation(paradiseSourceLocation);
    const [points] = await Promise.all([
      loadParadiseSourcePoints(course),
      loadParadiseVisualAssets(course),
    ]);
    await transitionIntoParadise(course, points, opts.useTransition !== false);
    const controls = course.controlsHint || (course.movement === 'slide'
      ? 'Use the arrows to build speed. Spacebar jumps.'
      : 'Spacebar to fly. Arrow keys steer.');
    pushActivity(`${course.name}: ${controls} ${course.objective}.`);
    toast(controls, 3600);
    return paradiseRun;
  })();
  try {
    return await paradiseStartPromise;
  } finally {
    paradiseStartPromise = null;
  }
}

/** skills_is_learning / skills_at_max_acceleration for the Yellow Crumb items. */
function studyBuffContext(now = Date.now()) {
  const active = getActiveStudy(skillState, now);
  return {
    learning: Boolean(active),
    atMaxAcceleration: Boolean(active?.isAccelerated && active.acceleratedUntil >= active.endsAt),
  };
}

/** Hell's own state (hell-feature isDead): the source's pc.is_dead. */
function playerIsDead() {
  return features.query('isDead', engine) === true;
}

/**
 * paradise_ticket.js verbs.eat: 20 iMG + 1 energy and a quip for each ticket;
 * `count` from the card's "Eat how many?" eats several in one go (the
 * handler's this.count).
 */
function eatPackedParadiseTicket(classTsid, count = 1) {
  if (!state.started || !paradiseCourseForTicket(classTsid)) return false;
  const label = listPackSlots(inv).find((entry) => entry.classTsid === classTsid)?.label || 'Ticket to Paradise';
  const n = Math.max(1, Math.min(Math.floor(Number(count) || 1), countItem(inv, classTsid)));
  if (!removeItem(inv, classTsid, n)) {
    toast('That ticket is no longer in your pack.');
    return false;
  }
  const energyGate = features.metabolicGate('energy', 'gain', engine);
  const eaten = eatParadiseTicket({ count: n, energyAllowed: energyGate.ok !== false });
  pc.imagination = (pc.imagination || 0) + eaten.imagination;
  if (eaten.energy > 0) pc.energy = Math.min(energyCap(), (pc.energy || 0) + eaten.energy);
  emitGameEvent(`${classTsid}:eat`, n);
  playSound(soundForConsume(classTsid, { drink: false }), { volume: 0.6, jitter: 0.05 });
  toast(eaten.quip, 3200);
  const plural = ITEM_CATALOG[classTsid]?.namePlural || `${label}s`;
  pushActivity({
    base: `You ate ${n > 1 ? `${n} ${plural}` : `a ${label}`}. ${eaten.quip}`,
    effects: eaten.energy > 0 ? { xp: eaten.imagination, energy: eaten.energy } : { xp: eaten.imagination },
  });
  if (energyGate.ok === false && energyGate.msg) pushActivity(energyGate.msg);
  if (player) floatText(player.x, player.y - 70, `+${eaten.imagination} iMG`, 0xf0c85a);
  if (app?.canvas) app.canvas.dataset.paradiseTicketEaten = `${classTsid}:${eaten.imagination}:${eaten.energy}`;
  updateHud();
  savePlayerState();
  return true;
}

function confirmParadiseTicketActivation(courseId) {
  const course = PARADISE_COURSES[courseId];
  if (!course) return false;
  const quote = quoteParadiseTicket(paradiseState, courseId, {
    imagination: pc.imagination,
    quoinMultiplier: quoinState.multiplier,
    dead: playerIsDead(),
  });
  if (!quote.ok) {
    const info = getPackUseInfo(course.ticketId);
    toast(info.reason || 'That ticket cannot be activated.');
    renderPackPopover(course.ticketId);
    return false;
  }
  closePackPopover();
  openScriptedQuestDialogue({
    title: `Go to ${course.name}?`,
    kicker: 'Ticket to Paradise',
    cancelable: true,
    beats: [{
      text: `Activating this ticket to ${course.name} will cost you ${quote.cost.toLocaleString()} iMG (though you're sure to make it back, and more). Any quoins collected will not count toward your daily quoin limit. Do you want to?!`,
      response: 'Activate',
    }],
    onComplete: async () => {
      if (countItem(inv, course.ticketId) < 1) {
        toast('That ticket is no longer in your pack.');
        return;
      }
      const activated = activateParadiseTicket(paradiseState, courseId, {
        imagination: pc.imagination,
        quoinMultiplier: quoinState.multiplier,
        dead: playerIsDead(),
      });
      if (!activated.ok) {
        toast(getPackUseInfo(course.ticketId).reason || 'The ticket fizzled.');
        return;
      }
      if (!removeItem(inv, course.ticketId, 1)) return;
      // Spending iMG never lowers lifetime XP (or the level it earned).
      pc.imagination = Math.max(0, pc.imagination - activated.cost);
      // Report #126: paradise_ticket.js verbs.activate ends in a successful verb, which item.js notifyVerb
      // counts as VERB:<ticket>:activate (fly_paradise.js 25-44). Here, not in startParadiseFlight: the QA
      // ?paradise= entry starts a course without a ticket and counts for nothing.
      emitGameEvent(`${course.ticketId}:activate`);
      savePlayerState();
      updateHud();
      await startParadiseFlight(courseId);
    },
  });
  return true;
}

function collectParadiseEntry(entry) {
  if (!entry?.sprite?.parent || entry.collected || !paradiseRun) return false;
  const result = collectParadisePickup(paradiseRun, entry.index, Date.now(), { level: pc.level });
  if (!result.ok) return false;
  entry.collected = true;
  const applied = applyParadiseReward(result.reward);
  const { x, y } = entry.sprite;
  if (entry.sprite.parent) entry.sprite.parent.removeChild(entry.sprite);
  if (!entry.sprite.destroyed) entry.sprite.destroy({ children: true });
  if (paradiseRun.courseId === 'starlit_night') {
    const star = paradiseBackdropStars[entry.index];
    if (star) star._litStartedAt = Date.now();
    const progress = paradiseRunProgress(paradiseRun);
    if (
      progress.collected === progress.total &&
      bgLayer?.paradiseMoonPlain &&
      !bgLayer.paradiseMoonFadeStartedAt
    ) {
      bgLayer.paradiseMoonFadeStartedAt = Date.now();
    }
  }
  const color = paradiseRewardColor(result.reward);
  playSfx('quoin', { volume: 0.58, rate: 0.92 + (entry.index % 5) * 0.07 });
  floatText(x, y - 20, applied.copy, color);
  burst(x, y, color, result.reward.amount >= 500 ? 24 : 12);
  pushActivity(`${paradiseCourse().name}: ${applied.copy}.`);
  updateHud();
  renderParadiseFlightHud();
  return true;
}

function passParadiseRingEntry(entry) {
  if (!entry?.sprite?.parent || entry.passed || !paradiseRun) return false;
  const result = passParadiseRing(paradiseRun, entry.index, Date.now());
  if (!result.ok) return false;
  entry.passed = true;
  const applied = applyParadiseReward(result.reward);
  entry.sprite.alpha = 0.24;
  entry.sprite.scale.set(1.18);
  playSfx('quest', { volume: 0.5, rate: 0.86 + entry.index * 0.08 });
  floatText(entry.sprite.x, entry.sprite.y - 130, applied.copy, 0xffe278);
  burst(entry.sprite.x, entry.sprite.y, 0xffe278, 28);
  pushActivity(`Cloud Ring ${entry.index + 1}: ${applied.copy}.`);
  updateHud();
  renderParadiseFlightHud();
  return true;
}

function unlockParadiseExit() {
  if (!paradiseExit || paradiseExit.active) return;
  paradiseExit.active = true;
  paradiseExit.shut.visible = false;
  paradiseExit.arrow.visible = true;
  paradiseExit.sprite.alpha = 1;
  paradiseExit.sprite.scale.set(1.05);
  playSfx('quest', { volume: 0.62, rate: 1.08 });
  burst(paradiseExit.sprite.x, paradiseExit.sprite.y - 55, 0xd6f6ff, 25);
  const course = paradiseCourse();
  toast(course.completion, 4800);
  if (course.completionSound) playSound(course.completionSound, { volume: 0.8 });
  pushActivity(course.completion);
  paradiseCompletionAnnounced = true;
  renderParadiseFlightHud();
}

async function returnFromParadise({ expired = false, abandon = false } = {}) {
  if (!paradiseRun || paradiseTransitionBusy) return false;
  paradiseTransitionBusy = true;
  const destination = paradiseSourceLocation?.tsid
    ? { ...paradiseSourceLocation }
    : { tsid: STREET_INDEX.default };
  const finalStatus = expired ? 'expired' : abandon ? 'abandoned' : paradiseRun.status;
  closeQuestDialogue({ force: true });
  keys.clear();
  if (player) {
    player.rotation = 0;
    player.pivot.y = 0;
  }
  paradiseRun = null;
  paradiseSourceLocation = null;
  paradisePickups = [];
  paradiseRings = [];
  paradiseExit = null;
  paradiseBackdropStars = [];
  paradiseCompletionAnnounced = false;
  const hud = document.getElementById('paradise-flight-hud');
  if (hud) hud.hidden = true;
  try {
    await enterStreetWithTransition(destination.tsid, {
      spawnX: destination.x,
      spawnY: destination.y,
      quiet: true,
    });
    savePlayerLocation(destination);
    savePlayerState();
    if (app?.canvas) app.canvas.dataset.paradiseStatus = finalStatus;
    if (expired) toast('Your four minutes in Paradise are up. Another ticket can take you back.', 4500);
    else if (abandon) toast('You leave Paradise and return to Ur.', 3200);
    updateHud();
    return true;
  } finally {
    paradiseTransitionBusy = false;
  }
}

function completeParadiseAtExit() {
  if (!paradiseIsInstanced() || !paradiseExit?.active || paradiseTransitionBusy) return false;
  const result = finishParadiseRun(paradiseRun, Date.now());
  if (!result.ok) return false;
  const course = paradiseCourse();
  const applied = applyParadiseReward(result.completionReward);
  paradiseState.completions[course.id] = (paradiseState.completions[course.id] || 0) + 1;
  savePlayerState();
  updateHud();
  playSfx('quest', { volume: 0.72, rate: 1.1 });
  openScriptedQuestDialogue({
    title: course.name,
    kicker: 'Paradise complete',
    beats: [{
      text: `${course.completion} ${applied.copy}.`,
      response: 'Return to Ur',
    }],
    onComplete: () => returnFromParadise(),
  });
  renderParadiseFlightHud();
  return true;
}

function confirmLeaveParadise() {
  if (!paradiseIsInstanced()) return;
  openScriptedQuestDialogue({
    title: paradiseCourse().name,
    kicker: 'Leave Paradise?',
    cancelable: true,
    beats: [{
      text: 'This private Paradise will dissolve behind you, but another ticket can bring you back.',
      response: 'Return to Ur',
    }],
    onComplete: () => returnFromParadise({ abandon: true }),
  });
}

function handleParadiseSlideInput() {
  if (!paradiseIsInstanced() || paradiseCourse()?.movement !== 'slide' || !player) return;
  const left = keys.has('ArrowLeft') || keys.has('a') || keys.has('A');
  const right = keys.has('ArrowRight') || keys.has('d') || keys.has('D');
  const now = movementNow();
  const jumpRequested = hasQueuedJump(jumpState, now);
  const steer = player.onGround ? 0.18 : 0.08;
  if (left && !right) player.vx = Math.max(-9.5, player.vx - steer);
  else if (right && !left) player.vx = Math.min(10.5, player.vx + steer);
  if (jumpRequested) {
    clearJumpQueue(jumpState);
    if (player.onGround) {
      player.vy = -8.9 - Math.min(1.8, Math.abs(player.vx) * 0.13);
      player.onGround = false;
      playSfx('jump', { volume: 0.48, rate: 1.08 });
      burst(player.x, player.y - 2, 0xe9f7f7, 9);
    }
  }
  applyPlayerFacing();
  if (Math.abs(player.vx) > 0.4 || !player.onGround) setPlayerAnim('walk');
  else setPlayerAnim('idle');
}

function handleParadiseFlightInput() {
  if (!paradiseIsInstanced() || !player) return;
  const previewRing =
    paradiseCourse()?.id === 'cloud_rings' &&
    new URLSearchParams(location.search).get('paradisepreview') === 'ring'
      ? paradiseRings[0]
      : null;
  const previewMoon =
    paradiseCourse()?.id === 'radial_heights' &&
    new URLSearchParams(location.search).get('paradisepreview') === 'moon';
  const starlitPreview =
    paradiseCourse()?.id === 'starlit_night'
      ? new URLSearchParams(location.search).get('paradisepreview')
      : '';
  const previewStarlitMoon = starlitPreview === 'moon' || starlitPreview === 'smile';
  if (previewRing?.sprite?.parent) {
    // Keep the dedicated visual-QA route framed on the first tunnel. Normal
    // course play retains gravity and the complete flight model.
    player.x = previewRing.sprite.x - 330;
    player.y = previewRing.sprite.y - 80;
    player.vx = 0;
    player.vy = 0;
    player.rotation = 0;
    player.onGround = false;
    setPlayerAnim('idle');
    return;
  }
  if (previewMoon) {
    player.x = 1080;
    player.y = 1120;
    player.vx = 0;
    player.vy = 0;
    player.rotation = 0;
    player.onGround = false;
    setPlayerAnim('idle');
    return;
  }
  if (previewStarlitMoon) {
    player.x = 1100;
    player.y = 350;
    player.vx = 0;
    player.vy = 0;
    player.rotation = 0;
    player.onGround = false;
    setPlayerAnim('idle');
    return;
  }
  const left = keys.has('ArrowLeft') || keys.has('a') || keys.has('A');
  const right = keys.has('ArrowRight') || keys.has('d') || keys.has('D');
  const lift =
    keys.has(' ') ||
    keys.has('ArrowUp') ||
    keys.has('w') ||
    keys.has('W');
  const down = keys.has('ArrowDown') || keys.has('s') || keys.has('S');
  if (left && !right) player.vx = Math.max(-5.8, player.vx - 0.34);
  else if (right && !left) player.vx = Math.min(5.8, player.vx + 0.34);
  else player.vx *= 0.965;
  if (lift && !down) player.vy = Math.max(-5.4, player.vy - 0.46);
  else if (down && !lift) player.vy = Math.min(5.2, player.vy + 0.38);
  else player.vy = Math.min(3.1, player.vy + 0.16);
  player.vy *= 0.985;
  player.onGround = false;
  applyPlayerFacing();
  if (Math.abs(player.vx) > 0.3 || Math.abs(player.vy) > 0.3) setPlayerAnim('walk');
  else setPlayerAnim('idle');
}

function paradiseSlidePhysics(dt) {
  if (!paradiseIsInstanced() || paradiseCourse()?.movement !== 'slide' || !player) return;
  const course = paradiseCourse();
  const previewFinish =
    new URLSearchParams(location.search).get('paradisepreview') === 'finish';
  if (previewFinish) {
    player.x = 3160;
    player.y = slipTerrainY(player.x);
    player.vx = 0;
    player.vy = 0;
    player.onGround = true;
    player.rotation = Math.atan(slipTerrainSlope(player.x)) * 0.34;
    return;
  }
  const previousX = player.x;
  const slope = slipTerrainSlope(player.x);
  if (player.onGround) {
    // Gravity projected onto the authored hill provides the characteristic
    // accelerate-downhill, bleed-speed-uphill rhythm visible in the source.
    player.vx += slope * 0.34 * dt;
    player.vx *= Math.pow(0.994, dt);
    if (Math.abs(player.vx) < 0.12) player.vx = 0;
  } else {
    player.vy += 0.43 * dt;
    player.vx *= Math.pow(0.998, dt);
  }
  player.vx = clamp(player.vx, -10.5, 10.5);
  player.x = clamp(player.x + player.vx * dt, 32, course.width - 32);
  if (player.x <= 33 && player.vx < 0) player.vx *= -0.32;
  if (player.x >= course.width - 33 && player.vx > 0) player.vx *= -0.24;
  const ground = slipTerrainY(player.x);
  if (player.onGround) {
    player.y = ground;
    player.vy = 0;
  } else {
    player.y += player.vy * dt;
    if (player.y >= ground && player.vy >= -0.4) {
      player.y = ground;
      player.vy = 0;
      player.onGround = true;
      playSfx('step', { volume: 0.18, rate: 1.25 });
      burst(player.x, player.y, 0xf3fbfb, Math.abs(player.vx) > 6 ? 12 : 6);
    }
  }
  const groundAngle = Math.atan(slipTerrainSlope(player.x));
  const airAngle = clamp(player.vy * 0.018 + player.vx * 0.006, -0.18, 0.18);
  const rotationTarget = player.onGround ? clamp(groundAngle * 0.34, -0.24, 0.24) : airAngle;
  player.rotation += (rotationTarget - player.rotation) * dampingAlpha(0.18, dt);
  player.pivot.y = player.onGround ? Math.sin(time * 0.32) * Math.min(1.4, Math.abs(player.vx) * 0.12) : 0;
  if (
    player.onGround &&
    Math.abs(player.x - previousX) > 1.5 &&
    Math.floor(time) % 6 === 0
  ) {
    const spray = new PIXI.Graphics();
    spray.circle(0, 0, 1.8 + (Math.floor(time) % 3)).fill({ color: 0xf7ffff, alpha: 0.56 });
    spray.position.set(player.x - Math.sign(player.vx || 1) * 20, player.y - 5);
    spray._vx = -player.vx * 0.12;
    spray._vy = -0.2 - Math.abs(player.vx) * 0.03;
    spray._life = 0;
    spray._max = 34;
    fxLayer.addChild(spray);
  }
  if (app?.canvas) {
    app.canvas.dataset.paradiseSlope = slope.toFixed(3);
    app.canvas.dataset.paradiseGrounded = player.onGround ? '1' : '0';
    app.canvas.dataset.paradiseSpeed = Math.abs(player.vx).toFixed(2);
  }
}

function paradiseFlightPhysics(dt) {
  if (!paradiseIsInstanced() || !player) return;
  const course = paradiseCourse();
  player.x = clamp(player.x + player.vx * dt, 34, course.width - 34);
  player.y = clamp(player.y + player.vy * dt, 72, course.height - 45);
  if (player.x <= 35 && player.vx < 0) player.vx *= -0.24;
  if (player.x >= course.width - 35 && player.vx > 0) player.vx *= -0.24;
  if (player.y <= 73 && player.vy < 0) player.vy *= -0.18;
  if (player.y >= course.height - 46 && player.vy > 0) player.vy *= -0.18;
  const bankTarget = clamp(player.vy * 0.026 + player.vx * 0.012, -0.15, 0.15);
  player.rotation += (bankTarget - player.rotation) * dampingAlpha(0.14, dt);
  player.pivot.y = Math.sin(time * 0.13) * 1.4;
  if (Math.abs(player.vx) + Math.abs(player.vy) > 2.4 && Math.floor(time) % 7 === 0) {
    const mote = new PIXI.Graphics();
    mote.circle(0, 0, 1.5 + (Math.floor(time) % 3)).fill({ color: 0xf3fbff, alpha: 0.52 });
    mote.position.set(player.x - Math.sign(player.vx || 1) * 24, player.y - 35);
    mote._vx = -player.vx * 0.12;
    mote._vy = 0.18;
    mote._life = 0;
    mote._max = 38;
    fxLayer.addChild(mote);
  }
}

function updateParadiseFlight(dt) {
  if (!paradiseIsInstanced() || paradiseTransitionBusy) return;
  const now = Date.now();
  const course = paradiseCourse();
  const autoplay = new URLSearchParams(location.search).get('paradiseautoplay');
  const autoplayActive = autoplay === '1' || autoplay === course.id;
  if (course.id === 'starlit_night') {
    for (const star of paradiseBackdropStars) {
      if (!star || star.destroyed) continue;
      star.alpha = starlitRevealAlpha(star._litStartedAt, now);
    }
    const plain = bgLayer?.paradiseMoonPlain;
    if (plain && !plain.destroyed) {
      plain.alpha = starlitMoonPlainAlpha(bgLayer.paradiseMoonFadeStartedAt, now);
    }
    if (app?.canvas) {
      app.canvas.dataset.paradiseStarlitLit = String(
        paradiseBackdropStars.filter((star) => star?._litStartedAt > 0).length
      );
      app.canvas.dataset.paradiseStarlitMoonAlpha = plain
        ? plain.alpha.toFixed(3)
        : '0.000';
      app.canvas.dataset.paradiseStarlitMoonState = !bgLayer?.paradiseMoonFadeStartedAt
        ? 'plain'
        : plain?.alpha > 0
          ? 'revealing'
          : 'smile';
    }
  }
  if (paradiseRun.status === 'complete') {
    if (autoplayActive && isQuestDialogueOpen() && now >= paradiseAutoNextAt) {
      paradiseAutoNextAt = now + 170;
      advanceQuestDialogue();
    }
    renderParadiseFlightHud();
    return;
  }
  if (paradiseRemainingMs(paradiseRun, now) <= 0) {
    expireParadiseRun(paradiseRun, now);
    pushActivity(`Your four minutes in ${course.name} came to an end.`);
    returnFromParadise({ expired: true });
    return;
  }
  if (course.art) paradiseCourseRuntime.tick(paradiseCourseHost(), course, dt);
  for (const flake of bgLayer?.paradiseSnowflakes || []) {
    flake.y += flake._speed * dt;
    flake.x += flake._drift * dt;
    if (flake.y > course.height - 190) flake.y = -8;
    if (flake.x < 0) flake.x = course.width;
    else if (flake.x > course.width) flake.x = 0;
  }
  const bodyScale = features.query('avatarBodyScale', engine) ?? 1;
  for (const entry of paradisePickups) {
    if (entry.collected || !entry.sprite?.parent) continue;
    entry.sprite.phase += 0.048 * dt;
    entry.sprite.y = entry.sprite.baseY + Math.sin(entry.sprite.phase) * 8;
    const pulse = 1 + Math.sin(entry.sprite.phase * 1.4) * 0.075;
    entry.sprite.scale.set((entry.sprite.baseScale || 1) * pulse);
    // Ticket 37: the street quoin's own box (items/quoin.js onPlayerCollision 156, paradise-flight.js paradisePickupTouches).
    const pick = { x: entry.sprite.x, y: entry.sprite.y, radius: entry.point.radius };
    if (!menuTarget && paradisePickupTouches(course, pick, player, { scale: bodyScale, typeId: entry.typeId, drawnScale: entry.sprite.baseScale })) {
      collectParadiseEntry(entry);
    }
  }
  for (const entry of paradiseRings) {
    if (entry.passed || !entry.sprite?.parent) continue;
    entry.sprite._cloudPhase += 0.022 * dt;
    const breathe = 1 + Math.sin(entry.sprite._cloudPhase) * 0.018;
    entry.sprite.scale.set(breathe);
    for (const puff of entry.sprite._cloudPuffs || []) {
      const drift = Math.sin(entry.sprite._cloudPhase * 1.7 + puff._phase);
      puff.x = puff._baseX + drift * 2.4;
      puff.y = puff._baseY + Math.cos(entry.sprite._cloudPhase + puff._phase) * 1.8;
      puff.alpha = puff._baseAlpha + drift * 0.035;
      if (puff._shadow) {
        puff._shadow.x = puff.x + 3;
        puff._shadow.y = puff.y + 5;
      }
    }
    const dx = player.x - entry.sprite.x;
    const dy = player.y - 34 - entry.sprite.y;
    if ((dx * dx) / (entry.rx * entry.rx) + (dy * dy) / (entry.ry * entry.ry) <= 1) {
      passParadiseRingEntry(entry);
    }
  }
  const starlitRevealComplete =
    course.id !== 'starlit_night' ||
    starlitMoonPlainAlpha(bgLayer?.paradiseMoonFadeStartedAt, now) <= 0;
  if (paradiseObjectiveComplete(paradiseRun) && starlitRevealComplete) {
    unlockParadiseExit();
  }
  if (
    paradiseExit?.active &&
    !isQuestDialogueOpen() &&
    Math.hypot(
      paradiseExit.sprite.x - player.x,
      paradiseExit.sprite.y - player.y
    ) < 74
  ) {
    completeParadiseAtExit();
    return;
  }
  // Report 131: touching it while it is shut says why, and how many are left.
  if (
    paradiseExit && !paradiseExit.active && now >= paradiseExit.lineAt &&
    Math.hypot(paradiseExit.sprite.x - player.x, paradiseExit.sprite.y - player.y) < 74
  ) {
    const line = paradiseExitClosedLine(paradiseRun);
    if (line) {
      paradiseExit.lineAt = now + 5000;
      toast(line, 3600);
    }
  }

  if (autoplayActive && now >= paradiseAutoNextAt) {
    paradiseAutoNextAt = now + 170;
    if (isQuestDialogueOpen()) {
      advanceQuestDialogue();
      return;
    }
    const ring = paradiseRings.find((entry) => !entry.passed && entry.sprite?.parent);
    const pickup = paradisePickups.find((entry) => !entry.collected && entry.sprite?.parent);
    const target = ring?.sprite || pickup?.sprite || (paradiseExit?.active ? paradiseExit.sprite : null);
    if (target) {
      player.x = target.x;
      player.y = ring ? target.y + 34 : pickup ? target.y + 30 : target.y;
      player.vx = 0;
      player.vy = 0;
      if (course.movement === 'slide' && pickup) player.onGround = false;
    }
  }
  renderParadiseFlightHud();
}

function updateIlmenskieAutoplay() {
  if (new URLSearchParams(location.search).get('jonesautoplay') !== '1') return;
  if (!questState.active?.[ILMENSKIE_QUEST_ID] || ilmenskieAutoBusy) return;
  const now = Date.now();
  if (now < ilmenskieAutoNextAt) return;
  ilmenskieAutoNextAt = now + 420;
  const rescue = ilmenskieStory();
  if (isQuestDialogueOpen()) {
    advanceQuestDialogue();
    return;
  }
  if (currentStreetTsid !== AXIS_DENYDE_STREET_ID && !rescue.pickedUpJones) {
    ilmenskieAutoBusy = true;
    teleportToAxisDenyde().finally(() => {
      ilmenskieAutoBusy = false;
      ilmenskieAutoNextAt = Date.now() + 500;
    });
    return;
  }
  if (currentStreetTsid === AXIS_DENYDE_STREET_ID && !rescue.metJones && ilmenskieTarget) {
    handleIlmenskieTarget(ilmenskieTarget, 'talk_to');
    return;
  }
  if (currentStreetTsid === AXIS_DENYDE_STREET_ID && rescue.metJones && !rescue.pickedUpJones && ilmenskieTarget) {
    handleIlmenskieTarget(ilmenskieTarget, 'pickup');
    return;
  }
  if (currentStreetTsid === AXIS_DENYDE_STREET_ID && rescue.pickedUpJones) {
    ilmenskieAutoBusy = true;
    teleportFromAxisDenyde().finally(() => {
      ilmenskieAutoBusy = false;
      ilmenskieAutoNextAt = Date.now() + 500;
    });
    return;
  }
  if (rescue.pickedUpJones && !rescue.releasedJones) releasePackedIlmenskieJones();
}

const ILMENSKIE_CAVE_DIALOGUE = [
  {
    text: 'Thank the Giants you’re here, and not a second too soon!',
    response: 'What’s wrong?',
  },
  {
    text: 'I seem to have become trapped somehow. Probably something about an idol and an ancient curse. I’m pretty sure mummies were involved in some capacity. We can work out the details later. Anyway, the cave entrance has collapsed, and I can’t reach the exit. You’ve got to help me escape!',
    response: 'How do I do that?',
  },
  {
    text: 'Just pick me up, and we can get the hell out of here!',
    response: 'OK',
  },
];

const ILMENSKIE_RELEASE_DIALOGUE = [
  {
    text: 'That was a close one. Thanks for your help; this will rank among one of my greatest adventures.',
    response: 'Getting stuck in a cave?',
  },
  {
    text: 'We can spice it up a little. I’ll throw in something about the cult of an ancient god and a pit full of serpents. Trust me, this stuff is box office dynamite.',
    response: 'If you say so.',
  },
];

function ilmenskieStory() {
  return ensureIlmenskieState(questState);
}

function spawnIlmenskieJones({ released = false } = {}) {
  if (!entityLayer || !questState.active?.[ILMENSKIE_QUEST_ID]) return null;
  const rescue = ilmenskieStory();
  if (!released) {
    if (currentStreetTsid !== AXIS_DENYDE_STREET_ID || rescue.pickedUpJones || rescue.releasedJones) {
      return null;
    }
  }
  const frames = textures.jonesWalk?.frames || [];
  const spr = new PIXI.AnimatedSprite(frames.length ? frames.slice(0, 8) : [PIXI.Texture.WHITE]);
  spr.label = 'ilmenskie-jones';
  spr.anchor.set(0.5, 1);
  spr.animationSpeed = 0.08;
  spr.loop = true;
  spr.scale.set(1.28);
  spr.x = released ? player.x + 82 : 2444;
  spr.y = released ? player.y : 330;
  spr.zIndex = 46;
  spr.play();
  entityLayer.addChild(spr);
  ilmenskieTarget = register({
    classId: 'npc_piggy_explorer',
    label: 'Ilmenskie Jones',
    // G318: the opening words of items/npc_piggy_explorer.js 8 (his description).
    subtitle: 'Professor of porkthropology, obtainer of rare artifacts',
    sprite: spr,
    state: { rescueState: rescue, released },
  });
  if (app?.canvas) {
    app.canvas.dataset.ilmenskiePhase = rescue.phase;
    app.canvas.dataset.ilmenskieObjective = ilmenskieObjective(rescue, currentStreetTsid);
  }
  return ilmenskieTarget;
}

function handleIlmenskieTarget(target, verbId) {
  if (!target || target !== ilmenskieTarget) return;
  const rescue = ilmenskieStory();
  if (verbId === 'nibble') {
    showSpeechBubble(target, {
      speaker: 'Ilmenskie Jones',
      text: "Don't get fresh with me, kid. This is life or death here.",
      durationMs: 5200,
    });
    // npc_piggy_explorer.js 284-286 (the source spells him "Ilmenksie" there).
    pushActivity('You tried to nibble Ilmenskie Jones.');
    return;
  }
  if (verbId === 'talk_to') {
    meetIlmenskieJones(rescue);
    target.state.rescueState = rescue;
    openScriptedQuestDialogue({
      title: 'Ilmenskie Jones',
      kicker: 'Sealed Cavern',
      beats: ILMENSKIE_CAVE_DIALOGUE,
      onComplete: () => {
        toast('Pick up Ilmenskie Jones, then use Map to escape.');
        savePlayerState();
        updateHud();
      },
    });
    return;
  }
  if (verbId !== 'pickup') return;
  const result = pickupIlmenskieJones(rescue);
  if (!result.ok) {
    toast(result.reason === 'meet_first' ? 'Talk to Ilmenskie Jones first.' : 'Jones is already packed.');
    return;
  }
  addItem(inv, HOGTIED_JONES_ID, 1);
  if (target.sprite?.parent) target.sprite.parent.removeChild(target.sprite);
  if (target.sprite && !target.sprite.destroyed) target.sprite.destroy();
  interactables = interactables.filter((entry) => entry !== target);
  ilmenskieTarget = null;
  playSfx('pickup', { volume: 0.52, rate: 0.82 });
  toast('You picked up Ilmenskie Jones. Open Map to teleport out.', 4200);
  pushActivity('You picked up Ilmenskie Jones.');
  if (app?.canvas) {
    app.canvas.dataset.ilmenskiePhase = rescue.phase;
    app.canvas.dataset.ilmenskieObjective = ilmenskieObjective(rescue, currentStreetTsid);
  }
  savePlayerState();
  updateHud();
}

async function teleportToAxisDenyde() {
  if (!questState.active?.[ILMENSKIE_QUEST_ID]) return false;
  const rescue = ilmenskieStory();
  if (currentStreetTsid !== AXIS_DENYDE_STREET_ID) {
    rememberIlmenskieSource(rescue, instanceSourceHere({
      tsid: currentStreetTsid,
      x: player?.x,
      y: player?.y,
    }));
  }
  closeMap();
  closeVerbMenu();
  pushActivity('Teleporting through the sealed entrance to Axis Denyde…');
  await enterStreetWithTransition(AXIS_DENYDE_STREET_ID, {
    spawnX: 2240,
    spawnY: 330,
    quiet: true,
  });
  savePlayerLocation(rescue.sourceLocation);
  savePlayerState();
  if (app?.canvas) {
    app.canvas.dataset.ilmenskiePhase = rescue.phase;
    app.canvas.dataset.ilmenskieObjective = ilmenskieObjective(rescue, currentStreetTsid);
  }
  toast(rescue.pickedUpJones ? 'The cavern is still sealed. Teleport back out.' : 'Axis Denyde. Find Ilmenskie Jones.', 3600);
  return true;
}

async function teleportFromAxisDenyde() {
  const rescue = ilmenskieStory();
  if (currentStreetTsid !== AXIS_DENYDE_STREET_ID || !rescue.sourceLocation?.tsid) return false;
  const destination = { ...rescue.sourceLocation };
  closeMap();
  closeVerbMenu();
  await enterStreetWithTransition(destination.tsid, {
    spawnX: destination.x,
    spawnY: destination.y,
    quiet: true,
  });
  savePlayerLocation(destination);
  savePlayerState();
  if (app?.canvas) {
    app.canvas.dataset.ilmenskiePhase = rescue.phase;
    app.canvas.dataset.ilmenskieObjective = ilmenskieObjective(rescue, currentStreetTsid);
  }
  toast('You escaped the Sealed Cavern. Release Jones from your pack.', 4200);
  pushActivity('You teleported out of Axis Denyde with Ilmenskie Jones.');
  updateHud();
  return true;
}

function releasePackedIlmenskieJones() {
  const rescue = ilmenskieStory();
  const gate = canReleaseIlmenskieJones(rescue, currentStreetTsid);
  if (!gate.ok) {
    toast(gate.message);
    return false;
  }
  if (!removeItem(inv, HOGTIED_JONES_ID, 1)) {
    toast('Ilmenskie Jones is not in your pack.');
    return false;
  }
  releaseIlmenskieJones(rescue, currentStreetTsid);
  const target = spawnIlmenskieJones({ released: true });
  playSfx('pickup', { volume: 0.46, rate: 1.25 });
  burst(target?.sprite?.x || player.x, (target?.sprite?.y || player.y) - 55, 0xe8e1ce, 18);
  pushActivity('You released Ilmenskie Jones.');
  openScriptedQuestDialogue({
    title: 'Ilmenskie Jones',
    kicker: 'Safe at last',
    beats: ILMENSKIE_RELEASE_DIALOGUE,
    onComplete: () => {
      const updates = applyQuestProgress(questState, 'rescue_pig', 1, pc);
      announceQuestCompletions(updates);
      if (target?.sprite?.parent) target.sprite.parent.removeChild(target.sprite);
      if (target?.sprite && !target.sprite.destroyed) target.sprite.destroy();
      interactables = interactables.filter((entry) => entry !== target);
      ilmenskieTarget = null;
      if (app?.canvas) {
        app.canvas.dataset.ilmenskiePhase = 'released';
        app.canvas.dataset.ilmenskieObjective = 'Ilmenskie Jones rescued';
      }
      savePlayerState();
      updateHud();
    },
  });
  savePlayerState();
  updateHud();
  return true;
}

function homeIsInstanced() {
  return homeState.inHome === true &&
    [HOME_STREET_TSID, HOME_INTERIOR_TSID].includes(currentStreetTsid);
}

function updateHomeChrome() {
  const button = document.getElementById('home-btn');
  const badge = document.getElementById('mail-unread-badge');
  const unread = unreadMailCount(mailboxState, Date.now());
  if (button) {
    button.classList.toggle('is-owned', homeState.owned);
    button.title = homeState.owned
      ? `${homeIsInstanced() ? 'At home' : 'Go home'} · ${unread} unread mail`
      : 'Get your home street';
  }
  if (badge) {
    badge.textContent = String(unread);
    badge.hidden = unread < 1;
  }
  // HOMES2: the button shows a parcel waits at a mailbox.
  const parcels = parcelsWaitingCount();
  const mailBtn = document.getElementById('mail-btn');
  if (mailBtn) {
    if (parcels > 0) mailBtn.dataset.parcel = String(parcels);
    else delete mailBtn.dataset.parcel;
  }
  renderTopBar(document, { unread, parcels });
  if (homeMailboxTarget?.sprite && !homeMailboxTarget.sprite.destroyed) {
    homeMailboxTarget.state.unread = unread;
    homeMailboxTarget.subtitle = unread
      ? `${unread} unread message${unread === 1 ? '' : 's'}`
      : 'Your very own mail';
    homeMailboxTarget.sprite.texture = textureFromUrl(unread > 0
      ? 'assets/sprites/mailbox/npc_mailbox_variant_mailboxRight_x1_has_mail_idle_png_1354832230.webp'
      : 'assets/sprites/mailbox/npc_mailbox_variant_mailboxRight_x1_idle_png_1354832227.webp');
  }
  if (app?.canvas) {
    app.canvas.dataset.homeOwned = homeState.owned ? '1' : '0';
    app.canvas.dataset.homeStyle = homeState.style || '';
    app.canvas.dataset.homeRoom = homeIsInstanced() ? homeState.room : '';
    app.canvas.dataset.mailUnread = String(unread);
    app.canvas.dataset.mailTotal = String(mailboxState.messages.length);
  }
}

function closeHomePanel() {
  const panel = document.getElementById('home-panel');
  if (panel) panel.hidden = true;
}

function isHomePanelOpen() {
  const panel = document.getElementById('home-panel');
  return Boolean(panel && !panel.hidden);
}

function renderHomePanel() {
  const body = document.getElementById('home-body');
  const title = document.getElementById('home-panel-title');
  if (!body) return;
  if (!homeState.owned) {
    // G208: no home yet: the panel is the Home Street Selection Machine (js/home-ticket.js).
    if (title) title.textContent = HOME_MACHINE.label;
    renderTicketMachine(body, homeTicketHost());
    const machineMeta = document.getElementById('home-meta');
    if (machineMeta) machineMeta.textContent = '';
    return;
  }

  const style = HOME_STYLES[homeState.style] || HOME_STYLES.meadow;
  if (title) title.textContent = `${style.label} home`;
  // MPANELS: the footer line (the owned card's own words).
  const homeMeta = document.getElementById('home-meta');
  // Ticket 67: what it offers follows where you are (in Paradise from your house, Teleport home).
  const atHome = homeIsInstanced();
  if (homeMeta) homeMeta.textContent = atHome ? 'You are home' : 'One thought away';
  const locationCopy = atHome
    ? homeState.room === 'interior'
      ? 'You are inside your house.'
      : 'You are on your home street.'
    : 'Your home is one thought away.';
  const unread = unreadMailCount(mailboxState, Date.now());
  body.innerHTML = `
    <div class="home-owned-hero" style="--home-accent:${style.accent}">
      <div class="home-owned-mark" aria-hidden="true">⌂</div>
      <div>
        <h3>Your ${escapeHtml(style.label)} home</h3>
        <p>${escapeHtml(locationCopy)}</p>
      </div>
    </div>
    <div class="home-owned-actions">
      ${atHome
        ? `<button type="button" class="btn-glitch-primary" data-home-action="mail">${unread ? `Open mailbox (${unread})` : 'Open mailbox'}</button>
           <button type="button" data-home-action="${homeState.room === 'interior' ? 'outside' : 'inside'}">${homeState.room === 'interior' ? 'Go outside' : 'Enter house'}</button>
           <button type="button" data-home-action="return">Return to Ur</button>`
        : '<button type="button" class="btn-glitch-primary" data-home-action="teleport">Teleport home</button>'}
      <span class="home-owned-meta">${homeState.visits} visit${homeState.visits === 1 ? '' : 's'} · ${unread} unread</span>
    </div>
  `;
  body.querySelectorAll('[data-home-action]').forEach((button) => {
    button.addEventListener('click', async () => {
      const action = button.dataset.homeAction;
      closeHomePanel();
      if (action === 'teleport') await teleportHome();
      else if (action === 'return') await returnFromHome();
      else if (action === 'inside') await switchHomeRoom('interior');
      else if (action === 'outside') await switchHomeRoom('street');
      else if (action === 'mail') openMailboxPanel();
    });
  });
}

/** G208: what the free Home Street Ticket (js/home-ticket.js) needs from the game. */
function homeTicketHost() {
  return {
    inv,
    home: homeState,
    gate: () => features.travelGate(HOME_STREET_TSID, engine, { via: 'home' }),
    dialogue: (opts) => openScriptedQuestDialogue(opts),
    toast: (msg) => toast(msg),
    activity: (msg) => pushActivity(msg),
    changed(made) {
      if (made) seedMailbox(mailboxState, Date.now());
      updateHud();
      updateHomeChrome();
      savePlayerState();
    },
    reopen: () => openHomePanel(),
    async goHome() {
      const result = await teleportHome();
      if (!result?.ok && isHomePanelOpen()) renderHomePanel();
    },
  };
}

function openHomePanel() {
  closeMailboxPanel();
  closeMap();
  closeVendor();
  closeQuestPanel();
  closePackPopover();
  if (!homeState.owned && offerHomeTicket(homeTicketHost())) {
    closeHomePanel();
    return;
  }
  renderHomePanel();
  const panel = document.getElementById('home-panel');
  if (panel) panel.hidden = false;
}

function closeMailboxPanel() {
  const panel = document.getElementById('mail-panel');
  if (panel) panel.hidden = true;
  mailboxComposeReplyTo = null;
  mailboxAt = false;
}

function isMailboxOpen() {
  const panel = document.getElementById('mail-panel');
  return Boolean(panel && !panel.hidden);
}

function mailWhen(timestamp) {
  if (!timestamp) return 'now';
  const seconds = Math.max(0, Math.floor((Date.now() - timestamp) / 1000));
  if (seconds < 60) return 'now';
  if (seconds < 3600) return `${Math.floor(seconds / 60)}m`;
  if (seconds < 86_400) return `${Math.floor(seconds / 3600)}h`;
  return `${Math.floor(seconds / 86_400)}d`;
}

function mailboxRows() {
  if (mailboxFolder === 'archived') {
    return listMailboxMessages(mailboxState, { now: Date.now(), archived: true });
  }
  if (mailboxFolder === 'sent') {
    return listMailboxMessages(mailboxState, { now: Date.now(), outgoing: true });
  }
  return listMailboxMessages(mailboxState, { now: Date.now() });
}

function mailAttachmentLabel(message) {
  const parts = [];
  if (message.attachment) {
    parts.push(`${message.attachment.count}× ${ITEM_CATALOG[message.attachment.classTsid]?.label || message.attachment.classTsid}`);
  }
  if (message.currants) parts.push(`◎ ${message.currants} currants`);
  return parts.join(' · ');
}

function renderMailboxCompose(recipient = '', replyTo = null) {
  const reader = document.getElementById('mail-reader');
  if (!reader) return;
  // Ticket 86: a new letter is not any message in the list, so none shows as the one open (a reply
  // keeps its message marked); a click on a message, or on a folder, reads it.
  if (!replyTo) document.querySelectorAll('#mail-list .mail-row.is-selected').forEach((row) => row.classList.remove('is-selected'));
  // G478: in multiplayer the letter goes to a real player through the site (player-mail-feature).
  const online = engine.mode === 'multiplayer' ? features.query('mailCompose', engine) : null;
  if (online) {
    renderPlayerMailCompose(reader, online, recipient, replyTo);
    return;
  }
  // A truthy sentinel distinguishes a new unsent draft from the ordinary
  // reader state so the once-per-second delivery refresh does not erase it.
  mailboxComposeReplyTo = replyTo || '__new_mail__';
  const reply = mailboxState.messages.find((message) => message.id === replyTo);
  const selectedRecipient = recipient || reply?.sender || MAIL_COMPANIONS[0];
  const attachable = listPackItemSlots(inv)
    .filter((slot) => slot.count > 0)
    .slice(0, 80);
  reader.innerHTML = `
    <form id="mail-compose-form" class="mail-compose-form">
      <label>To
        <select name="recipient">
          ${MAIL_COMPANIONS.map((name) => `<option value="${escapeHtml(name)}" ${name === selectedRecipient ? 'selected' : ''}>${escapeHtml(name)}</option>`).join('')}
        </select>
      </label>
      <label>Message
        <textarea name="text" maxlength="500" required placeholder="Write something envelope-sized…"></textarea>
      </label>
      <div class="mail-compose-grid">
        <label>Attach one stack
          <select name="attachment">
            <option value="">Nothing</option>
            ${attachable.map((slot) => `<option value="${escapeHtml(slot.classTsid)}" data-count="${slot.count}" data-icon="${escapeHtml(slot.icon || '')}">${escapeHtml(slot.label)}</option>`).join('')}
          </select>
        </label>
        <label>Qty
          <input name="quantity" type="number" min="1" value="1" />
        </label>
        <label>Enclose currants
          <input name="currants" type="number" min="0" max="${Math.max(0, Math.floor(pc.currants))}" value="0" />
        </label>
      </div>
      <div class="mail-compose-cost">
        <span>Base postage starts at 2 currants</span>
        <strong data-mail-cost>◎ 2</strong>
      </div>
      <div class="mail-message-actions">
        <button type="submit" class="btn-glitch-primary">Send mail</button>
        <button type="button" data-mail-cancel>Cancel</button>
      </div>
    </form>
  `;
  const form = reader.querySelector('#mail-compose-form');
  themeMailPickers(form);
  const updateCost = () => {
    const data = new FormData(form);
    const classTsid = String(data.get('attachment') || '');
    const count = Math.max(0, Math.floor(Number(data.get('quantity')) || 0));
    const currants = Math.max(0, Math.floor(Number(data.get('currants')) || 0));
    const cost = mailCost({
      itemBaseCost: ITEM_CATALOG[classTsid]?.baseCost || 10,
      itemCount: classTsid ? count : 0,
      currants,
    });
    const costEl = form.querySelector('[data-mail-cost]');
    if (costEl) costEl.textContent = `◎ ${cost}`;
  };
  form.addEventListener('input', updateCost);
  form.querySelector('[data-mail-cancel]')?.addEventListener('click', () => {
    mailboxComposeReplyTo = null;
    renderMailboxPanel();
  });
  form.addEventListener('submit', (event) => {
    event.preventDefault();
    const data = new FormData(form);
    const classTsid = String(data.get('attachment') || '');
    const count = classTsid ? Math.max(1, Math.floor(Number(data.get('quantity')) || 1)) : 0;
    const result = sendMail(mailboxState, pc, inv, {
      recipient: String(data.get('recipient') || ''),
      text: String(data.get('text') || ''),
      attachment: classTsid ? { classTsid, count } : null,
      attachmentBaseCost: ITEM_CATALOG[classTsid]?.baseCost || 10,
      currants: Math.max(0, Math.floor(Number(data.get('currants')) || 0)),
      replyTo: mailboxComposeReplyTo === '__new_mail__' ? null : mailboxComposeReplyTo,
      now: Date.now(),
    });
    if (!result.ok) {
      const messages = {
        empty: 'Write a message first.',
        missing_item: 'That item stack is no longer in your pack.',
        no_money: `You need ${result.shortfall} more currants.`,
        recipient: 'Choose someone to receive this.',
      };
      toast(messages[result.reason] || 'That letter could not be sent.');
      return;
    }
    mailboxFolder = 'sent';
    mailboxSelectedId = result.id;
    mailboxComposeReplyTo = null;
    pushActivity(`Mail sent · ${result.postage} currants postage.`);
    emitGameEvent('mail_sent');
    toast('Your letter is on its way.', 2400);
    playSound('PACKAGE_SENT', { volume: 0.55 });
    updateHud();
    updateHomeChrome();
    savePlayerState();
    renderMailboxPanel();
  });
  updateCost();
  form.querySelector('textarea')?.focus({ preventScroll: true });
}

/**
 * DECOPOLISH (Austin 2026-11-02: no OS menus): the letter's pickers (who to, which stack to attach)
 * as the game's own type-to-filter list (js/combobox.js), the stacks with their icons and counts.
 * The selects stay as the form's values.
 */
function themeMailPickers(form) {
  for (const [name, label, placeholder] of [['recipient', 'Send to', 'Choose who…'], ['attachment', 'Attach one stack', 'Nothing']]) {
    const select = form?.querySelector(`select[name="${name}"]`);
    if (!select) continue;
    const combo = createCombobox(select, { label, placeholder, className: 'combo-form', minListWidth: 220 });
    combo.input.dataset.mailPick = name;
  }
}

/**
 * G478: Write mail in multiplayer: To a real player (your buddies offered,
 * MailComposeUI.as:384-411), at most 300 characters, one stack of up to 999,
 * currants, the postage the site will take (mail_get_message_cost).
 */
function renderPlayerMailCompose(reader, online, recipient = '', replyTo = null) {
  mailboxComposeReplyTo = replyTo || '__new_mail__';
  const reply = mailboxState.messages.find((message) => message.id === replyTo);
  const rules = online.rules || {};
  const attachable = listPackItemSlots(inv).filter((slot) => slot.count > 0).slice(0, 80);
  const buddies = (online.buddies || []).map((b) => b.name).filter(Boolean);
  reader.innerHTML = `
    <form id="mail-compose-form" class="mail-compose-form" data-player-mail-compose>
      <label>To
        <input name="recipient" type="text" autocomplete="off" maxlength="64" required placeholder="${escapeHtml(online.placeholder || '')}" value="${escapeHtml(recipient || reply?.sender || '')}" />
      </label>
      ${reply?.text ? `<blockquote class="mail-quote">${escapeHtml(reply.text)}</blockquote>` : ''}
      <label>Message
        <textarea name="text" maxlength="${Number(rules.textMax) || 300}" placeholder="Write something envelope-sized…"></textarea>
      </label>
      <div class="mail-compose-grid">
        <label>Attach one stack
          <select name="attachment">
            <option value="">Nothing</option>
            ${attachable.map((slot) => `<option value="${escapeHtml(slot.classTsid)}" data-count="${slot.count}" data-icon="${escapeHtml(slot.icon || '')}">${escapeHtml(slot.label)}</option>`).join('')}
          </select>
        </label>
        <label>Qty
          <input name="quantity" type="number" min="1" max="${Number(rules.countMax) || 999}" value="1" />
        </label>
        <label>Enclose currants
          <input name="currants" type="number" min="0" max="${Math.max(0, Math.min(Number(rules.currantsMax) || 999999, Math.floor(pc.currants)))}" value="0" />
        </label>
      </div>
      <div class="mail-compose-cost">
        <span>Postage, with any currants you enclose</span>
        <strong data-mail-cost>◎ 2</strong>
      </div>
      <p class="mail-compose-status" data-mail-status aria-live="polite"></p>
      <div class="mail-message-actions">
        <button type="submit" class="btn-glitch-primary">Send mail</button>
        <button type="button" data-mail-cancel>Cancel</button>
      </div>
    </form>
  `;
  const form = reader.querySelector('#mail-compose-form');
  themeMailPickers(form);
  // SEATSELECT: To is any player's name, your buddies offered as you type (MailComposeUI.as
  // 384-411), in the game's own list rather than the browser's suggestion menu.
  createSuggestBox(form.querySelector('input[name="recipient"]'), { suggestions: buddies, label: 'Send to', className: 'combo-form', minListWidth: 220 });
  const read = () => {
    const data = new FormData(form);
    const c = String(data.get('attachment') || '');
    return {
      to: String(data.get('recipient') || '').trim(),
      text: String(data.get('text') || ''),
      item: c ? { c, n: Math.max(1, Math.floor(Number(data.get('quantity')) || 1)) } : null,
      currants: Math.max(0, Math.floor(Number(data.get('currants')) || 0)),
    };
  };
  const updateCost = () => {
    const f = read();
    const costEl = form.querySelector('[data-mail-cost]');
    if (costEl) costEl.textContent = `◎ ${online.cost({ c: f.item?.c, n: f.item?.n || 0, currants: f.currants })}`;
  };
  const status = (text) => {
    const el = form.querySelector('[data-mail-status]');
    if (el) el.textContent = text || '';
  };
  form.addEventListener('input', updateCost);
  form.querySelector('[data-mail-cancel]')?.addEventListener('click', () => {
    mailboxComposeReplyTo = null;
    renderMailboxPanel();
  });
  let sending = false;
  form.addEventListener('submit', (event) => {
    event.preventDefault();
    if (sending) return;
    sending = true;
    const button = form.querySelector('button[type="submit"]');
    if (button) button.disabled = true;
    status('Sending…');
    const f = read();
    Promise.resolve(features.query('mailSend', { ...f, reply: reply?.playerMail || null }, engine)).then((result) => {
      sending = false;
      if (button) button.disabled = false;
      if (!result?.ok) {
        status(result?.text || 'That letter could not be sent.');
        toast(result?.text || 'That letter could not be sent.');
        return;
      }
      mailboxFolder = 'sent';
      mailboxSelectedId = result.row;
      mailboxComposeReplyTo = null;
      pushActivity(`Mail sent to ${result.to} · ${result.postage} currants postage.`);
      emitGameEvent('mail_sent');
      toast(result.parcel ? 'Your parcel is on its way. It arrives in about 7 minutes.' : 'Your letter is on its way.', 2600);
      playSound('PACKAGE_SENT', { volume: 0.55 });
      updateHud();
      updateHomeChrome();
      savePlayerState();
      renderMailboxPanel();
    });
  });
  updateCost();
  form.querySelector(recipient || reply ? 'textarea' : 'input[name="recipient"]')?.focus({ preventScroll: true });
}

function renderMailboxReader(message) {
  const reader = document.getElementById('mail-reader');
  if (!reader) return;
  if (!message) {
    reader.innerHTML = '<div class="mail-empty"><div><strong>No message selected</strong><br/>Choose an envelope, or write a new one.</div></div>';
    return;
  }
  if (!message.outgoing) {
    const wasUnread = !message.read;
    readMail(mailboxState, message.id, Date.now());
    if (wasUnread) savePlayerState();
  }
  const attachment = mailAttachmentLabel(message);
  const canReceive = !message.outgoing && attachment && !message.attachmentsClaimed;
  // HOMES2: what the site holds in a letter waits for a mailbox; the button reads and writes anywhere.
  const notHere = canReceive && message.ledger && !mailboxAt;
  reader.innerHTML = `
    <p class="mail-message-from">${message.outgoing ? 'To' : 'From'} ${escapeHtml(message.outgoing ? message.recipient : message.sender)}</p>
    <h3 class="mail-message-title">${escapeHtml(mailTitle(message))}</h3>
    <time class="mail-message-time">${new Date(message.deliveryAt).toLocaleString()}</time>
    ${message.quote ? `<blockquote class="mail-quote" data-mail-quote>${message.quote.from ? `<cite>${escapeHtml(message.quote.from)} wrote</cite>` : ''}${escapeHtml(message.quote.text)}</blockquote>` : ''}
    <div class="mail-message-body">${escapeHtml(message.text)}</div>
    ${attachment ? `
      <div class="mail-attachment">
        ${message.attachment ? `<img src="${escapeHtml(ITEM_CATALOG[message.attachment.classTsid]?.icon || `assets/sprites/icons/${message.attachment.classTsid}.webp`)}" alt="" />` : '<span class="currant-coin">◎</span>'}
        <div class="mail-attachment-copy">
          <strong>${escapeHtml(attachment)}</strong>
          <span>${message.attachmentsClaimed ? 'Collected' : notHere ? 'Waiting for you at any mailbox' : 'Waiting in this envelope'}</span>
        </div>
        ${canReceive && !notHere ? '<button type="button" class="btn-glitch-primary" data-mail-receive>Receive</button>' : ''}
        ${notHere ? '<button type="button" class="btn-glitch-primary" data-mail-receive-away disabled title="You can only collect this at a mailbox.">Receive</button>' : ''}
      </div>
      ${notHere ? '<p class="mail-collect-note" data-mail-collect-note>Open a mailbox to collect it: yours on your home street, or any mailbox on a street.</p>' : ''}` : ''}
    <div class="mail-message-actions">
      ${!message.outgoing && !message.ledger ? `${message.playerMail && !message.fromId ? '' : '<button type="button" class="btn-glitch-primary" data-mail-reply>Reply</button>'}
        <button type="button" data-mail-archive>${message.archived ? 'Move to inbox' : 'Archive'}</button>
        <button type="button" data-mail-delete>Delete</button>` : ''}
      ${!message.outgoing && message.ledger && message.playerMail ? `${message.fromId ? '<button type="button" class="btn-glitch-primary" data-mail-reply>Reply</button>' : ''}
        <button type="button" data-mail-archive>${message.archived ? 'Move to inbox' : 'Archive'}</button>` : ''}
      ${message.ledger && message.attachmentsClaimed ? '<button type="button" data-mail-delete>Delete</button>' : ''}
      ${message.ledger && message.playerMail && !message.attachmentsClaimed ? '<button type="button" data-mail-delete disabled title="You still have attachments!">Delete</button>' : ''}
    </div>
  `;
  reader.querySelector('[data-mail-receive]')?.addEventListener('click', () => {
    // G333: an attachment the site's ledger holds (an auction delivery) is received through the site.
    const settled = message.ledger ? features.query('mailReceive', message, engine) : null;
    if (settled) {
      Promise.resolve(settled).finally(() => { updateHud(); updateHomeChrome(); savePlayerState(); renderMailboxPanel(); });
      return;
    }
    const result = receiveMailAttachments(mailboxState, inv, pc, message.id, Date.now());
    if (!result.ok) {
      toast('There is nothing left to receive.');
      return;
    }
    const itemCopy = result.item
      ? `${result.item.count}× ${ITEM_CATALOG[result.item.classTsid]?.label || result.item.classTsid}`
      : '';
    const currantCopy = result.currants ? `◎ ${result.currants}` : '';
    toast(`Received ${[itemCopy, currantCopy].filter(Boolean).join(' and ')}.`);
    pushActivity(`Mailbox delivery collected: ${[itemCopy, currantCopy].filter(Boolean).join(' · ')}`);
    updateHud();
    savePlayerState();
    renderMailboxPanel();
  });
  reader.querySelector('[data-mail-reply]')?.addEventListener('click', () => {
    renderMailboxCompose(message.sender, message.id);
  });
  reader.querySelector('[data-mail-archive]')?.addEventListener('click', () => {
    archiveMail(mailboxState, message.id, !message.archived);
    mailboxSelectedId = null;
    savePlayerState();
    updateHomeChrome();
    renderMailboxPanel();
  });
  reader.querySelector('[data-mail-delete]')?.addEventListener('click', () => {
    deleteMail(mailboxState, message.id);
    mailboxSelectedId = null;
    savePlayerState();
    updateHomeChrome();
    renderMailboxPanel();
  });
  updateHomeChrome();
}

function renderMailboxPanel() {
  const list = document.getElementById('mail-list');
  if (!list) return;
  document.querySelectorAll('[data-mail-folder]').forEach((button) => {
    const on = button.dataset.mailFolder === mailboxFolder;
    button.classList.toggle('active', on);
    // MPANELS: the folders are tabs (role=tab, the roving tabindex).
    button.setAttribute('aria-selected', on ? 'true' : 'false');
    button.tabIndex = on ? 0 : -1;
  });
  const rows = mailboxRows();
  // MPANELS: the footer line: the folder's count and the unread.
  const mailMeta = document.getElementById('mail-meta');
  if (mailMeta) {
    const unread = unreadMailCount(mailboxState, Date.now());
    mailMeta.textContent = `${rows.length} ${rows.length === 1 ? 'message' : 'messages'} here · ${unread} unread`;
  }
  if (!rows.some((message) => message.id === mailboxSelectedId)) {
    mailboxSelectedId = rows[0]?.id || null;
  }
  list.innerHTML = rows.length ? '' : '<div class="mail-empty"><div>This folder is pleasingly empty.</div></div>';
  for (const message of rows) {
    const button = document.createElement('button');
    button.type = 'button';
    const open = message.id === mailboxSelectedId && mailboxComposeReplyTo !== '__new_mail__';
    button.className = `mail-row${open ? ' is-selected' : ''}${!message.read && !message.outgoing ? ' is-unread' : ''}`;
    button.dataset.mailId = message.id;
    const party = message.outgoing ? message.recipient : message.sender;
    button.innerHTML = `
      <span class="mail-row-dot"></span>
      <span class="mail-row-copy"><strong>${escapeHtml(party)}</strong><span>${escapeHtml(message.text)}</span></span>
      <time>${mailWhen(message.deliveryAt)}</time>
    `;
    button.addEventListener('click', () => {
      mailboxSelectedId = message.id;
      // A message clicked while a letter is being written is read (the letter was over it, ticket 86).
      mailboxComposeReplyTo = null;
      renderMailboxPanel();
    });
    list.appendChild(button);
  }
  if (!mailboxComposeReplyTo) {
    const selected = rows.find((message) => message.id === mailboxSelectedId) || null;
    renderMailboxReader(selected);
  }
  updateHomeChrome();
}

/**
 * `compose` (the Mail Dispatcher): open on a new letter, as the client's MailManager.start opened the
 * mail window on MailDialog.COMPOSE (a mailbox opened it on the inbox, parseMessages). The inbox is
 * not read underneath it (ticket 86: its first message was marked read and drawn, then covered by
 * the letter, so the Inbox tab looked open on a message it was not showing).
 */
function openMailboxPanel({ anywhere = false, atMailbox = false, compose = false } = {}) {
  if (!homeState.owned && !anywhere) {
    openHomePanel();
    toast('A mailbox comes with your home street.');
    return;
  }
  if (homeState.owned) seedMailbox(mailboxState, Date.now());
  closeHomePanel();
  closeMap();
  closePackPopover();
  mailboxFolder = 'inbox';
  mailboxComposeReplyTo = compose ? '__new_mail__' : null;
  mailboxAt = atMailbox === true;
  renderMailboxPanel();
  const panel = document.getElementById('mail-panel');
  if (panel) panel.hidden = false;
  if (compose) renderMailboxCompose();
  if (homeMailboxTarget?.sprite) {
    homeMailboxTarget.sprite.scale.set(1.05, 0.94);
    setTimeout(() => {
      if (homeMailboxTarget?.sprite && !homeMailboxTarget.sprite.destroyed) {
        homeMailboxTarget.sprite.scale.set(1, 1);
      }
    }, 180);
  }
}

function drawHomeBackground(styleId, room) {
  const style = HOME_STYLES[styleId] || HOME_STYLES.meadow;
  const colors = {
    meadow: { sky: 0xa8d8eb, ground: 0x72b65e, dark: 0x3e7e48, wall: 0xf2d7a0 },
    firebog: { sky: 0x725a76, ground: 0x9f5d4d, dark: 0x5e3b4e, wall: 0xd99b72 },
    uralia: { sky: 0x786b9b, ground: 0x6d7267, dark: 0x454453, wall: 0xc2afc9 },
  }[style.id];
  const container = new PIXI.Container();
  container.worldH = cameraWorldHeightForGround(
    AUTHORED_VIEW_H,
    620,
    LOCATION_VIEW_H
  );
  const art = new PIXI.Graphics();
  if (room === 'interior') {
    art.rect(0, 0, 1500, 620).fill(colors.wall);
    for (let x = 0; x < 1500; x += 160) art.rect(x, 0, 5, 620);
    art.fill({ color: 0xf8eac8, alpha: 0.28 });
    art.rect(0, 620, 1500, 140).fill(colors.dark);
    art.ellipse(750, 180, 520, 140).fill({ color: 0xffffff, alpha: 0.28 });
  } else {
    art.rect(0, 0, 1500, 620).fill(colors.sky);
    art.ellipse(180, 120, 190, 58).fill({ color: 0xffffff, alpha: 0.55 });
    art.ellipse(1180, 165, 250, 72).fill({ color: 0xffffff, alpha: 0.38 });
    art.rect(0, 520, 1500, 240).fill(colors.ground);
    art.ellipse(760, 600, 1200, 100).fill({ color: colors.dark, alpha: 0.7 });
  }
  container.addChild(art);
  if (room !== 'interior') {
    const houseAsset = {
      meadow: { path: 'assets/decos/groddle/house_orange_front_01.png', width: 852 },
      firebog: { path: 'assets/decos/groddle/k03_gingerbreadhouse_01.png', width: 1180 },
      uralia: { path: 'assets/decos/groddle/cl2_housePurple_back_01.png', width: 320 },
    }[style.id];
    const house = new PIXI.Sprite(textureFromUrl(houseAsset.path));
    house.anchor.set(0.5, 1);
    house.x = 1020;
    house.y = 620;
    house.scale.set(Math.min((style.id === 'uralia' ? 540 : 650) / houseAsset.width, 1));
    house.alpha = 0.98;
    container.addChild(house);
  }
  container.platformsScreen = [{ id: 'home-ground', x1: 0, y1: 620, x2: 1500, y2: 620, pc_perm: 1 }];
  return container;
}

function makeHomeDoorSprite(room) {
  const asset = {
    meadow: { path: 'assets/decos/groddle/door_asset_house_large_01.png', height: 668 },
    firebog: { path: 'assets/decos/groddle/door_asset_house_large_05.png', height: 668 },
    uralia: { path: 'assets/decos/groddle/door_asset_house_medium_03.png', height: 586 },
  }[homeState.style] || { path: 'assets/decos/groddle/door_asset_house_large_01.png', height: 668 };
  const sprite = new PIXI.Sprite(textureFromUrl(asset.path));
  sprite.anchor.set(0.5, 1);
  sprite.x = room === 'interior' ? 1220 : 1000;
  sprite.y = GROUND_Y;
  sprite.scale.set((room === 'interior' ? 240 : 190) / asset.height);
  sprite.zIndex = 25;
  entityLayer.addChild(sprite);
  return sprite;
}

function makeHomeReturnSprite() {
  const marker = new PIXI.Container();
  marker.x = 115;
  marker.y = GROUND_Y;
  marker.zIndex = 20;
  const pole = new PIXI.Graphics();
  pole.roundRect(-7, -142, 14, 142, 6).fill(0x70455b);
  pole.roundRect(-64, -145, 128, 46, 14).fill(0xf2d76d);
  marker.addChild(pole);
  const label = new PIXI.Text({ text: 'Return to Ur', style: {
    fontFamily: 'Trebuchet MS, sans-serif',
    fontSize: 15,
    fontWeight: '700',
    fill: 0x563f59,
  } });
  label.anchor.set(0.5);
  label.y = -122;
  marker.addChild(label);
  entityLayer.addChild(marker);
  return marker;
}

function spawnHomeSceneTargets(room) {
  homeMailboxTarget = null;
  homeDoorTarget = null;
  homeReturnTarget = null;
  if (room === 'street') {
    const unread = unreadMailCount(mailboxState, Date.now());
    const mailbox = new PIXI.Sprite(textureFromUrl(unread > 0
      ? 'assets/sprites/mailbox/npc_mailbox_variant_mailboxRight_x1_has_mail_idle_png_1354832230.webp'
      : 'assets/sprites/mailbox/npc_mailbox_variant_mailboxRight_x1_idle_png_1354832227.webp'));
    mailbox.anchor.set(0.5, 1);
    mailbox.x = 430;
    mailbox.y = GROUND_Y;
    mailbox.zIndex = itemZ('npc_mailbox', 4);
    entityLayer.addChild(mailbox);
    homeMailboxTarget = register({
      classId: 'npc_mailbox',
      label: 'Mailbox',
      subtitle: unread ? `${unread} unread message${unread === 1 ? '' : 's'}` : 'Your very own mail',
      sprite: mailbox,
      state: { unread },
    });
    const door = makeHomeDoorSprite(room);
    homeDoorTarget = register({
      classId: 'home_door',
      label: 'Your House',
      subtitle: 'The indoor half of home',
      sprite: door,
      state: { room: 'street' },
    });
    const marker = makeHomeReturnSprite();
    const way = homeReturnDestination();
    homeReturnTarget = register({
      classId: 'home_return_marker',
      label: way.label,
      subtitle: `Back to ${way.label}`,
      sprite: marker,
      state: { returnLabel: way.label, returnHub: way.hubName },
    });
  } else {
    const door = makeHomeDoorSprite(room);
    homeDoorTarget = register({
      classId: 'home_door',
      label: 'Front Door',
      subtitle: 'Back to your home street and mailbox',
      sprite: door,
      state: { room: 'interior' },
    });
    const rug = new PIXI.Graphics();
    rug.ellipse(650, GROUND_Y + 2, 310, 42).fill({ color: 0x9e5d7b, alpha: 0.8 });
    rug.zIndex = 1;
    entityLayer.addChildAt(rug, 0);
  }
}

async function renderHomeScene(room = homeState.room || 'street', opts = {}) {
  const targetTsid = room === 'interior' ? HOME_INTERIOR_TSID : HOME_STREET_TSID;
  clearWorldEntities();
  if (bgLayer && world) {
    world.removeChild(bgLayer);
    bgLayer.destroy({ children: true });
  }
  // The homes feature (js/features/homes-feature.js) builds the scene.
  const homeScene = features.query('homeScene', room, engine);
  WORLD_W = homeScene?.width || 1500;
  GROUND_Y = Number(homeScene?.groundY) || 620;
  bgLayer = homeScene?.background || drawHomeBackground(homeState.style, room);
  world.addChildAt(bgLayer, 0);
  streetPlatforms = bgLayer.platformsScreen;
  streetWalls = [];
  climb = { active: false, wall: null };
  currentStreetTsid = targetTsid;
  currentStreet = {
    tsid: targetTsid,
    label: room === 'interior' ? 'Your House' : 'Your Home Street',
    hubId: 'home',
    hubName: 'Homes',
    // The scene's own height (the street map's shape and dots: a home street is 972 tall).
    bounds: { l: 0, r: WORLD_W, t: 0, b: Number(bgLayer.worldH) || AUTHORED_VIEW_H },
    platforms: streetPlatforms,
    signposts: [],
  };
  if (homeScene) {
    const targets = homeScene.spawnTargets() || {};
    homeMailboxTarget = targets.mailbox || null;
    homeDoorTarget = targets.door || null;
    homeReturnTarget = targets.gate || null;
  } else {
    spawnHomeSceneTargets(room);
  }
  if (player) {
    const sceneX = homeScene?.spawnFor?.(opts);
    player.x = Number.isFinite(sceneX) ? sceneX : Number.isFinite(opts.spawnX) ? opts.spawnX : room === 'interior' ? 1030 : 250;
    player.y = GROUND_Y;
    player.vx = 0;
    player.vy = 0;
    player.onGround = true;
  }
  camTarget = cameraTargetForPlayer(player?.x || 250);
  camY = cameraTargetY(player?.y || GROUND_Y, activeCameraWorldHeight(), LOCATION_VIEW_H);
  world.x = -Math.round(camTarget);
  world.y = -Math.round(camY);
  homeScene?.enter?.();
  // G226: the room's dropped stacks (clearWorldEntities took their sprites).
  refreshDroppedWorldItems();
  const name = document.getElementById('street-name');
  if (name) {
    name.textContent = `${currentStreet.label} · ${HOME_STYLES[homeState.style]?.label || 'Meadow'} Home`;
    name.dataset.tsid = targetTsid;
  }
  if (app?.canvas) app.canvas.dataset.homeScene = room;
  updateHomeChrome();
  updateHud();
  return currentStreet;
}

/**
 * A look standing still as a picture (a data URL, cached by look and size): the home card's owner
 * (G249: the client loaded pc.singles_url + '_172.png') and Your looks (ticket 59: the client's
 * AvatarLookUI drew singles_base + '_100.png', 100x144).
 */
const lookPortraits = new Map();
async function lookPortraitUrl(vector, size = POL_OWNER_SIZE, pad = 12) {
  if (!avatarCatalog) avatarCatalog = await loadAvatarCatalog().catch(() => null);
  if (!avatarCatalog) return null;
  const look = resolveLook(vector && typeof vector === 'object' ? vector : {}, avatarCatalog);
  const key = `${size.w}x${size.h}|${lookKey(look)}`;
  if (!lookPortraits.has(key)) {
    lookPortraits.set(key, prepareLook(look).then((prep) => {
      const canvas = document.createElement('canvas');
      canvas.width = size.w * 2;
      canvas.height = size.h * 2;
      return paintVectorPreview(prep, canvas, 801, { pad, flip: true }).toDataURL('image/png');
    }).catch(() => null));
  }
  return lookPortraits.get(key);
}
function ownerPortraitUrl() {
  return lookPortraitUrl(playerAppearance.vector);
}

/**
 * G249: the home card (LoadingLocationPOLView) for your home street, house or
 * Tower: its visits (location.js getLoadingInfo 3157-3159 pols_visited, read
 * before this entry counts), then counted. knownVisits credits saves from
 * before the history was kept (home visits, house visits).
 */
function homeLoadingCard(pol) {
  if (!pol?.type) return null;
  const tower = pol.type === 'tower';
  const slot = engine.streetSlot(tower ? `${STREET_VISITS_SLOT}:tower` : STREET_VISITS_SLOT, pol.type === 'exterior' ? HOME_STREET_TSID : HOME_INTERIOR_TSID);
  const known = Math.max(0, Number(pol.knownVisits ?? (pol.type === 'exterior' ? homeState.visits - 1 : tower ? 0 : features.query('houseVisits'))) || 0);
  const visit = streetLoadingVisit(slot, { knownVisits: known });
  recordStreetEntry(slot, Date.now(), known);
  return { ...pol, visit, ownerImg: ownerPortraitUrl };
}

async function showLocationTransition({
  fromLabel = '',
  fromHub = '',
  toLabel = '',
  toHub = '',
  pol = null,
  load,
} = {}) {
  const el = document.getElementById('screen-transition');
  if (!el) return load?.();
  let result = null;
  const card = homeLoadingCard(pol);
  await runStreetTransition(el, {
    fromLabel,
    fromHub,
    toLabel,
    toHub,
    pol: card,
    // G270: targets still loading their art (patches-feature) count too, as location.js counts items.
    details: card ? () => loadingCardDetails({ targets: [...interactables, ...features.collect('pendingTargets', engine)], quoinTypes: quoins.map((q) => q.typeId), visit: card.visit }) : undefined,
    onMid: async () => {
      result = await load?.();
    },
  });
  return result;
}

/**
 * Ticket 67: back into your home at the end of an instance you started there (a Ticket to
 * Paradise, a quest street), at the spot you left, the stay still going: Glitch kept your own
 * house as the way back (players/inc_instances.js instances_enter 81-86: get_simple_location,
 * not pols_get_entrance_outside, for the owner) and teleported you there (instances_left 168-176).
 */
async function arriveInHome(tsid, opts = {}) {
  homeState.inHome = true;
  homeState.room = tsid === HOME_INTERIOR_TSID ? 'interior' : 'street';
  const at = Number.isFinite(opts.spawnX) ? { spawnX: opts.spawnX, arrive: 'exact' } : {};
  const load = () => renderHomeScene(homeState.room, at);
  if (opts.useTransition === false) return load();
  return showLocationTransition({
    fromLabel: currentStreet?.label || '',
    fromHub: currentStreet?.hubName || '',
    toLabel: homeState.room === 'interior' ? 'Your House' : 'Your Home Street',
    toHub: `${HOME_STYLES[homeState.style]?.label || 'Meadow'} Home`,
    pol: { type: homeState.room === 'interior' ? 'interior' : 'exterior' },
    load,
  });
}

/**
 * Ticket 67: where an instance started here leads back to: this spot, or in a feature scene
 * (another player's home, a quest room) the street the scene leads back to, since a scene can't
 * be entered again by its tsid (it fell back to the arrival street).
 */
function instanceSourceHere(here) {
  const back = engine.inScene() ? engine.sceneReturnTo : null;
  return back?.tsid ? { tsid: back.tsid, x: back.x, y: back.y } : here;
}

async function teleportHome({ room = 'street' } = {}) {
  if (!homeState.owned) {
    openHomePanel();
    return { ok: false, reason: 'not_owned' };
  }
  if (homeIsInstanced()) return { ok: false, reason: 'already_home' };
  if (
    greedyStreetIsInstanced() || legalizeIsInstanced() || summersDayIsInstanced() ||
    deEmbiggenifyIsInstanced() || rookWoodsIsInstanced() || winterWalkIsInstanced() ||
    fourLetterIsInstanced() || paradiseIsInstanced()
  ) {
    toast('Finish or leave this instance before teleporting home.');
    return { ok: false, reason: 'instance' };
  }
  const source = homeTripSource();
  // Ticket 57: a stay at home a scene left behind (it leads back home) is over once you teleport.
  if (homeState.inHome) homeState.inHome = false;
  const result = beginHomeVisit(homeState, source);
  if (!result.ok) return result;
  // /house (inc_houses.js houses_go_to_new_house go_inside) lands straight inside the house.
  if (room === 'interior') homeState.room = 'interior';
  closeHomePanel();
  closeMap();
  closeVerbMenu();
  await showLocationTransition({
    fromLabel: source.label,
    fromHub: source.hubName,
    toLabel: homeState.room === 'interior' ? 'Your House' : 'Your Home Street',
    pol: { type: homeState.room === 'interior' ? 'interior' : 'exterior' },
    toHub: `${HOME_STYLES[homeState.style]?.label || 'Meadow'} Home`,
    load: () => renderHomeScene(homeState.room),
  });
  pushActivity(`Teleported home from ${source.label}.`);
  toast('Welcome home. Your mailbox is waiting.', 3000);
  savePlayerState();
  return result;
}

/**
 * Ticket 57: where Teleport home remembers you came from. In a feature scene (another player's
 * home, a quest room) that is the street the scene leads back to, since the scene itself can't be
 * entered again from Return to Ur; a scene that leads home keeps the home's own way back.
 */
function homeTripSource() {
  const back = engine.inScene() ? engine.sceneReturnTo : null;
  if (back?.tsid) {
    const meta = STREET_INDEX.streets?.[back.tsid];
    return { tsid: back.tsid, label: meta?.label || back.label || back.tsid, hubName: meta?.hubName || '', x: back.x, y: back.y };
  }
  return {
    tsid: currentStreetTsid,
    label: currentStreet?.label || currentStreetTsid,
    hubName: currentStreet?.hubName || '',
    x: player?.x,
    y: player?.y,
  };
}

async function switchHomeRoom(room) {
  if (!homeIsInstanced()) return false;
  const result = room === 'interior'
    ? enterHomeInterior(homeState)
    : leaveHomeInterior(homeState);
  if (!result.ok) return false;
  await showLocationTransition({
    fromLabel: currentStreet?.label || 'Home',
    fromHub: 'Homes',
    toLabel: result.label,
    toHub: 'Homes',
    pol: { type: room === 'interior' ? 'interior' : 'exterior' },
    load: () => renderHomeScene(room, { arrive: 'door', spawnX: room === 'interior' ? 1030 : 910 }),
  });
  savePlayerState();
  return true;
}

/**
 * GATESIGN: where your home's way out leads: the street you came from (homeState.returnLocation),
 * else your arrival street (STREET_INDEX.default), with its label and hub name for the Back to Ur
 * signpost's arm and the Imagination hub's Back to world tip (ImgMenuHome.as: label + ", " + hub).
 */
function homeReturnDestination(back = homeState.returnLocation) {
  const tsid = back?.tsid || STREET_INDEX.default;
  const meta = STREET_INDEX.streets?.[tsid];
  return {
    ...(back || {}),
    tsid,
    label: back?.label || meta?.label || 'Groddle',
    hubName: back?.hubName || meta?.hubName || '',
  };
}

/**
 * GATESIGN: the Imagination menu's Back to world (ImgMenuHome.as at home, ImgMenuBackToWorld.as in
 * another player's home): where it leads ({ label, hubName, tip, art }) and go(), or null out in
 * the world. Anywhere in your own home (street, house), as the original's isTsidInHome counted the
 * house too; a visit to someone's home (neighbours-mp-feature) answers with its own way back.
 */
function homeWayOut() {
  const visit = features.query('homeVisitWayOut', engine);
  const base = visit || (homeIsInstanced() ? { ...homeReturnDestination(), go: () => returnFromHome() } : null);
  if (!base) return null;
  const tip = base.hubName && base.hubName !== base.label ? `${base.label}, ${base.hubName}` : base.label;
  return { ...base, tip, art: base.tsid ? resolveLoadingImg(base.tsid) : null };
}

async function returnFromHome() {
  if (!homeIsInstanced()) return false;
  // Ticket 41: busy from the first step, before endHomeVisit stops counting you as home.
  return onStreetTrip(() => returnFromHomeTrip());
}

async function returnFromHomeTrip() {
  const result = endHomeVisit(homeState);
  if (!result.ok) return false;
  const destination = homeReturnDestination(result.returnLocation);
  closeHomePanel();
  closeMailboxPanel();
  await enterStreetWithTransition(destination.tsid, {
    spawnX: destination.x,
    spawnY: destination.y,
    quiet: true,
  });
  pushActivity(`Returned from home to ${currentStreet?.label || destination.label}.`);
  toast('Back in Ur.', 2200);
  savePlayerState();
  savePlayerLocation({ tsid: destination.tsid, x: player?.x, y: player?.y });
  return true;
}

function handleHomeTarget(target, verbId) {
  if (target?.classId === 'npc_mailbox' && verbId === 'view_inbox') {
    openMailboxPanel({ atMailbox: true });
    return true;
  }
  if (target?.classId === 'home_door') {
    if (verbId === 'enter_house') switchHomeRoom('interior');
    else if (verbId === 'leave_house') switchHomeRoom('street');
    return true;
  }
  if (target?.classId === 'home_return_marker' && verbId === 'return_to_world') {
    returnFromHome();
    return true;
  }
  return false;
}

/**
 * The location's avatar filter. The client gives the middleground layer's filters to your avatar
 * and every other player's (AddAvatarViewCmd, MiddleGroundRenderer.createPcView: Layer.filtersA,
 * ColorMatrix.getFilter), so a room whose middleground is desaturated shows everyone in grey. A
 * scene names it as `avatarFilters` (Layer filter values: saturation, brightness, ...); null clears.
 * Remote players take it from engine.avatarTone (features/realtime-feature.js).
 */
let avatarTone = null;
function setAvatarTone(filters) {
  const matrix = filters ? glitchLayerMatrix(filters) : null;
  if (player && avatarTone) {
    const left = (player.filters || []).filter((f) => f !== avatarTone);
    player.filters = left.length ? left : null;
  }
  avatarTone = null;
  if (!matrix || !globalThis.PIXI?.ColorMatrixFilter) return;
  avatarTone = new PIXI.ColorMatrixFilter();
  avatarTone.matrix = matrix;
  avatarTone.glitchFilters = filters;
  if (player) player.filters = [...(player.filters || []), avatarTone];
}

function clearWorldEntities() {
  cancelCurrentAction({ quiet: true });
  endStreetOverlays();
  // Player report 23: a new street starts with no key held (a real one comes back on its next repeat).
  heldKeys.releaseAll('street');
  clearHoverGlow();
  releaseSignpostFocus();
  clearSignpostBoardHover();
  recentInteractionTarget = null;
  recentInteractionUntil = 0;
  clearSpeechBubbles();
  for (const spr of [...entityLayer.children]) {
    if (spr === player) continue;
    entityLayer.removeChild(spr);
  }
  features.streetClear(engine);
  if (entityLayer) entityLayer.filters = null;
  setAvatarTone(null);
  interactables = [];
  piggies = [];
  chickens = [];
  apples = [];
  worldMusicblocks = [];
  droppedItemSprites = [];
  quoins = [];
  butterflies = [];
  trees = [];
  localCompanions = [];
  if (app?.canvas) {
    app.canvas.dataset.localCompanionCount = '0';
    app.canvas.dataset.localCompanionNames = '';
    app.canvas.dataset.localCompanionPositions = '';
    app.canvas.dataset.localCompanionSpeaker = '';
    app.canvas.dataset.localCompanionSpeech = '';
  }
  // Unregister plot interactables with gardens
  for (const g of gardens) {
    for (const pt of g.state?.plotTargets || []) {
      // interactables cleared en masse below
    }
  }
  gardens = [];
  mineRocks = [];
  activeGarden = null;
  activeShrineTarget = null;
  spinningWheelTarget = null;
  spinningWheelLastPhase = '';
  spinningWheelPrompted = false;
  stootDollTarget = null;
  stopPhantomHeartbeat();
  phantomTarget = null;
  if (hogHaulCarrySprite?.parent) hogHaulCarrySprite.parent.removeChild(hogHaulCarrySprite);
  if (hogHaulCarrySprite && !hogHaulCarrySprite.destroyed) hogHaulCarrySprite.destroy();
  hogHaulBaits = [];
  hogHaulPigTargets = [];
  hogHaulPenTarget = null;
  hogHaulCarrySprite = null;
  hogHaulRivalSprite = null;
  hogHaulRivalWaypoints = [];
  hogHaulRivalWaypointIndex = 0;
  fourLetterTargets = [];
  fourLetterMrBlock = null;
  ilmenskieTarget = null;
  clearWinterAtmosphere();
  winterWalkMotes = [];
  winterWalkPortal = null;
  summersDayBonusQuoins = [];
  summersDayExit = null;
  summersDayAnnexReveal = null;
  rookCrushers = [];
  rookEggTarget = null;
  rookHitFx = null;
  paradisePickups = [];
  paradiseRings = [];
  paradiseExit = null;
  paradiseBackdropStars = [];
  homeMailboxTarget = null;
  homeDoorTarget = null;
  homeReturnTarget = null;
  const fourLetterHud = document.getElementById('four-letter-hud');
  if (fourLetterHud) fourLetterHud.hidden = true;
  const legalizeHud = document.getElementById('legalize-hud');
  if (legalizeHud) legalizeHud.hidden = true;
  const paradiseHud = document.getElementById('paradise-flight-hud');
  if (paradiseHud) paradiseHud.hidden = true;
  const summersDayHud = document.getElementById('summers-day-hud');
  if (summersDayHud) summersDayHud.hidden = true;
  const greedyStreetHud = document.getElementById('greedy-street-hud');
  if (greedyStreetHud) greedyStreetHud.hidden = true;
  const rookHud = document.getElementById('rook-woods-hud');
  if (rookHud) rookHud.hidden = true;
  const rookMuseumHud = document.getElementById('rook-museum-hud');
  if (rookMuseumHud) rookMuseumHud.hidden = true;
  const deEmbiggenifyHud = document.getElementById('de-embiggenify-hud');
  if (deEmbiggenifyHud) deEmbiggenifyHud.hidden = true;
  closeShrinePanel();
  portalSprites = [];
  closeGardenPanel();
}

/**
 * Load original street geometry + multi-layer decos.
 * @param {string} tsid
 * @param {{ spawnX?: number, spawnY?: number, quiet?: boolean }} [opts]
 */
async function enterStreet(tsid, opts = {}) {
  // Ticket 67: your home is no street file (it resolved to the arrival street, a stay still set).
  if (isHomePlaceTsid(tsid) && homeState.owned) return arriveInHome(tsid, { ...opts, useTransition: false });
  const firstVisit = !persistentWorldState.streets?.[tsid];
  if (!opts.bypassFeatureGates) {
    const redirect = features.enterGate(tsid, engine);
    if (redirect?.tsid && redirect.tsid !== tsid) {
      return enterStreet(resolveIndexTsid(redirect.tsid) || redirect.tsid, {
        ...opts,
        spawnX: redirect.spawnX,
        spawnY: redirect.spawnY,
        bypassFeatureGates: true,
      });
    }
  }
  if (featState.nextStep !== 1) {
    resetIncantationChain(featState);
    assistedFeatChain = null;
    clearFeatCompanionTimers();
  }
  const data = await loadStreetData(tsid);
  assertStreetGeometry(data);
  if (LAST_FEAT_STREET_LABELS[data.tsid]) {
    // The archived XML carries its internal template label; production map
    // data and the supplied recording preserve these public Roobrik names.
    data.label = LAST_FEAT_STREET_LABELS[data.tsid];
  }
  if (data.tsid === STOOT_MEMORIAL_STREET_ID) {
    // The archived private street omits its hub label. G315: 'unnnn' is in hub 96
    // (inc_data_maps_prod.js 16973-16978, 679); the old hub label had no source.
    data.hubName = 'Jethimadh Tower: Mid';
  }
  features.prepareStreet(data, engine);
  currentStreet = data;
  currentStreetTsid = data.tsid;
  // Ticket 67: a world street ends a stay at home, however you got there, unless it is an
  // instance whose way back is your home.
  if (homeState.inHome) homeState.inHome = homeStayAfterArrival(homeState, { arrived: data.tsid, wayBack: instanceWayBack()?.tsid });
  WORLD_W = streetWidth(data);
  clearWorldEntities();

  if (bgLayer && world) {
    world.removeChild(bgLayer);
    bgLayer.destroy({ children: true });
  }
  const available = await loadDecoManifest();
  await loadSignpostTextures(PIXI);
  bgLayer = buildStreetView(data, PIXI, {
    renderer: app.renderer,
    available,
    cameraBottomPadding: cameraBottomSlack(LOCATION_VIEW_H),
    // The canvas runs on under the overlaid pack.
    skirtBelow: VIEW_H - LOCATION_VIEW_H,
    // G582: and past the street's right end, where the camera stops with the end left of the
    // Social drawer (syncCameraSafeArea reserves at most 0.42 of the view; the view grows with zoom).
    skirtRight: SKIRT_RIGHT_PAD,
  });
  streetPlatforms = bgLayer.platformsScreen;
  streetWalls = wallsScreen(data);
  if (entityLayer) {
    if (bgLayer.middlegroundMatrix) {
      const middlegroundColour = new PIXI.ColorMatrixFilter();
      middlegroundColour.matrix = bgLayer.middlegroundMatrix;
      entityLayer.filters = [middlegroundColour];
    } else {
      entityLayer.filters = null;
    }
  }
  climb = { active: false, wall: null };
  Object.assign(jumpState, createJumpState(movementNow()));
  // Ground reference = median of lower platforms
  const ys = streetPlatforms.map((p) => (p.y1 + p.y2) / 2).sort((a, b) => a - b);
  GROUND_Y = ys[Math.floor(ys.length * 0.75)] || streetPlatforms[0]?.y1 || 800;
  world.addChildAt(bgLayer, 0);
  syncStreetFront();
  if (app?.canvas) app.canvas.dataset.streetFrontLayers = (bgLayer.frontLayers || []).join(',');

  // Tiny Speck's late-game location objects retain each street's real item
  // population. Allocate all of it in one pass so independent systems never
  // reuse the same handful of platform points or bury the arrival spot.
  const ecologyEntry = features.ecologyOverride(data, engine) || ecologyForStreet(data.tsid);
  currentStreetPopulation = populationForStreet(data.tsid, ecologyEntry, {
    starter: data.tsid === STREET_INDEX.default,
  });
  if (currentStreetPopulation.giantId) {
    data.officialGiantId = currentStreetPopulation.giantId;
  }
  // The store belongs to the street's vendor: it closes when you leave the street, as the client's
  // dialogs did on a move (Dialog.as close_on_move 58, 367-373) and the server only traded with a
  // vendor in your location (main.js doStoreBuy -> getTargetStack, pc.location.apiLockStack).
  if (isVendorOpen()) closeVendor();
  activeVendor = selectVendorProfile(
    currentStreetTsid,
    new URLSearchParams(location.search).get('vendor') || '',
    {
      rocks: currentStreetPopulation.rockClasses.length,
      store: STREET_INDEX.streets?.[currentStreetTsid]?.store,
    }
  );
  // Seasonal stock (Glitchmas Crackers and Cards) comes and goes with the calendar;
  // the multiplayer Camera (G332, snaps-feature). Each feature's answer feeds the next.
  for (const feature of features.features) {
    if (typeof feature.vendorProfile === 'function') activeVendor = feature.vendorProfile(activeVendor, engine) || activeVendor;
  }
  // Signposts, doors and ladder feet stay clear (street-ecology.js streetReservedSpots,
  // shared with the realtime server's layout).
  const reserved = streetReservedSpots(data);
  // Multiplayer: no per-player reservation, so every player's street (and the
  // realtime server's layout, tools/build-realtime-objects.mjs) puts each
  // rock, tree and node in the same place.
  if (GAME_MODE !== 'multiplayer' && Number.isFinite(opts.spawnX) && Number.isFinite(opts.spawnY)) {
    reserved.push({ x: opts.spawnX, y: opts.spawnY, key: 'saved-arrival', clearance: 210 });
  }
  currentStreetPlacement = planStreetPlacements(
    streetPlatforms,
    [
      { key: 'player', count: 1, clearance: 190 },
      { key: 'trees', count: currentStreetPopulation.treeClasses.length, clearance: 135 },
      { key: 'gardens', count: currentStreetPopulation.gardens, clearance: 165 },
      { key: 'vendor', count: currentStreetPopulation.vendor ? 1 : 0, clearance: 120 },
      { key: 'shrine', count: currentStreetPopulation.shrine ? 1 : 0, clearance: 135 },
      { key: 'rocks', count: currentStreetPopulation.rockClasses.length, clearance: 74 },
      { key: 'piggies', count: currentStreetPopulation.piggies, clearance: 92 },
      { key: 'chickens', count: currentStreetPopulation.chickens, clearance: 86 },
      { key: 'butterflies', count: currentStreetPopulation.butterflies, clearance: 62 },
      { key: 'flyingButterflies', count: currentStreetPopulation.flyingButterflies, clearance: 58 },
      { key: 'apples', count: currentStreetPopulation.apples, clearance: 30 },
      { key: 'musicblocks', count: currentStreetPopulation.musicblocks, clearance: 45 },
      { key: 'quoins', count: currentStreetPopulation.quoins, clearance: 28 },
      ...features.collect('placementGroups', currentStreetPopulation, data, engine),
    ],
    { worldW: WORLD_W, seed: data.tsid, reserved }
  );
  const placement = (key) => currentStreetPlacement.groups[key] || [];

  // Place living content on its reserved real-platform anchors.
  const pigPoints = placement('piggies');
  piggies = spawnPiggies(pigPoints.map((p) => p.x));
  // A walking animal turns before its floor ends (street-ecology.js animalPatrolRange).
  piggies.forEach((spr, i) => {
    const p = pigPoints[i];
    if (p) { spr.x = p.x; spr.y = p.y + 2; spr.baseX = p.x; spr.range = animalPatrolRange('piggies', p.room); }
    // Its own walk (features/animal-mood-feature.js walks it back here after food).
    spr.home = { x: spr.baseX, range: spr.range };
  });
  const chickenPoints = placement('chickens');
  chickens = spawnChickens(chickenPoints.map((p) => p.x));
  chickens.forEach((spr, i) => {
    const p = chickenPoints[i];
    if (p) { spr.x = p.x; spr.y = p.y + 2; spr.baseX = p.x; spr.range = animalPatrolRange('chickens', p.room); }
  });
  const butterflyPoints = placement('butterflies');
  butterflies = spawnButterflies(
    butterflyPoints.map((p) => p.x),
    placement('flyingButterflies')
  );
  // Only snap resting (path) butterflies to platforms — leave flyers in the air.
  let restIdx = 0;
  butterflies.forEach((spr) => {
    if (spr._ambient) return;
    const p = butterflyPoints[restIdx];
    restIdx += 1;
    if (p) {
      spr.x = p.x;
      spr.y = p.y + 2;
      spr._groundY = p.y;
    }
  });
  apples = spawnApples(placement('apples'));
  worldMusicblocks = spawnMusicblockDrop(placement('musicblocks')[0], true);
  const treeSpots = placement('trees').map((point, index) => ({
    x: point.x,
    y: point.y,
    classId: currentStreetPopulation.treeClasses[index],
  }));
  trees = spawnTrees(treeSpots);
  // Animated official eight-scene quoins placed along reachable platforms.
  // A rebuilt room whose picture shows where its quoins sit hands them in (features' quoinSpots: screen-space centres).
  const roomQuoins = features.query('quoinSpots', data, engine);
  quoins = spawnQuoins(Array.isArray(roomQuoins) ? roomQuoins : placement('quoins'));

  // Signposts are manually hit-tested by individual destination board.
  portalSprites = bgLayer.signViews || [];
  if (currentStreetPopulation.vendor) spawnVendorNpc(placement('vendor')[0]);
  if (currentStreetPopulation.shrine) await spawnShrine(placement('shrine')[0]);
  refreshDroppedWorldItems();
  placement('gardens').forEach((point, index) => {
    // The first bed grows crops and the second herbs, except on the Herb Gardens streets (report 188).
    const bed = streetGardenBed(data.tsid, index);
    spawnGarden({
      x: point.x,
      y: point.y + 2,
      cols: bed.cols,
      rows: 2,
      gardenType: bed.gardenType,
      bed: bed.bed,
    });
  });
  spawnMineRocks(currentStreetPopulation.rockClasses, placement('rocks'));

  if (player) {
    const spawn = placement('player')[0];
    const sourceSpawnX =
      data.tsid === STOOT_MEMORIAL_STREET_ID ? WORLD_W * 0.72 : spawn?.x;
    player.x = opts.spawnX ?? sourceSpawnX ?? WORLD_W * 0.5;
    player.y = opts.spawnY ?? spawn?.y ?? GROUND_Y;
    // Clamp saved/spawn coords into street bounds
    player.x = clamp(player.x, 40, Math.max(80, WORLD_W - 40));
    const streetH = bgLayer?.worldH || VIEW_H;
    player.y = clamp(player.y, 40, Math.max(80, streetH - 20));
    // /stuck's spot: this arrival, or the street's own when this entry restores a place (quiet).
    streetArrival = opts.quiet || !Number.isFinite(opts.spawnX)
      ? {
        tsid: data.tsid,
        x: clamp(sourceSpawnX ?? WORLD_W * 0.5, 40, Math.max(80, WORLD_W - 40)),
        y: clamp(spawn?.y ?? GROUND_Y, 40, Math.max(80, streetH - 20)),
        from: 'street',
      }
      : { tsid: data.tsid, x: player.x, y: player.y, from: 'arrival' };
    player.vx = 0;
    player.vy = 0;
    player.onGround = true;
    noteGrounded(jumpState, true, movementNow());
  }
  const summerStory = ensureSummersDayStory(questState);
  if (
    player &&
    summerStory.pendingQurazies > 0 &&
    summerStory.qurazyStreetTsid === currentStreetTsid
  ) {
    const rewardPoints = summersDayQurazyPoints(player);
    for (let index = 0; index < summerStory.pendingQurazies; index += 1) {
      quoins.push(
        spawnWorldQuoin(rewardPoints[index], 'qurazy', {
          useExactY: true,
          phaseIndex: index,
          summersDayRewardIndex: index,
        })
      );
    }
  }
  if (data.tsid === STOOT_MEMORIAL_STREET_ID) spawnStootMemorial();
  if (currentStreetPopulation.companions !== false) {
    spawnLocalCompanions();
    countCompanionFollowStreet(data.tsid);
  } else {
    stopCompanionFollowForInstance();
  }
  spawnPhantomQuestEncounter();
  spawnIlmenskieJones();
  features.streetEnter(data, engine, opts);
  mapTrail = noteMapTrail(mapTrail, { tsid: data.tsid, hubId: data.hubId });
  if (firstVisit) emitGameEvent(`street_first_visit:${data.tsid}`);
  if (!engine.inScene()) {
    recordStreetEntry(engine.streetSlot(STREET_VISITS_SLOT, data.tsid), Date.now(), achieveState.groups?.locations_visited?.includes(data.tsid) ? 1 : 0);
  }
  recordStreetVisit(data.tsid);
  emitGameEvent(`street_entered:${String(data.label || '').toLowerCase().replace(/[^a-z0-9]+/g, '_')}`);
  if (app?.canvas) {
    const pop = currentStreetPopulation;
    app.canvas.dataset.ecologySource = pop.source;
    app.canvas.dataset.ecologySourceTsid = pop.sourceTsid || '';
    app.canvas.dataset.ecologyOfficialGiant = pop.giantId || '';
    app.canvas.dataset.ecologyPopulation = [
      `piggies=${pop.piggies}`,
      `chickens=${pop.chickens}`,
      `butterflies=${pop.butterflies + pop.flyingButterflies}`,
      `trees=${pop.treeClasses.length}`,
      `rocks=${pop.rockClasses.length}`,
      `gardens=${pop.gardens}`,
      `vendor=${Number(pop.vendor)}`,
      `shrine=${Number(pop.shrine)}`,
    ].join(',');
    const gap = nearestPlacementGap(currentStreetPlacement, 'player');
    app.canvas.dataset.ecologyPlayerClearance = Number.isFinite(gap) ? String(Math.round(gap)) : 'none';
    app.canvas.dataset.ecologyCandidates = String(currentStreetPlacement.candidateCount);
  }
  camTarget = cameraTargetForPlayer(player.x);
  const streetH = activeCameraWorldHeight();
  camY = cameraTargetY(player.y, streetH, LOCATION_VIEW_H);
  world.x = -Math.round(camTarget);
  world.y = -Math.round(camY);
  updateHud();
  // Street nameplate
  const nameEl = document.getElementById('street-name');
  if (nameEl) {
    const winterLabel = winterLocationLabel(data.tsid);
    const stootLabel = data.tsid === STOOT_MEMORIAL_STREET_ID
      ? { street: 'unnnn', hub: 'Jethimadh Tower: Mid' }
      : null;
    const streetLabel = winterLabel?.street || stootLabel?.street ||
      (data.tsid === AXIS_DENYDE_STREET_ID ? 'Axis Denyde' : data.label);
    const hubLabel = winterLabel?.hub ?? stootLabel?.hub ??
      (data.tsid === AXIS_DENYDE_STREET_ID ? 'Pollokoo' : data.hubName);
    nameEl.textContent = hubLabel ? `${streetLabel} · ${hubLabel}` : streetLabel;
    nameEl.dataset.tsid = data.tsid;
  }
  // Hub-tuned ambient BGM (GSJS ambient_hub_map → ambient_library)
  // Canvas data-ambient-theme: the street's theme, with or without sound (G184 QA).
  if (app?.canvas) app.canvas.dataset.ambientTheme = resolveAmbientTheme(data);
  if (state.started && audio.ctx) {
    const prevTheme = ambientThemeId;
    setAmbientForStreet(data);
    if (!opts.quiet && ambientThemeId !== prevTheme) {
      pushActivity(`Music: ${themeLabel(ambientThemeId)}`);
    }
  }
  // Not under the start card or into the tutorial (newxp-feature arrivalQuiet, G339).
  if (!opts.quiet && features.query('arrivalQuiet', engine) !== true) toast(`Arrived: ${data.label}`, 2800);
  // Auto-save map location after every successful street enter
  if (player) savePlayerLocation({ tsid: data.tsid, x: player.x, y: player.y });
  return data;
}

/**
 * Shared travel entry used by map click, T key, and signpost click.
 * Full-screen crossfade modeled on LoadingLocationView.
 * @param {string} toTsid
 * @param {{ label?: string }} [meta]
 */
async function travelTo(toTsid, meta = {}) {
  const featureGate = features.travelGate(toTsid, engine, { via: meta.via });
  if (!featureGate.ok) {
    toast(featureGate.msg || 'You cannot travel there right now.');
    return { ok: false, reason: 'feature_gate' };
  }
  if (homeIsInstanced()) {
    toast('Use the signpost by your house, or Back to world on X, to leave home.');
    return { ok: false, reason: 'home_instance' };
  }
  if (greedyStreetIsInstanced()) {
    toast('Storyland has no map routes. Finish all five acts or use Leave.');
    return { ok: false, reason: 'greedy_story_instance' };
  }
  if (legalizeIsInstanced()) {
    toast('This application has no map routes. Finish the bureaucracy or use Leave.');
    return { ok: false, reason: 'legalize_instance' };
  }
  if (summersDayIsInstanced()) {
    toast('The Giants’ shared memory has no map routes. Find the way home or use Leave.');
    return { ok: false, reason: 'summers_day_instance' };
  }
  if (deEmbiggenifyIsInstanced()) {
    toast('The catalogue page has no map routes. Finish the search or use Leave.');
    return { ok: false, reason: 'eesti_instance' };
  }
  if (rookWoodsIsInstanced()) {
    toast("The Rooks' Woods have no map routes. Reach the Egg or use Leave.");
    return { ok: false, reason: 'rook_instance' };
  }
  if (winterWalkIsInstanced()) {
    toast('The winter path has no map routes. Follow the motes or use Leave.');
    return { ok: false, reason: 'winter_instance' };
  }
  const plan = planTravel(currentStreetTsid, toTsid, STREET_INDEX.streets);
  if (!plan.ok) {
    if (plan.reason === 'already_here') toast('Already here.');
    else if (plan.reason === 'not_loaded') toast('That street is not loaded yet.');
    else toast('Cannot travel there.');
    return plan;
  }
  closeMap();
  closeVerbMenu();
  closeSkillsPanel();
  closeAchievePanel();
  closeQuestPanel();
  closeBuffsPanel();
  closeMakePanel();
  closeVendor();
  // Signposts land on the connect's source arrival point (build-street-navigation.mjs).
  const arrive = meta.arrive && Number.isFinite(meta.arrive.x) && Number.isFinite(meta.arrive.y)
    ? { spawnX: meta.arrive.x, spawnY: meta.arrive.y }
    : {};
  try {
    await enterStreetWithTransition(plan.toTsid, arrive);
  } catch (err) {
    // A failed street fetch leaves you where you were; say so instead of nothing.
    console.warn('travel', err);
    toast(`Could not reach ${plan.label || meta.label || 'that street'}. Try again in a moment.`, 4000);
    return { ok: false, reason: 'load_failed' };
  }
  if (player) floatText(player.x, player.y - 80, '✦ ' + (meta.label || plan.label), 0xc9a0ff);
  pushActivity(`Arrived: ${plan.label || meta.label || plan.toTsid}`);
  return plan;
}

/** Where an ordinary signpost cannot be used: says why and returns true (T and the arm keys). */
function signpostTravelRefused() {
  if (homeIsInstanced()) {
    toast('Use the signpost by your house, or Back to world on X, to leave home.');
    return true;
  }
  if (greedyStreetIsInstanced()) {
    toast('Storyland has no ordinary signposts.');
    return true;
  }
  if (legalizeIsInstanced()) {
    toast('The Bureaucratic Hall has no ordinary signposts.');
    return true;
  }
  if (summersDayIsInstanced()) {
    toast('There are no ordinary signposts inside this memory.');
    return true;
  }
  if (deEmbiggenifyIsInstanced()) {
    toast('Every ordinary signpost is enormous while you are this small.');
    return true;
  }
  if (rookWoodsIsInstanced()) {
    toast('Humbaba has sealed every ordinary signpost during the trial.');
    return true;
  }
  if (winterWalkIsInstanced()) {
    toast('The cold has frozen every ordinary signpost.');
    return true;
  }
  return false;
}

/**
 * The post the avatar stands at, as Enter and the T hint find it (in reach up and down, never
 * from a ladder: the client gave a climber no signpost, ladder-top-signposts.js), with its view.
 */
function signpostAtHand() {
  if (climb.active || !player) return null;
  if (currentStreet) {
    const near = signpostNear(walkUpSignpostStreet(currentStreet), player.x, 140, player.y);
    const view = near ? (portalSprites || []).find((v) => v && !v.destroyed && v.signpost === near.signpost) : null;
    if (view?.signBoards?.length) return { signpost: near.signpost, view, views: [view], boards: view.signBoards.map((board) => ({ view, board })) };
  }
  return scenePostAtHand();
}

/**
 * FRIENDPOST: the posts a scene draws itself (the home street's signpost: homes-feature's post
 * and its Back to Ur arm, home-street-mp-feature's friends' arms), as the registered targets'
 * sprites that carry scene boards (street-render.js addSignBoard).
 */
function sceneSignViews() {
  const out = [];
  for (const t of interactables) {
    const v = t?.sprite;
    if (v && !v.destroyed && v.parent && v.signBoards?.some((b) => b.scene) && !out.includes(v)) out.push(v);
  }
  return out;
}

/** Every post on screen whose arms are boards: the street's and the scene's. */
function signViewsHere() {
  const scene = sceneSignViews();
  return scene.length ? [...(portalSprites || []), ...scene] : portalSprites;
}

/**
 * FRIENDPOST: the scene post the avatar stands at (the street posts' 140 px), its views' arms
 * together, numbered from the top (Back to Ur 1, the friends 2 on), as one post.
 */
function scenePostAtHand() {
  const views = sceneSignViews();
  let best = null;
  for (const v of views) {
    const dx = Math.abs(v.x - player.x);
    if (dx > 140 || Math.abs(v.y - player.y) > 120) continue;
    if (!best || dx < Math.abs(best.x - player.x)) best = v;
  }
  if (!best) return null;
  const post = views.filter((v) => Math.abs(v.x - best.x) < 2 && Math.abs(v.y - best.y) < 2);
  const boards = post.flatMap((view) => view.signBoards.map((board) => ({ view, board }))).sort((a, b) => Number(a.board.key) - Number(b.board.key));
  return { signpost: null, view: best, views: post, boards };
}

/** What an arm says it leads to (QA data and the hover hint). */
function signBoardLabel(board) {
  return board?.connection?.label || board?.connection?.tsid || board?.tip || board?.label?.text || '';
}

/** Austin 2026-11-01: the post at hand shows each arm's number key (street-render.js setSignpostKeys). */
let keyedSignViews = [];
function showSignpostKeys(at) {
  const views = at?.views || [];
  if (views.length === keyedSignViews.length && views.every((v, i) => v === keyedSignViews[i])) return;
  for (const v of keyedSignViews) if (v && !v.destroyed) setSignpostKeys(v, false);
  keyedSignViews = views;
  for (const v of views) setSignpostKeys(v, true);
  if (app?.canvas) app.canvas.dataset.signpostKeys = at ? at.boards.map(({ board }) => `${board.key}:${signBoardLabel(board)}`).join('|') : '';
}

/**
 * 1 to 9 at a post take that arm (numbered from the top), as a click on it does. False when no
 * post is at hand or it has no such arm, so the key keeps its own use (5 says hi).
 */
function signpostArmFor(key) {
  if (!/^[1-9]$/.test(String(key))) return null;
  const at = signpostAtHand();
  return at?.boards.find(({ board }) => board.key === String(key)) || null;
}

/**
 * FRIENDPOST: a scene post's arm runs its verb on its target as the post's menu would (the
 * walk-over included, requestVerb): a friend's arm goes to their home street, Back to Ur back
 * out (SignpostView.as clickHandler 519-525 and go 581-584: a click on a sign is that sign).
 */
function takeSceneArm(hit) {
  const board = hit?.board;
  const target = board?.target || interactables.find((t) => t?.sprite === hit?.view) || null;
  if (!target) return false;
  const verbs = menuVerbsFor(target) || [];
  const verb = board.verbId ? verbs.find((v) => v.id === board.verbId) : verbs.find((v) => v.enabled !== false) || verbs[0];
  setCanvasData('signpostArm', `${board.key}:${target.classId || ''}:${verb?.id || ''}`);
  clearSignpostBoardHover();
  if (!verb) return false;
  if (verb.enabled === false) {
    if (verb.reason) toast(verb.reason, 2600);
    else openVerbMenu(target);
    return true;
  }
  requestVerb(target, verb);
  return true;
}

/** RIGHTCLICK: the shared menu (js/ui/context-menu.js) the world opens for a signpost's arms. */
let worldCtxMenu = null;
function worldContextMenu() {
  if (!worldCtxMenu) worldCtxMenu = createContextMenu({ doc: document, host: document.getElementById('game-root'), id: 'world-ctx-menu', className: 'world-ctx-menu', setData: setCanvasData });
  return worldCtxMenu;
}

/**
 * RIGHTCLICK (js/world-context-menu.js; Austin 2026-11-03: a menu is not an act): a right-click on
 * the world opens what a left click would open, under the left click's guards, and on a one-click
 * thing (the mailbox, a scene signpost's arm) its full menu; on an ordinary signpost's arm, the
 * post's arms. It never walks, never runs a verb and never cancels the one running.
 */
function worldRightClick(e) {
  const blocked = !state.started ? 'not-started'
    : menuTarget ? 'menu-open'
      : isMapOpen() ? 'map'
        : isScreenFxBlocking() ? 'screen'
          : app?.canvas?.dataset.cameraMode === '1' ? 'camera'
            : features.query('homeEditMode', engine) ? 'decorating'
              : Date.now() < worldMenuEchoUntil ? 'echo'
                // The press that closed a menu does nothing else (R6), as a left click's does.
                : lastPressAt >= 0 && (verbMenuClosedByPointerAt === lastPressAt || worldCtxMenu?.closedByPressAt() === lastPressAt) ? 'closed-a-menu'
                  : '';
  if (!blocked && !e.clientX && !e.clientY) {
    // The keys' own contextmenu with no keydown before it: Enter's menu (the nearest thing's).
    setCanvasData('worldRightClick', 'keys');
    tryOpenNearestMenu();
    return;
  }
  let signBoard = null;
  let best = null;
  if (!blocked) {
    const bounds = app.canvas.getBoundingClientRect();
    const sx = (e.clientX - bounds.left) * (VIEW_W / bounds.width) + camTarget;
    const sy = (e.clientY - bounds.top) * (VIEW_H / bounds.height) + (camY || 0);
    signBoard = signpostBoardAt(signViewsHere(), sx, sy);
    best = signBoard ? null : pickInteractableAt(sx, sy);
  }
  const outOfReach = Boolean(best && behindFloorFromPlayer(best) && !walkOverReaches(best));
  const action = worldContextAction({ blocked, board: signBoard?.board || null, thing: best, outOfReach });
  setCanvasData('worldRightClick', action.why ? `${action.kind}:${action.why}` : action.kind);
  if (action.kind === 'arms') {
    openSignpostArmsMenu(signBoard, { x: e.clientX, y: e.clientY });
    return;
  }
  if (action.kind === 'scene-arm') {
    // A scene post's arm runs its verb on a left click (takeSceneArm): here, that target's full menu.
    const target = signBoard.board.target || interactables.find((t) => t?.sprite === signBoard.view) || null;
    clearSignpostBoardHover();
    if (target) openWorldMenuFor(target);
    return;
  }
  if (action.kind === 'out-of-reach') {
    if (app?.canvas) app.canvas.dataset.reachBlocked = best.classId || '';
    toast(OUT_OF_REACH_LINE);
    return;
  }
  if (action.kind === 'menu') {
    setHoverTarget(best);
    // The mailbox too: its full menu, where a left click checks the mail at once.
    openWorldMenuFor(best);
  }
}

/** The verb menu on a thing, opened by a right-click (QA: canvas data contextMenu "world:<class>"). */
function openWorldMenuFor(target) {
  openVerbMenu(target);
  if (menuTarget === target) setCanvasData('contextMenu', `world:${target.classId || target.kind || ''}`);
}

/** RIGHTCLICK: a signpost's arms as a menu at the pointer, the arm clicked focused; a pick takes that road. */
function openSignpostArmsMenu(hit, at) {
  const view = hit?.view;
  if (!view) return false;
  const avail = availableStreetTsids();
  const rows = signpostArmRows((view.signBoards || []).map((board) => ({ board })), {
    inGame: (board) => Boolean(pickConnection({ connects: [board.connection] }, avail)),
    label: signBoardLabel,
    notInGame: ROAD_NOT_IN_GAME,
  });
  const clicked = rows.findIndex((r) => r.board === hit.board);
  clearSignpostBoardHover();
  return worldContextMenu().open({
    title: 'Signpost',
    rows,
    at,
    owner: `signpost:${signBoardLabel(hit.board) || ''}`,
    focusIndex: clicked < 0 ? null : clicked,
    onPick: (id) => {
      const row = rows.find((r) => r.id === id);
      if (row) takeSignBoard({ view, board: row.board });
    },
  });
}

/**
 * RIGHTCLICK (audit later batch item 1, js/ui/player-menu.js): another player's menu "from a list"
 * (a chat name, a buddy row, a Chats row, a minimap dot), as Glitch's startPcMenuFromList
 * (InteractionMenuController.as 664-693). On your street it is their whole world menu; anywhere
 * else the rows that work at a distance. Your own name opens nothing. `before` and `after`: a
 * surface's own rows around it ({ id, label, tip, run }); `omit`: verb ids it already has.
 * Returns whether it opened.
 */
let playerCtxMenu = null;
function playerContextMenu() {
  // fixed: it opens from the chat column too, which Classic draws beside #game-root (outside its clip).
  if (!playerCtxMenu) playerCtxMenu = createContextMenu({ doc: document, host: document.getElementById('game-root'), id: 'player-ctx-menu', className: 'player-ctx-menu', rowData: 'playerRow', fixed: true, setData: setCanvasData });
  return playerCtxMenu;
}

/** Another player's Glitch on this street (the party feature's target), or null. */
function streetPlayerTarget(id) {
  const pid = Number(id) || 0;
  return interactables.find((t) => t?.classId === 'pc_remote' && Number(t.playerId) === pid && t.sprite && !t.sprite.destroyed) || null;
}

function selfPlayerId() {
  return Number(features.query('realtimeClient', engine)?.me?.id) || 0;
}

/** The name the open player menu was made with (refreshPlayerMenus draws its rows again from it). */
let playerListMenuName = '';

function openPlayerListMenu({ id, name = '', at = null, anchor = null, keys = false, opener = null, findOpener = null, before = [], after = [], omit = [], layer = '' } = {}) {
  if (GAME_MODE !== 'multiplayer' || !opensPlayerMenu(id, selfPlayerId())) return false;
  const pid = Number(id);
  const here = streetPlayerTarget(pid);
  const target = here || listPlayerTarget({ id: pid, name });
  playerListMenuName = target.label;
  const rows = [...before, ...playerMenuRows(menuVerbsFor(target) || [], { here: Boolean(here), omit }), ...after];
  return playerContextMenu().open({
    title: here?.label || target.label,
    rows,
    at,
    anchor,
    keys,
    opener,
    findOpener,
    layer,
    owner: `player:${pid}`,
    data: { playerMenu: here ? 'here' : 'list' },
    onPick: (rowId, { row }) => {
      if (typeof row?.run === 'function') {
        row.run();
        return;
      }
      // As they are now: they may have left the street (or come) while it was open.
      const now = streetPlayerTarget(pid) || listPlayerTarget({ id: pid, name: target.label });
      const verb = (menuVerbsFor(now) || []).find((v) => v.id === rowId);
      if (!verb || verb.enabled === false) return;
      setCanvasData('playerMenuPick', `${pid}:${rowId}`);
      // No Glitch to walk to (or a verb running): the row's own action, as the instant ones are.
      if (!now.sprite || (currentAction && !(Number(verb.durationMs) > 0))) executeVerb(now, verb.id);
      else requestVerb(now, verb);
    },
  });
}

/**
 * A player's menu open now, drawn again from their verbs as they are now (a row's state changed:
 * features/profiles-feature.js once a page lookup answers): the menu from a list updates its rows
 * in place, the world's verb menu on their Glitch (at its verbs, not a picker) is drawn again with
 * the focus where it was. Returns whether a menu was open for them.
 */
function refreshPlayerMenus(id) {
  const pid = Number(id) || 0;
  if (!pid) return false;
  let open = false;
  if (playerCtxMenu?.isOpenFor(`player:${pid}`)) {
    open = true;
    const here = streetPlayerTarget(pid);
    const target = here || listPlayerTarget({ id: pid, name: playerListMenuName });
    playerCtxMenu.update(playerMenuRows(menuVerbsFor(target) || [], { here: Boolean(here) }));
  }
  const menu = document.getElementById('verb-menu');
  if (menuTarget?.classId === 'pc_remote' && Number(menuTarget.playerId) === pid && menu && !menu.hidden && !menu.dataset.vmLevel) {
    open = true;
    const rows = [...menu.querySelectorAll('.vm-row')];
    const at = rows.indexOf(document.activeElement);
    renderVerbMenu(menuTarget, menuVerbsFor(menuTarget));
    if (at >= 0) focusVerbRow(menu, at);
  }
  return open;
}

/**
 * RIGHTCLICK (audit later batch item 6): a signpost on the minimap (features/street-minimap-feature.js):
 * Walk here (what a click on it does), then the post's arms, each taking its road as a click on
 * that arm in the world does (takeSignBoard). `id`, `x`, `y`: the mark (js/ui/street-minimap.js
 * signpostMarks / sceneSignMarks, street px). QA: contextMenu minimap-sign:<id>.
 */
function minimapSignViews(id, x, y) {
  const key = String(id || '');
  if (key.startsWith('scene:')) {
    return sceneSignViews().filter((v) => Math.abs(Math.round(v.x) - x) <= 8 && Math.abs(Math.round(v.y) - y) <= 8);
  }
  const l = Number(currentStreet?.bounds?.l) || 0;
  const t = Number(currentStreet?.bounds?.t) || 0;
  const views = portalSprites || [];
  const byId = views.filter((v) => v?.signpost && String(v.signpost.id || '') === key);
  if (byId.length) return byId;
  return views.filter((v) => v?.signpost && Math.abs(Number(v.signpost.x) - l - x) < 2 && Math.abs(Number(v.signpost.y) - t - y) < 2);
}

function openMinimapSignpostMenu({ id, x, y, at = null, anchor = null, keys = false, opener = null, findOpener = null, walk = null } = {}) {
  const views = minimapSignViews(id, Number(x) || 0, Number(y) || 0);
  const boards = views.flatMap((view) => (view.signBoards || []).map((board) => ({ board, view })));
  const avail = availableStreetTsids();
  const arms = signpostArmRows(boards, {
    inGame: (board) => board.scene || Boolean(pickConnection({ connects: [board.connection] }, avail)),
    label: signBoardLabel,
    notInGame: ROAD_NOT_IN_GAME,
  }).map((r) => ({ ...r, id: `arm${r.id}`, view: boards.find((b) => b.board === r.board)?.view }));
  const rows = [{ id: 'walk', label: 'Walk here', tip: 'Walk to this signpost.' }, ...arms];
  return worldContextMenu().open({
    title: 'Signpost',
    rows,
    at,
    anchor,
    keys,
    opener,
    findOpener,
    owner: `minimap-sign:${id}`,
    onPick: (rowId, { row }) => {
      if (rowId === 'walk') walk?.();
      else if (row?.view && row.board) takeSignBoard({ view: row.view, board: row.board });
    },
  });
}

/**
 * A signpost arm whose street is not in the game's street set (61 arms, e.g. "The Next Step"). The
 * Map cannot reach it either; the old toast said the road was not loaded yet, which read as if it
 * would load later (ticket 37 follow-up).
 */
const ROAD_NOT_IN_GAME = "That road leads somewhere that isn't in the game. Pick another destination on the Map.";

function signpostArmKey(key) {
  const hit = signpostArmFor(key);
  if (!hit) return false;
  if (app?.canvas) app.canvas.dataset.signpostArmKey = `${key}:${signBoardLabel(hit.board) || hit.board.connection?.label || ''}`;
  return takeSignBoard(hit);
}

/** Take one arm of the post at hand ({ view, board }): its road, or a scene arm's verb. */
function takeSignBoard(hit) {
  const { board } = hit;
  releaseSignpostFocus();
  if (board.scene) {
    takeSceneArm(hit);
    return true;
  }
  if (signpostTravelRefused()) return true;
  const conn = pickConnection({ connects: [board.connection] }, availableStreetTsids());
  if (!conn) {
    toast(ROAD_NOT_IN_GAME);
    return true;
  }
  travelTo(conn.tsid, { label: conn.label, arrive: conn.arrive, via: 'signpost' });
  return true;
}

/*
 * SIGNFOCUS (Austin 2026-11-02, ticket 21): Enter or E at a post works as the client's: one arm
 * goes at once; several arms make the post take hold with the top arm lit, Up/Down or W/S move
 * between arms (wrapping round), Enter goes, Escape, Left/Right or A/D let go, and the avatar
 * stands still meanwhile (SignpostView.as tryFocus 382-416, focus 447-462, go 581-584,
 * escapeHandler 586-588, downHandler 590-599, upHandler 601-610; stops_avatar_on_focus).
 * The number keys stay (Austin 2026-11-01); T no longer travels (the client had no T at a post).
 */
/** @type {{ boards: { view: any, board: any }[], index: number } | null} */
let signpostFocus = null;

/** The post's arms top first (their numbers), as Enter steps through them. */
function signpostBoardsInOrder(at) {
  return [...(at?.boards || [])].sort((a, b) => (Number(a.board.key) || 99) - (Number(b.board.key) || 99) || (a.board.index || 0) - (b.board.index || 0));
}

function lightFocusedBoard() {
  const entry = signpostFocus?.boards[signpostFocus.index];
  if (!entry) return;
  setSignpostBoardHover({ view: entry.view, board: entry.board, index: entry.board.index, connection: entry.board.connection });
  setCanvasData('signpostFocus', `${signpostFocus.index + 1}/${signpostFocus.boards.length}:${signBoardLabel(entry.board) || entry.board.connection?.label || ''}`);
}

function releaseSignpostFocus() {
  if (!signpostFocus) return;
  signpostFocus = null;
  clearSignpostBoardHover();
  setCanvasData('signpostFocus', '');
}

/** Enter (or E, or the chooser's signpost tile) at a post. */
function enterSignpost() {
  const at = signpostAtHand();
  const boards = signpostBoardsInOrder(at);
  // No drawn arms (a post whose roads are all hidden or unloaded): the old travel and its refusals.
  if (!boards.length) {
    doTeleport();
    return;
  }
  if (boards.length === 1) {
    takeSignBoard(boards[0]);
    return;
  }
  signpostFocus = { boards, index: 0 };
  // The avatar stands still while the post has hold of it.
  for (const k of ['ArrowLeft', 'ArrowRight', 'a', 'A', 'd', 'D']) keys.delete(k);
  if (player) player.vx = 0;
  lightFocusedBoard();
}

/**
 * A key while a post is held: true when the post took it. A move key (Left/Right, A/D) lets go
 * and then walks; a number key lets go and takes its arm.
 */
function signpostFocusKey(e) {
  if (!signpostFocus) return false;
  const at = signpostAtHand();
  if (!at || !signpostFocus.boards.every((entry) => at.boards.some(({ board }) => board === entry.board))) {
    releaseSignpostFocus();
    return false;
  }
  const n = signpostFocus.boards.length;
  if (['ArrowUp', 'w', 'W', 'ArrowDown', 's', 'S'].includes(e.key)) {
    e.preventDefault();
    const step = ['ArrowUp', 'w', 'W'].includes(e.key) ? -1 : 1;
    signpostFocus.index = (signpostFocus.index + step + n) % n;
    lightFocusedBoard();
    return true;
  }
  if (e.key === 'Enter' || e.key === 'e' || e.key === 'E') {
    e.preventDefault();
    if (!e.repeat) takeSignBoard(signpostFocus.boards[signpostFocus.index]);
    return true;
  }
  if (e.key === ' ') {
    e.preventDefault();
    return true;
  }
  if (e.key === 'Escape') {
    e.preventDefault();
    releaseSignpostFocus();
    return true;
  }
  if (['ArrowLeft', 'ArrowRight', 'a', 'A', 'd', 'D'].includes(e.key) || /^[1-9]$/.test(e.key)) releaseSignpostFocus();
  return false;
}

function doTeleport() {
  if (signpostTravelRefused()) return;
  if (!currentStreet) return;
  // Player report 33: only a post the avatar's hit box reaches up and down (street-model.js signpostReachY).
  const plan = planSignpostTravel(
    walkUpSignpostStreet(currentStreet),
    player.x,
    availableStreetTsids(),
    140,
    (s) => signpostReachY(currentStreet, s, player.y),
  );
  if (!plan.ok) {
    if (plan.reason === 'no_signpost') {
      toast('No signpost nearby. Open the Map (G) to teleport, or walk closer to a wooden post.');
    } else if (plan.reason === 'not_loaded') {
      const labels = (plan.labels || []).join(', ');
      toast(labels
        ? `Signpost lists: ${labels}. Open Map (G) for loaded streets.`
        : 'Signpost has no loaded destinations. Open Map (G).');
    }
    return;
  }
  travelTo(plan.toTsid, { label: plan.label, arrive: plan.arrive, via: 'signpost' });
}

function renderIlmenskieMapCallout(panel) {
  panel?.querySelector('.map-quest-teleport')?.remove();
  if (!panel || !questState.active?.[ILMENSKIE_QUEST_ID]) return;
  const rescue = ilmenskieStory();
  const box = document.createElement('section');
  box.className = 'map-quest-teleport';
  const inCavern = currentStreetTsid === AXIS_DENYDE_STREET_ID;
  const title = document.createElement('strong');
  title.textContent = inCavern ? 'Axis Denyde · Sealed Cavern' : 'Quest teleport · Axis Denyde';
  const copy = document.createElement('span');
  copy.textContent = ilmenskieObjective(rescue, currentStreetTsid);
  box.append(title, copy);
  if (!rescue.releasedJones && (!rescue.pickedUpJones || inCavern)) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'content-action-btn';
    if (inCavern && rescue.pickedUpJones) {
      button.textContent = 'Teleport out with Jones';
      button.addEventListener('click', teleportFromAxisDenyde);
    } else if (inCavern) {
      button.textContent = 'Find Jones before leaving';
      button.disabled = true;
    } else {
      button.textContent = 'Teleport to Axis Denyde';
      button.addEventListener('click', teleportToAxisDenyde);
    }
    box.appendChild(button);
  }
  const card = panel.querySelector('.map-card');
  const mapCanvas = panel.querySelector('.map-canvas');
  if (card && mapCanvas) card.insertBefore(box, mapCanvas);
  else card?.appendChild(box);
}

function renderHomeMapCallout(panel) {
  panel?.querySelector('.map-home-card')?.remove();
  if (!panel) return;
  const box = document.createElement('section');
  box.className = 'map-home-card';
  const copy = document.createElement('div');
  const title = document.createElement('strong');
  const detail = document.createElement('span');
  const unread = unreadMailCount(mailboxState, Date.now());
  if (homeState.owned) {
    const style = HOME_STYLES[homeState.style] || HOME_STYLES.meadow;
    title.textContent = `Your ${style.label} home`;
    detail.textContent = unread
      ? `${unread} unread mail · remembers where to return`
      : 'Your mailbox is quiet · remembers where to return';
  } else {
    title.textContent = 'A place of your own';
    detail.textContent = 'Free, with a Home Street Ticket from your Magic Rock';
  }
  copy.append(title, detail);
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'content-action-btn';
  button.textContent = homeState.owned ? 'Teleport home' : 'Get your home street';
  button.addEventListener('click', () => {
    closeMap();
    if (homeState.owned) teleportHome();
    else openHomePanel();
  });
  box.append(copy, button);
  const card = panel.querySelector('.map-card');
  const mapCanvas = panel.querySelector('.map-canvas');
  if (card && mapCanvas) card.insertBefore(box, mapCanvas);
  else card?.appendChild(box);
}

/**
 * @param {string} [hubId]  Open a specific hub map; default = player's hub
 */
async function openMap(hubId, { find = '', focus = '' } = {}) {
  // On the subway train: the line you are riding (features/subway-feature.js openMapOverride).
  if (!hubId && !find && features.query('openMapOverride', engine) === true) return;
  if (homeIsInstanced()) {
    openHomePanel();
    return;
  }
  if (greedyStreetIsInstanced()) {
    toast('Storyland is read, not mapped.');
    return;
  }
  if (summersDayIsInstanced()) {
    toast('A Summer’s Day is remembered, not mapped.');
    return;
  }
  if (deEmbiggenifyIsInstanced()) {
    toast('The map is much too large while you are this small.');
    return;
  }
  if (rookWoodsIsInstanced()) {
    toast("The Rooks' Woods are not drawn on any map.");
    return;
  }
  if (winterWalkIsInstanced()) {
    toast('The winter path is not drawn on any map.');
    return;
  }
  if (fourLetterIsInstanced()) {
    toast('The map is much too large while you are this small.');
    return;
  }
  if (isShrineOpen()) closeShrinePanel();
  const panel = document.getElementById('map-panel');
  const canvas = document.getElementById('map-canvas');
  const title = document.getElementById('map-hub-title');
  const sub = panel?.querySelector('.map-sub');
  const hubSelect = document.getElementById('map-hub-select');
  if (!panel || !canvas) return;
  closeVendor();
  closeQuestPanel();

  // A hub chosen on the open map holds until it closes or the player moves streets.
  if (!isMapOpen() || mapPanelStreetTsid !== currentStreetTsid) mapPanelHubId = null;
  let spot = { hubId: '56', tsid: currentStreetTsid };
  try {
    spot = await playerMapSpot(await ensureMapIndex());
  } catch (err) {
    console.error(err);
  }
  const targetHub = String(hubId || mapPanelHubId || spot.hubId);
  mapPanelHubId = hubId ? targetHub : mapPanelHubId;
  mapPanelStreetTsid = currentStreetTsid;

  let hubData;
  let mapIndex = null;
  try {
    mapIndex = await ensureMapIndex();
    hubData = await loadHubMapData(targetHub);
  } catch (err) {
    console.error(err);
    toast('Could not load hub map data.');
    return;
  }

  // Populate hub dropdown (once per open with fresh index)
  if (hubSelect && mapIndex) {
    const hubs = listHubsFromIndex(mapIndex, { keep: targetHub });
    const prev = hubSelect.value;
    hubSelect.innerHTML = '';
    for (const h of hubs) {
      const opt = document.createElement('option');
      opt.value = h.hubId;
      opt.textContent = `${h.hubName} (${h.streetCount})`;
      if (h.hubId === targetHub) opt.selected = true;
      hubSelect.appendChild(opt);
    }
    // The streets too, listed only when you type (the client's LocationSearchMap: regions and streets;
    // none on Gentle Island, HubMapDialog.as 1004-1006).
    const onIsland = targetHub === '129';
    for (const st of onIsland ? [] : mapSearchStreets(STREET_INDEX.streets, hubs)) {
      const opt = document.createElement('option');
      opt.value = st.value;
      opt.textContent = st.label;
      opt.dataset.hint = st.hint;
      opt.dataset.searchOnly = '1';
      hubSelect.appendChild(opt);
    }
    if (!hubSelect.dataset.bound) {
      hubSelect.dataset.bound = '1';
      hubSelect.addEventListener('change', () => {
        const street = parseMapSearchValue(hubSelect.value);
        if (street) openMap(street.hubId, { find: street.tsid });
        else openMap(hubSelect.value);
      });
    } else if (prev && prev !== targetHub) {
      hubSelect.value = targetHub;
    }
    // Themed type-to-search picker in front of the (hidden) select.
    // Ticket 21: the box shows the region on show, with a magnifier; a click empties it for a search
    // (the client's LocationSearchMap: its magnifier and "Search" text, HubMapDialog.as 197-202).
    hubCombobox ||= createCombobox(hubSelect, { placeholder: 'Search a region or street', label: 'Regions and streets', search: true });
    hubCombobox.refresh();
  }

  // "You" on the hub map: the current street, or the street that stands for it (spot.tsid).
  const view = buildHubMapView(hubData, spot.hubId === targetHub ? spot.tsid : currentStreetTsid, STREET_INDEX.streets);
  // Ticket 66: streets still under construction show it before you try to go (map-graph.js `building`).
  let building = 0;
  for (const st of view.streets || []) {
    if (!st.loaded || st.current) continue;
    st.building = Boolean(features.query('streetUnderConstruction', st.loadedTsid || st.tsid, engine));
    if (st.building) building += 1;
  }
  if (app?.canvas) {
    app.canvas.dataset.mapHub = targetHub;
    app.canvas.dataset.mapYou = view.streets?.find((st) => st.current)?.tsid || '';
    app.canvas.dataset.mapBuilding = String(building);
  }
  if (title) title.textContent = view.hubName;
  if (sub) {
    // The painted-or-geometry note is for QA only (js/panel-copy.js), not the player's subtitle.
    sub.textContent = hubMapSubtitle(view);
    sub.dataset.mapArt = hubMapArtNote(view);
    // Modern folds it onto the one quiet line under the map, where a narrow window cuts it short.
    sub.title = sub.textContent;
  }

  canvas.innerHTML = renderHubMapSvg(view);
  // The street icons' tips on hover and keyboard focus (vendor, shrine, subway; MapHub.as).
  bindMapIconTips(canvas);
  // Ticket 21: the canvas keeps the drawn frame's shape (style.css .map-canvas aspect-ratio).
  const frame = canvas.querySelector('svg')?.getAttribute('viewBox')?.split(' ').map(Number) || [];
  if (frame[2] > 0 && frame[3] > 0) canvas.style.setProperty('--map-aspect', `${frame[2]} / ${frame[3]}`);
  // MAPZOOM: zoom and pan (js/map-zoom.js); a redraw of the region on show keeps the view, another region opens at fit.
  mapZoomFor(canvas).attach(canvas.querySelector('svg'), targetHub);

  canvas.querySelectorAll('.map-street.travelable').forEach((g) => {
    g.addEventListener('click', (e) => {
      const tsid = g.getAttribute('data-tsid');
      const label = g.getAttribute('data-label') || tsid;
      const plan = mapClickTravel(currentStreetTsid, tsid, STREET_INDEX.streets);
      if (!plan.ok) {
        if (plan.reason === 'already_here') toast('You are already here.');
        else if (plan.reason === 'not_loaded') toast(`${label} is not loaded in this demo.`);
        else toast('Cannot travel there.');
        return;
      }
      // QA routes that hop by Map keep the old free travel (&maptravel=free).
      if (new URLSearchParams(location.search).get('maptravel') === 'free') {
        closeMap();
        travelTo(plan.toTsid, { label: plan.label || label });
        return;
      }
      openMapStreetMenu(canvas, e, { tsid: plan.toTsid, label: plan.label || label, hubId: targetHub, hubName: view.hubName });
    });
    // RIGHTCLICK: a right-click opens the same menu (the world never sees it: the Map is over it).
    g.addEventListener('contextmenu', (e) => {
      e.preventDefault();
      const tsid = g.getAttribute('data-tsid');
      const label = g.getAttribute('data-label') || tsid;
      const plan = mapClickTravel(currentStreetTsid, tsid, STREET_INDEX.streets);
      if (!plan.ok) {
        if (plan.reason === 'already_here') openMapStreetMenu(canvas, e, { tsid, label, hubId: targetHub, hubName: view.hubName }, { here: true });
        return;
      }
      openMapStreetMenu(canvas, e, { tsid: plan.toTsid, label: plan.label || label, hubId: targetHub, hubName: view.hubName });
    });
  });

  canvas.querySelectorAll('.map-street.current').forEach((g) => {
    g.addEventListener('click', () => toast(MAP_ALREADY_HERE));
    // RIGHTCLICK: your own street's menu, both rows greyed with why.
    g.addEventListener('contextmenu', (e) => {
      e.preventDefault();
      const tsid = g.getAttribute('data-tsid');
      openMapStreetMenu(canvas, e, { tsid, label: g.getAttribute('data-label') || tsid, hubId: targetHub, hubName: view.hubName }, { here: true });
    });
  });

  canvas.querySelectorAll('.map-hub-go').forEach((g) => {
    g.addEventListener('click', () => {
      const nextHub = g.getAttribute('data-hub');
      const label = g.getAttribute('data-label') || 'that hub';
      if (nextHub && mapIndex?.hubs?.[nextHub]?.streetCount > 0) {
        openMap(nextHub);
        toast(`Viewing ${label.replace(/^To:\s*/i, '')} map (explore only).`);
      } else {
        toast(`${label}: no map data for that hub.`);
      }
    });
  });

  canvas.querySelectorAll('line.map-seg.dim').forEach((line) => {
    line.style.cursor = 'default';
    line.addEventListener('click', () => {
      const name = line.getAttribute('data-name') || 'Street';
      toast(`${name}: map only (street not loaded in this demo).`);
    });
  });

  renderIlmenskieMapCallout(panel);
  renderHomeMapCallout(panel);
  panel.querySelectorAll('.map-feature-card').forEach((el) => el.remove());
  for (const el of features.collect('mapCards', engine)) {
    el.classList.add('map-feature-card');
    panel.querySelector('.map-card')?.insertBefore(el, panel.querySelector('.map-canvas'));
  }
  arrangeMapCards(panel);
  panel.hidden = false;
  fitMapCanvas(panel);
  if (find) showFoundStreet(canvas, find, view);
  else if (focus) focusMapOn(canvas, focus);
}

/**
 * MAPZOOM (ticket 76, Austin 2026-11-04; G521): the Map's zoom and pan, one for the Map's canvas
 * (js/map-zoom.js). QA: canvas data mapZoom "<zoom>@<cx>,<cy>" (map units).
 */
let mapZoom = null;
function mapZoomFor(canvas) {
  mapZoom ||= createMapZoom(canvas, {
    onChange: (v) => setCanvasData('mapZoom', `${v.zoom.toFixed(2)}@${Math.round(v.cx)},${Math.round(v.cy)}`),
  });
  return mapZoom;
}

/** Where a street sits on the Map now drawn (its line's middle), or the route's pin for a room behind a door. */
function mapSpotOf(canvas, tsid) {
  const g = [...canvas.querySelectorAll('.map-street')].find((n) => n.getAttribute('data-tsid') === tsid);
  const line = g?.querySelector('line.map-seg');
  if (line) {
    const n = (k) => Number(line.getAttribute(k)) || 0;
    return { x: (n('x1') + n('x2')) / 2, y: (n('y1') + n('y2')) / 2 };
  }
  const pin = canvas.querySelector('.map-route-pin');
  if (pin?.getBBox) {
    const b = pin.getBBox();
    return { x: b.x + b.width / 2, y: b.y + b.height };
  }
  return null;
}

/** MAPZOOM: the Map centred on a street (a search pick, Show destination), zoomed in to it. */
function focusMapOn(canvas, tsid) {
  const at = mapSpotOf(canvas, tsid);
  if (at) mapZoomFor(canvas).focus(at.x, at.y);
  return Boolean(at);
}

/**
 * MAPSIZE (ticket 76, Austin 2026-11-04): the Map takes the room the window leaves. The map panel's
 * box (style.css / classic.css: under the top bar, over the pack, inside --inset-l / --inset-r)
 * less the window's own head and lines gives the map's size (map-graph.js mapFitSize): its frame's
 * shape, the client's 760 x 460 at least when there is room (the key hint folds away first), up to
 * 1.5 times it. MAPFRAME (Austin 2026-11-04): the card takes the map's own width (the canvas is the
 * painting's shape exactly, never a wider box with bands beside the art). Measured again on a window
 * resize and whenever the panel or the card changes size
 * (the Social drawer, a side sheet, a route card). A 1x screen takes the Retina painting once the
 * map draws larger than 760 x 460. QA: canvas data mapFit "<w>x<h>@<scale>" plus " compact".
 */
let mapFitObserver = null;
let mapFitBusy = false;
function fitMapCanvas(panel = document.getElementById('map-panel')) {
  const card = panel?.querySelector('.map-card');
  const canvas = panel?.querySelector('.map-canvas');
  if (!card || !canvas || panel.hidden || mapFitBusy) return null;
  // MAPZOOM: the frame the region was drawn in (a zoomed map's viewBox is only part of it).
  const svgEl = canvas.querySelector('svg');
  const [, , frameW, frameH] = (svgEl?.dataset.frame || svgEl?.getAttribute('viewBox') || '').split(' ').map(Number);
  if (!(frameW > 0 && frameH > 0)) return null;
  mapFitBusy = true;
  let fit = null;
  try {
    const ps = getComputedStyle(panel);
    const px = (v) => parseFloat(v) || 0;
    const availW = panel.clientWidth - px(ps.paddingLeft) - px(ps.paddingRight);
    const availH = panel.clientHeight - px(ps.paddingTop) - px(ps.paddingBottom);
    const minH = px(getComputedStyle(canvas).minHeight);
    // The window's head and lines at the width it will have: measured with the map at its smallest
    // (no height, or the skin's floor), so nothing above it gives way; first across the whole room, then
    // again at the map's own width (MAPFRAME: the card hugs the map, so no plain bands beside it), which
    // can wrap a line, until it holds.
    let trialW = availW;
    for (let pass = 0; pass < 5; pass++) {
      card.style.setProperty('--map-card-w', `${Math.floor(trialW)}px`);
      card.dataset.mapFit = 'measure';
      card.dataset.mapCompact = '0';
      const chromeW = card.offsetWidth - canvas.offsetWidth;
      const chromeH = card.offsetHeight - canvas.offsetHeight;
      card.dataset.mapCompact = '1';
      const compactChromeH = card.offsetHeight - canvas.offsetHeight;
      const next = mapFitSize({ availW, availH, chromeW, chromeH, compactChromeH, frameW, frameH, minH });
      if (!next) break;
      fit = next;
      const cardW = fit.w + chromeW;
      card.style.setProperty('--map-card-w', `${cardW}px`);
      card.style.setProperty('--map-fit-w', `${fit.w}px`);
      card.style.setProperty('--map-fit-h', `${fit.h}px`);
      card.dataset.mapCompact = fit.compact ? '1' : '0';
      card.dataset.mapFit = 'on';
      if (Math.abs(cardW - trialW) < 1) break;
      trialW = cardW;
    }
    if (!fit) {
      delete card.dataset.mapFit;
      delete card.dataset.mapCompact;
      return null;
    }
    const soft = canvas.querySelector('image.map-bg-soft[data-hi]');
    if (soft && fit.scale * (Number(globalThis.devicePixelRatio) || 1) > 1.01) soft.setAttribute('href', soft.dataset.hi);
    setCanvasData('mapFit', `${fit.w}x${fit.h}@${fit.scale.toFixed(2)}${fit.compact ? ' compact' : ''}`);
  } finally {
    mapFitBusy = false;
  }
  // MAPZOOM: the zoom buttons take the corner that covers the least of this region.
  mapZoom?.placeControls();
  fitMapExtras(card);
  if (!mapFitObserver) {
    let queued = false;
    const again = () => {
      if (queued) return;
      queued = true;
      requestAnimationFrame(() => {
        queued = false;
        if (isMapOpen()) fitMapCanvas(panel);
      });
    };
    globalThis.addEventListener?.('resize', again);
    if (typeof ResizeObserver === 'function') {
      mapFitObserver = new ResizeObserver(again);
      mapFitObserver.observe(panel);
      mapFitObserver.observe(card);
    } else mapFitObserver = true;
  }
  return fit;
}

/** A street found with the Map's search: its line flashes (MapHub.as 785-828 alert()), or a note when the map does not draw it. */
function showFoundStreet(canvas, tsid, view) {
  const g = [...canvas.querySelectorAll('.map-street')].find((n) => n.getAttribute('data-tsid') === tsid);
  const label = STREET_INDEX.streets[tsid]?.label || tsid;
  if (app?.canvas) app.canvas.dataset.mapFound = g ? tsid : '';
  if (!g) {
    toast(`${label} is not drawn on the ${view.hubName} map.`);
    return;
  }
  g.classList.remove('is-found');
  void g.getBoundingClientRect();
  g.classList.add('is-found');
  // MAPZOOM: the Map zooms in to it and centres it.
  focusMapOn(canvas, tsid);
  toast(`${label}, ${view.hubName}`, 2600);
  setTimeout(() => g.classList.remove('is-found'), 4200);
}

/**
 * A street's menu on the Map (glitch-client InteractionMenuController.as 130-275):
 * Set as Destination (a guided path, the map-routes feature) and Teleport Here, which
 * the teleportation feature allows only with Teleportation IV, to a visited street,
 * with the energy and off cooldown (teleportation_map_teleport). The original never
 * moved you just for clicking a street.
 *
 * RIGHTCLICK (right-click audit later batch item 4): it is the shared menu (js/ui/context-menu.js):
 * key caps, the footer line with what a row does or why it can't be done, both skins' art. A left
 * click and a right-click on a street open it at the pointer; on your own street (a right-click; a
 * left click there still only says so) both rows are greyed with "You are already here."
 * QA: canvas data contextMenu map:<tsid>, mapStreetMenu <tsid>:teleport|route|here.
 */
const MAP_ALREADY_HERE = 'You are already here.';
let mapCtxMenu = null;
function mapStreetContextMenu() {
  if (!mapCtxMenu) mapCtxMenu = createContextMenu({ doc: document, host: document.getElementById('game-root'), id: 'map-street-menu', className: 'map-ctx-menu', rowData: 'mapRow', setData: setCanvasData });
  return mapCtxMenu;
}

function openMapStreetMenu(canvas, event, street, { here = false } = {}) {
  // Ticket 37 follow-up: a street still being built is no destination and no teleport target
  // (GSJS location.js 2915-2935 not_a_destination; InteractionMenuController.as 151-153, 206-208).
  const building = here ? null : features.query('streetUnderConstruction', street.tsid, engine);
  const tp = here
    ? { ok: false, error: MAP_ALREADY_HERE }
    : features.query('mapTeleport', 'check', street, engine) || { ok: false, error: 'You cannot teleport from here.' };
  const rows = [
    {
      id: 'destination',
      label: 'Set as Destination',
      tip: 'Get a guided path to this location',
      disabled: here || Boolean(building),
      reason: here ? MAP_ALREADY_HERE : building ? building.note : '',
    },
    {
      id: 'teleport',
      label: tp.ok && tp.energyCost ? `Teleport Here · ${tp.energyCost} energy` : 'Teleport Here',
      tip: tp.ok ? tp.tooltip || '' : '',
      disabled: !tp.ok,
      reason: tp.ok ? '' : tp.error || '',
    },
  ];
  const opened = mapStreetContextMenu().open({
    title: street.label,
    rows,
    at: { x: event.clientX, y: event.clientY },
    owner: `map:${street.tsid}`,
    onPick: (id) => {
      if (id === 'teleport') {
        features.query('mapTeleport', 'go', street, engine);
        return;
      }
      if (id !== 'destination') return;
      const res = features.query('mapRoute', 'set', { to: street.tsid, source: 'player' }, engine);
      // Routes never go through a closed road (js/map-routes.js findRoute): say which street is in the way.
      const through = res && res.ok === false ? routeThroughConstruction(res.through) : null;
      if (through) toast(`No open road leads to ${street.label} yet: the way runs through ${through.label}, which is still under construction. ${through.note}`, 6000);
      else if (res && res.ok === false) toast(res.error || 'No path to there.', 2600);
      else {
        pushActivity(`Destination set: ${street.label}.`);
        openMap(street.hubId);
      }
    },
  });
  if (opened && app?.canvas) app.canvas.dataset.mapStreetMenu = `${street.tsid}:${here ? 'here' : tp.ok ? 'teleport' : 'route'}`;
  return opened;
}

/**
 * The first of the streets still under construction that stand in a route's way (planRoute's
 * `through`): routes never go through a closed road, so the Map says which one to build.
 */
function routeThroughConstruction(streets) {
  if (!Array.isArray(streets)) return null;
  for (const tsid of streets) {
    const hit = features.query('streetUnderConstruction', tsid, engine);
    if (hit) return hit;
  }
  return null;
}

function closeMap() {
  const panel = document.getElementById('map-panel');
  if (panel) panel.hidden = true;
  if (mapCtxMenu?.isOpen()) mapCtxMenu.close({ focus: false });
  mapPanelHubId = null;
  // MAPZOOM: the next open starts at fit (the zoom is kept only while the Map stays open).
  mapZoom?.reset();
}

function isMapOpen() {
  const panel = document.getElementById('map-panel');
  return panel && !panel.hidden;
}

/** Ticket 81: the Projects panel (features/street-jobs-feature.js projectsPanel, js/ui/projects-sheet.js). */
function isProjectsOpen() {
  return features.query('projectsPanel', 'isOpen', engine) === true;
}

function closeProjectsPanel() {
  features.query('projectsPanel', 'close', engine);
}

function closeContentPanels() {
  closeProjectsPanel();
  closeQuestPanel();
  closeAchievePanel();
  closeFeatPanel();
  closeSkillsPanel();
  closeBuffsPanel();
  closeVendor();
}

function openQuestPanel() {
  if (greedyStreetIsInstanced()) {
    toast('Finish the bedtime story before taking another quest.');
    return;
  }
  if (isShrineOpen()) closeShrinePanel();
  closeMap();
  closeAchievePanel();
  closeFeatPanel();
  closeSkillsPanel();
  closeBuffsPanel();
  closeVendor();
  const panel = document.getElementById('quest-panel');
  if (panel) {
    // G255: the log draws only while its panel is open, so show it first.
    panel.hidden = false;
    updateHud();
  }
}

/** quests.json teleportation_rescue_pig offerTriggers: the skill that brings Ilmenskie Jones's quest. */
const ILMENSKIE_SKILL_ID = 'teleportation_4';
/**
 * What brought the other story quests in Glitch (Austin 2026-11-11: gate them as the original did,
 * except the Museum of the Rook): Notice the Unnoticeable at 302 locations visited
 * (players/inc_quests.js quests_enter_location), Four Letter Words at level 7 (quests.json
 * letter_block_2 offerTriggers), and Legalize It at a subway gate that turns you away for want of
 * papers (subway_gate.js 158 quests_offer; questState.story.gates.legalize records it).
 */
const PHANTOM_OFFER_LOCATIONS = 302;
const FOUR_LETTER_OFFER_LEVEL = 7;

const STORY_QUEST_IDS = [
  LEGALIZE_QUEST_ID,
  ILMENSKIE_QUEST_ID,
  DE_EMBIGGENIFY_QUEST_ID,
  WINTER_WALK_QUEST_ID,
  WINTER_WALK_REPEAT_QUEST_ID,
  SUMMERS_DAY_QUEST_ID,
  SUMMERS_DAY_REPEAT_QUEST_ID,
  FOUR_LETTER_QUEST_ID,
  ROOK_QUEST_ID,
  ROOK_HALL_START_QUEST_ID,
  HOG_HAUL_QUEST_ID,
  PHANTOM_QUEST_ID,
  REMEMBER_QUEST_ID,
];

function canOfferStoryQuest(classTsid) {
  if (questState.active?.[classTsid]) return false;
  if (classTsid === GREEDY_STREET_SPIRIT_QUEST_ID) {
    return canOfferGreedyFirst(questState, pc).ok && !greedyStreetIsInstanced();
  }
  if (classTsid === GREEDY_STREET_SPIRIT_REPEAT_ID) {
    const demo = String(new URLSearchParams(location.search).get('questdemo') || '');
    return canOfferGreedyRepeat(questState, Date.now(), {
      bypassCooldown: demo.startsWith('greedy'),
    }).ok && !greedyStreetIsInstanced();
  }
  if (
    classTsid === SUMMERS_DAY_QUEST_ID ||
    classTsid === SUMMERS_DAY_REPEAT_QUEST_ID
  ) {
    const demo = String(new URLSearchParams(location.search).get('questdemo') || '');
    return canOfferSummersDay(questState, {
      repeat: classTsid === SUMMERS_DAY_REPEAT_QUEST_ID,
      bypassCooldown: demo.startsWith('summer'),
    }).ok && !summersDayIsInstanced();
  }
  if (classTsid === DE_EMBIGGENIFY_QUEST_ID) {
    return (
      !questState.completed.includes(DE_EMBIGGENIFY_QUEST_ID) &&
      !questState.completed.includes(DE_EMBIGGENIFY_PART2_QUEST_ID) &&
      !deEmbiggenifyIsInstanced()
    );
  }
  // G334: multiplayer logs the Hog Haul by its ticket's challenge (js/quests-mp.js), not the bot race.
  if (classTsid === HOG_HAUL_QUEST_ID) return isSolo() && !hogHaulIsInstanced();
  if (classTsid === ROOK_QUEST_ID) {
    return !questState.completed.includes(ROOK_QUEST_ID) && !rookWoodsIsInstanced();
  }
  if (classTsid === ROOK_HALL_START_QUEST_ID) {
    return (
      !questState.completed.includes(ROOK_HALL_START_QUEST_ID) &&
      !questState.completed.includes(ROOK_HALL_QUEST_ID) &&
      !rookMuseumIsInstanced()
    );
  }
  if (classTsid === WINTER_WALK_QUEST_ID || classTsid === WINTER_WALK_REPEAT_QUEST_ID) {
    // Live report 2026-10-30 #7: the source's prerequisites and hour waits (js/winter-walk.js canOfferWinterWalk).
    const demo = String(new URLSearchParams(location.search).get('questdemo') || '');
    return canOfferWinterWalk(questState, {
      repeat: classTsid === WINTER_WALK_REPEAT_QUEST_ID,
      level: pc.level,
      summersDayDoneAt: Math.max(ensureSummersDayStory(questState).firstCompletedAt, questDoneAt(questState, SUMMERS_DAY_QUEST_ID)),
      bypassCooldown: demo.startsWith('winter'),
    }).ok && !winterWalkIsInstanced();
  }
  if (questState.completed.includes(classTsid)) return false;
  if (classTsid === PHANTOM_QUEST_ID && groupLabelCount(achieveState, 'locations_visited') < PHANTOM_OFFER_LOCATIONS) return false;
  if (classTsid === FOUR_LETTER_QUEST_ID && (Number(pc.level) || 0) < FOUR_LETTER_OFFER_LEVEL) return false;
  if (classTsid === LEGALIZE_QUEST_ID && !questState.story?.gates?.legalize) return false;
  // Ticket 192: Teleportation IV's quest (inc_data_skills.js teleportation_4 quest_id; its offer
  // reads "using your newly acquired powers of Teleportation IV"), offered once that skill is learned.
  if (classTsid === ILMENSKIE_QUEST_ID) return (skillState.learned || []).includes(ILMENSKIE_SKILL_ID);
  if (classTsid === LEGALIZE_QUEST_ID) return !legalizeIsInstanced();
  if (classTsid === REMEMBER_QUEST_ID) {
    return questState.completed.includes(PHANTOM_QUEST_ID) && countItem(inv, FADED_HEART_ID) > 0;
  }
  return (
    classTsid === PHANTOM_QUEST_ID ||
    classTsid === LEGALIZE_QUEST_ID ||
    classTsid === DE_EMBIGGENIFY_QUEST_ID ||
    classTsid === FOUR_LETTER_QUEST_ID ||
    classTsid === ROOK_QUEST_ID ||
    classTsid === ROOK_HALL_START_QUEST_ID ||
    classTsid === ILMENSKIE_QUEST_ID
  );
}

function appendStoryQuestOffers(box) {
  for (const classTsid of STORY_QUEST_IDS) {
    // G562: the repeats are a Street Spirit's reminisce, never in the log (hide_questlog 1; street_spirit.js 218-240).
    if (SPIRIT_REPEAT_QUESTS.includes(classTsid)) continue;
    if (!canOfferStoryQuest(classTsid)) continue;
    const def = getQuestCatalog()[classTsid];
    if (!def) continue;
    const card = document.createElement('div');
    card.className = 'q-card story-offer';
    const title = document.createElement('div');
    title.className = 'q-title';
    title.textContent = def.title;
    const desc = document.createElement('div');
    desc.className = 'q-req';
    renderQuestText(desc, def.desc);
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'content-action-btn';
    button.textContent =
      classTsid === LEGALIZE_QUEST_ID
        ? 'Visit the Back Alley'
      : classTsid === ILMENSKIE_QUEST_ID
        ? 'Hear about the sealed cavern'
      : classTsid === DE_EMBIGGENIFY_QUEST_ID
        ? 'Enter the catalogue page'
      : classTsid === WINTER_WALK_QUEST_ID
        ? 'Feel the cool breeze'
      : classTsid === WINTER_WALK_REPEAT_QUEST_ID
        ? 'Walk again'
      : classTsid === SUMMERS_DAY_QUEST_ID
        ? 'Remember a summer’s day'
      : classTsid === SUMMERS_DAY_REPEAT_QUEST_ID
        ? 'Reminisce again'
      : classTsid === HOG_HAUL_QUEST_ID
        ? questState.completed.includes(HOG_HAUL_QUEST_ID)
          ? 'Race again'
          : 'Join the race'
        : classTsid === FOUR_LETTER_QUEST_ID
          ? 'Meet Mr. Block'
        : classTsid === ROOK_HALL_START_QUEST_ID
          ? 'Visit the Museum of the Rook'
        : classTsid === PHANTOM_QUEST_ID
          ? 'Hear the ghost story'
          : 'Remember again';
    button.addEventListener('click', () => openQuestDialogue(classTsid));
    card.append(title, desc, button);
    // ENCYC: a story quest's offer links to its page.
    appendQuestEncyclopediaLink(card, classTsid);
    box.appendChild(card);
  }
}

/** ENCYC: "In the Encyclopedia" on a quest card, when the quest has a page (js/encyclopedia-links.js). */
function appendQuestEncyclopediaLink(card, classTsid) {
  if (!card || !classTsid || card.querySelector(':scope > .ency-link')) return;
  const ency = encyclopedia.link(document, { section: 'quests', id: classTsid }, 'q-ency');
  if (ency) card.appendChild(ency);
}

function renderQuestDialogueBeat() {
  const modal = document.getElementById('quest-dialogue');
  if (!modal || !questDialogueState) return;
  const { def, beats, index, mode } = questDialogueState;
  const beat = beats[index] || {
    text: cleanQuestMarkup(def?.offer || ''),
    response: '',
  };
  const kicker = document.getElementById('quest-dialogue-kicker');
  const title = document.getElementById('quest-dialogue-title');
  const copy = document.getElementById('quest-dialogue-copy');
  const next = document.getElementById('quest-dialogue-next');
  const cancel = document.getElementById('quest-dialogue-cancel');
  if (kicker) {
    // kicker: null is a line with no speaker (G213: a location event's VOG overlay).
    kicker.hidden = questDialogueState.kicker === null;
    kicker.textContent = questDialogueState.kicker || (mode === 'script' ? 'Conversation' : 'New quest');
  }
  if (title) {
    // G228: title: null is a prompt with no heading (engine.prompt without a source title).
    title.hidden = !def && questDialogueState.title === null;
    title.textContent = def?.title || questDialogueState.title || 'Quest';
  }
  if (copy) renderQuestText(copy, beat.markup ?? beat.text);
  // #83: on the last page, a line when accepting moves you.
  let note = document.getElementById('quest-dialogue-note');
  if (!note && copy) {
    note = document.createElement('p');
    note.id = 'quest-dialogue-note';
    note.className = 'quest-dialogue-note';
    copy.after(note);
  }
  if (note) {
    note.textContent = index >= beats.length - 1 ? questDialogueState.note || '' : '';
    note.hidden = !note.textContent;
  }
  if (next) {
    const finalBeat = index >= beats.length - 1;
    next.textContent =
      mode === 'script'
        ? finalBeat && questDialogueState.primaryLabel
          ? questDialogueState.primaryLabel
          : beat.response || (finalBeat ? 'All right' : 'Continue')
        : finalBeat
          ? // G318: the quest's own button_accept (quests.json acceptLabel), else quest.js's default (quests/quest.js 14).
            questDialogueState.acceptLabel || def?.acceptLabel || "Ok, I'll do it!"
          : beat.response || 'Continue';
    next.dataset.accept = mode === 'offer' && finalBeat ? '1' : '0';
    const blocked = finalBeat ? questDialogueState.primaryBlocked || '' : '';
    next.disabled = Boolean(blocked);
    next.title = blocked;
  }
  if (cancel) {
    cancel.hidden = (mode === 'script' && questDialogueState.cancelable !== true) || questDialogueState.noDecline === true;
    cancel.textContent =
      mode === 'script'
        ? questDialogueState.cancelLabel || 'Close'
        : questDialogueState.declineLabel || def?.declineLabel || 'Not right now';
  }
  // G211: Magic Rock offers take QuestConversationUI's look; G225: its other
  // lines the FamiliarDialog CONVERSATION panel (js/familiar.js).
  const offer = mode === 'offer' || questDialogueState.offer === true;
  const look = familiarLook({ look: questDialogueState.look, kicker: questDialogueState.kicker, mode, offer });
  const urgent = look === 'familiar' && questDialogueState.urgent === true;
  const inLog = look === 'familiar' && questDialogueState.inLog === true;
  const head = modal.querySelector('#quest-dialogue-head span');
  // ConversationManager.as 155-165: a titled familiar conversation shows the quest book and its title.
  if (head) head.textContent = look === 'conversation' ? (title && !title.hidden ? title.textContent : '') : familiarCardHeading({ offer, kicker: questDialogueState.kicker });
  const closeX = document.getElementById('quest-dialogue-close');
  // The card's close X declines like "Not right now" (in the Quests dialog it only closes the card);
  // emergencies have none (QuestConversationUI.as 154-155), but ticket 21 gives them one: it
  // dismisses the card unanswered (closeQuestDialogue dismiss). The conversation panel's X ends a
  // conversation that can be left (ChoicesDialog.as 327-344).
  if (closeX) closeX.hidden = !['familiar', 'conversation'].includes(look) || (!urgent && (!cancel || cancel.hidden) && !inLog);
  // Split steps show one button; the decline joins the last one (QuestConversationUI.as 207-252).
  if (cancel && look === 'familiar' && offer && closeX && !closeX.hidden && index < beats.length - 1) cancel.hidden = true;
  const wasHidden = modal.hidden;
  modal.hidden = false;
  applyFamiliarLook(modal, { look, urgent, grow: wasHidden, at: inLog ? questLogCardSpot(modal) : null });
  if (app?.canvas) app.canvas.dataset.questCardLook = `${look}${urgent ? ':urgent' : ''}${inLog ? ':log' : ''}`;
}

/** G225: an offer opened from the Quests dialog sits inside it (QuestsDialog.as 229-231: x 10, list top + 10). */
function questLogCardSpot(modal) {
  const panel = document.getElementById('quest-panel');
  const list = document.getElementById('quest');
  if (!panel || panel.hidden || !list) return null;
  const base = modal.getBoundingClientRect();
  const p = panel.getBoundingClientRect();
  const l = list.getBoundingClientRect();
  return { x: p.left - base.left + 10, y: l.top - base.top + 10 };
}

/** A story quest's offer card. G562: a Street Spirit's reminisce names itself and the source's buttons. */
function openQuestDialogue(classTsid, { kicker = 'Magic Rock', acceptLabel = '', declineLabel = '' } = {}) {
  const def = getQuestCatalog()[classTsid];
  if (!def || !canOfferStoryQuest(classTsid)) return false;
  closeQuestPanel();
  closePackPopover();
  questDialogueState = {
    mode: 'offer',
    def,
    beats: withQuestMarkup(parseQuestConversation(def.offer), def.offer),
    index: 0,
    kicker,
    note: questMoveNote(def),
    acceptLabel,
    declineLabel,
  };
  renderQuestDialogueBeat();
  return true;
}

/** The open prompt's timeout (G198, js/prompt-timeout.js): { state, handle }. */
let questDialogueTimeout = null;

function cancelQuestDialogueTimeout() {
  questDialogueTimeout?.handle.cancel();
  questDialogueTimeout = null;
  if (app?.canvas) app.canvas.dataset.promptTimeout = '';
}

/**
 * A source prompt's `timeout` (seconds; `timeoutMs` for remake rows) closes
 * the card on its own once it has been shown that long (PromptView.as
 * addPrompt 350-354), with `timeoutValue` as the choice (sendChoice 174-185:
 * none when unset, so onTimeout gets null). The clock waits for the loading
 * card and holds while the pointer is over the card (removePromptIfNotOver).
 */
function armQuestDialogueTimeout(opts) {
  const ms = promptTimeoutMs(opts);
  if (!ms || !questDialogueState) return;
  const mine = questDialogueState;
  const handle = armPromptTimeout({
    ms,
    timeoutValue: opts.timeoutValue,
    hoverEl: document.querySelector('#quest-dialogue .quest-dialogue-card'),
    onExpire: (choice) => {
      if (questDialogueTimeout?.state === mine) questDialogueTimeout = null;
      if (questDialogueState !== mine) return;
      closeQuestDialogue({ force: true });
      if (app?.canvas) app.canvas.dataset.promptTimeout = `expired:${choice ?? ''}`;
      opts.onTimeout?.(choice);
    },
  });
  questDialogueTimeout = { state: mine, handle };
  if (app?.canvas) app.canvas.dataset.promptTimeout = `armed:${ms}`;
}

function openScriptedQuestDialogue({
  title,
  kicker = 'Mr. Block',
  beats,
  onComplete,
  onCancel,
  cancelable = false,
  primaryLabel = '',
  cancelLabel = '',
  timeout = 0,
  timeoutMs = 0,
  timeoutValue = null,
  onTimeout = null,
  look = '',
  offer = false,
  urgent = false,
  inLog = false,
  noDecline = false,
  primaryBlocked = '',
  note = '',
}) {
  // G217: an offer or prompt that arrives over the Enter chooser or a verb menu waits until they close.
  if (holdScriptedDialog(arguments[0])) return;
  // G225: an offer opened from the Quests dialog shows inside it.
  if (!inLog) closeQuestPanel();
  closePackPopover();
  cancelQuestDialogueTimeout();
  questDialogueState = {
    mode: 'script',
    title,
    kicker,
    look,
    offer,
    urgent,
    inLog,
    beats: (beats || []).map((beat) =>
      typeof beat === 'string' ? { text: beat, response: 'Continue' } : beat
    ),
    index: 0,
    onComplete,
    onCancel,
    cancelable,
    primaryLabel,
    cancelLabel,
    noDecline: noDecline === true,
    primaryBlocked: String(primaryBlocked || ''),
    note: String(note || ''),
  };
  renderQuestDialogueBeat();
  armQuestDialogueTimeout({ timeout, timeoutMs, timeoutValue, onTimeout });
}

/**
 * G217: scripted dialogs (offers, prompts, conversations) that arrived while
 * the Enter chooser or a verb menu was open. Features that pop one on a timer
 * (Pooped, a finished job, a location event) used to cover the menu you were
 * choosing from; they now show once it has closed, oldest first.
 */
const heldScriptedDialogs = [];

function holdScriptedDialog(opts) {
  // G267: a prompt or line (not another offer) that pops while an emergency offer is up waits
  // for it to be answered. The client stacks prompts beside the quest card (PromptView.as
  // addPrompt 330-354) and shows an emergency whatever prompts are up (QuestsDialog.as
  // onEmergencyTick 335-340); with one card, the croak prompt used to push Hell's offer off.
  const underEmergency = !opts?.offer && isQuestDialogueOpen() && questDialogueState?.urgent === true;
  // STARTCARD: and anything raised while the start card is up waits for the player to start.
  if (!opts || !(startHeld() || menuTarget || enterChooser?.isOpen() || underEmergency || familiarWaitsForScreen(opts))) return false;
  // Ticket 39: the same offer asked again while it waits takes the waiting one's place, never a
  // second card (Bellzebooze queued once a frame through a screen's fade, ~19 copies to click through).
  const same = opts.offer ? heldScriptedDialogs.findIndex((held) => held?.offer && held.title === opts.title) : -1;
  if (same >= 0) {
    heldScriptedDialogs[same] = opts;
    return true;
  }
  heldScriptedDialogs.push(opts);
  if (app?.canvas) app.canvas.dataset.dialogHeld = String(heldScriptedDialogs.length);
  return true;
}

/**
 * G364: the Magic Rock's own talk (a quest offer, or any line in its
 * familiar or conversation look) waits while a screen is showing:
 * TSFrontController.as startFamiliarConversationWithPayload 2134-2139 bails on
 * screen_view_open and queues the payload (2185-2186; quest offers are dropped there, the remake holds them) for familiar_retry_timer
 * (StateModel.as 116). A voice-of-rock overlay is an announcement, not the dialog.
 */
function familiarWaitsForScreen(opts) {
  if (!opts || opts.vog) return false;
  const look = familiarLook({ look: opts.look, kicker: opts.kicker, offer: opts.offer });
  return (look === 'familiar' || look === 'conversation') && isScreenViewOpen();
}

function releaseHeldScriptedDialog() {
  if (startHeld() || !heldScriptedDialogs.length || menuTarget || enterChooser?.isOpen() || isQuestDialogueOpen() || isVogOpen()) return;
  if (familiarWaitsForScreen(heldScriptedDialogs[0])) return;
  const next = heldScriptedDialogs.shift();
  // G228: a held VOG goes back to its own overlay.
  if (next?.vog) openLocationVog(next);
  else openScriptedQuestDialogue(next);
  if (app?.canvas) app.canvas.dataset.dialogHeld = String(heldScriptedDialogs.length);
}

/** Ticket 21: when the player last dismissed an emergency card with Escape or its X (0: never). */
let urgentDismissedAt = 0;

function closeQuestDialogue(opts = {}) {
  if (
    questDialogueState?.mode === 'script' &&
    questDialogueState.cancelable !== true &&
    opts.force !== true
  ) {
    return false;
  }
  // G225: an emergency offer on the street has no close and ignores Escape in the original
  // (QuestConversationUI.as 154-155, escKeyHandler 410-414). Ticket 21 (2026-11-01): a card that
  // keeps coming back must never trap the player, so here Escape and its X dismiss it unanswered
  // (opts.dismiss): it waits, and the Magic Rock brings it back on another street.
  const dismissing = questDialogueState?.urgent === true && !questDialogueState.inLog && opts.cancel !== true && opts.force !== true;
  if (dismissing && opts.dismiss !== true) return false;
  if (dismissing) urgentDismissedAt = Date.now();
  const onCancel =
    opts.cancel === true && typeof questDialogueState?.onCancel === 'function'
      ? questDialogueState.onCancel
      : null;
  const modal = document.getElementById('quest-dialogue');
  if (modal) modal.hidden = true;
  if (questDialogueTimeout?.state === questDialogueState) cancelQuestDialogueTimeout();
  questDialogueState = null;
  if (onCancel) onCancel();
  return true;
}

/** The focused button when it sits in an open dialog, else null (Enter and Space belong to it). */
function focusedDialogButton() {
  const button = document.activeElement?.closest?.('button, [role="button"]');
  if (!button || button.disabled) return null;
  // The pack row's buttons too: Enter or Space on a focused bag or stack presses it (opens the tray or
  // the stack's actions), never the nearest thing's menu or a jump. BUILDER: the decorate and cultivate
  // tray, banner, floating actions and Place button (js/ui/home-builder.js) likewise.
  const dialog = button.closest('dialog, [role="dialog"], [aria-modal="true"], .glitch-modal, #pack-bar, #homes-bar, #homes-pop, #homes-place');
  return dialog && !dialog.hidden ? button : null;
}

/** The newest-on-top window stack (js/window-stack.js), installed in main. */
let windowStack = null;

/**
 * The game's plain panels by id, with what closes each (the Escape chain's last step closes them
 * all at once). When one of them is the topmost window, opened over a dialog or an offer,
 * Escape closes it first, as the newest window is the one on top.
 */
const PANEL_CLOSERS = Object.freeze({
  'map-panel': () => closeMap(),
  'vendor-panel': () => closeVendor(),
  'quest-panel': () => closeQuestPanel(),
  'achieve-panel': () => closeAchievePanel(),
  'feat-panel': () => closeFeatPanel(),
  'skills-panel': () => closeSkillsPanel(),
  'buffs-panel': () => closeBuffsPanel(),
  'projects-panel': () => closeProjectsPanel(),
  'make-panel': () => closeMakePanel(),
  'garden-panel': () => closeGardenPanel(),
  'avatar-panel': () => closeAvatarPanel(),
  'shrine-panel': () => closeShrinePanel(),
});

/**
 * Escape for the topmost window when it is one of the plain panels over another window (a Map
 * opened over the Magic Rock's offer); true when it closed it. A panel on its own keeps the
 * chain's order (pack card, verb menus and the action first).
 */
function escapeTopPanel() {
  const open = windowStack?.restack() || [];
  if (open.length < 2) return false;
  const top = windowStack.top();
  const close = top ? PANEL_CLOSERS[top.id] : null;
  if (!close) return false;
  close();
  return true;
}

/**
 * Player report 16: Esc has something here to close or stop. The main Escape branch then keeps
 * the key from the browser (preventDefault): Safari's full-screen window takes an Escape the page
 * left unhandled as "leave full screen", so Esc closes the panel and full screen stays. With
 * nothing open, Esc goes on to the browser as before. (A full screen a page asked for, the
 * Fullscreen API, always ends on Esc; only Chromium's Keyboard Lock can hold it.)
 */
function escapeHasWork() {
  return Boolean(
    menuTarget ||
    currentAction ||
    gardenTend ||
    isPackPopoverOpen() ||
    isFeedPickerOpen() ||
    isEmotionalBearPickerOpen() ||
    isQuestDialogueOpen() ||
    isRookMuseumExhibitOpen() ||
    isMailboxOpen() ||
    isHomePanelOpen() ||
    isMapOpen() ||
    isVendorOpen() ||
    isQuestOpen() ||
    isAchieveOpen() ||
    isFeatOpen() ||
    isSkillsOpen() ||
    isBuffsOpen() ||
    isProjectsOpen() ||
    isMakeOpen() ||
    isGardenOpen() ||
    isAvatarOpen() ||
    isShrineOpen() ||
    features.query('packOpenBag') ||
    packRow.isSearching() ||
    panelOnScreen() ||
    [...document.querySelectorAll('[role="dialog"][aria-modal="true"]')].some((d) => d.getClientRects().length > 0)
  );
}

/** True while escapeOpenFeatureDialog's own Escape is on its way (it must not be relayed again). */
let relayingEscape = false;

/**
 * Esc for a feature's dialog that holds no focus (Buddies, House Keys, Groups and the rest are
 * opened from the Menu, so focus stays on the menu button and their own Escape listener, on the
 * dialog's shade, never hears the key). The topmost shown aria-modal dialog is handed an Escape;
 * true when that closed it. A dialog with no listener of its own stays open and Escape goes on
 * to the game's own panels below.
 */
function escapeOpenFeatureDialog() {
  const shown = [...document.querySelectorAll('[role="dialog"][aria-modal="true"]')].filter((d) => d.getClientRects().length > 0);
  // The newest is on top (js/window-stack.js); without the stack, the last one in the page.
  const top = windowStack ? windowStack.topmost(shown) : shown.at(-1);
  if (!top) return false;
  relayingEscape = true;
  try {
    top.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true, cancelable: true }));
  } finally {
    relayingEscape = false;
  }
  return !top.isConnected || top.getClientRects().length === 0;
}

function isQuestDialogueOpen() {
  const modal = document.getElementById('quest-dialogue');
  return Boolean(modal && !modal.hidden);
}

/** G255: the open dialog's final answer is blocked (no_starting_quests on accept_and_start): it does nothing. */
function questAcceptBlocked() {
  const st = questDialogueState;
  return Boolean(st?.primaryBlocked && st.index >= (st.beats?.length || 0) - 1);
}

function advanceQuestDialogue() {
  if (!questDialogueState || questAcceptBlocked()) return;
  const { def, beats, mode } = questDialogueState;
  // A scripted beat may act on its answer (G189: a conversation's reward on that step).
  beats[questDialogueState.index]?.onAnswer?.();
  if (questDialogueState.index < beats.length - 1) {
    questDialogueState.index += 1;
    renderQuestDialogueBeat();
    return;
  }
  if (mode === 'script') {
    const onComplete = questDialogueState.onComplete;
    closeQuestDialogue({ force: true });
    if (typeof onComplete === 'function') onComplete();
    return;
  }
  if (def.classTsid === HOG_HAUL_QUEST_ID) {
    questState.completed = questState.completed.filter((id) => id !== HOG_HAUL_QUEST_ID);
  }
  if (def.classTsid === WINTER_WALK_REPEAT_QUEST_ID) {
    questState.completed = questState.completed.filter(
      (id) => id !== WINTER_WALK_REPEAT_QUEST_ID
    );
  }
  if (def.classTsid === SUMMERS_DAY_REPEAT_QUEST_ID) {
    questState.completed = questState.completed.filter(
      (id) => id !== SUMMERS_DAY_REPEAT_QUEST_ID
    );
  }
  if (def.classTsid === GREEDY_STREET_SPIRIT_REPEAT_ID) {
    questState.completed = questState.completed.filter(
      (id) => id !== GREEDY_STREET_SPIRIT_REPEAT_ID
    );
  }
  if (def.classTsid === ROOK_QUEST_ID) {
    const tool = findWorkingRookTool(inv, toolState);
    if (!tool.ok) {
      toast(tool.msg, 4200);
      closeQuestDialogue({ force: true });
      return;
    }
  }
  const result = assignQuest(questState, def.classTsid, {
    ignorePrereq: [
      GREEDY_STREET_SPIRIT_REPEAT_ID,
      WINTER_WALK_QUEST_ID,
      WINTER_WALK_REPEAT_QUEST_ID,
      SUMMERS_DAY_QUEST_ID,
      SUMMERS_DAY_REPEAT_QUEST_ID,
    ].includes(def.classTsid),
  });
  if (!result.ok) {
    toast(result.reason === 'prereq' ? 'Finish the earlier story first.' : 'That quest is unavailable.');
    closeQuestDialogue();
    return;
  }
  if (def.classTsid === PHANTOM_QUEST_ID || def.classTsid === REMEMBER_QUEST_ID) {
    ghostQuestStory({
      reset: def.classTsid === PHANTOM_QUEST_ID,
    });
  }
  if (def.classTsid === ILMENSKIE_QUEST_ID) {
    const rescue = ensureIlmenskieState(questState);
    rememberIlmenskieSource(rescue, instanceSourceHere({
      tsid: currentStreetTsid,
      x: player?.x,
      y: player?.y,
    }));
  }
  closeQuestDialogue();
  if (
    def.classTsid === SUMMERS_DAY_QUEST_ID ||
    def.classTsid === SUMMERS_DAY_REPEAT_QUEST_ID
  ) {
    markSummersDayOffered(questState);
  }
  playSfx('alert', { volume: 0.65 });
  pushActivity(`New quest: ${def.title}. ${cleanQuestMarkup(def.desc)}`);
  toast(`New quest: ${def.title}`, 3600);
  updateHud();
  if (def.classTsid === ILMENSKIE_QUEST_ID) openMap();
  else if (def.classTsid === LEGALIZE_QUEST_ID) startLegalizeIt();
  else if (def.classTsid === HOG_HAUL_QUEST_ID) startHogHaulRace();
  else if (def.classTsid === GREEDY_STREET_SPIRIT_QUEST_ID) startGreedyStreetSpirit();
  else if (def.classTsid === GREEDY_STREET_SPIRIT_REPEAT_ID) {
    startGreedyStreetSpirit({ repeat: true });
  }
  else if (def.classTsid === WINTER_WALK_QUEST_ID) startWinterWalk();
  else if (def.classTsid === WINTER_WALK_REPEAT_QUEST_ID) startWinterWalk({ repeat: true });
  else if (def.classTsid === SUMMERS_DAY_QUEST_ID) startSummersDay();
  else if (def.classTsid === SUMMERS_DAY_REPEAT_QUEST_ID) startSummersDay({ repeat: true });
  else if (def.classTsid === FOUR_LETTER_QUEST_ID) startFourLetterQuest();
  else if (def.classTsid === DE_EMBIGGENIFY_QUEST_ID) startDeEmbiggenify();
  else if (def.classTsid === ROOK_QUEST_ID) startRookWoodsQuest();
  else if (def.classTsid === ROOK_HALL_START_QUEST_ID) startRookMuseum();
  else spawnPhantomQuestEncounter();
}

function closeQuestPanel() {
  const panel = document.getElementById('quest-panel');
  if (panel) panel.hidden = true;
  questSheet.closeMenu();
  // Ticket 77: a search ends with the sheet (the sort stays).
  questSheet.clearSearch();
}

function isQuestOpen() {
  const panel = document.getElementById('quest-panel');
  return panel && !panel.hidden;
}

const FEAT_COMPANIONS = EMOTIONAL_BEAR_COMPANIONS;

function clearFeatCompanionTimers() {
  for (const timer of featCompanionTimers) clearTimeout(timer);
  featCompanionTimers = [];
}

function updateLocalChatDockPosition() {
  const pack = document.getElementById('pack-bar');
  const root = document.getElementById('game-root');
  if (!pack || !root) return;
  // Docked in Decoration Mode's Pack tab (js/ui/home-builder.js renderDock) the band is the tray's
  // height: what stops above the pack keeps its place, as on the tray's other tabs.
  if (pack.dataset.hbDock) return;
  root.style.setProperty('--pack-live-height', `${Math.ceil(pack.offsetHeight) + 8}px`);
}

function showLocalChatBubble(participant, message, { feat = false, mine = false, playerId = 0, rk = '' } = {}) {
  // SOCIAL: the drawer keeps the line (Local online, the Activity log solo) instead of a fading bubble.
  // RIGHTCLICK: `playerId`, another player's line: their name in it opens their menu.
  // REACTIONS: `rk`, the line's reaction key online (js/chat-reactions.js).
  if (socialDrawer) {
    socialDrawer.localLine(participant, message, { feat, mine, playerId, rk });
    return;
  }
  const stream = document.getElementById('local-chat-stream');
  if (!stream) return;
  const bubble = document.createElement('div');
  bubble.className = `local-chat-bubble${feat ? ' is-feat' : ''}`;
  const speaker = document.createElement('b');
  speaker.textContent = `${participant}: `;
  bubble.append(speaker, document.createTextNode(message));
  stream.prepend(bubble);
  while (stream.children.length > 4) stream.removeChild(stream.lastChild);
  const timer = setTimeout(() => bubble.remove(), 7200);
  bubble.addEventListener('click', () => {
    clearTimeout(timer);
    bubble.remove();
  });
}

function handleFeatResult(result, participant) {
  if (result.activityLine) pushActivity(result.activityLine);
  if (result.broken) {
    playSfx('alert', { volume: 0.4, rate: 0.72 });
    assistedFeatChain = null;
    clearFeatCompanionTimers();
    toast(result.activityLine, 3200);
  } else if (result.ok) {
    playSfx(result.chainCompleted ? 'quest' : 'alert', { volume: 0.5 });
    // inc_feats.js:104-106: every contribution of yours grants Down to the Wire (once).
    if (result.participant === 'Ur') engine.grantAchievement('down_to_the_wire');
    // location.js 4529-4553: your line's 1, 2 or 3 points toward the personal Feat (G143).
    if (result.participant === 'Ur') engine.featsIncrement('makeup_feat_redux', result.points);
    if (result.firstContribution) {
      const updates = applyAchievementProgress(
        achieveState,
        'feats:contributed',
        1,
        pc
      );
      announceAchievementUpdates(updates);
      toast(
        `Your incantation counted toward “${INCANTATION_FEAT_TITLE}”.`,
        4200
      );
    } else if (result.chainCompleted) {
      toast(`Chain complete! ${result.chainParticipants.join(', ')} scored six points.`, 3800);
      assistedFeatChain = null;
    }
    app.canvas.dataset.featStep = String(result.step);
    app.canvas.dataset.featPoints = String(featState.totalPoints);
    app.canvas.dataset.featChains = String(featState.chainsCompleted);
    app.canvas.dataset.featParticipant = participant;
  }
  renderFeatPanel();
  updateFeatChrome();
  savePlayerState();
}

function sayLocalChat(message, participant = 'Ur', { quietActivity = false } = {}) {
  const typed = String(message || '').trim().slice(0, CHAT_MAX_CHARS);
  if (!typed) return { ok: false, reason: 'empty' };
  // main.js doLocalChat 1708-1710: under the cone of silence the line goes nowhere, not even a bubble of your own (G480).
  if (participant === 'Ur' && features.query('localChatRefused', engine)) return { ok: false, reason: 'suspended' };
  // The word filter (the remake's own addition, js/word-filter.js): the line is shown with a bad word as a grawlix.
  const text = filterText(typed);
  const result = submitIncantation(featState, text, participant, Date.now());
  // Multiplayer: the player's line also goes to the street, under their own name (realtime-feature);
  // the server filters it for everyone and its chat log keeps what was typed.
  const shown = participant === 'Ur' ? features.query('playerChatName', engine) || participant : participant;
  if (participant === 'Ur') features.query('localChatSaid', typed, engine);
  showLocalChatBubble(shown, text, { feat: result.matched || result.broken, mine: participant === 'Ur' });
  // The Local chat dock keeps the whole chain. In-world, keep only the current
  // speaker readable instead of stacking three large bubbles over the actors.
  if (result.matched) clearSpeechBubbles();
  if (hidesChatBubble(text)) {
    // A plain "hi" says hi (the hi sign) with no bubble (RightSideManager.as 233).
  } else if (participant === 'Ur') {
    showSpeechBubble(playerSpeechTarget, {
      speaker: shown,
      // The bubble shows a long line's start; the chat keeps every word (chatBubbleText).
      text: chatBubbleText(text),
      durationMs: result.matched ? 12_000 : 7_200,
    });
  } else {
    showLocalCompanionSpeech(participant, chatBubbleText(text), {
      durationMs: result.matched ? 12_000 : 7_200,
    });
  }
  if (result.ok || result.broken) {
    handleFeatResult(result, participant);
  } else if (!quietActivity && participant === 'Ur' && !socialDrawer) {
    // NOTIFY: chat stays in chat (bubble and dock); solo keeps it in the Activity log for scrollback
    // (the modern skin's drawer already logged it through showLocalChatBubble).
    notify.chat(`${shown}: ${text}`, { online: GAME_MODE === 'multiplayer' });
  }
  return result;
}

/**
 * Multiplayer: another player's Local line. main.js doLocalChat 1732-1745 ran every speaker's line
 * through the street's chain, so a line from someone new can carry it on and any other line
 * breaks it (clearIncantationsFeat 4573-4585). Points are only ever yours for your own lines.
 */
function hearLocalChat(speaker, text, { playerId = 0, rk = '' } = {}) {
  // 'Ur' is this player in the chain (feats.js); another player of that name keeps their own seat.
  const participant = speaker === 'Ur' ? 'Ur (player)' : speaker;
  const result = speaker ? submitIncantation(featState, text, participant, Date.now()) : { ok: false, matched: false, broken: false };
  showLocalChatBubble(speaker, text, { feat: result.matched || result.broken, playerId: Number(playerId) || 0, rk: String(rk || '') });
  if (result.ok || result.broken) handleFeatResult(result, participant);
  return result;
}

function finishAssistedFeatChain(playerResult) {
  if (!assistedFeatChain || !playerResult?.ok) return;
  const remaining = INCANTATION_LINES.filter((line) => line.step > playerResult.step);
  remaining.forEach((line, index) => {
    const companion = FEAT_COMPANIONS[(playerResult.step + index) % FEAT_COMPANIONS.length];
    const timer = setTimeout(() => {
      if (!assistedFeatChain) return;
      sayLocalChat(line.phrase, companion, { quietActivity: true });
    }, 620 * (index + 1));
    featCompanionTimers.push(timer);
  });
}

function sayAssignedFeatLine() {
  if (!assistedFeatChain) return;
  const line = INCANTATION_LINES[assistedFeatChain.playerStep - 1];
  const result = sayLocalChat(line.phrase, 'Ur');
  if (result.ok) finishAssistedFeatChain(result);
  closeFeatPanel();
  const input = document.getElementById('local-chat-input');
  if (input) input.value = '';
}

function gatherFeatChain() {
  clearFeatCompanionTimers();
  resetIncantationChain(featState);
  const playerStep = (featState.chainsCompleted % INCANTATION_LINES.length) + 1;
  assistedFeatChain = { playerStep };
  gatherLocalCompanions();
  for (let step = 1; step < playerStep; step += 1) {
    const line = INCANTATION_LINES[step - 1];
    sayLocalChat(line.phrase, FEAT_COMPANIONS[step - 1], { quietActivity: true });
  }
  renderFeatPanel();
  const input = document.getElementById('local-chat-input');
  // SOCIAL: the input is in the drawer; show it before filling it in.
  socialDrawer?.revealInput();
  if (input) {
    input.value = INCANTATION_LINES[playerStep - 1].phrase;
    input.focus({ preventScroll: true });
    input.select();
  }
}

function renderFeatPanel() {
  const chain = document.getElementById('feat-chain');
  const status = featStatus(featState);
  if (!chain) return;
  const title = document.getElementById('feat-title');
  if (title) title.textContent = status.title;
  chain.innerHTML = '';
  for (const line of INCANTATION_LINES) {
    const row = document.createElement('div');
    const done = status.nextStep > line.step;
    const current = status.nextStep === line.step;
    row.className = `feat-line${done ? ' done' : ''}${current ? ' current' : ''}`;
    const number = document.createElement('b');
    number.textContent = String(line.step);
    const phrase = document.createElement('span');
    phrase.textContent = line.phrase;
    const points = document.createElement('small');
    points.textContent = `+${line.points}`;
    row.append(number, phrase, points);
    chain.appendChild(row);
  }
  document.getElementById('feat-total').textContent = String(status.totalPoints);
  document.getElementById('feat-personal').textContent = String(status.personalPoints);
  document.getElementById('feat-complete').textContent = String(status.chainsCompleted);
  const prompt = document.getElementById('feat-prompt');
  const say = document.getElementById('feat-say');
  if (assistedFeatChain) {
    const line = INCANTATION_LINES[assistedFeatChain.playerStep - 1];
    if (prompt) {
      prompt.textContent =
        status.nextStep === assistedFeatChain.playerStep
          ? `Your turn. Say: “${line.phrase}”`
          : 'The street is finishing the chain…';
    }
    if (say) {
      say.hidden = status.nextStep !== assistedFeatChain.playerStep;
      say.textContent = `Say line ${line.step}`;
    }
  } else {
    if (prompt) {
      // Multiplayer: three different players on one street, one line each, in order (location.js 4522-4570).
      prompt.textContent = status.nextStep === 1
        ? (GAME_MODE === 'multiplayer'
          ? 'Three different players on one street each say one line in Local chat, in order. Anything else said in between breaks the chain.'
          : 'Gather two street companions, then take your turn in the chain.')
        : `Waiting for someone new to say line ${status.nextStep}.`;
    }
    if (say) say.hidden = true;
  }
  // MPANELS: the sheet's footer line (the Feat button's own words for the chain).
  const meta = document.getElementById('feat-meta');
  if (meta) meta.textContent = status.nextStep === 1 ? `${status.totalPoints} street points so far` : `Chain waiting for line ${status.nextStep}`;
}

function updateFeatChrome() {
  const button = document.getElementById('feat-btn');
  if (!button) return;
  button.classList.toggle('is-active', featState.nextStep !== 1);
  button.title = featState.nextStep === 1
    ? `Current Feat (H) · ${featState.totalPoints} street points`
    : `Current Feat (H) · chain waiting for line ${featState.nextStep}`;
}

function openFeatPanel() {
  if (isShrineOpen()) closeShrinePanel();
  closeMap();
  closeQuestPanel();
  closeAchievePanel();
  closeSkillsPanel();
  closeBuffsPanel();
  closeVendor();
  const panel = document.getElementById('feat-panel');
  if (panel) {
    renderFeatPanel();
    panel.hidden = false;
  }
}

function closeFeatPanel() {
  const panel = document.getElementById('feat-panel');
  if (panel) panel.hidden = true;
}

function isFeatOpen() {
  const panel = document.getElementById('feat-panel');
  return Boolean(panel && !panel.hidden);
}

function renderAchievePanel() {
  const box = document.getElementById('achieve-body');
  const meta = document.getElementById('achieve-meta');
  if (!box) return;
  box.innerHTML = '';
  box.className = 'quest-log-body ui-sheet-body achieve-grid'; // ui-sheet-body: the sheet's one scroller (the header stays put)
  const catN = Object.keys(getAchievementCatalog()).length;
  const allRows = browseAchievementLog(achieveState, achievementBrowser);
  const visibleRows = allRows.slice(0, achievementBrowser.limit);
  if (meta) {
    meta.textContent = `${achieveState.unlocked.length} unlocked · ${allRows.length} matching · ${catN} in catalog`;
  }
  document.querySelectorAll('[data-achieve-status]').forEach((button) => {
    const active = button.dataset.achieveStatus === achievementBrowser.status;
    button.classList.toggle('active', active);
    button.setAttribute('aria-pressed', active ? 'true' : 'false');
  });
  const category = document.getElementById('achieve-category');
  if (category) category.value = achievementBrowser.category;
  const search = document.getElementById('achieve-search');
  if (search && search.value !== achievementBrowser.query) search.value = achievementBrowser.query;

  if (!visibleRows.length) {
    const empty = document.createElement('div');
    empty.className = 'badge-browser-empty';
    empty.textContent = 'No badges match those filters.';
    box.appendChild(empty);
  }
  for (const row of visibleRows) {
    const card = document.createElement('div');
    card.className = 'badge-card' + (row.unlocked ? ' done' : '');
    const tsid = row.def.classTsid || row.classTsid || '';
    card.dataset.badgeTsid = row.redacted ? 'secret' : tsid;
    card.dataset.badgeStatus = row.status;
    const art = row.redacted ? null : badgeArtFor(tsid);
    if (art) {
      const icon = document.createElement('img');
      icon.className = 'badge-art';
      icon.dataset.source = art.generated ? 'reimagined' : 'official-archive';
      icon.loading = 'lazy';
      icon.decoding = 'async';
      icon.width = 48;
      icon.height = 48;
      icon.src = art.url;
      icon.alt = '';
      icon.onerror = () => icon.replaceWith(achievementBadgeFallback(row.def));
      card.appendChild(icon);
    } else {
      card.appendChild(achievementBadgeFallback(row.redacted
        ? { name: 'Secret Achievement' }
        : row.def));
    }
    const body = document.createElement('div');
    const title = document.createElement('div');
    title.className = 'q-title';
    title.textContent = (row.redacted ? 'Secret Achievement' : row.def.name) +
      (row.unlocked ? ' ✓' : row.status === 'progress' ? ' …' : '');
    body.appendChild(title);
    const desc = document.createElement('div');
    desc.className = 'q-req';
    desc.textContent = row.redacted
      ? 'Keep exploring to reveal this badge.'
      : row.def.desc || row.def.statusText || '';
    body.appendChild(desc);
    if (!row.redacted && row.def.category) {
      const label = document.createElement('div');
      label.className = 'badge-category';
      label.textContent = achievementCategoryLabel(row.def.category);
      body.appendChild(label);
    }
    if (row.unlocked && !row.redacted && trophyOfBadge(tsid)) {
      const find = document.createElement('div');
      find.className = 'badge-category';
      find.dataset.badgeTrophy = trophyOfBadge(tsid);
      find.textContent = TROPHY_FIND_TEXT;
      body.appendChild(find);
    }
    if (art?.generated) {
      const note = document.createElement('div');
      note.className = 'badge-reimagined';
      note.textContent = 'Reimagined badge art';
      note.title = 'The original badge image was not archived, so this one was redrawn in its style.';
      body.appendChild(note);
    }
    for (const c of row.redacted ? [] : row.conditions || []) {
      const r = document.createElement('div');
      r.className = 'q-req badge-condition';
      const itemLabel = ITEM_CATALOG[c.name]?.label || '';
      r.textContent = `${achievementConditionLabel(c, itemLabel)}: ${c.current} / ${c.num}`;
      body.appendChild(r);
    }
    // inc_achievements.js 520-544: these count what is in the pack at one time, so say so (report #199).
    if (!row.redacted && !row.unlocked && HELD_AT_ONCE.includes(tsid)) {
      const held = document.createElement('div');
      held.className = 'badge-category';
      held.dataset.badgeHeldAtOnce = '1';
      held.textContent = HELD_AT_ONCE_TEXT;
      body.appendChild(held);
    }
    card.appendChild(body);
    box.appendChild(card);
  }
  if (visibleRows.length < allRows.length) {
    const more = document.createElement('button');
    more.type = 'button';
    more.className = 'badge-load-more';
    more.textContent = `Show more (${allRows.length - visibleRows.length} remaining)`;
    more.addEventListener('click', () => {
      achievementBrowser.limit += ACHIEVEMENT_PAGE_SIZE;
      renderAchievePanel();
    });
    box.appendChild(more);
  }
  box.dataset.badgeMatching = String(allRows.length);
  box.dataset.badgeRendered = String(visibleRows.length);
  box.dataset.badgeCatalog = String(catN);
  if (app?.canvas) {
    app.canvas.dataset.badgeMatching = String(allRows.length);
    app.canvas.dataset.badgeRendered = String(visibleRows.length);
    app.canvas.dataset.badgeCatalog = String(catN);
    app.canvas.dataset.badgeFilter = achievementBrowser.status;
    app.canvas.dataset.badgeCategory = achievementBrowser.category;
  }
}

