function renderSkillsPanel() {
  const box = document.getElementById('skills-body');
  if (!box) return;
  renderSkillTreePanel({
    box,
    meta: document.getElementById('skills-meta'),
    state: skillState,
    ctx: {
      ...skillStudyContext(),
      questName: (id) => getQuestCatalog()[id]?.title || id.replace(/_/g, ' '),
      achievementName: (id) => getAchievementCatalog()[id]?.name || id.replace(/_/g, ' '),
      giantName: (id) => GIANTS[id]?.name || id,
      emblemCount: (giant) => countItem(inv, `emblem_${giant}`),
      // ENCYC: "In the Encyclopedia" under an open skill that has a page.
      encyclopediaLink: (id) => encyclopedia.link(document, { section: 'skills', id }, 'skill-ency'),
      // Unlearning (features/unlearning-feature.js): progress + per-skill check.
      unlearning: features.query('skillUnlearning', engine),
      // G330: a multiplayer game shows the notes of skills that need other players as working.
      online: engine.mode === 'multiplayer',
    },
    actions: {
      start: (id) => runSkillStudyAction(id, 'start'),
      resume: (id) => runSkillStudyAction(id, 'resume'),
      pause: (id) => runSkillStudyAction(id, 'pause'),
      spendEmblem: (id) => spendEmblemForSkillUnlock(id),
      unlearn: (id) => features.query('runSkillUnlearn', id, 'start', engine),
      cancelUnlearn: (id) => features.query('runSkillUnlearn', id, 'cancel', engine),
    },
  });
}

/** Start, resume, or pause one study from the Skills panel. */
function runSkillStudyAction(classTsid, action, confirmed = false) {
  const def = getSkillCatalog()[classTsid];
  const name = skillTitle(def) || classTsid;
  // skills_train refuses while a skill is being unlearned.
  const gate = action === 'pause' ? null : features.query('skillStudyGate', classTsid, engine);
  if (gate && gate.ok === false) {
    toast(gate.msg);
    renderSkillsPanel();
    return;
  }
  // G205: ImaginationSkillDetailsUI.as onLearnClick 300-320 asks before an
  // accelerated study is paused by a switch; the remake's Pause asks too.
  const active = confirmed ? null : getActiveStudy(skillState, Date.now());
  const pausesActive = action === 'pause' ? active?.classTsid === classTsid : active && active.classTsid !== classTsid;
  if (active?.isAccelerated && pausesActive) {
    confirmAcceleratedStudyPause(classTsid, action, active);
    return;
  }
  const result = action === 'pause'
    ? pauseSkillStudy(skillState, classTsid, Date.now())
    : startSkillStudy(skillState, classTsid, skillStudyContext(), Date.now());
  if (result.completed?.length) handleSkillCompletions(result.completed);
  // skills_train 791: the switched-away study is announced first.
  for (const id of result.pausedIds || []) {
    pushActivity(`You paused learning ${skillTitle(getSkillCatalog()[id]) || id}.`);
  }
  if (result.ok && action === 'start' && result.reason === 'started') {
    playSound('BEGIN_LEARNING_SKILL', { volume: 0.6 });
    toast(`Started studying ${name} · ${formatStudyTime(result.durationSeconds)}`);
    // inc_skills.js 857 and the 914 learning note.
    pushActivity(`You started learning ${name}. Skill learning will continue while you do other things. It even goes on when you're not playing the game.`);
  } else if (result.ok) {
    const verb = action === 'pause' ? 'Paused' : 'Resumed';
    toast(`${verb} ${name}.`);
    // inc_skills.js 791 and 849.
    pushActivity(`You ${verb.toLowerCase()} learning ${name}.`);
  } else {
    toast(`Cannot study ${name} yet.`);
  }
  updateHud();
  renderSkillsPanel();
}

/**
 * ImaginationSkillDetailsUI.as 306-319: the ConfirmationDialog before an
 * accelerated study is paused. The Pause button's "Yup, pause it" is remake
 * copy (the original had no pause button, only a switch).
 */
function confirmAcceleratedStudyPause(classTsid, action, active) {
  const activeName = skillTitle(getSkillCatalog()[active.classTsid]) || active.classTsid;
  const primary = action === 'pause' ? 'Yup, pause it' : 'Yup, start learning!';
  app.canvas.dataset.skillSpeedConfirm = action;
  openScriptedQuestDialogue({
    title: 'Stop your accelerated learning?',
    kicker: 'Skills',
    cancelable: true,
    primaryLabel: primary,
    cancelLabel: 'No, nevermind',
    beats: [{
      text: `Are you sure you want to pause learning ${activeName}? You will lose your accelerated learning speed if you do.`,
      response: primary,
    }],
    onComplete: () => {
      app.canvas.dataset.skillSpeedConfirm = 'yes';
      runSkillStudyAction(classTsid, action, true);
    },
    onCancel: () => {
      app.canvas.dataset.skillSpeedConfirm = 'no';
      renderSkillsPanel();
    },
  });
}

/** emblem_base spend: trade one pack emblem for its skill-unlock badge. */
function spendEmblemForSkillUnlock(classTsid) {
  const result = spendEmblemForSkill(inv, achieveState.unlocked, classTsid);
  if (!result.ok) {
    toast(result.reason === 'no_emblem' ? 'You need that Giant\'s emblem first.' : 'That emblem is already spent.');
    renderSkillsPanel();
    return;
  }
  const badge = unlockAchievement(achieveState, result.achievement, pc);
  if (badge.ok) {
    announceAchievementUpdates([
      { classTsid: result.achievement, unlocked: true, rewards: badge.rewards, def: badge.def },
    ]);
  }
  const name = skillTitle(getSkillCatalog()[classTsid]) || classTsid;
  pushActivity(`You spent an Emblem of ${GIANTS[result.giant]?.name || result.giant}. You are now able to learn ${name}.`);
  toast(`You are now able to learn ${name}.`, 3600);
  playSfx('quest', { volume: 0.55, rate: 1.08 });
  updateHud();
  renderSkillsPanel();
  savePlayerState();
}

function skillStudyContext() {
  return {
    level: pc.level,
    completedQuests: questState.completed,
    unlockedAchievements: achieveState.unlocked,
    upgrades: pc.imaginationUpgrades || [],
    // Brain capacity and category learning-speed cards (imagination feature).
    timeFactor: (def) => features.query('skillTimeFactor', def, engine) ?? 1,
  };
}

function handleSkillCompletions(completed, { offline = false } = {}) {
  for (const row of completed || []) {
    const name = row.def?.name || row.classTsid;
    // G218: the familiar's "Woohoo! New skill learned..." panel
    // (features/familiar-dialog-feature.js) hears this event and replaces the
    // old toast and award screen (FamiliarDialog SKILL_LEARNED; inc_skills.js 1442-1444 activity).
    emitGameEvent(`skill_learned:${row.classTsid}`);
    logMoment(skillLearnedActivity(skillTitle(row.def) || name, row.def?.learned || '', { offline }));
  }
  // inc_skills.js:1513 (on learning) and player.js:217 (on login): eleven skills known.
  // Solo counts only the ones learned beyond the demo kit (G306); saves that hold it keep it.
  if (skillsLearnedCount() >= 11) engine.grantAchievement('first_eleven_skills');
}

function updateSkillChrome(now = Date.now()) {
  const button = document.getElementById('skills-btn');
  if (!button) return;
  // Skills lives in the Menu; the study countdown stays on the bar as its own chip.
  const chip = document.getElementById('study-chip');
  const active = getActiveStudy(skillState, now);
  if (!active) {
    button.textContent = 'Skills';
    button.title = 'Skills (K)';
    button.classList.remove('is-studying');
    if (chip) paintIdleSkillChip(chip, availableSkillCount(now));
    return;
  }
  const def = getSkillCatalog()[active.classTsid];
  const remaining = formatStudyTime(active.remainingSeconds);
  const name = skillTitle(def) || def?.name || active.classTsid;
  button.textContent = `Study · ${remaining}`;
  button.title = `${name}: ${remaining} remaining`;
  button.classList.add('is-studying');
  if (chip) paintStudyChip(chip, active.classTsid, name, remaining);
}

/** How many skills can be learned now (the Skills panel's "ready"), counted at most every 5 s. */
let idleSkillCount = { at: 0, n: 0 };
function availableSkillCount(now = Date.now()) {
  if (now - idleSkillCount.at < 5000) return idleSkillCount.n;
  const ctx = { ...skillStudyContext(), unlearning: features.query('skillUnlearning', engine) };
  idleSkillCount = { at: now, n: skillTreeCounts(skillState, ctx, now).available };
  return idleSkillCount.n;
}

/**
 * Ticket 39 (2026-11-02): with nothing being learned the pill says how many skills are ready,
 * in the original's own words: the iMG menu's Skills cloud read "N available"
 * (ImgMenuSkills.as 150). The 2012 HUD's skill book showed only while learning
 * (PlayerSkillBookUI.as 58-69), so with none ready the pill stays hidden.
 */
function paintIdleSkillChip(chip, n) {
  if (!(n > 0)) {
    chip.hidden = true;
    return;
  }
  paintStudyChip(chip, '', 'Skills', `${n} available`, String(n));
  chip.dataset.sub = `${n} ${n === 1 ? 'skill' : 'skills'} you can learn now`;
  delete chip.dataset.tipIcon;
  chip.querySelector('.study-chip-card small').textContent = chip.dataset.sub;
  chip.setAttribute('aria-label', `Not learning a skill. ${n} available. Open Skills`);
}

/**
 * The bar's study pill (Austin 2026-11-01): the skill's name, cut short when long, and the
 * time left; hovered or focused, a card under it shows the skill's icon and its whole name.
 */
function paintStudyChip(chip, classTsid, name, remaining, short = remaining) {
  let label = chip.querySelector('.study-chip-label');
  if (!label) {
    chip.textContent = '';
    label = document.createElement('span');
    label.className = 'study-chip-label';
    label.innerHTML = '<span class="study-chip-name"></span><span class="study-chip-time"></span><span class="study-chip-short"></span>';
    const card = document.createElement('span');
    card.className = 'study-chip-card';
    card.setAttribute('aria-hidden', 'true');
    card.innerHTML = '<img class="study-chip-icon" alt="" width="48" height="48"><span class="study-chip-copy"><strong></strong><small></small></span>';
    chip.append(label, card);
  }
  const card = chip.querySelector('.study-chip-card');
  label.firstChild.textContent = studyPillName(name);
  // A no-break space: a plain one collapses at the start of the inline time ("Skills· 16 available").
  label.children[1].textContent = ` · ${remaining}`;
  // A narrow bar (topbar.js fitTopActions) shows only this: the time left, or how many are ready.
  label.children[2].textContent = short;
  if (chip.dataset.skill !== classTsid) {
    chip.dataset.skill = classTsid;
    const icon = card.querySelector('.study-chip-icon');
    // The idle pill (paintIdleSkillChip) has no skill, so no picture.
    icon.hidden = !classTsid;
    if (classTsid) icon.src = skillArtFor(classTsid, CARD_ART_LAYERS);
    else icon.removeAttribute('src');
    card.querySelector('strong').textContent = name;
  }
  card.querySelector('small').textContent = `${remaining} left`;
  // Modern draws the card as the bar's own tooltip (js/ui/topbar.js data-tip-icon); Classic shows the card.
  chip.dataset.tip = name;
  chip.dataset.sub = `${remaining} left`;
  chip.dataset.tipIcon = card.querySelector('.study-chip-icon').getAttribute('src');
  chip.removeAttribute('title');
  chip.setAttribute('aria-label', `Studying ${name}, ${remaining} left. Open Skills`);
  chip.hidden = false;
}

