  closeFeatPanel();
  if (isShrineOpen()) closeShrinePanel();
  closeMap();
  closeQuestPanel();
  closeAchievePanel();
  closeSkillsPanel();
  closeVendor();
  const panel = document.getElementById('buffs-panel');
  if (panel) {
    renderBuffsPanel();
    panel.hidden = false;
  }
